export type Ty =
  | { k: "num" } | { k: "str" } | { k: "bigint" } | { k: "null" } | { k: "undef" } | { k: "void" }
  | { k: "never" } | { k: "unknown" } | { k: "object" } | { k: "symbol" } | { k: "err" }
  | { k: "lit"; v: string | number | boolean }
  | Rec
  | { k: "arr"; el: Ty }
  | { k: "tup"; els: Ty[] }
  | Fn
  | { k: "union"; ts: Ty[] }
  | Named
  | { k: "tv"; n: string };

export const rec = () => (props: Record<string, Ty>, opt: string[] = []): Rec => ({
  k: "rec",
  props: new Map(Object.entries(props).map(([k, t]) => [k, { t, opt: opt.includes(k) }])),
});

// the names of a type parameter list node (acorn-typescript gives each name as an Identifier or a string)
export const tpNames = () => (tp: { readonly params?: readonly { readonly name: string | { readonly name: string } }[] } | null | undefined): string[] =>
  (tp?.params ?? []).map((x) => (typeof x.name === "string" ? x.name : x.name.name));

export const union = (show, typeKey, ERR, UNKNOWN, NEVER) => (ts: Ty[]): Ty => {
  function flatten(t: Ty): Ty[] {
    return t.k === "union" ? t.ts.flatMap(flatten) : t.k === "never" ? [] : [t];
  }
  const flat = ts.flatMap(flatten);
  if (flat.some((t) => t.k === "err")) return ERR;
  if (flat.some((t) => t.k === "unknown")) return UNKNOWN;
  const seen = new Set<string>();
  const out: Mut<Ty[]> = [];
  const has = (k: string) => flat.some((t) => t.k === k);
  for (const t of flat) {
    if (t.k === "lit" && ((typeof t.v === "string" && has("str")) || (typeof t.v === "number" && has("num")))) continue;
    const key = show(t);
    if (seen.has(key) && out.some((o) => show(o) === key && typeKey(o) === typeKey(t))) continue;
    seen.add(key);
    out.push(t);
  }
  const kept = out;
  const first = kept[0];
  return first === undefined ? NEVER : kept.length === 1 ? first : { k: "union", ts: kept };
};

// a type in full, with what show() leaves out past depth 6, a closed record and a member's flags (not a parameter's
// name or a signature's flags, which show() and the dedupe before it leave out too): two types with one key are one type. A memo or a dedupe keyed by show() takes two types for one when they differ only deep (holes step 8)
export const typeKey = () => {
  const fl = (f: Flags | undefined): string => (f === undefined ? "" : `#${f.mutates ? "m" : ""}${f.fresh ? "f" : ""}${f.view ? "v" : ""}${f.retains ? "r" : ""}${f.banned ? "b" : ""}${f.intrinsic ? "i" : ""}`);
  function key(t: Ty, d: number): string {
    if (d > 200) return "…";
    const k = (x: Ty) => key(x, d + 1);
    switch (t.k) {
      case "lit": return `L${typeof t.v}:${JSON.stringify(t.v)}`;
      case "arr": return `A(${k(t.el)})`;
      case "tup": return `T(${t.els.map(k).join(",")})`;
      case "union": return `U(${t.ts.map(k).join("|")})`;
      case "named": return `N${t.n}<${t.args.map(k).join(",")}>`;
      case "tv": return `V${t.n}`;
      case "fn": return `F<${t.tps.join(",")}>(${t.ps.map((p) => `${p.opt ? "?" : ""}${k(p.t)}`).join(",")}${t.rest ? `...${k(t.rest)}` : ""})=>${k(t.ret)}`;
      case "rec": {
        const ps = [...t.props].map(([n, p]) => `${JSON.stringify(n)}${p.opt ? "?" : ""}${fl(p.flags)}:${k(p.t)}`);
        return `R${t.exact === true ? "!" : ""}{${ps.join(";")}|${t.index ? k(t.index) : ""}|${(t.calls ?? []).map(k).join(",")}|${(t.ctors ?? []).map(k).join(",")}|${(t.without ?? []).join(",")}}`;
      }
      default: return t.k;
    }
  }
  return (t: Ty): string => key(t, 0);
};

// t with no closed record type: what a Mut or a state cell holds may be replaced or written by other values
export const inexact = () => {
  function go(t: Ty, d: number): Ty {
    if (d > 12) return t;
    switch (t.k) {
      case "rec": return { k: "rec", props: new Map([...t.props].map(([k, p]): [string, Prop] => [k, { ...p, t: go(p.t, d + 1) }])), index: t.index, calls: t.calls, ctors: t.ctors };
      case "arr": return { k: "arr", el: go(t.el, d + 1) };
      case "tup": return { k: "tup", els: t.els.map((x) => go(x, d + 1)) };
      case "union": return { k: "union", ts: t.ts.map((x) => go(x, d + 1)) };
      case "named": return { k: "named", n: t.n, args: t.args.map((x) => go(x, d + 1)) };
      default: return t;
    }
  }
  return (t: Ty): Ty => go(t, 0);
};

export const show = () => {
  function show(t: Ty, depth: number): string {
    if (depth > 6) return "…";
    const s = (x: Ty) => show(x, depth + 1);
    switch (t.k) {
      case "num": return "number";
      case "str": return "string";
      case "undef": return "undefined";
      case "lit": return typeof t.v === "string" ? JSON.stringify(t.v) : String(t.v);
      case "arr": return (t.el.k === "union" || t.el.k === "fn" ? `(${s(t.el)})` : s(t.el)) + "[]";
      case "tup": return `[${t.els.map(s).join(", ")}]`;
      case "union": {
        const hasT = t.ts.some((x) => x.k === "lit" && x.v === true), hasF = t.ts.some((x) => x.k === "lit" && x.v === false);
        const rest = t.ts.filter((x) => !(hasT && hasF && x.k === "lit" && typeof x.v === "boolean")).map(s);
        return (hasT && hasF ? [...rest, "boolean"] : rest).join(" | ");
      }
      case "named": return t.args.length ? `${t.n}<${t.args.map(s).join(", ")}>` : t.n;
      case "tv": return t.n;
      case "fn": return `${t.tps.length ? `<${t.tps.join(", ")}>` : ""}(${[...t.ps.map((p) => `${p.n}${p.opt ? "?" : ""}: ${s(p.t)}`), ...(t.rest ? [`...r: ${s(t.rest)}[]`] : [])].join(", ")}) => ${s(t.ret)}`;
      case "rec": {
        const ps = [
          ...[...t.props].map(([k, p]) => `${k}${p.opt ? "?" : ""}: ${s(p.t)}`),
          ...(t.index ? [`[k: string]: ${s(t.index)}`] : []),
          ...(t.calls ?? []).map(s),
        ];
        return `{ ${ps.join("; ")} }`;
      }
      default: return t.k;
    }
  }
  return (t: Ty, depth: number = 0): string => show(t, depth);
};

export const subst = (union) => {
  function substFn(f: Fn, m: Subst): Fn {
    const inner = f.tps.length ? new Map([...m].filter(([k]) => !f.tps.includes(k))) : m;
    return { ...f, ps: f.ps.map((p) => ({ ...p, t: subst(p.t, inner) })), rest: f.rest && subst(f.rest, inner), ret: subst(f.ret, inner), decl: f.decl ?? f };
  }
  function subst(t: Ty, m: Subst): Ty {
    if (m.size === 0) return t;
    switch (t.k) {
      case "tv": return m.get(t.n) ?? t;
      case "arr": return { k: "arr", el: subst(t.el, m) };
      case "tup": return { k: "tup", els: t.els.map((x) => subst(x, m)) };
      case "union": return union(t.ts.map((x) => subst(x, m)));
      case "named": return t.args.length ? { k: "named", n: t.n, args: t.args.map((x) => subst(x, m)) } : t;
      case "fn": return substFn(t, m);
      case "rec": {
        const props = new Map<string, Prop>();
        for (const [k, p] of t.props) props.set(k, { ...p, t: subst(p.t, m) });
        return { k: "rec", props: props, index: t.index && subst(t.index, m), calls: t.calls?.map((c) => substFn(c, m)), ctors: t.ctors?.map((c) => substFn(c, m)) };
      }
      default: return t;
    }
  }
  return subst;
};

export const hasTv = () => {
  function hasTv(t: Ty, names?: Set<string>): boolean {
    switch (t.k) {
      case "tv": return !names || names.has(t.n);
      case "arr": return hasTv(t.el, names);
      case "tup": return t.els.some((x) => hasTv(x, names));
      case "union": return t.ts.some((x) => hasTv(x, names));
      case "named": return t.args.some((x) => hasTv(x, names));
      case "fn": return t.ps.some((p) => hasTv(p.t, names)) || (!!t.rest && hasTv(t.rest, names)) || hasTv(t.ret, names);
      case "rec": return [...t.props.values()].some((p) => hasTv(p.t, names)) || (!!t.index && hasTv(t.index, names));
      default: return false;
    }
  }
  return hasTv;
};

// Rename a generic function's type parameters to unique names so nested instantiations do not collide.
// fresh: the caller's count of names made so far; the names are n'(fresh+1), n'(fresh+2), ...
export const instantiate = (subst) => (f: Fn, fresh: number): { f: Fn; tvs: string[] } => {
  if (!f.tps.length) return { f, tvs: [] };
  const tvs = f.tps.map((n, i) => `${n}'${fresh + i + 1}`);
  const m: Subst = new Map(f.tps.map((n, i): [string, Ty] => [n, { k: "tv", n: tvs[i] ?? n }]));
  const g = subst({ ...f, tps: [] }, m);
  // subst maps a fn to a fn
  if (g.k !== "fn") throw new Error(`instantiate: subst gave ${g.k}`);
  return { f: { ...g, decl: f.decl ?? f }, tvs };
};

// Shallow literal widening (let bindings, inferred returns, inferred type arguments).
export const widen = (STR, NUM, BOOL, union) => {
  function widen(t: Ty): Ty {
    if (t.k === "lit") return typeof t.v === "string" ? STR : typeof t.v === "number" ? NUM : BOOL;
    if (t.k === "union") return union(t.ts.map(widen));
    return t;
  }
  return widen;
};

export type TypeShape =
  | { k: "num" } | { k: "str" } | { k: "bool" } | { k: "null" } | { k: "undef" } | { k: "unknown" }
  | { k: "lit"; v: string | number | boolean }
  | { k: "arr"; el: TypeShape }
  | { k: "tup"; els: TypeShape[] }
  | { k: "rec"; props: [string, TypeShape, boolean][] }
  | { k: "union"; ts: TypeShape[] }
  | { k: "ref"; n: string }
  | { k: "defs"; defs: [string, TypeShape][]; body: TypeShape }
  | { k: "fn"; ps: TypeShape[]; ret: TypeShape; async: boolean };

// one expansion of an annotation, at most limit deep. open and rec hold tyKey keys: the aliases being expanded, and those
// met again inside themselves; defs: the definition of each recursive alias by its ref's name; names: per key, that
// name (show's, unique)
// met: the parts made so far (a9 (2026-11-23), B-4: an alias that is not recursive is expanded at each use, so a type
// that branches at each level has a shape exponential in its depth; SHAPE_PARTS bounds it)
export type ShapeCtx = Mut<{ open: readonly string[]; rec: Set<string>; defs: Map<string, TypeShape>; names: Map<string, string>; limit: number; met: number }>;

// the text of t with each part given as c gives it
export const tyText = () => (t: Ty, c: (x: Ty | undefined) => string): string => {
  const cs = (xs: readonly Ty[] | undefined): string => (xs ?? []).map(c).join(",");
  const q = (n: string): string => JSON.stringify(n);
  switch (t.k) {
    case "lit": return `lit ${typeof t.v} ${typeof t.v === "string" ? q(t.v) : Object.is(t.v, -0) ? "-0" : String(t.v)}`;
    case "arr": return `arr ${c(t.el)}`;
    case "tup": return `tup ${cs(t.els)}`;
    case "union": return `union ${cs(t.ts)}`;
    case "named": return `named ${q(t.n)} ${cs(t.args)}`;
    case "tv": return `tv ${q(t.n)}`;
    case "fn": return `fn ${q(t.tps.join(","))} ${t.ps.map((p) => `${q(p.n)}${p.opt ? "?" : ""}:${c(p.t)}`).join(",")} ...${c(t.rest)} => ${c(t.ret)}`;
    case "rec": return `rec ${[...t.props].map(([n, p]) => `${q(n)}${p.opt ? "?" : ""}:${c(p.t)}`).join(",")} [${c(t.index)}] (${cs(t.calls)}) new(${cs(t.ctors)})`;
    default: return t.k;
  }
};

// a text for t that two types share only when they are the same type (show shortens a deep type with …); each part in
// parentheses, so the text reads one way
export const tyKey = (tyText) => (t: Ty): string => {
  function key(x: Ty | undefined): string {
    return x ? `(${tyText(x, key)})` : "";
  }
  return key(t);
};

export const refName = (show) => (t: Ty, key: string, ctx: ShapeCtx): string => {
  const hit = ctx.names.get(key);
  if (hit !== undefined) return hit;
  const base = show(t), taken = [...ctx.names.values()];
  let n = base;
  for (let i = 2; taken.includes(n); i++) n = `${base} (${i})`;
  ctx.names = new Map([...ctx.names, [key, n]]);
  return n;
};

// a generic alias expanded over placeholders, then given its arguments: expand keeps one expansion per name as show
// prints it, and show shortens a deep argument, so two deep arguments would share one
export const expandFull = (subst) => (t: Named, expand: (t: Ty) => Ty): Ty => {
  if (!t.args.length) return expand(t);
  const ps = t.args.map((_, i) => ` ${i}`);
  return subst(expand({ k: "named", n: t.n, args: ps.map((n) => ({ k: "tv", n })) }), new Map(t.args.map((a, i) => [` ${i}`, a])));
};

// the definition of n reaches n through unions and refs alone, so no finite value is checked against it
export const unproductive = () => (n: string, defs: Map<string, TypeShape>): boolean => {
  const met: Mut<Set<string>> = new Set();
  function go(s: TypeShape): boolean {
    if (s.k === "union") { for (const m of s.ts) if (go(m)) return true; return false; }
    if (s.k !== "ref") return false;
    if (s.n === n) return true;
    if (met.has(s.n)) return false;
    met.add(s.n);
    const d = defs.get(s.n);
    return d !== undefined && go(d);
  }
  const d = defs.get(n);
  return d !== undefined && go(d);
};

// true | false is boolean
export const boolUnion = () => (ts: readonly TypeShape[]): TypeShape => {
  const isBool = (s: TypeShape): boolean => s.k === "lit" && typeof s.v === "boolean";
  return ts.filter(isBool).length === 2 ? { k: "union", ts: [...ts.filter((s) => !isBool(s)), { k: "bool" }] } : { k: "union", ts: [...ts] };
};

// each of xs as a shape, d deep, or the first error
export const shapesOf = () => (xs: readonly Ty[], sub: ShapeSub, d: number, ctx: ShapeCtx): { readonly k: "many"; readonly shapes: TypeShape[] } | ShapeErr => {
  const out: Mut<TypeShape[]> = [];
  for (const x of xs) { const s = sub(x, d, ctx); if (s.k === "error") return s; out.push(s); }
  return { k: "many", shapes: out };
};

export const recShape = () => (t: Rec, sub: ShapeSub, d: number, ctx: ShapeCtx): ShapeOr => {
  if (t.calls?.length || t.ctors?.length) return { k: "error", error: "a function" };
  if (t.index) return { k: "error", error: "an index signature" };
  const props: Mut<[string, TypeShape, boolean][]> = [];
  for (const [n, p] of t.props) { const s = sub(p.t, d, ctx); if (s.k === "error") return { k: "error", error: `${n}: ${s.error}` }; props.push([n, s, p.opt]); }
  return { k: "rec", props: props };
};

// an alias met again while it is being expanded is a ref, and the shape of the whole annotation lists the definition of
// each such alias once (defs); an alias that is not recursive is expanded in place
export const aliasShape = (tyKey, refName, expandFull) => (t: Named, sub: ShapeSub, d: number, X: Expansion, ctx: ShapeCtx): ShapeOr => {
  const key = tyKey(t);
  if (ctx.open.includes(key) || ctx.defs.has(ctx.names.get(key) ?? "")) { ctx.rec = new Set([...ctx.rec, key]); return { k: "ref", n: refName(t, key, ctx) }; }
  ctx.open = [...ctx.open, key];
  const s = sub(expandFull(t, X.expand), d, ctx);
  ctx.open = ctx.open.slice(0, -1);
  if (s.k === "error" || !ctx.rec.has(key)) return s;
  const n = refName(t, key, ctx);
  ctx.defs = new Map([...ctx.defs, [n, s]]);
  return { k: "ref", n };
};

export const namedShape = (show, aliasShape) => (t: Named, sub: ShapeSub, d: number, X: Expansion, ctx: ShapeCtx): ShapeOr => {
  if (t.n === "Promise") return { k: "error", error: "a promise" };
  if (X.isAlias(t.n)) return aliasShape(t, sub, d, X, ctx);
  const el = t.args[0];
  if ((t.n === "Array" || t.n === "ReadonlyArray") && el !== undefined) { const s = sub(el, d, ctx); return s.k === "error" ? s : { k: "arr", el: s }; }
  return { k: "error", error: `${show(t)}, which the boundary does not check` };
};

// t as a shape within one expansion, depth deep
export const shapeIn = (show, shapesOf, boolUnion, recShape, namedShape, SHAPE_PARTS) => (t0: Ty, X: Expansion, ctx: ShapeCtx): ShapeOr => {
  function go(t: Ty, depth: number, c: ShapeCtx): ShapeOr {
    // a generic alias whose arguments grow at each level never repeats
    if (depth > c.limit) return { k: "error", error: "a recursive type" };
    c.met += 1;
    if (c.met > SHAPE_PARTS) return { k: "error", error: `a type too large to check at run time (its run-time form has more than ${SHAPE_PARTS} parts)` };
    const d = depth + 1;
    switch (t.k) {
      case "num": return { k: "num" };
      case "str": return { k: "str" };
      case "null": return { k: "null" };
      case "undef": case "void": return { k: "undef" };
      case "unknown": return { k: "unknown" };
      // a9 (2026-11-23), B-2: the shape is written into the compiled cell as JSON, which writes Infinity as null
      case "lit": return typeof t.v === "number" && !Number.isFinite(t.v) ? { k: "error", error: `${show(t)}, a literal type JSON cannot write` } : { k: "lit", v: t.v };
      case "fn": return { k: "error", error: "a function" };
      case "arr": { const el = go(t.el, d, c); return el.k === "error" ? el : { k: "arr", el }; }
      case "tup": { const els = shapesOf(t.els, go, d, c); return els.k === "error" ? els : { k: "tup", els: els.shapes }; }
      case "union": { const ts = shapesOf(t.ts, go, d, c); return ts.k === "error" ? ts : boolUnion(ts.shapes); }
      case "rec": return recShape(t, go, d, c);
      case "named": return namedShape(t, go, d, X, c);
      default: return { k: "error", error: `${show(t)}, which the boundary does not check` };
    }
  }
  return go(t0, 0, ctx);
};

// the body with the definitions of its refs, unless one of them is unproductive
export const withDefs = (unproductive) => (body: ShapeOr, defs: Map<string, TypeShape>): ShapeOr => {
  if (body.k === "error" || !defs.size) return body;
  const bad = [...defs.keys()].find((n) => unproductive(n, defs));
  if (bad !== undefined) return { k: "error", error: `${bad}, a recursive type with no object or array between it and itself` };
  return { k: "defs", defs: [...defs], body };
};

// The shape of an annotation. A type nested deeper than 16 is refused unless it is recursive; a recursive one is expanded
// again up to 256, as a ring of aliases closes only after each is open
export const shapeAt = (shapeIn, withDefs) => (t: Ty, X: Expansion): ShapeOr => {
  const near: ShapeCtx = { open: [], rec: new Set(), defs: new Map(), names: new Map(), limit: 16, met: 0 };
  const first = shapeIn(t, X, near);
  if (first.k !== "error") return withDefs(first, near.defs);
  const far: ShapeCtx = { open: [], rec: new Set(), defs: new Map(), names: new Map(), limit: 256, met: 0 };
  const again = shapeIn(t, X, far);
  return far.rec.size ? withDefs(again, far.defs) : first;
};

// a function's shape: no type parameters and no rest parameter; its parameters and its result, or the T of a Promise<T>
// result, must cross
export const fnShape = (shapeAt) => (f: Fn, X: Expansion): ShapeOr => {
  if (f.tps.length || f.rest) return { k: "error", error: "a function with type parameters or a rest parameter" };
  const part = (x: Ty, what: string): ShapeOr => { const s = shapeAt(x, X); return s.k === "error" ? { k: "error", error: `a function whose ${what} is or holds ${s.error}` } : s; };
  const ps: Mut<TypeShape[]> = [];
  for (const [i, p] of f.ps.entries()) { const s = part(p.t, `parameter ${p.n !== "" ? p.n : String(i + 1)}`); if (s.k === "error") return s; ps.push(p.opt ? { k: "union", ts: [s, { k: "undef" }] } : s); }
  const ret = f.ret.k === "named" && f.ret.n === "Promise" ? f.ret.args[0] : undefined;
  const r = part(ret ?? f.ret, "result");
  return r.k === "error" ? r : { k: "fn", ps: ps, ret: r, async: ret !== undefined };
};

// The shape of a parameter's annotation. fnOk (not under State): a function type may be the whole annotation
export const boundaryShapeAt = (shapeAt, fnShape) => (t: Ty, X: Expansion, fnOk: boolean): ShapeOr => {
  let f = t;
  for (let i = 0; i < 16 && f.k === "named" && X.isAlias(f.n); i++) f = X.expand(f);
  return fnOk && f.k === "fn" ? fnShape(f, X) : shapeAt(t, X);
};

// the key a check is remembered by
export const checkKey = () => (source: string, tsx: boolean, outside: readonly CheckOutside[] | null): string =>
  (tsx ? "x" : "s") + (outside !== null && outside.length ? JSON.stringify(outside) : "") + "\u0000" + source;

// key set to v and moved to the end (most recently used), the oldest dropped past limit
export const lruTouch = () => <V,>(m: Map<string, V>, key: string, v: V, limit: number): Map<string, V> => {
  const out: Mut<Map<string, V>> = new Map([...m].filter(([k]) => k !== key));
  out.set(key, v);
  const first = [...out.keys()][0];
  if (out.size > limit && first !== undefined) out.delete(first);
  return out;
};

// each cell text kept (its index) or a stand-in of the same name and line count for one that does not parse; the k-th
// declaration of a name is "<name> (k)" (core.ts distinctNames)
export const standIns = () => (cells: readonly CellText[]): StoodIn => {
  const seen: Mut<Map<string, number>> = new Map();
  const texts: Mut<(number | string)[]> = [];
  const unparsed: Mut<(readonly [string, string])[]> = [];
  for (const [i, c] of cells.entries()) {
    const name = c.declared;
    const n = name !== null ? (seen.get(name) ?? 0) + 1 : 0;
    if (name !== null) seen.set(name, n);
    if (c.parseError === null) { texts.push(i); continue; }
    if (name === null) continue;
    unparsed.push([n > 1 ? `${name} (${n})` : name, c.parseError]);
    texts.push(`const ${name} = () => $ss$unparsed;` + "\n".repeat(c.lines - 1));
  }
  return { texts: texts, unparsed: unparsed };
};

// the caller and island cells the checker did not accept (the last verdict of a name)
export const refusedCells = () => (verdicts: readonly CellVerdict[], caller: string, order: readonly string[]): readonly string[] => {
  const ok = new Map(verdicts.map((v) => [v.name, v.ok]));
  return [caller, ...order].filter((n) => ok.get(n) !== true);
};

// an island's key, new unless its text has one; a key is never reused for other text
export const islandKey = () => (known: string | undefined, made: number, caller: string): { readonly key: string; readonly made: number } =>
  known !== undefined ? { key: known, made } : { key: `island${made + 1}:${caller}`, made: made + 1 };

export type RegOps = {
  readonly expand: (t: Ty) => Ty;
  readonly isAlias: (n: string) => boolean;
  readonly member: (t: Ty, name: string) => Prop | undefined;
  readonly isTypedArray: (t: Ty) => boolean;
  readonly same: (a: Ty, b: Ty) => boolean;
  readonly at: (ts: Ty[], i: number) => Ty;
  // a new number each call, for type variable names no other comparison uses: alias expansion memoises by name
  readonly fresh: () => number;
  // x1 (2026-11-24, C): n is a member every function value has (intrinsics.ts FN_OWN_MEMBERS)
  readonly fnOwn?: (n: string) => boolean;
};

// what member lookup takes from the Registry: its declarations, an interface's record, and the strict-index setting
export type DeclOps = {
  readonly decl: (n: string) => DeclInfo | undefined;
  readonly expand: (t: Ty) => Ty;
  readonly ifaceRec: (n: string) => Rec;
  readonly strictIndex: () => boolean;
  readonly at: (ts: Ty[], i: number) => Ty;
};

// a name expanded before it is compared: an alias, or an interface of the module, a foreign file or JSX. Elem is the
// one JSX type that is not structural: only JSX makes one (h at run time), so a record is not one
export const isAliasWith = (WRAPPERS) => (D: DeclOps) => (n: string): boolean => {
  const d = D.decl(n);
  return !!d && !WRAPPERS.has(n) && (d.kind === "alias" || d.origin === "user" || d.origin === "foreign" || (d.origin === "jsx" && n !== "Elem"));
};

// The type names the checker gives a meaning of its own: declared by the intrinsics, the prelude or JSX, the
// wrappers, and the names convert reads first. decls: the Registry's declarations before the user's are loaded
export const builtinNamesOf = (WRAPPERS, CONVERT_NAMES) => (decls: [string, DeclInfo][]): Set<string> =>
  new Set([...decls.filter(([, d]) => d.origin !== "user" && d.origin !== "foreign").map(([n]) => n), ...WRAPPERS, ...CONVERT_NAMES]);

// a named type's property: an interface's, with the type arguments put in for its parameters
export const namedMemberWith = (UNKNOWN, subst) => (D: DeclOps, member: (t: Ty, name: string) => Prop | undefined) => (t: Named, name: string): Prop | undefined => {
  if (t.n === "Mut" || t.n === "Borrowed") return member(D.at(t.args, 0), name);
  if (t.n === "Iterable" || t.n === "ArrayLike") return undefined;
  const d = D.decl(t.n), p = d ? D.ifaceRec(t.n).props.get(name) : undefined;
  if (!d || !p) return undefined;
  const m: Subst = new Map(d.tps.map((n, i): [string, Ty] => [n, t.args[i] ?? UNKNOWN]));
  return { ...p, t: subst(p.t, m) };
};

// The declared property name of t, not yet with undefined added for an optional or index read
export const memberWith = (STR, NUM, UNDEF, named, union, namedMemberWith) => (D: DeclOps) => {
  const namedMember = namedMemberWith(D, member);
  function member(t0: Ty, name: string): Prop | undefined {
    const t = D.expand(t0);
    switch (t.k) {
      case "named": return namedMember(t, name);
      case "rec": {
        const p = t.props.get(name), index = t.index;
        return p ? p : index ? { t: D.strictIndex() ? union([index, UNDEF]) : index, opt: false } : undefined;
      }
      case "arr": return member(named("Array", t.el), name);
      case "tup": return name === "length" ? { t: { k: "lit", v: t.els.length }, opt: false } : member(named("Array", union(t.els)), name);
      case "str": return member(named("String"), name);
      case "num": return member(named("Number"), name);
      case "lit": return member(typeof t.v === "string" ? STR : typeof t.v === "number" ? NUM : named("Boolean"), name);
      case "union": return t.ts.every((x) => x.k === "lit" && typeof x.v === "boolean") ? member(named("Boolean"), name) : undefined;
      default: return undefined;
    }
  }
  return member;
};

export const callSigsWith = () => (R: RegOps) => {
  function callSigs(t0: Ty): Fn[] {
    const t = R.expand(t0);
    if (t.k === "fn") return [t];
    if (t.k === "rec") return t.calls ?? [];
    return t.k === "named" && (t.n === "Mut" || t.n === "Borrowed") ? callSigs(R.at(t.args, 0)) : [];
  }
  return callSigs;
};

// the element type of a named iterable: a collection, a typed array or a match
export const namedElemWith = (union, STR, NUM, UNDEF) => (R: RegOps, iterElem: (t: Ty) => Ty | undefined) => (t: Named): Ty | undefined => {
  if (t.n === "Iterable" || t.n === "ArrayLike" || t.n === "Set") return t.args[0];
  if (t.n === "Mut" || t.n === "Borrowed") return iterElem(R.at(t.args, 0));
  if (t.n === "Map") return { k: "tup", els: [R.at(t.args, 0), R.at(t.args, 1)] };
  if (R.isTypedArray(t)) return NUM;
  // a match is an array of the whole match and each group, undefined for a group that did not take part
  return t.n === "RegExpMatchArray" ? union([STR, UNDEF]) : undefined;
};

// the element type of for...of, spread or Iterable<T>, or undefined when t is not iterable
export const iterElemWith = (union, STR, ERR, namedElemWith) => (R: RegOps) => {
  const namedElem = namedElemWith(R, iterElem);
  function iterElem(t0: Ty): Ty | undefined {
    const t = R.expand(t0);
    switch (t.k) {
      case "arr": return t.el;
      case "tup": return union(t.els);
      case "str": return STR;
      case "lit": return typeof t.v === "number" || typeof t.v === "boolean" ? undefined : STR;
      case "err": return ERR;
      case "named": return namedElem(t);
      case "union": {
        const es: Mut<Ty[]> = [];
        let all = true;
        for (const x of t.ts) { const e = iterElem(x); if (e) es.push(e); else all = false; }
        return all ? union(es) : undefined;
      }
      default: return undefined;
    }
  }
  return iterElem;
};

// t is one of the types with no parts: s <: t by kind and literal value
export const primSub = () => (s: Ty, t: Ty): boolean => {
  switch (t.k) {
    case "num": return s.k === "num" || (s.k === "lit" && typeof s.v === "number");
    case "str": return s.k === "str" || (s.k === "lit" && typeof s.v === "string");
    case "lit": return s.k === "lit" && s.v === t.v;
    case "void": return s.k === "void" || s.k === "undef";
    case "null": case "undef": case "bigint": case "symbol": case "never": return s.k === t.k;
    case "object": return ["rec", "arr", "tup", "fn", "named", "object"].includes(s.k);
    default: return false;
  }
};

// arrays are covariant; a tuple is an array of each of its elements
export const seqSubWith = () => (R: RegOps, sub: Sub) => (s: Ty, t: { k: "arr"; el: Ty } | { k: "tup"; els: Ty[] }, seen: Mut<Set<string>>): boolean => {
  if (t.k === "arr") {
    if (s.k === "arr") return sub(s.el, t.el, seen);
    if (s.k !== "tup") return false;
    for (const e of s.els) if (!sub(e, t.el, seen)) return false;
    return true;
  }
  if (s.k !== "tup" || s.els.length !== t.els.length) return false;
  let i = 0;
  for (const a of s.els) if (!sub(a, R.at(t.els, i++), seen)) return false;
  return true;
};

// a function type: parameters contravariant, the result covariant; s has no parameter that t does not declare. Generic on both sides with as many type
// parameters: compared with both renamed to the same fresh names. x1 (2026-11-24, V): a void result is compared as
// any other (void takes undefined only), so a call typed void holds undefined; a callback whose result is dropped is
// typed unknown (intrinsics.ts forEach), where the forgetting rule's plain test applies
export const fnSubWith = (subst) => (R: RegOps, sub: Sub) => {
  function fnSub(s: Fn, t: Fn, seen: Mut<Set<string>>): boolean {
    if (s.tps.length || t.tps.length) {
      if (s.tps.length !== t.tps.length) return false;
      const fresh: Ty[] = s.tps.map(() => ({ k: "tv", n: `$a${R.fresh()}` }));
      const open = (f: Fn): Fn => { const g = subst({ ...f, tps: [] }, new Map(f.tps.map((x, i): [string, Ty] => [x, R.at(fresh, i)]))); return g.k === "fn" ? g : f; };
      return fnSub(open(s), open(t), seen);
    }
    const tRest = t.rest, sRest = s.rest;
    // open part 5 (OP, RP): a parameter s requires is required in t at its place, so a call through t passes it
    if (s.ps.some((p, i) => !p.opt && (t.ps[i]?.opt ?? true))) return false;
    // open (2026-11-25): a parameter t does not declare may get a caller's extra argument (map's index and array)
    if (!tRest && (sRest || s.ps.length > t.ps.length)) return false;
    for (let i = 0; i < s.ps.length; i++) {
      const tp = t.ps[i]?.t ?? tRest, sp = s.ps[i];
      if (!tp || !sp) break;
      if (!sub(tp, sp.t, seen)) return false;
    }
    if (tRest && sRest && !sub(tRest, sRest, seen)) return false;
    return sub(s.ret, t.ret, seen);
  }
  return fnSub;
};

// some call signature of fs is a subtype of c
export const someFnSub = () => (fnSub: FnSub) => (fs: Fn[], c: Fn, seen: Mut<Set<string>>): boolean => {
  for (const f of fs) if (fnSub(f, c, seen)) return true;
  return false;
};

// a value with a call or construct signature reaches a record type with none only where a function of no known
// signature would: no index and every member optional (holes step 9; a call-less record held any function before)
// w1 (2026-11-24, the forgetting rule): the named types that are not plain data: the handles, Mut, a response, an
// element, the pool, a promise, a generator or an iterable
export const NOT_PLAIN = () => new Set(["Action", "State", "StateCell", "Events", "Listener", "Mut", "Borrowed", "FetchResponse", "Elem", "Pool", "Promise", "Generator", "AsyncGenerator", "Iterator", "IterableIterator", "Iterable"]);

// t is plain data: it holds no function, Action, State or Events handle, Mut, promise, iterator or response, nor unknown,
// object or a type parameter, which may hold one; a named type with a then or next member is a promise or an iterator.
// An alias met again on the walk counts as plain (what it adds is walked where it was first met)
// the reads plain takes, which a RegOps and the checker's registry core both give
export type PlainR = { readonly isAlias: (n: string) => boolean; readonly expand: (t: Ty) => Ty; readonly member: (t: Ty, name: string) => Prop | undefined; readonly fnOwn?: (n: string) => boolean };

export const plainWith = (typeKey, NOT_PLAIN) => (R: PlainR) => (t0: Ty): boolean => {
  const seen: Mut<Set<string>> = new Set();
  function plain(t: Ty): boolean {
    switch (t.k) {
      case "unknown": case "object": case "tv": case "fn": return false;
      case "arr": return plain(t.el);
      case "tup": return t.els.every((x) => plain(x));
      case "union": return t.ts.every((x) => plain(x));
      case "rec": return !t.calls?.length && !t.ctors?.length && [...t.props.values()].every((p) => plain(p.t)) && (t.index === undefined || plain(t.index));
      case "named": {
        if (!R.isAlias(t.n)) return !NOT_PLAIN.has(t.n) && R.member(t, "then") === undefined && R.member(t, "next") === undefined && t.args.every((x) => plain(x));
        const key = typeKey(t);
        if (seen.has(key)) return true;
        seen.add(key);
        return plain(R.expand(t));
      }
      default: return true;
    }
  }
  return plain(t0);
};

// w1: a record type t with no call or construct signature takes only a record s with none (not a function, array,
// tuple, primitive, unknown, object, type parameter or a value of a named type such as Error, Map or Promise). y1
// (2026-11-24): w1's width test (what t does not declare of s must be plain data) is gone: a response, promise or
// iterator left out is refused at run time where it is handed over, and a function or Action left out is not reached
// by a conversion (banned member names, @plain). x1 (2026-11-24, C):
// t with a call or construct signature: a record s with one too keeps that rule (a function s has only members of
// its own, which recSubWith compares by name); any other s is left to recSubWith's signature check
export const takesRecord = () => (se: Ty, t: Rec): boolean => {
  const callable = !!t.calls?.length || !!t.ctors?.length;
  if (callable && (se.k !== "rec" || (!se.calls?.length && !se.ctors?.length))) return true;
  return se.k === "rec" && (callable || (!se.calls?.length && !se.ctors?.length));
};

// w1: why s is not assignable to t by the forgetting rule, as a message ending in a fix, or null: s or a part of s
// (by t's members, array elements and an alias or Mut expanded) is a non-record given a record type
export const forgotWith = (show) => (R: PlainR) => {
  function why(s0: Ty, t0: Ty, d: number): string | null {
    const s = R.expand(s0.k === "named" && (s0.n === "Mut" || s0.n === "Borrowed") ? s0.args[0] ?? s0 : s0), t = R.expand(t0);
    if (d > 6) return null;
    if (s.k === "arr" && t.k === "arr") return why(s.el, t.el, d + 1);
    // x1 (2026-11-24, C): a member every function has, which the type gives another type
    const fnLike = s.k === "fn" || (s.k === "rec" && (!!s.calls?.length || !!s.ctors?.length));
    if (fnLike && t.k === "rec") for (const k of t.props.keys()) if (R.fnOwn?.(k) === true && R.member(s, k) === undefined)
      return `every function has its own ${k}, and the type declares ${k} of its own: leave ${k} out of the type, or name the member differently`;
    if (t.k !== "rec" || ((t.calls?.length || t.ctors?.length) && !(s.k === "rec" && fnLike))) return null;
    if (fnLike && !t.calls?.length && !t.ctors?.length) return `a function is not a record, so a record type does not take it: give it a function type (${show(s)})`;
    if (s.k !== "rec") return ["null", "undef", "void", "never", "err", "union", "unknown", "object", "tv"].includes(s.k) ? null : `${show(s)} is not a record, so a record type does not take it: give it its own type (${show(s)})`;
    for (const [k, p] of t.props) { const sp = s.props.get(k); const w = sp ? why(sp.t, p.t, d + 1) : null; if (w) return `${k}: ${w}`; }
    return null;
  }
  return (s: Ty, t: Ty): string | null => why(s, t, 0);
};

// open (2026-11-25): why s is not assignable to t by fnSubWith's parameter count, as a message ending in a fix, or null:
// s or a part of s (by t's members, elements, type arguments and union members) is a function with a parameter
// that the function type it is given does not declare
export const extraParamsWith = (show) => (R: PlainR) => {
  const sigs = (t: Ty): Fn[] => (t.k === "fn" ? [t] : t.k === "rec" ? t.calls ?? [] : []);
  const over = (f: Fn, c: Fn): boolean => !c.rest && (!!f.rest || f.ps.length > c.ps.length);
  // open part 5 (OP, RP): the first parameter f requires that c lets a caller leave out, or -1
  const omit = (f: Fn, c: Fn): number => f.ps.findIndex((p, i) => !p.opt && (c.ps[i]?.opt ?? true));
  function why(s0: Ty, t0: Ty, d: number): string | null {
    const s = R.expand(s0.k === "named" && (s0.n === "Mut" || s0.n === "Borrowed") ? s0.args[0] ?? s0 : s0), t = R.expand(t0);
    if (d > 6) return null;
    const pairs: Mut<[Ty, Ty][]> = s.k === "arr" && t.k === "arr" ? [[s.el, t.el]] : s.k === "tup" && t.k === "arr" ? s.els.map((x): [Ty, Ty] => [x, t.el])
      : s.k === "tup" && t.k === "tup" ? s.els.map((x, i): [Ty, Ty] => [x, t.els[i] ?? x]) : s.k === "named" && t.k === "named" && s.n === t.n ? s.args.map((x, i): [Ty, Ty] => [x, t.args[i] ?? x])
      : s.k === "union" ? s.ts.map((x): [Ty, Ty] => [x, t]) : t.k === "union" ? t.ts.map((x): [Ty, Ty] => [s, x]) : [];
    if (s.k === "rec" && t.k === "rec") for (const [k, p] of t.props) { const sp = s.props.get(k); if (sp) pairs.push([sp.t, p.t]); }
    for (const [a, b] of pairs) { const w = why(a, b, d + 1); if (w !== null) return w; }
    const fs = sigs(s), f = fs[0];
    for (const c of sigs(t)) if (f !== undefined && fs.every((g) => over(g, c))) {
      const n = f.rest ? "a rest parameter" : `${f.ps.length} parameters`;
      return `${d > 0 ? show(f) : "the function"} has ${n} and its type declares ${c.ps.length}: a caller can pass more arguments than the type declares, so a parameter past them can get a value of another type; ${f.rest ? "remove the rest parameter, or give the type a rest parameter" : `remove the parameters after the first ${c.ps.length}, or declare them in the type`}`;
    }
    for (const c of sigs(t)) {
      const i = f !== undefined && fs.every((g) => omit(g, c) >= 0) ? omit(f, c) : -1, p = f?.ps[i];
      if (p !== undefined) return `${d > 0 && f !== undefined ? show(f) : "the function"} requires ${p.n}, and its type lets a caller leave that argument out (${c.ps[i] ? "an optional parameter" : "a rest parameter"}), so ${p.n} gets undefined; make ${p.n} optional or give it a default value, or make the parameter required in the type`;
    }
    return null;
  }
  return (s: Ty, t: Ty): string | null => why(s, t, 0);
};

// w1 (2026-11-24, A-4): what in t JSON.stringify gives undefined for (undefined, a function), or a type that may hold one
// (unknown, object, a type parameter), or null: aliases expanded, Mut unwrapped, union members each
export const jsonGapWith = (show) => (R: PlainR) => (t0: Ty): string | null => {
  const go = (t: Ty, d: number): string | null => {
    if (d > 10) return null;
    if (t.k === "named" && (t.n === "Mut" || t.n === "Borrowed")) return go(t.args[0] ?? t, d + 1);
    if (t.k === "named" && R.isAlias(t.n)) return go(R.expand(t), d + 1);
    if (t.k === "union") { for (const m of t.ts) { const w = go(m, d + 1); if (w) return w; } return null; }
    if (t.k === "undef" || t.k === "void") return "undefined";
    if (t.k === "fn" || (t.k === "rec" && (!!t.calls?.length || !!t.ctors?.length))) return `a function (${show(t)})`;
    return t.k === "unknown" || t.k === "object" || t.k === "tv" ? `${show(t)}, which may be either` : null;
  };
  return go(t0, 0);
};

// a record type t: each of its properties, its index signature and its call signatures
export const recSubWith = (propT, someFnSub, takesRecord, UNKNOWN) => (R: RegOps, sub: Sub, fnSub: FnSub, callSigs: (t: Ty) => Fn[]) => {
  return (s: Ty, t: Rec, seen: Mut<Set<string>>): boolean => {
  if (["null", "undef", "void"].includes(s.k) || (s.k === "named" && ["State", "StateCell", "Action"].includes(s.n))) return false; // State...: nominal
  const se = R.expand(s), some = someFnSub(fnSub);
  if (!takesRecord(se, t)) return false;
  // a record type may stand for a value with more members (width); only a literal's type and the intrinsics are closed
  const closed = !["object", "unknown", "tv"].includes(se.k) && (se.k !== "rec" || se.exact === true || [...se.props.values()].some((p) => p.flags?.intrinsic));
  // a closed record type holds only closed values: what is assigned to it must be one, with no other member
  if (t.exact === true && !(se.k === "rec" && se.exact === true && [...se.props.keys()].every((k) => t.props.has(k)))) return false;
  // x1 (2026-11-24, C): a function has its own name, length, call...: t may not declare one the source does not
  const fnLike = se.k === "fn" || (se.k === "rec" && (!!se.calls?.length || !!se.ctors?.length));
  for (const [k, p] of t.props) {
    const sp = R.member(se, k);
    if (!sp && fnLike && R.fnOwn?.(k) === true) return false;
    if (!sp) { if (p.opt && (closed || (se.k === "rec" && se.without?.includes(k) === true) || sub(UNKNOWN, propT(p), seen))) continue; return false; }
    if (sp.flags?.banned || (!p.opt && sp.opt)) return false;
    // a spread, rest or clone copies only own enumerable properties; a member from a prototype is not one
    if (!p.opt && !p.flags?.intrinsic && (se.k !== "rec" || sp.flags?.intrinsic)) return false;
    if (!sub(propT(sp), propT(p), seen)) return false;
  }
  const index = t.index;
  if (index) {
    if (se.k !== "rec" || !(closed || se.index !== undefined)) return false; // an open record may hold other members (holes step 10)
    for (const [, p] of se.props) if (p.flags?.banned || !sub(propT(p), index, seen)) return false;
    const sIndex = se.index;
    if (sIndex && !sub(sIndex, index, seen)) return false;
  }
  for (const c of t.calls ?? []) if (!some(callSigs(se), c, seen)) return false;
  return true;
  };
};

// a named type t: Iterable and ArrayLike by element, Mut and State invariant, Action contravariant, the rest covariant
export const namedSubWith = (UNKNOWN, inexact) => (R: RegOps, sub: Sub, iterElem: (t: Ty) => Ty | undefined) => (s: Ty, t: Named, seen: Mut<Set<string>>): boolean => {
  const t0 = R.at(t.args, 0);
  if (t.n === "Iterable" || t.n === "ArrayLike") {
    const e = iterElem(s);
    return !!e && (t.n === "Iterable" || s.k !== "named" || !["Map", "Set"].includes(s.n)) && sub(e, t0, seen);
  }
  if (s.k !== "named" || s.n !== t.n) return false;
  const s0 = R.at(s.args, 0);
  // a fresh Mut record is exact; the writable view it is passed as need not be
  if (t.n === "Mut") return sub(s0, t0, seen) && sub(t0, inexact(s0), seen);
  if (t.n === "State") return sub(s0, t0, seen) && sub(t0, s0, seen);
  if (t.n === "Action") return sub(t0, s0, seen);
  let i = 0;
  for (const a of t.args) if (!sub(s.args[i++] ?? UNKNOWN, a, seen)) return false;
  return true;
};

// s is or has as a member (aliases expanded) a Mut or Borrowed, which sub unwraps before it scans a union; a generic
// alias is not walked and counts as one that may
export const unwrapsWith = () => (R: RegOps) => (s: Ty): boolean => {
  const aliases: Mut<Set<string>> = new Set();
  function unwraps(x: Ty): boolean {
    if (x.k === "union") { for (const m of x.ts) if (unwraps(m)) return true; return false; }
    if (x.k !== "named") return false;
    if (!R.isAlias(x.n)) return x.n === "Mut" || x.n === "Borrowed";
    if (x.args.length) return true;
    if (aliases.has(x.n)) return false;
    aliases.add(x.n);
    return unwraps(R.expand(x));
  }
  return unwraps(s);
};

// s <: t found without the scan sub makes of a union: s is t, s is a member of t (t's alias expanded) by object or by
// alias without type arguments, or of such a member of t that is a union alias without type arguments, or arrays or a
// union of s made of such; a member that unwraps is left to sub, and so is a type sub takes without expanding. Only
// for a whole comparison (Registry.sub): within one, a pair the scan tried stays in seen and is taken as true when it is
// met again
export const memberOfWith = (unwrapsWith) => (R: RegOps) => (s: Ty, t: Ty): boolean => {
  const unwraps = unwrapsWith(R);
  const sameAlias = (a: Ty, b: Ty): boolean => a.k === "named" && b.k === "named" && a.n === b.n && !a.args.length && !b.args.length && R.isAlias(a.n);
  // perf2 (2026-11-27): x is a member of m, a union alias without type arguments (AstNode in AstNode | null)
  const inPlain = (x: Ty, m: Ty): boolean => {
    if (m.k !== "named" || m.args.length || !R.isAlias(m.n)) return false;
    const me = R.expand(m);
    return me.k === "union" && me.ts.some((n) => R.same(x, n) || sameAlias(x, n));
  };
  function sure(x: Ty, y: Ty): boolean {
    if (R.same(x, y)) return true;
    if (y.k === "unknown" || x.k === "err" || y.k === "err" || x.k === "never") return false;
    if (x.k === "arr" && y.k === "arr") return sure(x.el, y.el);
    if (x.k === "union") { for (const m of x.ts) if (!sure(m, y)) return false; return true; }
    const ye = y.k === "named" && R.isAlias(y.n) ? R.expand(y) : y;
    return ye.k === "union" && ye.ts.some((m) => R.same(x, m) || sameAlias(x, m) || inPlain(x, m)) && !unwraps(x);
  }
  return sure(s, t);
};

// Subtyping. Values are immutable: covariant everywhere except function parameters, Mut and State
export const subWith = (typeKey, isNamed, primSub, seqSubWith, fnSubWith, someFnSub, recSubWith, namedSubWith) => (R: RegOps, iterElem: (t: Ty) => Ty | undefined, callSigs: (t: Ty) => Fn[]) => {
  const seqSub = seqSubWith(R, sub), fnSub = fnSubWith(R, sub), some = someFnSub(fnSub);
  const recSub = recSubWith(R, sub, fnSub, callSigs), namedSub = namedSubWith(R, sub, iterElem);
  function sub(s: Ty, t: Ty, seen: Mut<Set<string>>): boolean {
    if (R.same(s, t) || t.k === "unknown" || s.k === "err" || t.k === "err" || s.k === "never") return true;
    if ((s.k === "named" && R.isAlias(s.n)) || (t.k === "named" && R.isAlias(t.n))) {
      const key = typeKey(s) + " <: " + typeKey(t);
      if (seen.has(key)) return true;
      seen.add(key);
      return sub(R.expand(s), R.expand(t), seen);
    }
    if (s.k === "union") { for (const m of s.ts) if (!sub(m, t, seen)) return false; return true; }
    if (s.k === "named" && (s.n === "Mut" || s.n === "Borrowed") && !isNamed(t, s.n)) return sub(R.at(s.args, 0), t, seen);
    if (t.k === "union") { for (const m of t.ts) if (sub(s, m, seen)) return true; return false; }
    if (s.k === "tv") return t.k === "tv" && t.n === s.n;
    switch (t.k) {
      case "arr": case "tup": return seqSub(s, t, seen);
      case "fn": return some(callSigs(s), t, seen);
      case "rec": return recSub(s, t, seen);
      case "named": return namedSub(s, t, seen);
      default: return primSub(s, t);
    }
  }
  return sub;
};

// p a union: each member of a takes the member of p of its shape, else a type parameter if p has exactly one
export const unifyUnionWith = (members, hasAnyTv) => (unify: Unify, sub: Sub) => (p: { k: "union"; ts: Ty[] }, a: Ty, m: Mut<Subst>, tvs: Set<string>, depth: number): void => {
  const tvM = p.ts.filter((x) => x.k === "tv" && tvs.has(x.n));
  const others = p.ts.filter((x) => !(x.k === "tv" && tvs.has(x.n)));
  const only = tvM.length === 1 ? tvM[0] : undefined;
  for (const x of members(a)) {
    const shape = others.find((q) => (q.k === x.k && (q.k !== "named" || (x.k === "named" && x.n === q.n))) || (q.k === "arr" && x.k === "tup"));
    if (shape && hasAnyTv(shape, tvs)) unify(shape, x, m, tvs, depth + 1);
    else if (others.some((q) => { const seen = new Set<string>(); return sub(x, q, seen); })) continue;
    else if (only) unify(only, x, m, tvs, depth + 1);
  }
};

// p a record type: each property of p takes a's property of that name, and p's index signature every property of a
export const unifyRecWith = (propT) => (R: RegOps, unify: Unify) => (p: Rec, a: Ty, m: Mut<Subst>, tvs: Set<string>, depth: number): void => {
  const U = (x: Ty, y: Ty) => unify(x, y, m, tvs, depth + 1);
  const ae = R.expand(a), index = p.index;
  for (const [k, q] of p.props) { const ap = R.member(ae, k); if (ap) U(q.t, ap.t); }
  if (index && ae.k === "rec") { for (const [, ap] of ae.props) U(index, propT(ap)); if (ae.index) U(index, ae.index); }
};

// p an array, tuple, function, record or named type: a takes the parts of p it has
export const unifyShapeWith = () => (R: RegOps, unify: Unify, unifyRec: (p: Rec, a: Ty, m: Mut<Subst>, tvs: Set<string>, depth: number) => void, iterElem: (t: Ty) => Ty | undefined, callSigs: (t: Ty) => Fn[]) => (p: Ty, a: Ty, m: Mut<Subst>, tvs: Set<string>, depth: number): void => {
  const U = (x: Ty, y: Ty) => unify(x, y, m, tvs, depth + 1);
  let i = 0;
  switch (p.k) {
    case "arr":
      if (a.k === "arr") U(p.el, a.el);
      else if (a.k === "tup") { for (const e of a.els) U(p.el, e); }
      else if (a.k === "named" && (a.n === "Iterable" || a.n === "ArrayLike")) U(p.el, R.at(a.args, 0));
      return;
    case "tup": if (a.k === "tup") for (const e of p.els) { const x = a.els[i++]; if (x) U(e, x); } return;
    case "fn": {
      const f = callSigs(a)[0];
      if (f) { for (const q of p.ps) { const x = f.ps[i++]; if (x) U(q.t, x.t); } U(p.ret, f.ret); }
      return;
    }
    case "rec": unifyRec(p, a, m, tvs, depth); return;
    case "named": {
      const e = p.n === "Iterable" || p.n === "ArrayLike" ? iterElem(a) : undefined;
      if (p.n === "Iterable" || p.n === "ArrayLike") { if (e) U(R.at(p.args, 0), e); }
      else if (a.k === "named" && a.n === p.n) for (const x of p.args) { const y = a.args[i++]; if (y) U(x, y); }
      return;
    }
    default: return;
  }
};

// Inference: the candidates for the type variables in tvs, found by matching parameter type p against argument type a
export const unifyWith = (union, isNamed, unifyUnionWith, unifyRecWith, unifyShapeWith) => (R: RegOps, sub: Sub, iterElem: (t: Ty) => Ty | undefined, callSigs: (t: Ty) => Fn[]) => {
  const byUnion = unifyUnionWith(unify, sub), byShape = unifyShapeWith(R, unify, unifyRecWith(R, unify), iterElem, callSigs);
  function unify(p: Ty, a: Ty, m: Mut<Subst>, tvs: Set<string>, depth: number): void {
    if (depth > 12 || a.k === "err") return;
    if (p.k === "tv") {
      const prev = m.get(p.n);
      if (tvs.has(p.n)) m.set(p.n, prev ? union([prev, a]) : a);
      return;
    }
    if (a.k === "named" && R.isAlias(a.n)) unify(p, R.expand(a), m, tvs, depth + 1);
    else if (p.k === "named" && R.isAlias(p.n)) unify(R.expand(p), a, m, tvs, depth + 1);
    else if (p.k === "union") byUnion(p, a, m, tvs, depth);
    else if (a.k === "union" && p.k !== "named") { for (const x of a.ts) unify(p, x, m, tvs, depth + 1); }
    else if (a.k === "named" && (a.n === "Mut" || a.n === "Borrowed") && !isNamed(p, a.n)) unify(p, R.at(a.args, 0), m, tvs, depth + 1);
    else byShape(p, a, m, tvs, depth);
  }
  return unify;
};

export const uncloneableWith = (UNCLONEABLE_NAMES) => (R: RegOps) => {
  function uncloneable(t: Ty, depth: number = 0): string | null {
    // holes8: deeper than 8, a type argument and an open type were let through; the page's island now clones as a
    // worker does, so these also fail at run time
    if (depth > 8) return "a type nested deeper than 8 levels";
    if (t.k === "named" && R.isAlias(t.n)) return uncloneable(R.expand(t), depth + 1);
    const first = (xs: Ty[]): string | null => { for (const x of xs) { const w = uncloneable(x, depth + 1); if (w) return w; } return null; };
    switch (t.k) {
      case "fn": return "a function";
      case "named": return UNCLONEABLE_NAMES.includes(t.n) ? t.n : first(t.args);
      case "unknown": case "object": case "tv": return "a value of an open type (unknown, object or a type parameter), which may be a function";
      case "arr": return uncloneable(t.el, depth + 1);
      case "tup": return first(t.els);
      case "union": return first(t.ts);
      case "rec": return t.calls?.length ? "a function" : first([...t.props.values()].map((p) => p.t));
      default: return null;
    }
  }
  return uncloneable;
};

// what structuredClone cannot copy in a value of type t: it throws on a function, a symbol or a host object, and a
// value of an open type (unknown, object, a type parameter) may be one (infer.ts, a structuredClone call)
export const CLONEABLE_NAMES = () => ["Error", "RegExp", "RegExpMatchArray", "ArrayBuffer", "DataView"];

export const cloneProblemWith = (show, CLONEABLE_NAMES) => (R: RegOps) => {
  function cloneProblem(t: Ty, depth: number = 0): string | null {
    if (depth > 10) return null;
    const first = (xs: Ty[]): string | null => { for (const x of xs) { const w = cloneProblem(x, depth + 1); if (w) return w; } return null; };
    switch (t.k) {
      case "fn": return "is or holds a function";
      case "symbol": return "is or holds a symbol";
      case "unknown": case "object": case "tv": return `may be or hold a function (its type is ${show(t)})`;
      case "arr": return cloneProblem(t.el, depth + 1);
      case "tup": return first(t.els);
      case "union": return first(t.ts);
      case "rec": return t.calls?.length ? "is or holds a function" : first([...[...t.props.values()].map((p) => p.t), ...(t.index ? [t.index] : [])]);
      case "named":
        if (R.isAlias(t.n)) return cloneProblem(R.expand(t), depth + 1);
        if (["Mut", "Borrowed", "Map", "Set"].includes(t.n)) return first(t.args);
        if (CLONEABLE_NAMES.includes(t.n) || R.isTypedArray(t)) return null;
        return `is or holds a ${t.n}`;
      default: return null;
    }
  }
  return cloneProblem;
};

// undefined is a value of t: t is undefined, void or unknown, or a union with one of them (aliases expanded)
export const admitsUndefinedWith = () => (R: RegOps) => {
  function admitsUndefined(t: Ty, depth: number = 0): boolean {
    return depth <= 12 && (t.k === "undef" || t.k === "void" || t.k === "unknown" ||
      (t.k === "named" && R.isAlias(t.n) && admitsUndefined(R.expand(t), depth + 1)) || (t.k === "union" && t.ts.some((x) => admitsUndefined(x, depth + 1))));
  }
  return admitsUndefined;
};

// the types t is made of: elements, members, properties, signatures' parameters and results
export const partsOf = () => (t: Ty): Ty[] => {
  switch (t.k) {
    case "arr": return [t.el];
    case "tup": return t.els;
    case "union": return t.ts;
    case "rec": return [...[...t.props.values()].map((p) => p.t), ...(t.calls ?? []).flatMap((f) => [...f.ps.map((p) => p.t), f.ret]), ...(t.index ? [t.index] : [])];
    case "fn": return [...t.ps.map((p) => p.t), t.ret];
    default: return [];
  }
};

// the first of names that t mentions anywhere (aliases expanded), or null
export const holdsWith = (partsOf) => (R: RegOps) => (t: Ty, names: string[]): string | null => {
  // per alias without type arguments, the least depth its walk found nothing from; from as deep it finds nothing again
  const none: Mut<Map<string, number>> = new Map();
  function holds(x: Ty, depth: number): string | null {
    if (depth > 12) return null;
    if (x.k === "named" && names.includes(x.n)) return x.n;
    if (x.k === "named" && R.isAlias(x.n)) {
      const plain = x.args.length === 0, at = none.get(x.n);
      if (plain && at !== undefined && at <= depth) return null;
      const w = holds(R.expand(x), depth + 1);
      if (!w && plain) none.set(x.n, depth);
      return w;
    }
    for (const k of x.k === "named" ? x.args : partsOf(x)) { const w = holds(k, depth + 1); if (w) return w; }
    return null;
  }
  return holds(t, 0);
};

// t holds err, or an alias the checker could not convert: such a parameter type was reported where it is written
export const hasErrWith = () => (R: RegOps) => {
  function hasErr(t: Ty, depth: number = 0): boolean {
    if (depth > 8) return false;
    const any = (xs: Ty[]): boolean => xs.some((x) => hasErr(x, depth + 1));
    switch (t.k) {
      case "err": return true;
      case "arr": return hasErr(t.el, depth + 1);
      case "tup": return any(t.els);
      case "union": return any(t.ts);
      case "named": return any(t.args) || R.expand(t).k === "err";
      case "fn": return any(t.ps.map((p) => p.t)) || hasErr(t.ret, depth + 1);
      case "rec": return any([...t.props.values()].map((p) => p.t));
      default: return false;
    }
  }
  return hasErr;
};

// names the call lists that are not cells, and outputs it also lists as inputs or refs
export const specProblems = () => (names: Set<string>, spec: IslandSpec): IslandProblem[] => {
  const cut = new Set([...spec.inputs, ...spec.refs]);
  return [
    ...[...spec.inputs, ...spec.refs, ...spec.outputs].filter((n) => !names.has(n)).map((n) => ({ name: n, msg: `no cell ${n}` })),
    ...spec.outputs.filter((n) => cut.has(n)).map((n) => ({ name: n, msg: `${n} is both an output and an input or ref` })),
  ];
};

// capabilities: the names of the capabilities, which an island cell may not take
export const islandWith = (specProblems) => (capabilities: Set<string>) => (cells: IslandCell[], spec: IslandSpec): Island => {
  const by = new Map(cells.map((c): [string, IslandCell] => [c.name, c]));
  const cut = new Set([...spec.inputs, ...spec.refs]);
  const problems: Mut<IslandProblem[]> = [...specProblems(new Set(by.keys()), spec)];
  const order: Mut<string[]> = [];
  const seen = new Set<string>();
  function visit(n: string, from: string): void {
    if (cut.has(n) || seen.has(n)) return;
    seen.add(n);
    const c = by.get(n);
    if (!c) {
      problems.push({ name: from, msg: capabilities.has(n) ? `island cell ${from} takes the capability ${n}` : `island cell ${from} takes ${n}, which is not a cell` });
      return;
    }
    if (c.refCell) problems.push({ name: n, msg: `${n} is a state cell; list it in refs` });
    for (const p of c.params) visit(p, n);
    order.push(n);
  }
  for (const o of spec.outputs) if (by.has(o) && !cut.has(o)) visit(o, o);
  return { order: order, problems: problems };
};

// e1 (2026-11-23): the names the compiler writes into a compiled cell. Each runtime cell and capability is an input
// ss_<name> (tc-text.ss.ts tcInputsIn), a closure registration calls ss_closure or ss_methods with a list whose
// parameter is ss_i (tc-reg.ss.ts, fnreg.ts), and a duplicate or a type is a variable $ss$… (tcVariableName)
export const emittedName = () => (name: string): boolean => name.startsWith("ss_") || name.startsWith("$ss$");

export const RESERVED_MSG = (viewofInputName, emittedName) => (name: string): string => viewofInputName(name)
  ? `${name} is reserved: Observable JavaScript names a cell's viewof inputs $0, $1, …`
  : emittedName(name)
  ? `${name} is reserved: the compiler names what it inserts into a compiled cell ss_… and $ss$…, so a name with either prefix would replace it; rename it`
  : `${name} is reserved: Observable JavaScript reads it as a keyword`;

// a cell may not be named like an input the compiled cells take from the module's scope: a state cell's value takes
// Generators, an events or listener cell takes invalidation (a parameter named invalidation is the capability)
export const reservedCellName = (reservedName) => (name: string): boolean => reservedName(name) || name === "Generators" || name === "invalidation";

export const RESERVED_CELL_MSG = (reservedName, RESERVED_MSG) => (name: string): string => reservedName(name)
  ? RESERVED_MSG(name)
  : `${name} is reserved as a cell name: compiled cells take ${name} from the module, and a cell of that name would replace it`;

// a9 (2026-11-23): the compiler refuses a cell whose text holds its insertion mark or its language mark (tc-build.ss.ts
// tcCompileChecked), so the checker refuses it first; the marks are written split, as there
export const reservedText = () => (text: string): string | null => ["/*" + "ss", "/*" + '{lang:"ss"}*/'].find((m) => text.includes(m)) ?? null;

// e1 (2026-11-23), B5: a syntax ban's message is the node kind, but for x!, which ergonomics1 21 met as the word
// TSNonNullExpression: it names what the checker accepts in its place
export const banMessage = () => (rule: string, kind: string): string => rule === "no-non-null"
  ? "x! (a non-null assertion) is not checked; narrow the value instead: x ?? fallback, if (x === undefined) return …, or a for…of loop over an array in place of an index"
  : kind;

// a node whose type is not above, or that has a field its record does not declare: its acorn type in kind, its
// child fields and its other fields as lists
export type Other = { type: "Other"; nid: number; start: number; end: number; line: number; kind: string; fields: OtherField[]; props: OtherProp[] };

export const kidsGroup1 = (kidOne, kidMany) => (n: AstNode): AstKid[] | null => {
  switch (n.type) {
    case "ArrayExpression": return [...kidMany("elements", n.elements)];
    case "ArrayPattern": return [...kidMany("elements", n.elements), ...kidOne("typeAnnotation", n.typeAnnotation)];
    case "ArrowFunctionExpression": return [...kidOne("returnType", n.returnType), ...kidOne("id", n.id), ...kidMany("params", n.params), { key: "body", node: n.body }, ...kidOne("typeParameters", n.typeParameters)];
    case "AssignmentExpression": return [{ key: "left", node: n.left }, { key: "right", node: n.right }];
    case "AssignmentPattern": return [{ key: "left", node: n.left }, { key: "right", node: n.right }];
    case "AwaitExpression": return [{ key: "argument", node: n.argument }];
    case "BinaryExpression": return [{ key: "left", node: n.left }, { key: "right", node: n.right }];
    case "BlockStatement": return [...kidMany("body", n.body)];
    case "BreakStatement": return [...kidOne("label", n.label)];
    case "CallExpression": return [{ key: "callee", node: n.callee }, ...kidMany("arguments", n.arguments), ...kidOne("typeArguments", n.typeArguments)];
    case "CatchClause": return [...kidOne("param", n.param), { key: "body", node: n.body }];
    case "ChainExpression": return [{ key: "expression", node: n.expression }];
    case "ClassBody": return [...kidMany("body", n.body)];
    case "ClassDeclaration": return [...kidMany("decorators", n.decorators), { key: "id", node: n.id }, ...kidOne("superClass", n.superClass), ...kidMany("implements", n.implements), { key: "body", node: n.body }];
    case "ClassExpression": return [...kidOne("id", n.id), ...kidOne("superClass", n.superClass), { key: "body", node: n.body }];
    case "ConditionalExpression": return [{ key: "test", node: n.test }, { key: "consequent", node: n.consequent }, { key: "alternate", node: n.alternate }];
    case "ContinueStatement": return [...kidOne("label", n.label)];
    case "Decorator": return [{ key: "expression", node: n.expression }];
    case "DoWhileStatement": return [{ key: "body", node: n.body }, { key: "test", node: n.test }];
    case "ExportAllDeclaration": return [...kidOne("exported", n.exported), { key: "source", node: n.source }, ...kidMany("attributes", n.attributes)];
    case "ExportDefaultDeclaration": return [{ key: "declaration", node: n.declaration }];
    default: return null;
  }
};

export const kidsGroup2 = (kidOne, kidMany) => (n: AstNode): AstKid[] | null => {
  switch (n.type) {
    case "ExportNamedDeclaration": return [...kidOne("declaration", n.declaration), ...kidMany("specifiers", n.specifiers), ...kidOne("source", n.source), ...kidMany("attributes", n.attributes)];
    case "ExportSpecifier": return [{ key: "local", node: n.local }, { key: "exported", node: n.exported }];
    case "ExpressionStatement": return [{ key: "expression", node: n.expression }];
    case "ForInStatement": return [{ key: "left", node: n.left }, { key: "right", node: n.right }, { key: "body", node: n.body }];
    case "ForOfStatement": return [{ key: "left", node: n.left }, { key: "right", node: n.right }, { key: "body", node: n.body }];
    case "ForStatement": return [...kidOne("init", n.init), ...kidOne("test", n.test), ...kidOne("update", n.update), { key: "body", node: n.body }];
    case "FunctionDeclaration": return [{ key: "id", node: n.id }, ...kidOne("typeParameters", n.typeParameters), ...kidMany("params", n.params), ...kidOne("returnType", n.returnType), { key: "body", node: n.body }];
    case "FunctionExpression": return [...kidOne("id", n.id), ...kidOne("typeParameters", n.typeParameters), ...kidMany("params", n.params), ...kidOne("returnType", n.returnType), { key: "body", node: n.body }];
    case "Identifier": return [...kidOne("typeAnnotation", n.typeAnnotation)];
    case "IfStatement": return [{ key: "test", node: n.test }, { key: "consequent", node: n.consequent }, ...kidOne("alternate", n.alternate)];
    case "ImportAttribute": return [{ key: "key", node: n.key }, { key: "value", node: n.value }];
    case "ImportDeclaration": return [...kidMany("specifiers", n.specifiers), { key: "source", node: n.source }, ...kidMany("attributes", n.attributes)];
    case "ImportDefaultSpecifier": return [{ key: "local", node: n.local }];
    case "ImportExpression": return [{ key: "source", node: n.source }, ...kidOne("options", n.options)];
    case "ImportNamespaceSpecifier": return [{ key: "local", node: n.local }];
    case "ImportSpecifier": return [{ key: "imported", node: n.imported }, { key: "local", node: n.local }];
    case "JSXAttribute": return [{ key: "name", node: n.name }, ...kidOne("value", n.value)];
    case "JSXClosingElement": return [{ key: "name", node: n.name }];
    case "JSXElement": return [{ key: "openingElement", node: n.openingElement }, ...kidOne("closingElement", n.closingElement), ...kidMany("children", n.children)];
    case "JSXExpressionContainer": return [{ key: "expression", node: n.expression }];
    case "JSXFragment": return [{ key: "openingFragment", node: n.openingFragment }, { key: "closingFragment", node: n.closingFragment }, ...kidMany("children", n.children)];
    default: return null;
  }
};

export const kidsGroup3 = (kidOne, kidMany) => (n: AstNode): AstKid[] | null => {
  switch (n.type) {
    case "JSXMemberExpression": return [{ key: "object", node: n.object }, { key: "property", node: n.property }];
    case "JSXNamespacedName": return [{ key: "namespace", node: n.namespace }, { key: "name", node: n.name }];
    case "JSXOpeningElement": return [{ key: "name", node: n.name }, ...kidMany("attributes", n.attributes)];
    case "JSXOpeningFragment": return [...kidMany("attributes", n.attributes)];
    case "JSXSpreadAttribute": return [{ key: "argument", node: n.argument }];
    case "JSXSpreadChild": return [{ key: "expression", node: n.expression }];
    case "LabeledStatement": return [{ key: "body", node: n.body }, { key: "label", node: n.label }];
    case "LogicalExpression": return [{ key: "left", node: n.left }, { key: "right", node: n.right }];
    case "MemberExpression": return [{ key: "object", node: n.object }, { key: "property", node: n.property }];
    case "MetaProperty": return [{ key: "meta", node: n.meta }, { key: "property", node: n.property }];
    case "MethodDefinition": return [{ key: "key", node: n.key }, ...kidOne("typeParameters", n.typeParameters), { key: "value", node: n.value }, ...kidMany("decorators", n.decorators)];
    case "NewExpression": return [{ key: "callee", node: n.callee }, ...kidOne("typeArguments", n.typeArguments), ...kidMany("arguments", n.arguments)];
    case "ObjectExpression": return [...kidMany("properties", n.properties)];
    case "ObjectPattern": return [...kidMany("properties", n.properties), ...kidOne("typeAnnotation", n.typeAnnotation)];
    case "ParenthesizedExpression": return [...kidOne("expression", n.expression)];
    case "Program": return [...kidMany("body", n.body)];
    case "Property": return [{ key: "key", node: n.key }, { key: "value", node: n.value }];
    case "PropertyDefinition": return [{ key: "key", node: n.key }, ...kidOne("typeAnnotation", n.typeAnnotation), ...kidOne("value", n.value)];
    case "RestElement": return [{ key: "argument", node: n.argument }, ...kidOne("typeAnnotation", n.typeAnnotation)];
    case "ReturnStatement": return [...kidOne("argument", n.argument)];
    case "SequenceExpression": return [...kidMany("expressions", n.expressions)];
    default: return null;
  }
};

export const kidsGroup4 = (kidOne, kidMany) => (n: AstNode): AstKid[] | null => {
  switch (n.type) {
    case "SpreadElement": return [{ key: "argument", node: n.argument }];
    case "StaticBlock": return [...kidMany("body", n.body)];
    case "SwitchCase": return [...kidMany("consequent", n.consequent), ...kidOne("test", n.test)];
    case "SwitchStatement": return [{ key: "discriminant", node: n.discriminant }, ...kidMany("cases", n.cases)];
    case "TSArrayType": return [{ key: "elementType", node: n.elementType }];
    case "TSAsExpression": return [{ key: "expression", node: n.expression }, { key: "typeAnnotation", node: n.typeAnnotation }];
    case "TSCallSignatureDeclaration": return [...kidOne("typeParameters", n.typeParameters), ...kidMany("parameters", n.parameters), { key: "typeAnnotation", node: n.typeAnnotation }];
    case "TSConditionalType": return [{ key: "checkType", node: n.checkType }, { key: "extendsType", node: n.extendsType }, { key: "trueType", node: n.trueType }, { key: "falseType", node: n.falseType }];
    case "TSConstructSignatureDeclaration": return [...kidOne("typeParameters", n.typeParameters), ...kidMany("parameters", n.parameters), { key: "typeAnnotation", node: n.typeAnnotation }];
    case "TSConstructorType": return [...kidOne("typeParameters", n.typeParameters), ...kidMany("parameters", n.parameters), { key: "typeAnnotation", node: n.typeAnnotation }];
    case "TSDeclareFunction": return [{ key: "id", node: n.id }, ...kidOne("typeParameters", n.typeParameters), ...kidMany("params", n.params), ...kidOne("returnType", n.returnType)];
    case "TSDeclareMethod": return [...kidOne("id", n.id), ...kidMany("params", n.params), { key: "returnType", node: n.returnType }];
    case "TSEnumDeclaration": return [{ key: "id", node: n.id }, ...kidMany("members", n.members)];
    case "TSEnumMember": return [{ key: "id", node: n.id }, ...kidOne("initializer", n.initializer)];
    case "TSExportAssignment": return [{ key: "expression", node: n.expression }];
    case "TSExpressionWithTypeArguments": return [{ key: "expression", node: n.expression }, ...kidOne("typeParameters", n.typeParameters)];
    case "TSExternalModuleReference": return [{ key: "expression", node: n.expression }];
    case "TSFunctionType": return [...kidOne("typeParameters", n.typeParameters), ...kidMany("parameters", n.parameters), { key: "typeAnnotation", node: n.typeAnnotation }];
    case "TSImportEqualsDeclaration": return [{ key: "id", node: n.id }, { key: "moduleReference", node: n.moduleReference }];
    case "TSImportType": return [{ key: "argument", node: n.argument }, ...kidOne("qualifier", n.qualifier), ...kidOne("typeArguments", n.typeArguments)];
    case "TSIndexSignature": return [...kidMany("parameters", n.parameters), { key: "typeAnnotation", node: n.typeAnnotation }];
    default: return null;
  }
};

export const kidsGroup5 = (kidOne, kidMany) => (n: AstNode): AstKid[] | null => {
  switch (n.type) {
    case "TSIndexedAccessType": return [{ key: "objectType", node: n.objectType }, { key: "indexType", node: n.indexType }];
    case "TSInferType": return [{ key: "typeParameter", node: n.typeParameter }];
    case "TSInstantiationExpression": return [{ key: "expression", node: n.expression }, { key: "typeArguments", node: n.typeArguments }];
    case "TSInterfaceBody": return [...kidMany("body", n.body)];
    case "TSInterfaceDeclaration": return [{ key: "id", node: n.id }, ...kidOne("typeParameters", n.typeParameters), ...kidMany("extends", n.extends), { key: "body", node: n.body }];
    case "TSIntersectionType": return [...kidMany("types", n.types)];
    case "TSLiteralType": return [{ key: "literal", node: n.literal }];
    case "TSMappedType": return [{ key: "typeParameter", node: n.typeParameter }, ...kidOne("nameType", n.nameType), { key: "typeAnnotation", node: n.typeAnnotation }];
    case "TSMethodSignature": return [{ key: "key", node: n.key }, ...kidOne("typeParameters", n.typeParameters), ...kidMany("parameters", n.parameters), ...kidOne("typeAnnotation", n.typeAnnotation)];
    case "TSModuleBlock": return [...kidMany("body", n.body)];
    case "TSModuleDeclaration": return [{ key: "id", node: n.id }, { key: "body", node: n.body }];
    case "TSNamedTupleMember": return [{ key: "label", node: n.label }, { key: "elementType", node: n.elementType }];
    case "TSNamespaceExportDeclaration": return [{ key: "id", node: n.id }];
    case "TSNonNullExpression": return [{ key: "expression", node: n.expression }];
    case "TSOptionalType": return [{ key: "typeAnnotation", node: n.typeAnnotation }];
    case "TSParameterProperty": return [{ key: "parameter", node: n.parameter }];
    case "TSParenthesizedType": return [{ key: "typeAnnotation", node: n.typeAnnotation }];
    case "TSPropertySignature": return [{ key: "key", node: n.key }, ...kidOne("typeAnnotation", n.typeAnnotation)];
    case "TSQualifiedName": return [{ key: "left", node: n.left }, { key: "right", node: n.right }];
    case "TSRestType": return [{ key: "typeAnnotation", node: n.typeAnnotation }];
    case "TSSatisfiesExpression": return [{ key: "expression", node: n.expression }, { key: "typeAnnotation", node: n.typeAnnotation }];
    default: return null;
  }
};

export const kidsGroup6 = (kidOne, kidMany) => (n: AstNode): AstKid[] | null => {
  switch (n.type) {
    case "TSTupleType": return [...kidMany("elementTypes", n.elementTypes)];
    case "TSTypeAliasDeclaration": return [{ key: "id", node: n.id }, ...kidOne("typeParameters", n.typeParameters), { key: "typeAnnotation", node: n.typeAnnotation }];
    case "TSTypeAnnotation": return [{ key: "typeAnnotation", node: n.typeAnnotation }];
    case "TSTypeAssertion": return [{ key: "typeAnnotation", node: n.typeAnnotation }, { key: "expression", node: n.expression }];
    case "TSTypeLiteral": return [...kidMany("members", n.members)];
    case "TSTypeOperator": return [{ key: "typeAnnotation", node: n.typeAnnotation }];
    case "TSTypeParameter": return [...kidOne("constraint", n.constraint), ...kidOne("default", n.default)];
    case "TSTypeParameterDeclaration": return [...kidMany("params", n.params)];
    case "TSTypeParameterInstantiation": return [...kidMany("params", n.params)];
    case "TSTypePredicate": return [{ key: "parameterName", node: n.parameterName }, ...kidOne("typeAnnotation", n.typeAnnotation)];
    case "TSTypeQuery": return [{ key: "exprName", node: n.exprName }];
    case "TSTypeReference": return [{ key: "typeName", node: n.typeName }, ...kidOne("typeArguments", n.typeArguments)];
    case "TSUnionType": return [...kidMany("types", n.types)];
    case "TaggedTemplateExpression": return [{ key: "tag", node: n.tag }, { key: "quasi", node: n.quasi }];
    case "TemplateLiteral": return [...kidMany("expressions", n.expressions), ...kidMany("quasis", n.quasis)];
    case "ThrowStatement": return [{ key: "argument", node: n.argument }];
    case "TryStatement": return [{ key: "block", node: n.block }, ...kidOne("handler", n.handler), ...kidOne("finalizer", n.finalizer)];
    case "UnaryExpression": return [{ key: "argument", node: n.argument }];
    case "UpdateExpression": return [{ key: "argument", node: n.argument }];
    case "VariableDeclaration": return [...kidMany("declarations", n.declarations)];
    case "VariableDeclarator": return [{ key: "id", node: n.id }, ...kidOne("init", n.init)];
    default: return null;
  }
};

export const kidsGroup7 = (kidOne, kidMany) => (n: AstNode): AstKid[] | null => {
  switch (n.type) {
    case "WhileStatement": return [{ key: "test", node: n.test }, { key: "body", node: n.body }];
    case "WithStatement": return [...kidOne("object", n.object), ...kidOne("body", n.body)];
    case "YieldExpression": return [{ key: "argument", node: n.argument }];
    default: return null;
  }
};

// the position each line starts at
export const lineStarts = () => (src: string): number[] => {
  const out: Mut<number[]> = [0];
  for (let i = 0; i < src.length; i++) if (src.charCodeAt(i) === 10) out.push(i + 1);
  return out;
};

// the line (from 1) of position pos, given the line starts
export const lineIn = () => (starts: number[], pos: number): number => {
  let lo = 0, hi = starts.length - 1;
  while (lo < hi) {
    const m = (lo + hi + 1) >> 1;
    if ((starts[m] ?? 0) <= pos) lo = m; else hi = m - 1;
  }
  return lo + 1;
};

// parse.ts line: the line of a position in src
export const lineAt = (lineStarts, lineIn) => (src: string): ((pos: number) => number) => {
  const starts = lineStarts(src);
  return (pos: number) => lineIn(starts, pos);
};

// parse.ts leading: the comments separated from start (and from each other) only by whitespace
export const leadingComments = () => (ast: Ast, start: number): AstComment[] => {
  const out: Mut<AstComment[]> = [];
  let at = start;
  for (let i = ast.comments.length - 1; i >= 0; i--) {
    const c = ast.comments[i];
    if (!c || c.end > at) continue;
    if (ast.src.slice(c.end, at).trim() !== "") break;
    out.unshift(c);
    at = c.start;
  }
  return out;
};

// parse.ts isFn
export const isFnNode = () => (n: AstNode | null): boolean =>
  n !== null && (n.type === "ArrowFunctionExpression" || n.type === "FunctionExpression" || n.type === "FunctionDeclaration");

// parse.ts kids: the children outside type positions, in source order
export const kidsOf = (childrenOf, TYPE_FIELDS) => (n: AstNode): AstNode[] =>
  childrenOf(n).filter((k) => !TYPE_FIELDS.has(k.key)).map((k) => k.node).toSorted((a, b) => a.start - b.start);

// every node of the tree, at its nid
export const byNid = (childrenOf) => (ast: Ast): (AstNode | null)[] => {
  const out: Mut<(AstNode | null)[]> = Array.from({ length: ast.count }, () => null);
  const todo: Mut<AstNode[]> = [ast.program];
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    out[n.nid] = n;
    for (const k of childrenOf(n)) todo.push(k.node);
  }
  return out;
};

// the nid of each node's parent, at its nid (-1 for the program); a tree cannot hold its parent, as a value that
// contains itself does not cross
export const parentNids = (childrenOf) => (ast: Ast): number[] => {
  const out: Mut<number[]> = Array.from({ length: ast.count }, () => -1);
  const todo: Mut<AstNode[]> = [ast.program];
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    for (const k of childrenOf(n)) { out[k.node.nid] = n.nid; todo.push(k.node); }
  }
  return out;
};

// the nids are a pre-order numbering: every nid below count occurs once, and each node's subtree holds exactly the nids
// from its own to its own + its size - 1. The boundary checks the shape, not this
export const preorder = (childrenOf) => (ast: Ast): boolean => {
  const seen: Mut<boolean[]> = Array.from({ length: ast.count }, () => false);
  // the size of n's subtree when it holds the nids n.nid .. n.nid + size - 1, each once; -1 when it does not
  const size = (n: AstNode): number => {
    if (n.nid < 0 || n.nid >= ast.count || seen[n.nid]) return -1;
    seen[n.nid] = true;
    let s = 1, hi = n.nid;
    for (const k of childrenOf(n)) {
      const c = k.node.nid > n.nid ? size(k.node) : -1;
      if (c < 0) return -1;
      s += c;
      hi = Math.max(hi, k.node.nid + c - 1);
    }
    return hi === n.nid + s - 1 ? s : -1;
  };
  return size(ast.program) === ast.count;
};

// a type or interface with a built-in type's name (it is not loaded: the cells read the built-in)
export const typeClash = (declOf) => (st: AstNode, builtin: Set<string>): ModErr[] => {
  const d = declOf(st);
  if (d.type !== "TSTypeAliasDeclaration" && d.type !== "TSInterfaceDeclaration") return [];
  const id = d.id;
  if (id.type !== "Identifier" || !builtin.has(id.name)) return [];
  return [{ at: d, rule: "builtin-type-name", msg: `${id.name} is a built-in type; give this ${d.type === "TSInterfaceDeclaration" ? "interface" : "type"} another name` }];
};

// e1 (2026-11-23), B5: the alias names a type node is with nothing structural between (names, unions, intersections,
// parentheses, Mut and Borrowed, and a generic alias that gives back an argument); args: a type parameter's names; path: aliases unfolded
export const aliasHeads = () => {
  function aliasHeads(decls: Map<string, AstNode>, n: AstNode, args: Map<string, string[]>, path: Set<string>): string[] {
    if (n.type === "TSParenthesizedType") return aliasHeads(decls, n.typeAnnotation, args, path);
    if (n.type === "TSUnionType" || n.type === "TSIntersectionType") return n.types.flatMap((x) => aliasHeads(decls, x, args, path));
    if (n.type !== "TSTypeReference" || n.typeName.type !== "Identifier") return [];
    const name = n.typeName.name, given = args.get(name), d = decls.get(name), ta = n.typeArguments;
    if (given !== undefined) return given;
    // Mut<T> and Borrowed<T> are T to the registry, so they are no structure either
    const inner = ta !== null && ta.type === "TSTypeParameterInstantiation" ? ta.params[0] : undefined;
    if ((name === "Mut" || name === "Borrowed") && inner !== undefined) return aliasHeads(decls, inner, args, path);
    if (d === undefined || d.type !== "TSTypeAliasDeclaration" || d.typeParameters === null || d.typeParameters.type !== "TSTypeParameterDeclaration" || ta === null || ta.type !== "TSTypeParameterInstantiation" || path.has(name)) return [name];
    const m: Mut<Map<string, string[]>> = new Map();
    d.typeParameters.params.forEach((p, i) => { const a = ta.params[i]; if (p.type === "TSTypeParameter") m.set(p.name, a === undefined ? [] : aliasHeads(decls, a, args, path)); });
    return [name, ...aliasHeads(decls, d.typeAnnotation, m, new Set([...path, name]))];
  }
  return aliasHeads;
};

// a type alias that reaches itself through its heads alone has no object, array, tuple or function type to stop at
// (TypeScript's TS2456); expanding one did not return (ergonomics1 28). Each alias is visited once per search.
export const typeCycles = (declOf, aliasHeads) => (prog: AstNode): ModErr[] => {
  if (prog.type !== "Program") return [];
  const decls: Mut<Map<string, AstNode>> = new Map();
  for (const st of prog.body) { const d = declOf(st); if (d.type === "TSTypeAliasDeclaration" && d.id.type === "Identifier") decls.set(d.id.name, d); }
  const out: Mut<ModErr[]> = [];
  for (const [name, d] of decls) {
    if (d.type !== "TSTypeAliasDeclaration") continue;
    const seen: Mut<Set<string>> = new Set(), todo = [...aliasHeads(decls, d.typeAnnotation, new Map(), new Set([name]))];
    for (let x = todo.pop(); x !== undefined; x = todo.pop()) {
      if (x === name) { out.push({ at: d, rule: "type-cycle", msg: `type ${name} is defined by itself, with no object, array, tuple or function type between (as in type ${name} = ${name}); write out the type it stands for` }); break; }
      const e = decls.get(x);
      if (seen.has(x) || e === undefined || e.type !== "TSTypeAliasDeclaration") continue;
      seen.add(x);
      const ps = e.typeParameters !== null && e.typeParameters.type === "TSTypeParameterDeclaration" ? e.typeParameters.params : [];
      todo.push(...aliasHeads(decls, e.typeAnnotation, new Map(ps.flatMap((p): [string, string[]][] => (p.type === "TSTypeParameter" ? [[p.name, []]] : []))), new Set([x])));
    }
  }
  return out;
};

// Registry.load(typesOnly): a type or interface, exported or not, is not a statement the cell loop sees
export const isTypeStatement = (declOf) => (st: AstNode): boolean => {
  const d = declOf(st);
  return d.type === "TSTypeAliasDeclaration" || d.type === "TSInterfaceDeclaration";
};

// a const or let declarator: a cell when it binds a name to a function
export const declaratorCell = () => (x: AstNode, st: AstNode): Found => {
  if (x.type !== "VariableDeclarator") return { cells: [], errors: [] };
  const id = x.id, init = x.init;
  if (id.type === "Identifier" && init !== null && (init.type === "ArrowFunctionExpression" || init.type === "FunctionExpression")) return { cells: [{ name: id.name, fn: init, stmt: st }], errors: [] };
  return { cells: [], errors: [{ at: x, rule: "cell-not-function", msg: `${id.type === "Identifier" ? id.name : "?"} is not a function` }] };
};

// the rule for a statement that is not a cell
export const moduleLevelRule = () => (d: AstNode, st: AstNode): string | null => {
  if (st.type === "ImportDeclaration" && st.importKind === "type") return null;
  if (d.type === "TSEnumDeclaration") return "no-enum";
  if (d.type === "TSModuleDeclaration") return "no-namespace";
  if (d.type === "ClassDeclaration") return "no-class";
  return d.type === "VariableDeclaration" && d.kind === "var" ? "no-var" : "module-level";
};

// one statement the cell loop sees: its cells, or why it is not one
export const statementCells = (declOf, declaratorCell, moduleLevelRule, nodeKind) => (st: AstNode): Found => {
  const d = declOf(st);
  if (d.type === "FunctionDeclaration") {
    const id = d.id;
    return { cells: id.type === "Identifier" ? [{ name: id.name, fn: d, stmt: st }] : [], errors: [] };
  }
  if (d.type === "VariableDeclaration" && d.kind !== "var" && d.declare !== true) {
    const found = d.declarations.map((x) => declaratorCell(x, st));
    return { cells: found.flatMap((f) => f.cells), errors: found.flatMap((f) => f.errors) };
  }
  const rule = moduleLevelRule(d, st);
  return { cells: [], errors: rule === null ? [] : [{ at: st, rule, msg: `${nodeKind(d)} at module level` }] };
};

// the cells of a module and its module-level errors, in the order checkSources reports them
export const moduleShape = (typeClash, typeCycles, isTypeStatement, statementCells) => (prog: AstNode, builtin: Set<string>, shellNames: Set<string>): ModuleShape => {
  if (prog.type !== "Program") return { cells: [], clashes: [], errors: [] };
  const found = prog.body.filter((st) => !isTypeStatement(st)).map((st) => statementCells(st));
  const cells = found.flatMap((f) => f.cells);
  const dups: Mut<ModErr[]> = [];
  const seen: Mut<Set<string>> = new Set();
  for (const c of cells) {
    if (seen.has(c.name) || shellNames.has(c.name)) dups.push({ at: c.stmt, rule: "duplicate-cell", msg: `cell ${c.name} defined twice` });
    seen.add(c.name);
  }
  // a type cycle is a clash too: the alias is not loaded (e1)
  return { cells, clashes: [...prog.body.flatMap((st) => typeClash(st, builtin)), ...typeCycles(prog)], errors: [...found.flatMap((f) => f.errors), ...dups] };
};

export const SYNTAX_BANS = () => new Map<string, string>([["ThisExpression", "no-this"], ["ClassDeclaration", "no-class"], ["ClassExpression", "no-class"],
  ["TSAnyKeyword", "no-any"], ["TSNonNullExpression", "no-non-null"], ["ImportExpression", "no-dynamic-import"], ["TSEnumDeclaration", "no-enum"],
  ["TSModuleDeclaration", "no-namespace"], ["TSTypeAssertion", "no-cast"]]);

// x is a member's property or an object literal's key, not computed
export const namedByParent = () => (x: AstNode, p: AstNode | null): boolean => {
  if (p !== null && p.type === "MemberExpression") return !p.computed && p.property.nid === x.nid;
  return p !== null && p.type === "Property" && !p.computed && p.key.nid === x.nid && p.value.nid !== x.nid;
};

// `arguments` is allowed as a member's name or an object literal's key (computed or not)
export const argumentsAsName = () => (x: AstNode, p: AstNode | null): boolean => {
  if (p !== null && p.type === "MemberExpression") return p.property.nid === x.nid && !p.computed;
  return p !== null && p.type === "Property" && p.key.nid === x.nid;
};

// `as const` is not a cast
export const isAsConst = () => (x: TSAsExpression): boolean => {
  const t = x.typeAnnotation;
  const n = t.type === "TSTypeReference" ? t.typeName : null;
  return n !== null && n.type === "Identifier" && n.name === "const";
};

// what the walk reports at one node, in core.ts's order
export const bansAt = (SYNTAX_BANS, reservedName, RESERVED_MSG, viewofInputName, namedByParent, argumentsAsName, isAsConst, nodeKind, banMessage) => (x: AstNode, p: AstNode | null, inType: boolean): SyntaxDiag[] => {
  const r = SYNTAX_BANS.get(nodeKind(x));
  const reserved = x.type === "Identifier" && !inType && reservedName(x.name) && !(namedByParent(x, p) && !viewofInputName(x.name));
  return [
    ...(reserved && x.type === "Identifier" ? [{ at: x, rule: "reserved-name", msg: RESERVED_MSG(x.name), unsup: false }] : []),
    ...(r !== undefined ? [{ at: x, rule: r, msg: banMessage(r, nodeKind(x)), unsup: false }] : []),
    ...(x.type === "TSAsExpression" && !isAsConst(x) ? [{ at: x, rule: "no-cast", msg: "as cast", unsup: false }] : []),
    ...(x.type === "TSSatisfiesExpression" ? [{ at: x, rule: "unsupported", msg: "satisfies", unsup: true }] : []),
    ...(x.type === "VariableDeclaration" && x.kind === "var" ? [{ at: x, rule: "no-var", msg: "var", unsup: false }] : []),
    ...(x.type === "Identifier" && x.name === "arguments" && !argumentsAsName(x, p) ? [{ at: x, rule: "no-arguments", msg: "arguments", unsup: false }] : []),
    // e1 (2026-11-23): a BigInt literal as a key (TypeScript's TS1539); the checker read its key as "null"
    ...(x.type === "Literal" && x.bigint !== null && p !== null && p.type === "Property" && !p.computed && p.key.nid === x.nid ? [{ at: x, rule: "unsupported", msg: "a BigInt literal as a property key", unsup: true }] : []),
  ];
};

// the walk: every node under root in acorn's key order, with its parent and whether it is in a type position
export const syntaxBans = (childrenOf, bansAt, TYPE_FIELDS) => (root: AstNode): SyntaxDiag[] => {
  const out: Mut<SyntaxDiag[]> = [];
  const walk = (x: AstNode, p: AstNode | null, inType: boolean): void => {
    for (const d of bansAt(x, p, inType)) out.push(d);
    for (const c of childrenOf(x)) walk(c.node, x, inType || TYPE_FIELDS.has(c.key));
  };
  walk(root, null, false);
  return out;
};

// S4.9 (2026-11-23, m1 step 2): the type names that mean Mut, Mut and each alias whose whole body names one, to a fixpoint
export const mutNames = (childrenOf) => (prog: AstNode): Set<string> => {
  const aliases: Mut<[string, string][]> = [];
  const walk = (x: AstNode): void => {
    if (x.type === "TSTypeAliasDeclaration" && x.id.type === "Identifier" && x.typeAnnotation.type === "TSTypeReference" && x.typeAnnotation.typeName.type === "Identifier") aliases.push([x.id.name, x.typeAnnotation.typeName.name]);
    for (const c of childrenOf(x)) walk(c.node);
  };
  walk(prog);
  const out: Mut<Set<string>> = new Set(["Mut"]);
  for (let grew = true; grew; ) {
    grew = false;
    for (const [a, b] of aliases) if (out.has(b) && !out.has(a)) { out.add(a); grew = true; }
  }
  return out;
};

// x (a type node) is the whole annotation of a binding, a parameter (of a function or a function type) or a local, or
// the whole body of a type alias; p is its parent and g p's parent
export const wholeBindingType = () => (x: AstNode, p: AstNode | null, g: AstNode | null): boolean => {
  if (p !== null && p.type === "TSTypeAliasDeclaration") return p.typeAnnotation.nid === x.nid;
  if (p === null || p.type !== "TSTypeAnnotation" || g === null) return false;
  return g.type === "Identifier" || g.type === "ObjectPattern" || g.type === "ArrayPattern" || g.type === "RestElement" || g.type === "AssignmentPattern";
};

// [mut-nested]: a Mut, or a typeof type, that is not the whole type of a binding or an alias body (wholeBindingType)
export const mutPlaces = (childrenOf, mutNames, wholeBindingType) => (prog: AstNode): ModErr[] => {
  const names = mutNames(prog), out: Mut<ModErr[]> = [];
  const fix = "only the whole type of a parameter, of a local or of a type alias may be a Mut: give the inner value its own Mut local or parameter, or drop the Mut (a local bound to a fresh value is writable)";
  const walk = (x: AstNode, p: AstNode | null, g: AstNode | null): void => {
    const n = x.type === "TSTypeReference" && x.typeName.type === "Identifier" && names.has(x.typeName.name) ? x.typeName.name : null;
    if (n !== null && !wholeBindingType(x, p, g)) out.push({ at: x, rule: "mut-nested", msg: `${n === "Mut" ? "Mut<…>" : `${n} (a Mut)`} inside another type or as a function's result; ${fix}` });
    if (x.type === "TSTypeQuery" && !wholeBindingType(x, p, g)) out.push({ at: x, rule: "mut-nested", msg: `a typeof type inside another type or as a function's result, where it may hold a Mut; write the type out` });
    for (const c of childrenOf(x)) walk(c.node, x, p);
  };
  walk(prog, null, null);
  return out;
};

// the identifier characters [A-Za-z0-9_$] from pos
export const nameAt = () => (text: string, pos: number): string => {
  let e = pos;
  for (let c = text.charCodeAt(e); c === 36 || c === 95 || (c >= 48 && c <= 57) || (c >= 65 && c <= 90) || (c >= 97 && c <= 122); c = text.charCodeAt(e)) e++;
  return text.slice(pos, e);
};

export const standIn = (STAND_INS) => (k: number, len: number): string | null => {
  let ph = "", j = k;
  for (let i = 0; i < len; i++) { ph = STAND_INS.charAt(j % 40) + ph; j = Math.floor(j / 40); }
  return j > 0 ? null : ph;
};

export const distinctParse = (parseTree, nameAt, standIn) => (src: string, jsx: boolean): Distinct => {
  let text = src;
  const dups: Mut<[string, string][]> = [];
  for (let parses = 1; ; parses++) {
    const p = parseTree(text, jsx);
    const name = p.ok || !p.message.includes("has already been declared") ? "" : nameAt(text, p.pos);
    const ph = p.ok || name === "" ? null : standIn(dups.length, name.length);
    if (p.ok || ph === null || dups.some((d) => d[0] === ph)) return { parse: p, text, dups: dups, parses };
    dups.push([ph, src.slice(p.pos, p.pos + name.length)]);
    text = text.slice(0, p.pos) + ph + text.slice(p.pos + name.length);
  }
};

// a module's text checked for its shape and, per cell, the syntax pass; acorn's error as a value. A cell's name is
// given back with any stand-in replaced
export type SyntaxResult = { ok: true; shape: ModuleShape; names: string[]; diags: SyntaxDiag[][]; parses: number; mut: ModErr[] } | { ok: false; message: string; line: number };

export const syntaxCheck = (distinctParse, moduleShape, syntaxBans, mutPlaces) => (text: string, jsx: boolean, builtin: Set<string>, shellNames: Set<string>): SyntaxResult => {
  const d = distinctParse(text, jsx);
  const p = d.parse;
  if (!p.ok) return { ok: false, message: p.message, line: p.line };
  const shape = moduleShape(p.ast.program, builtin, shellNames);
  const names = shape.cells.map((c) => d.dups.reduce((n, [ph, name]) => n.split(ph).join(name), c.name));
  return { ok: true, shape, names, diags: shape.cells.map((c) => syntaxBans(c.fn)), parses: d.parses, mut: mutPlaces(p.ast.program) };
};

// what a read of a binding with no type yet does (Binding.lazy): report, or check its hoisted declaration
// w1 (2026-11-24, S-1): later, a const or let of the block not yet declared: a read of it is refused, as JavaScript would
// read this binding and not one outside; p3 (2026-11-25): fn, the function a const binds, read early where ixFwdSafe allows
export type IxLazy = { k: "none" } | { k: "unsup"; at: AstNode } | { k: "hoist"; fn: AstNode; env: IxEnv; busy: boolean } | { k: "later"; at: AstNode; fn: AstNode | null; env: IxEnv; body: readonly AstNode[]; busy: boolean };

// fi: the nid of the function declaring it (Binding.fi.node); fnNode: the nid of the function it names; -1 for none
export type IxBinding = {
  id: number; scope: number; name: string; t: Ty; kind: IxKind; nid: number; fi: number; fnNode: number;
  mutOwned: boolean; assigned: boolean; cellParam: boolean; checked: boolean; lazy: IxLazy;
};

// FnInfo without its lists (rets and yields live in IxCtl while the function is checked)
export type IxFnCtx = {
  fid: number; parent: IxFnCtx | null; isAsync: boolean; isGen: boolean; isCell: boolean; inAction: boolean;
  retCtx: Ty | null; retFromCtx: boolean; yieldCtx: Ty | null; tps: string[];
  // d1 (2026-11-24): the names assigned inside a function nested in this one (ixNestedAssigned)
  writes: Set<string>;
  // t1 (2026-11-24, E-1): the names assigned anywhere in this one's body (ixAssignedNames), for ixFnWritten
  assigns: Set<string>;
};

export type IxCtl = {
  cur: number; nextFlow: number; diags: IxLog | null; unsup: IxLog | null; rets: Ty[]; yields: Ty[];
  quiet: number; nextId: number; nextScope: number; nextNid: number; fresh: number;
  short: Set<number>; clones: Set<number>; breaks: IxBreaks | null; flagsAt: number; flags: Flags | undefined;
  // freshAt: the last call or new whose value is fresh (an intrinsic marked @fresh, structuredClone, snapshot)
  freshAt: number;
  // p3 (2026-11-25): >0 while overloads are tried, whose diagnostics a failed try drops: a body checked on a read then
  // is not kept as checked (ixFwdRead, ixLazyRead), so its errors are reported where they stay
  tries: number;
  gap: string | null; facts: IxFactLog | null; probe: IxProbe | null;
  // e1 (2026-11-23): each cast<T>(v) the cell's checker accepted, by its callee's position, and T's shape
  casts: [number, TypeShape][];
  // open part 6 (HO): each index write (x[i] =, x[i] op=, x[i]++) and length write the checker met, by the target's
  // position, and whether the run time checks it (all but a typed-array receiver)
  holes: [number, boolean][];
  // d1 (2026-11-24): where a binding a nested function assigns was read at its declared type, by position, its name
  fnw: Map<number, string>;
};

// a write the TypeScript Checker makes to facts, actionBodies, inActionUses or stateProps, which the passes after it read
export type IxFact =
  | { readonly k: "binding"; readonly b: IxBinding }
  | { readonly k: "bind"; readonly at: number; readonly id: number }
  | { readonly k: "helper"; readonly at: number; readonly id: number }
  | { readonly k: "sig"; readonly at: number; readonly sig: Fn }
  | { readonly k: "prelude"; readonly at: number; readonly name: string }
  | { readonly k: "flags"; readonly at: number; readonly flags: Flags | null }
  | { readonly k: "action"; readonly at: number }
  | { readonly k: "use"; readonly fi: number; readonly at: number; readonly rule: string; readonly msg: string }
  | { readonly k: "stateProp"; readonly at: number };

// the facts as plain data, keyed by nid, bindings by id (Checker.facts without fnInfo, which nothing reads)
export type IxFacts = {
  readonly types: Map<number, Ty>; readonly bindingOf: Map<number, number>; readonly bindings: Map<number, IxBinding>;
  readonly calls: Map<number, IxCallFact>; readonly memberFlags: Map<number, Flags | null>;
  readonly actionBodies: Set<number>; readonly inActionUses: IxUse[]; readonly stateProps: Set<number>;
};

// lite/registry.ts as the port calls it; quiet: the same functions, each inside Registry.peek; lax: strictIndex off
export type IxRegCore = {
  readonly isAlias: (n: string) => boolean;
  readonly expand: (t: Ty) => Ty;
  readonly member: (t: Ty, k: string) => Prop | undefined;
  readonly sub: (a: Ty, b: Ty) => boolean;
  readonly callSigs: (t: Ty) => Fn[];
  readonly iterElem: (t: Ty) => Ty | undefined;
  readonly unify: (p: Ty, a: Ty, m: Mut<Map<string, Ty>>, tvs: Set<string>) => void;
  readonly isTypedArray: (t: Ty) => boolean;
  // rgMayHide over this core, memoised (memo) for its checks
  readonly mayHide: (t: Ty) => boolean;
  // x1 (2026-11-24, C): a member every function value has
  readonly fnOwn?: (n: string) => boolean;
  // w1 (2026-11-24, the forgetting rule): what an IxReg has that a core may hold too, declared so that an IxReg is a core
  readonly quiet?: IxRegCore;
  readonly lax?: IxRegCore;
  readonly strictIndex?: boolean;
  readonly same?: (a: Ty, b: Ty) => boolean;
  readonly origin?: (n: string) => string | null;
  readonly convert?: (n: AstNode, tps: string[], look: Map<string, Ty> | null) => Ty;
  readonly sig?: (params: AstNode[], ret: AstNode, tps: string[], look: Map<string, Ty> | null) => Fn;
  readonly hasTypeQuery?: (n: AstNode) => boolean;
  readonly cloneProblem?: (t: Ty) => string | null;
  readonly drain?: () => IxDiag[];
  readonly compile?: ((e: AstNode, options: Ty | null) => IxCompile) | null;
};

export type IxReg = {
  readonly isAlias: (n: string) => boolean;
  readonly expand: (t: Ty) => Ty;
  readonly member: (t: Ty, k: string) => Prop | undefined;
  readonly sub: (a: Ty, b: Ty) => boolean;
  readonly callSigs: (t: Ty) => Fn[];
  readonly iterElem: (t: Ty) => Ty | undefined;
  readonly unify: (p: Ty, a: Ty, m: Mut<Map<string, Ty>>, tvs: Set<string>) => void;
  readonly isTypedArray: (t: Ty) => boolean;
  readonly mayHide: (t: Ty) => boolean;
  readonly fnOwn?: (n: string) => boolean;
  readonly quiet: IxRegCore;
  readonly lax: IxRegCore;
  readonly strictIndex: boolean;
  readonly same: (a: Ty, b: Ty) => boolean;
  readonly origin: (n: string) => string | null;
  readonly convert: (n: AstNode, tps: string[], look: Map<string, Ty> | null) => Ty;
  readonly sig: (params: AstNode[], ret: AstNode, tps: string[], look: Map<string, Ty> | null) => Fn;
  readonly hasTypeQuery: (n: AstNode) => boolean;
  readonly cloneProblem: (t: Ty) => string | null;
  // what the registry reported since the last call, in order
  readonly drain: () => IxDiag[];
  // core.ts's compile hook, run until it asks for the type of the options expression, then again with it
  readonly compile: ((e: AstNode, options: Ty | null) => IxCompile) | null;
};

// what one cell's check is given
export type IxInput = {
  fn: AstNode; injected: Ty[]; src: string; count: number; cellNames: Set<string>; allowed: Set<string>;
  globals: { name: string; t: Ty; kind: IxKind }[];
};

// the recursive entry points and the per-check constants every method reads
export type IxK = {
  readonly reg: IxReg; readonly src: string; readonly cellNames: Set<string>; readonly allowed: Set<string>; readonly probe: IxProbeAsk | null;
  readonly infer: (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode) => Ty;
  readonly check: (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode, expected: Ty | null, soft: boolean, ctx: boolean) => Ty;
  readonly cond: (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode) => IxCond;
  readonly stmt: (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, s: AstNode) => boolean;
  readonly fnExpr: (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv | null, e: AstNode, expected: Ty | null, injected: Ty[] | null) => Ty;
  readonly call: (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode, expected: Ty | null) => Ty;
  readonly bind: (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, p: AstNode, t: Ty, kind: IxKind, extra: IxExtra) => void;
};

export const ixOut = () => (log: IxLog | null): IxDiag[] => {
  const out: Mut<IxDiag[]> = [];
  for (let x = log; x !== null; x = x.next) out.unshift(x.d);
  return out;
};

export const ixFact = () => (C: IxCtls, f: IxFact): void => {
  C.facts = { f, next: C.facts };
};

// the registry's reports go into the logs before anything the port writes or measures
export const ixDrain = (ixPush) => (K: IxK, C: IxCtls): void => {
  for (const d of K.reg.drain()) {
    if (d.rule === "unsupported") C.unsup = ixPush(C.unsup, d);
    else C.diags = ixPush(C.diags, d);
  }
};

export const ixErr = (ixDrain, ixPush) => (K: IxK, C: IxCtls, at: AstNode, rule: string, msg: string): void => {
  ixDrain(K, C);
  // d1: a use of a binding a nested function assigns says why a check before it does not hold
  const w = C.fnw.get(at.start);
  C.diags = ixPush(C.diags, { start: at.start, end: at.end, rule, msg: w === undefined ? msg : `${msg}; ${w} is assigned in a function nested in the one that declares it, or is assigned other than at its declaration and read here in a nested function, so a check on it does not carry to this use: copy it to a const first (const y = ${w}; if (y !== null) …)` });
};

export const ixUnsup = (ixDrain, ixPush) => (K: IxK, C: IxCtls, at: AstNode, what: string): void => {
  ixDrain(K, C);
  C.unsup = ixPush(C.unsup, { start: at.start, end: at.end, rule: "unsupported", msg: what });
};

// the port does not implement this: the cell's result is NOT COVERED, never a silent answer
export const ixGap = (ERR) => (C: IxCtls, what: string): Ty => {
  if (C.gap === null) C.gap = what;
  return ERR;
};

// the two logs' lengths, as the overload retry compares them
export const ixMark = (ixDrain) => (K: IxK, C: IxCtls): { d: IxLog | null; u: IxLog | null } => {
  ixDrain(K, C);
  return { d: C.diags, u: C.unsup };
};

// a new flow object holding f
export const ixNewFlow = () => (W: IxFlows, C: IxCtls, f: IxFlow): number => {
  C.nextFlow += 1;
  W.set(C.nextFlow, f);
  return C.nextFlow;
};

// flow.set(k, t) on the flow object id, which every environment holding it sees
export const ixFlowSet = (ixFlowOf) => (W: IxFlows, id: number, k: string, t: Ty): void => {
  const m: Mut<IxFlow> = new Map(ixFlowOf(W, id));
  m.set(k, t);
  W.set(id, m);
};

// dropRoot: the narrowings of a binding and of every path below it go, in place
export const ixDropRoot = (ixFlowOf, ixPathOf) => (W: IxFlows, id: number, b: IxBinding): void => {
  const k = "#" + b.id;
  const m: Mut<IxFlow> = new Map(ixFlowOf(W, id));
  for (const key of [...m.keys()]) { const p = ixPathOf(key); if (p === k || p.startsWith(k + ".")) m.delete(key); }
  W.set(id, m);
};

// join: the keys both flows narrow, as the union of the two; a null side gives the other flow object itself
export const ixJoin = (ixFlowOf, ixNewFlow, union) => (W: IxFlows, C: IxCtls, a: number | null, b: number | null): number | null => {
  if (a === null) return b;
  if (b === null) return a;
  const out: Mut<IxFlow> = new Map();
  const fb = ixFlowOf(W, b);
  for (const [k, t] of ixFlowOf(W, a)) { const u = fb.get(k); if (u) out.set(k, union([t, u])); }
  return ixNewFlow(W, C, out);
};

// ---- scopes and bindings ----
export const ixNewScope = () => (C: IxCtls, env: IxEnv): IxEnv => {
  C.nextScope += 1;
  return { ...env, scope: C.nextScope, up: { id: env.scope, up: env.up } };
};

export const ixLookup = () => (V: IxVars, env: IxEnv, n: string): IxBinding | undefined => {
  const here = V.get(`${env.scope}:${n}`);
  if (here) return here;
  for (let c = env.up; c !== null; c = c.up) {
    const b = V.get(`${c.id}:${n}`);
    if (b) return b;
  }
  return undefined;
};

export const ixDeclare = (ixFact) => (V: IxVars, C: IxCtls, env: IxEnv, name: string, t: Ty, kind: IxKind, at: AstNode, extra: IxExtra, lazy: IxLazy, mutOwned: boolean, fnNode: number): IxBinding => {
  C.nextId += 1;
  const b: IxBinding = { id: C.nextId, scope: env.scope, name, t, kind, nid: at.nid, fi: env.fi.fid, fnNode, mutOwned, assigned: extra.assigned, cellParam: extra.cellParam, checked: false, lazy };
  V.set(`${env.scope}:${name}`, b);
  ixFact(C, { k: "binding", b });
  ixFact(C, { k: "bind", at: at.nid, id: b.id });
  return b;
};

// a binding changed: the one the scope holds under its name, as the original writes the Binding object; the facts
// keep it whether or not the scope still holds it
export const ixUpdate = (ixFact) => (V: IxVars, C: IxCtls, b: IxBinding): void => {
  const key = `${b.scope}:${b.name}`;
  const now = V.get(key);
  if (now && now.id === b.id) V.set(key, b);
  ixFact(C, { k: "binding", b });
};

// findBinding: a binding by id among those the scope chain holds
export const ixFindBinding = () => (V: IxVars, env: IxEnv, id: number): IxBinding | undefined => {
  const scopes: Mut<Set<number>> = new Set([env.scope]);
  for (let c = env.up; c !== null; c = c.up) scopes.add(c.id);
  for (const b of V.values()) if (b.id === id && scopes.has(b.scope)) return b;
  return undefined;
};

// typeCtx: the type parameters of the function and the functions around it
export const ixTps = () => (env: IxEnv): string[] => {
  const out: Mut<string[]> = [];
  for (let fi: IxFnCtx | null = env.fi; fi !== null; fi = fi.parent) for (const n of fi.tps) out.push(n);
  return out;
};

// typeofLookup, taken once: the type of each name the scope chain holds, the innermost first
export const ixLookTable = (ixLookup) => (V: IxVars, env: IxEnv): Map<string, Ty> => {
  const out: Mut<Map<string, Ty>> = new Map();
  for (const b of V.values()) {
    const seen = ixLookup(V, env, b.name);
    if (seen && seen.id === b.id && seen.kind !== "prelude") out.set(b.name, b.t);
  }
  return out;
};

// ---- union helpers and narrowing primitives ----
export const ixUm = () => {
  function um(R: IxRegCore, t: Ty): Ty[] {
    if (t.k === "union") return t.ts.flatMap((x) => um(R, x));
    if (t.k === "named" && R.isAlias(t.n)) {
      const e = R.expand(t);
      if (e.k === "union" || (e.k !== "rec" && e.k !== "err")) return um(R, e);
    }
    return t.k === "never" ? [] : [t];
  }
  return um;
};

export const ixFilter = (ixUm, union) => (R: IxRegCore, t: Ty, keep: (m: Ty) => boolean | Ty): Ty => {
  if (t.k === "err") return t;
  const out: Mut<Ty[]> = [];
  for (const m of ixUm(R, t)) {
    const r = keep(m);
    if (r === true) out.push(m);
    else if (r !== false) out.push(r);
  }
  return union(out);
};

// m, a record with no call signature, may hold a value of one of kinds although its typeof tag is "object": any such
// record a function (a callable type with m's members is assignable to it), {} and { a?: number } a string or an array
// a record admits a function only as a function of no known signature would reach it (holes step 9; any before)
export const ixAdmits = (STR, NUM, BOOL, BIGINT, SYMBOL, UNDEF, NEVER, UNKNOWN, arr) => {
  // a fresh Map bound to an annotated const is writable (S4.1), so the kept function captures a plain-typed name for it
  const W0 = new Map<string, Ty>([["string", STR], ["number", NUM], ["boolean", BOOL], ["bigint", BIGINT], ["symbol", SYMBOL], ["undefined", UNDEF], ["array", arr(NEVER)],
    ["function", { k: "fn", tps: [], ps: [], rest: NEVER, ret: UNKNOWN }]]);
  const W: Map<string, Ty> = W0;
  return (R: IxRegCore, m: Ty, kinds: string[]): boolean => {
    const x = m.k === "named" ? R.expand(m) : m;
    if (x.k !== "rec" || !!x.calls?.length || !!x.ctors?.length) return false;
    return kinds.some((k) => { const w = W.get(k); return w !== undefined && R.sub(w, m); });
  };
};

export const ixTruthy = (ixFilter) => (R: IxRegCore, t: Ty): Ty => ixFilter(R, t, (m) => {
  if (m.k === "null" || m.k === "undef" || m.k === "void") return false;
  if (m.k === "lit") return !!m.v;
  return true;
});

export const ixFalsy = (ixFilter, ixAdmits) => (R: IxRegCore, t: Ty): Ty => ixFilter(R, t, (m) => {
  if (["null", "undef", "void", "num", "str", "bigint", "unknown", "tv"].includes(m.k)) return true;
  if (m.k === "lit") return !m.v;
  return ixAdmits(R, m, ["number", "string", "boolean", "bigint"]);
});

// x === m in the original: the expansion is the type itself when it is not an alias
export const ixTypeTag = (unwrap) => {
  function typeTag(R: IxReg, m: Ty): string | null {
    switch (m.k) {
      case "num": return "number";
      case "str": return "string";
      case "bigint": return "bigint";
      case "symbol": return "symbol";
      case "undef": case "void": return "undefined";
      case "null": return "object";
      case "lit": return typeof m.v;
      case "fn": return "function";
      case "rec": return m.calls?.length ? "function" : "object";
      case "named": {
        if (m.n === "Action") return "function";
        const x = R.expand(unwrap(m));
        return R.same(x, m) ? "object" : typeTag(R, x);
      }
      case "arr": case "tup": return "object";
      default: return null;
    }
  }
  return typeTag;
};

// the type of a typeof kind a record may hold: a function of no known signature for "function" (holes step 9)
export const IX_KIND = (STR, NUM, BOOL, BIGINT, UNDEF, SYMBOL, NEVER, UNKNOWN) => new Map<string, Ty>([["string", STR], ["number", NUM], ["boolean", BOOL], ["bigint", BIGINT], ["undefined", UNDEF],
  ["symbol", SYMBOL], ["function", { k: "fn", tps: [], ps: [], rest: NEVER, ret: UNKNOWN }]]);

// a record and the kind k: for "function", the record with the kind's call signature; another kind has no member a
// record that admits it can require
export const ixKindOf = (IX_KIND) => (R: IxReg, m: Ty, k: string): Ty[] => {
  const w = IX_KIND.get(k), x = R.expand(m);
  if (w === undefined) return [];
  return k === "function" && w.k === "fn" && x.k === "rec" ? [{ k: "rec", props: x.props, calls: [w] }] : [w];
};

// a record whose tag is "object", on a side where a value of it may be of another kind, is the kinds it may hold
// there, a function kind intersected with the record (holes step 9: the owner's ruling; it stayed as itself before)
export const ixNarrowTypeof = (ixFilter, ixTypeTag, ixAdmits, IX_TYPEOF, ixKindOf, union) => (R: IxReg, t: Ty, tag: string, pos: boolean): Ty => ixFilter(R, t, (m) => {
  const mt = ixTypeTag(R, m);
  const ks = (pos ? [tag] : ["function", "string", "number", "boolean", "bigint", "symbol", "undefined"]).filter((k) => ixAdmits(R, m, [k]));
  if (mt === "object" && pos !== (tag === "object") && ks.length) return union(ks.flatMap((k) => ixKindOf(R, m, k)));
  if (mt !== null) return (mt === tag) === pos;
  if (!pos) return true;
  if (m.k === "unknown" || m.k === "tv") return IX_TYPEOF.get(tag) ?? false;
  return m.k === "object" ? tag === "object" || tag === "function" : true;
});

export const ixNarrowEq = (ixFilter, union, NULL, UNDEF) => (R: IxRegCore, t: Ty, v: Ty, pos: boolean, loose: boolean): Ty => {
  const nullish = v.k === "null" || v.k === "undef";
  return ixFilter(R, t, (m) => {
    if (pos) {
      if (loose && nullish) return m.k === "null" || m.k === "undef" || m.k === "void" || (m.k === "unknown" ? union([NULL, UNDEF]) : false);
      if (m.k === "unknown") return v;
      if (R.sub(v, m)) return v.k === "lit" || nullish ? v : true;
      return R.sub(m, v);
    }
    if (loose && nullish) return !(m.k === "null" || m.k === "undef" || m.k === "void");
    if ((v.k === "lit" || nullish) && R.sub(m, v) && R.sub(v, m)) return false;
    return true;
  });
};

// a member that does not declare k is kept on the true side: a value of it may have k as an extra property
export const ixNarrowIn = (ixFilter, UNKNOWN) => (R: IxRegCore, t: Ty, k: string, pos: boolean): Ty => ixFilter(R, t, (m) => {
  if (pos) {
    if (!!R.member(m, k) && R.expand(m).k !== "unknown") return true;
    const x = R.expand(m);
    if (x.k === "rec") { const props: Mut<Map<string, Prop>> = new Map(x.props); props.set(k, { t: UNKNOWN, opt: false }); return { ...x, props: props }; }
    if (x.k === "object" || x.k === "unknown") return { k: "rec", props: new Map([[k, { t: UNKNOWN, opt: false }]]) };
    return true;
  }
  const p = R.member(m, k);
  return !(p && !p.opt);
});

export const ixNarrowArray = (ixFilter, ixAdmits, arr, UNKNOWN) => (R: IxRegCore, t: Ty, pos: boolean): Ty => ixFilter(R, t, (m) => {
  if (m.k === "arr" || m.k === "tup") return pos;
  if (m.k === "unknown" || m.k === "object" || m.k === "tv") return pos ? arr(UNKNOWN) : true;
  return !pos || ixAdmits(R, m, ["array"]);
});

// discriminant: keep the members of t whose property k passes test
export const ixNarrowByProp = (ixFilter, propT) => (R: IxRegCore, t: Ty, k: string, test: (pt: Ty) => boolean): Ty => ixFilter(R, t, (m) => {
  const p = R.member(m, k);
  if (!p) return true;
  return test(propT(p));
});

export const ixHeldIn = (show) => {
  function heldIn(R: IxRegCore, s: Ty, depth: number, hit: (s: Ty) => boolean, calls: boolean): string | null {
    if (depth > 10) return null;
    const first = (xs: Ty[]): string | null => { for (const x of xs) { const w = heldIn(R, x, depth + 1, hit, calls); if (w) return w; } return null; };
    switch (s.k) {
      case "named":
        if (hit(s)) return show(s);
        if (R.isAlias(s.n)) return heldIn(R, R.expand(s), depth + 1, hit, calls);
        return first(s.args);
      case "arr": return first([s.el]);
      case "tup": return first(s.els);
      case "union": return first(s.ts);
      case "rec": return first([...[...s.props.values()].map((p) => p.t), ...(s.index ? [s.index] : []), ...(calls ? (s.calls ?? []).map((c) => c.ret) : [])]);
      case "fn": return calls ? first([s.ret]) : null;
      default: return null;
    }
  }
  return heldIn;
};

// y1 (2026-11-24): pendingIn, the first Promise, generator or iterator (Iterable: what values() gives) held in s, not in
// a function's result
export const ixPendingIn = (ixHeldIn) => (R: IxRegCore, s: Ty): string | null =>
  ixHeldIn(R, s, 0, (x) => x.k === "named" && ["Promise", "Generator", "AsyncGenerator", "Iterable", "Iterator", "IterableIterator", "AsyncIterator", "AsyncIterableIterator"].includes(x.n), false);

// promiseIn: the first promise-like, a Promise, a type with a then member, or object
export const ixPromiseIn = (show) => {
  function promiseIn(R: IxRegCore, s: Ty, depth: number): string | null {
    if (depth > 10) return null;
    const first = (xs: Ty[]): string | null => { for (const x of xs) { const w = promiseIn(R, x, depth + 1); if (w) return w; } return null; };
    if (s.k === "object" || (s.k !== "union" && s.k !== "err" && R.member(s, "then"))) return show(s);
    switch (s.k) {
      case "named":
        if (s.n === "Promise") return show(s);
        if (R.isAlias(s.n)) return promiseIn(R, R.expand(s), depth + 1);
        return first(s.args);
      case "arr": return first([s.el]);
      case "tup": return first(s.els);
      case "union": return first(s.ts);
      case "rec": return first([...[...s.props.values()].map((p) => p.t), ...(s.index ? [s.index] : [])]);
      default: return null;
    }
  }
  return promiseIn;
};

// t may be or hold a function, for the fed rule (S11.9): what ixMayHide says. w1 (2026-11-24): the second clause (a
// record a function is assignable to, one with no required member) is gone: a function reaches no record type (subtype.ss.ts takesRecord)
export const ixMayHoldFn = (ixMayHide) => (R: IxRegCore, t: Ty): boolean => ixMayHide(R, t);

// the first Action (or handle, by find) in s that a position of t of type unknown, object or an opaque type parameter
// would take. w1 (2026-11-24): t1's record-that-takes-any-object case (ixAnyObject, ixExtraHidden) is gone: what a
// record type leaves out of a value must be plain data, in subtype.ss.ts takesRecord, at every site
export const ixHidden = (ixMayHide, ixHiddenIn, isNamed) => {
  function hidden(H: IxHide, s: Ty, t: Ty, depth: number): string | null {
    if (depth > 10 || s.k === "err" || t.k === "err" || s.k === "never") return null;
    const R = H.R;
    if (!ixMayHide(R, t)) return null;
    // the same alias, with no arguments, on both sides: t keeps all s says (Ty to Ty walked every Flags member)
    if (s.k === "named" && t.k === "named" && s.n === t.n && !s.args.length && !t.args.length && R.isAlias(s.n)) return null;
    if (t.k === "unknown" || t.k === "object" || (t.k === "tv" && H.opaque?.has(t.n))) return H.find(s);
    if (s.k === "named" && R.isAlias(s.n)) return hidden(H, R.expand(s), t, depth + 1);
    if (t.k === "named" && R.isAlias(t.n)) return hidden(H, s, R.expand(t), depth + 1);
    if (s.k === "union") { for (const m of s.ts) { const w = hidden(H, m, t, depth + 1); if (w) return w; } return null; }
    if (s.k === "named" && (s.n === "Mut" || s.n === "Borrowed") && !isNamed(t, s.n)) return hidden(H, s.args[0] ?? s, t, depth + 1);
    if (t.k === "union") {
      // s goes to a member it is assignable to; it is hidden only when every such member hides it
      let w: string | null = null;
      for (const m of t.ts.filter((x) => R.sub(s, x))) { const x = hidden(H, s, m, depth + 1); if (!x) return null; w = x; }
      return w;
    }
    return ixHiddenIn(H, hidden, s, t, depth);
  }
  return hidden;
};

// hidden by the kind of t, once neither side is an alias or a union
export const ixHiddenIn = (ixHiddenFn, propT, NEVER) => (H: IxHide, hidden: IxHiddenFn, s: Ty, t: Ty, depth: number): string | null => {
  const R = H.R, sx = R.expand(s);
  const each = (pairs: [Ty, Ty][]): string | null => { for (const [a, b] of pairs) { const w = hidden(H, a, b, depth + 1); if (w) return w; } return null; };
  switch (t.k) {
    case "arr": return each((sx.k === "arr" ? [sx.el] : sx.k === "tup" ? sx.els : [R.iterElem(sx) ?? NEVER]).map((x): [Ty, Ty] => [x, t.el]));
    case "tup": return sx.k !== "tup" ? null : each(t.els.flatMap((x, i): [Ty, Ty][] => { const y = sx.els[i]; return y ? [[y, x]] : []; }));
    case "rec": {
      for (const [k, p] of t.props) { const sp = R.member(sx, k); const w = sp && hidden(H, propT(sp), propT(p), depth + 1); if (w) return w; }
      const index = t.index, sIndex = sx.k === "rec" ? sx.index : undefined;
      if (index && sx.k === "rec") for (const p of sx.props.values()) { const w = hidden(H, propT(p), index, depth + 1); if (w) return w; }
      // x1 (2026-11-24): and s's own index signature, which Object.fromEntries and a spread fill
      if (index && sIndex) { const w = hidden(H, sIndex, index, depth + 1); if (w) return w; }
      for (const c of t.calls ?? []) { const w = ixHiddenFn(H, hidden, s, c, depth); if (w) return w; }
      return null;
    }
    case "fn": return ixHiddenFn(H, hidden, s, t, depth);
    case "named": {
      const a0 = t.args[0];
      if (t.n === "Iterable" || t.n === "ArrayLike") { const el = R.iterElem(sx); return el && a0 ? hidden(H, el, a0, depth + 1) : null; }
      if (sx.k !== "named" || sx.n !== t.n) return null;
      return each(t.args.flatMap((x, i): [Ty, Ty][] => { const y = sx.args[i]; return y ? [[y, x]] : []; }));
    }
    default: return null;
  }
};

// a function of type s used as t: its return goes to t's return, and what t's caller passes to s's parameters
export const ixHiddenFn = () => (H: IxHide, hidden: IxHiddenFn, s: Ty, t: Fn, depth: number): string | null => {
  const f = H.R.callSigs(s)[0];
  if (!f) return null;
  const w = hidden(H, f.ret, t.ret, depth + 1);
  if (w) return w;
  for (let i = 0; i < t.ps.length && i < f.ps.length; i++) {
    const a = t.ps[i], b = f.ps[i];
    const x = a && b ? hidden(H, a.t, b.t, depth + 1) : null;
    if (x) return x;
  }
  return null;
};

// hides: an Action or a handle placed where its type becomes unknown, object or an opaque type parameter (S6.6). y1
// (2026-11-24): x1's third pass is narrowed to its direct case, a promise, generator or iterator whose own type is given
// unknown or object; a function, a Mut, and what a join or a type parameter launders go to the run time (freeze.ts)
export const ixHides = (ixHidden, ixActionIn, ixHandleIn, ixPendingIn, ixErr, show) => (K: IxK, C: IxCtls, at: AstNode, t: Ty, expected: Ty, opaque: Set<string> | null): boolean => {
  const R = K.reg.quiet, same = K.reg.same(t, expected);
  const w = same ? null : ixHidden({ R, opaque, find: (x: Ty) => ixActionIn(R, x) }, t, expected, 0);
  if (w) ixErr(K, C, at, "action-pass", `${show(t)} is given the type ${show(expected)}, which hides its ${w}; an Action goes only where an Action is expected`);
  const h = w || same ? null : ixHidden({ R, opaque, find: (x: Ty) => ixHandleIn(R, x) }, t, expected, 0);
  if (h) ixErr(K, C, at, "handle-pass", `${show(t)} is given the type ${show(expected)}, which hides its ${h}; a State or Events handle, or a FetchResponse, goes only where its own type is expected`);
  const f = w || h || same ? null : ixHidden({ R, opaque: null, find: (x: Ty) => ixPendingIn(R, x) }, t, expected, 0);
  if (f) ixErr(K, C, at, "forgets", `${show(t)} is given the type ${show(expected)}, which hides its ${f}; a promise, generator or iterator goes only where a type names it (the run time refuses one it finds anywhere else)`);
  return !w && !h && !f;
};

// soft: expected is a context only; ctx: expected is a context, not the type the value finally has
export const ixCheck = (ixCheck1) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode, expected: Ty | null, soft: boolean, ctx: boolean): Ty => {
  const outer = C.quiet;
  const q = soft || ctx || outer > 0;
  C.quiet = q && (e.type === "ObjectExpression" || e.type === "ArrayExpression" || e.type === "ConditionalExpression" || e.type === "LogicalExpression") ? 1 : 0;
  try { return ixCheck1(K, T, V, W, C, env, e, expected, soft, q); } finally { C.quiet = outer; }
};

// a literal, or a fresh call or new, checked against Mut<X>: checked against X, and its type is Mut<X> (S4: a fresh value
// is writable; no one else holds it). Any other value checked against Mut<X> is a [type] error: T is not a Mut<T>.
export const ixCheckFresh = (ixExpect) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode, expected: Ty, soft: boolean, q: boolean): Ty => {
  const x = expected.k === "named" ? expected.args[0] ?? expected : expected;
  const t = K.check(K, T, V, W, C, env, e, x, soft, q);
  const fresh = e.type === "ArrayExpression" || e.type === "ObjectExpression" || C.freshAt === e.nid;
  if (!soft && !fresh) ixExpect(K, C, e, t, expected, q);
  T.set(e.nid, fresh ? expected : t);
  return fresh ? expected : t;
};

export const ixCheck1 = (ixCheckFresh, ixCtxSensitive, ixHides, ixObjLit, ixArrLit, ixConditional, ixCheckLogical, ixExpect) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode, expected: Ty | null, soft: boolean, q: boolean): Ty => {
  if (expected === null) return K.infer(K, T, V, W, C, env, e);
  const viaMut = e.type === "CallExpression" && e.callee.type === "Identifier" && e.callee.name === "mut";
  if (expected.k === "named" && expected.n === "Mut" && !viaMut && ["ArrayExpression", "ObjectExpression", "CallExpression", "NewExpression"].includes(e.type)) return ixCheckFresh(K, T, V, W, C, env, e, expected, soft, q);
  if (expected.k === "unknown" && !ixCtxSensitive(e)) { const t = K.infer(K, T, V, W, C, env, e); if (!q) ixHides(K, C, e, t, expected, null); return t; }
  let t: Ty;
  switch (e.type) {
    case "ObjectExpression": t = ixObjLit(K, T, V, W, C, env, e, expected); break;
    case "ArrayExpression": t = ixArrLit(K, T, V, W, C, env, e, expected); break;
    case "ArrowFunctionExpression": case "FunctionExpression": t = K.fnExpr(K, T, V, W, C, env, e, expected, null); break;
    case "ConditionalExpression": { const c = ixConditional(K, T, V, W, C, env, e, expected); T.set(e.nid, c); return c; }
    case "LogicalExpression":
      if (e.operator !== "&&") { const l = ixCheckLogical(K, T, V, W, C, env, e, expected, soft, q); T.set(e.nid, l); return l; }
      t = K.infer(K, T, V, W, C, env, e);
      break;
    case "CallExpression": case "NewExpression": t = K.call(K, T, V, W, C, env, e, expected); break;
    default: t = K.infer(K, T, V, W, C, env, e);
  }
  T.set(e.nid, t);
  if (!soft) ixExpect(K, C, e, t, expected, q);
  return t;
};

export const ixInfer = (ixInfer1) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode): Ty => {
  const q = C.quiet;
  C.quiet = 0;
  try {
    const t = ixInfer1(K, T, V, W, C, env, e);
    T.set(e.nid, t);
    return t;
  } finally { C.quiet = q; }
};

export const ixInfer1 = (ixInferAtom, ixInferOp, ixInferRest, ixUnsup, ixGap, nodeKind, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode): Ty => {
  if (e.type === "Other") return ixGap(C, `node ${e.kind} (Other)`);
  const t = ixInferAtom(K, T, V, W, C, env, e) ?? ixInferOp(K, T, V, W, C, env, e) ?? ixInferRest(K, T, V, W, C, env, e);
  if (t !== null) return t;
  ixUnsup(K, C, e, nodeKind(e));
  return ERR;
};

// literals, names, and what the syntax pass reports
export const ixInferAtom = (ixLiteral, ixIdent, ixConstLit, ERR, STR, lit) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode): Ty | null => {
  switch (e.type) {
    case "Literal": return ixLiteral(e);
    case "TemplateLiteral": {
      for (const x of e.expressions) K.infer(K, T, V, W, C, env, x);
      const q = e.quasis[0];
      return e.expressions.length || q === undefined || q.type !== "TemplateElement" ? STR : lit(q.value.cooked ?? "");
    }
    case "Identifier": return ixIdent(K, T, V, W, C, env, e);
    case "ThisExpression": case "ClassExpression": case "ImportExpression": return ERR;
    case "TSNonNullExpression": case "TSTypeAssertion": K.infer(K, T, V, W, C, env, e.expression); return ERR;
    case "TSAsExpression": {
      const a = e.typeAnnotation, n = a.type === "TSTypeReference" ? a.typeName : null;
      if (n !== null && n.type === "Identifier" && n.name === "const") return ixConstLit(K, T, V, W, C, env, e.expression);
      K.infer(K, T, V, W, C, env, e.expression);
      return ERR;
    }
    default: return null;
  }
};

export const ixLiteral = (named, lit, BIGINT, NULL) => (e: Literal): Ty => {
  if (e.regex !== null) return named("RegExp");
  if (e.bigint !== null) return BIGINT;
  return e.value === null ? NULL : lit(e.value);
};

// p3 (2026-11-25): a later const function read where ixFwdSafe allows has the type a hoisted function declaration has:
// its annotations, else its body checked at the first such read (a read inside that check is a recursion without a type)
export const ixFwdRead = (ixAnnotatedSig, ixUnsup, ixUpdate, ixNewFlow, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, b: IxBinding): Ty => {
  const z = b.lazy;
  if (z.k !== "later" || z.fn === null || b.checked || b.t.k !== "err") return b.t;
  if (z.busy) { ixUnsup(K, C, z.fn, "recursive function without a return type"); return ERR; }
  const sig = ixAnnotatedSig(K, V, C, z.env, z.fn);
  if (sig !== null) { ixUpdate(V, C, { ...b, t: sig }); return sig; }
  ixUpdate(V, C, { ...b, lazy: { ...z, busy: true } });
  const own = C.cur;
  C.cur = ixNewFlow(W, C, new Map());
  const f = K.check(K, T, V, W, C, z.env, z.fn, null, false, false);
  C.cur = own;
  ixUpdate(V, C, C.tries > 0 ? { ...b, lazy: { ...z, busy: false } } : { ...b, t: f, checked: true, lazy: { ...z, busy: false } });
  return f;
};

// what reading a binding with no type yet gives (Binding.lazy)
export const ixLazyRead = (ixUnsup, ixUpdate, ixNewFlow, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, b: IxBinding): Ty => {
  const z = b.lazy;
  if (z.k === "none") return b.t;
  if (z.k === "unsup") { ixUnsup(K, C, z.at, "recursive function without a return type"); return ERR; }
  if (z.k === "later") return ERR;
  if (z.busy) { ixUnsup(K, C, z.fn, "recursive function without a return type"); return ERR; }
  ixUpdate(V, C, { ...b, lazy: { ...z, busy: true } });
  const own = C.cur;
  C.cur = ixNewFlow(W, C, new Map());
  const f = K.fnExpr(K, T, V, W, C, z.env, z.fn, null, null);
  C.cur = own;
  // p3 (2026-11-25): not kept while overloads are tried (IxCtl.tries)
  ixUpdate(V, C, C.tries > 0 ? { ...b, lazy: { ...z, busy: false } } : { ...b, t: f, checked: true, lazy: { k: "none" } });
  return f;
};

export const ixIdent = (ixLookup, ixLazyRead, ixFwdSafe, ixFwdWhy, ixFwdRead, ixFlowOf, ixFnWritten, ixErr, ixUnsup, ixFact, ixScopeNames, NEVER, UNKNOWN, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: Identifier): Ty => {
  if (K.probe !== null && !K.probe.member && C.probe === null && e.name === K.probe.name) C.probe = { k: "name", names: ixScopeNames(V, W, C, env), inAction: env.fi.inAction };
  const b = ixLookup(V, env, e.name);
  if (!b) {
    if (e.name === "arguments") return ERR;
    if (K.cellNames.has(e.name)) ixErr(K, C, e, "cell-by-name", `cell ${e.name} referenced by name; take it as a parameter (a cell may not read itself: a function that calls itself is made under a local name inside the cell, const f = memo((n: number): number => … f(n - 1) …); return f)`);
    else if (K.allowed.has(e.name)) ixUnsup(K, C, e, `intrinsic ${e.name} has no signature in lite/intrinsics.ts`);
    else if (e.name === "mut" || e.name === "freeze" || e.name === "borrow") ixErr(K, C, e, "removed-call", `${e.name}(...) is no longer part of the language: delete the call and keep its argument (a fresh value bound to a local is writable; a cell's value is frozen when it leaves the cell)`);
    else ixErr(K, C, e, "free-name", `free name ${e.name}`);
    return ERR;
  }
  // w1 (S-1), p3: a const or let of an enclosing block read before its declaration runs, unless ixFwdSafe allows it
  const z = b.lazy, why = z.k !== "later" ? null : z.fn === null ? "" : ixFwdSafe(z.body, z.at, e);
  if (why !== null) { ixErr(K, C, e, "free-name", ixFwdWhy(e.name, why, z.k === "later" && z.fn !== null)); return ERR; }
  ixFact(C, { k: "bind", at: e.nid, id: b.id });
  if (z.k === "later") return ixFwdRead(K, T, V, W, C, b);
  if (b.kind === "prelude") return b.t;
  // its argument is checked where it is called, so the value takes no argument (S2.6 lets a body name it)
  if (b.kind === "global" && e.name === "structuredClone" && !C.clones.has(e.nid)) return { k: "fn", tps: [], ps: [{ n: "v", t: NEVER, opt: false }], ret: UNKNOWN };
  // d1: a binding a nested function assigns is read at its declared type
  const fw = ixFnWritten(env, b);
  if (fw && !C.fnw.has(e.start)) C.fnw = new Map([...C.fnw, [e.start, b.name]]);
  const nt = fw ? undefined : ixFlowOf(W, C.cur).get("#" + b.id);
  if (nt) return nt;
  return b.checked ? b.t : ixLazyRead(K, T, V, W, C, b);
};

// the bindings in scope at env, innermost scope first, each name once, with its type in the current flow
export const ixScopeNames = (ixFlowOf) => (V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv): IxScopeName[] => {
  const ids: Mut<number[]> = [env.scope];
  for (let c = env.up; c !== null; c = c.up) ids.push(c.id);
  const flow = ixFlowOf(W, C.cur), seen: Mut<Set<string>> = new Set(), out: Mut<IxScopeName[]> = [];
  for (const id of ids) for (const b of V.values()) {
    if (b.scope !== id || seen.has(b.name)) continue;
    seen.add(b.name);
    out.push({ name: b.name, kind: b.kind, t: flow.get("#" + b.id) ?? b.t });
  }
  return out;
};

// d1 (2026-11-24): a let or parameter that a function nested in the one declaring it assigns (S3.11)
export const ixFnWritten = () => (env: IxEnv, b: IxBinding): boolean => {
  if (b.kind !== "let" && b.kind !== "param") return false;
  // t1 (E-1): or, used from a nested function, one its declaring function assigns other than at its declaration
  for (let f: IxFnCtx | null = env.fi; f !== null; f = f.parent) if (f.fid === b.fi) return f.writes.has(b.name) || (f.fid !== env.fi.fid && f.assigns.has(b.name));
  return false;
};

// a path (identifier or chain of non-computed members) as a narrowing key; links: a ?. member is one too; not a binding
// a nested function assigns (d1)
export const ixPathKey = (ixLookup, ixFnWritten, isNamed) => {
  function pathKey(V: IxVars, env: IxEnv, n: AstNode, links: boolean): string | null {
    if (n.type === "Identifier") {
      const b = ixLookup(V, env, n.name);
      if (!b || b.kind === "global" || b.kind === "prelude" || isNamed(b.t, "Mut") || ixFnWritten(env, b)) return null;
      return "#" + b.id;
    }
    if (n.type !== "MemberExpression" || (n.optional && !links)) return null;
    const base = pathKey(V, env, n.object, links);
    if (!base) return null;
    const p = n.property;
    if (!n.computed && p.type === "Identifier") return base + "." + p.name;
    if (n.computed && p.type === "Literal" && typeof p.value === "string") return base + (/^(0|[1-9]\d*)$/.test(p.value) ? `[${p.value}]` : "." + p.value);
    if (n.computed && p.type === "Literal" && typeof p.value === "number") return base + "[" + p.value + "]";
    return null;
  }
  return pathKey;
};

// A | B arrays read as (A | B)[]: sound because arrays are immutable outside Mut
export const ixCollapseArrays = (ixUm, union, arr) => (R: IxRegCore, t: Ty): Ty => {
  const ms = ixUm(R, t);
  const arrs = ms.filter((m) => m.k === "arr" || m.k === "tup");
  if (arrs.length < 2) return t;
  const els = arrs.map((m) => (m.k === "arr" ? m.el : m.k === "tup" ? union(m.els) : m));
  return union([...ms.filter((m) => m.k !== "arr" && m.k !== "tup"), arr(union(els))]);
};

// the intrinsic a type's members come from, or null for a user type
export const ixIntrinsicName = (show) => (R: IxReg, m: Ty): string | null => {
  const e = R.expand(m);
  if (e.k === "arr" || e.k === "tup") return "Array";
  if (e.k === "str" || (e.k === "lit" && typeof e.v === "string")) return "String";
  if (e.k === "num" || e.k === "lit") return "Number";
  if (e.k === "union" && e.ts.every((x) => x.k === "lit" && typeof x.v === "boolean")) return show(e);
  if (e.k === "named") { const o = R.origin(e.n); return o === null || o === "intrinsic" ? e.n : null; }
  return null;
};

export const ixMemberMissing = (ixErr, ixUnsup, ixIntrinsicName, show, UNDEF_FIX) => (K: IxK, C: IxCtls, m: Ty, k: string, at: AstNode, all: Ty): void => {
  if (m.k === "null" || m.k === "undef" || m.k === "void") return ixErr(K, C, at, "possibly-undefined", `property ${k} of a value that may be ${show(all)}${UNDEF_FIX}`);
  if (m.k === "unknown") return ixErr(K, C, at, "no-member", `property ${k} on Js/unknown; narrow it first`);
  const i = ixIntrinsicName(K.reg, m);
  if (i) ixUnsup(K, C, at, `intrinsic member ${i}.${k}`);
  else ixErr(K, C, at, "no-member", `no property ${k} on ${show(m)}`);
};

// x["0"] on an array-like is an index read, as in TypeScript
export const ixNumStr = (ixUm, unwrap) => (R: IxReg, e: MemberExpression, ot: Ty): string | null => {
  const p = e.property;
  if (!e.computed || p.type !== "Literal" || typeof p.value !== "string" || !/^(0|[1-9]\d*)$/.test(p.value)) return null;
  const v = p.value;
  return ixUm(R, ot).some((m) => { const x = R.expand(unwrap(m)); return x.k === "arr" || x.k === "tup" || (R.member(x, "length") !== undefined && !R.member(x, v)); }) ? v : null;
};

export const ixMember = (ixPathKey, ixFlowOf, ixCollapseArrays, ixNonNullish, ixNumStr, ixIndex, ixNamedMember, ixGap, nodeKind, lit, UNKNOWN) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: MemberExpression): Ty => {
  const ot0 = K.infer(K, T, V, W, C, env, e.object);
  // d1: a member error is reported at the property, so the note of a binding a nested function assigns goes there too
  const fwn = e.object.type === "Identifier" ? C.fnw.get(e.object.start) : undefined;
  if (fwn !== undefined) C.fnw = new Map([...C.fnw, [e.property.start, fwn]]);
  const k = ixPathKey(V, env, e, false);
  const nt = k ? ixFlowOf(W, C.cur).get(k) : undefined;
  const isShort = e.optional || C.short.has(e.object.nid);
  if (isShort) C.short = new Set([...C.short, e.nid]);
  const ot1 = ixCollapseArrays(K.reg, ot0);
  const ot = isShort ? ixNonNullish(K.reg, ot1) : ot1;
  const p = e.property, num = ixNumStr(K.reg, e, ot);
  let t: Ty;
  if (num !== null) { T.set(p.nid, lit(Number(num))); t = ixIndex(K, C, ot, lit(Number(num)), e, true); }
  else if (e.computed && !(p.type === "Literal" && typeof p.value === "string")) t = ixIndex(K, C, ot, K.infer(K, T, V, W, C, env, p), e, true);
  else if (p.type === "Literal") t = ixNamedMember(K, C, env, e, ot, String(p.value));
  else if (p.type === "Identifier" || p.type === "PrivateIdentifier") t = ixNamedMember(K, C, env, e, ot, p.name);
  else t = ixGap(C, `member property ${nodeKind(p)}`);
  if (K.probe !== null && K.probe.member && C.probe === null && !e.computed && (p.type === "Identifier" || p.type === "PrivateIdentifier") && p.name === K.probe.name) C.probe = { k: "member", t: T.get(e.object.nid) ?? UNKNOWN };
  return nt ?? t;
};

// a member read by name: each member of the object's type, one report per kind of member lacking it
export const ixNamedMember = (ixUm, ixMemberless, ixInActionOnly, ixReportMissing, ixErr, ixFact, propT, isNamed, unwrap, named, union, show, ERR) => (K: IxK, C: IxCtls, env: IxEnv, e: MemberExpression, ot: Ty, name: string): Ty => {
  const out: Mut<Ty[]> = [], missing: Mut<Ty[]> = [];
  let flags: Flags | undefined;
  let bad = false;
  for (const m of ixUm(K.reg, ot)) {
    if (m.k === "err") { bad = true; out.push(ERR); continue; }
    if (ixMemberless(m)) { ixErr(K, C, e, "type", `${show(m)} has no members`); bad = true; continue; }
    if (K.reg.expand(m).k === "err") { bad = true; out.push(ERR); continue; }
    const p = K.reg.member(m, name);
    if (!p) { missing.push(m); bad = true; out.push(ERR); continue; }
    if (isNamed(unwrap(m), "State")) ixInActionOnly(K, C, env, e, "state-write", `State.${name} outside action(...)`);
    if (p.flags?.banned) ixErr(K, C, e, "banned-member", `${K.src.slice(e.object.start, e.object.end)}.${name} is banned`);
    flags = p.flags ?? flags;
    const pt = propT(p);
    out.push(isNamed(m, "Borrowed") && p.flags?.view && !K.reg.callSigs(pt).length ? named("Borrowed", pt) : pt);
  }
  ixReportMissing(K, C, missing, name, e.property);
  C.flagsAt = e.nid;
  C.flags = flags;
  ixFact(C, { k: "flags", at: e.nid, flags: flags ?? null });
  return bad && out.length === 0 ? ERR : union(out);
};

export const ixReportMissing = (ixIntrinsicName, ixMemberMissing, union) => (K: IxK, C: IxCtls, missing: Ty[], name: string, at: AstNode): void => {
  const nullish = (m: Ty) => m.k === "null" || m.k === "undef" || m.k === "void";
  const intr = (m: Ty) => !nullish(m) && m.k !== "unknown" && ixIntrinsicName(K.reg, m) !== null;
  const kinds = [missing.filter(nullish), missing.filter((m) => m.k === "unknown"), missing.filter(intr), missing.filter((m) => !nullish(m) && m.k !== "unknown" && !intr(m))];
  for (const g of kinds) {
    const g0 = g[0];
    if (g0 !== undefined) ixMemberMissing(K, C, g.length === 1 || nullish(g0) ? g0 : union(g), name, at, union(g));
  }
};

// a use that only an action body may make; in a function nested in an action body it is kept for own.ts (the fold
// drops it when the function is an action body by then)
export const ixInActionOnly = (ixErr, ixFact) => (K: IxK, C: IxCtls, env: IxEnv, at: AstNode, rule: string, msg: string): void => {
  if (!env.fi.inAction) ixErr(K, C, at, rule, msg);
  else ixFact(C, { k: "use", fi: env.fi.fid, at: at.nid, rule, msg });
};

// an index read; strict: Registry.strictIndex, which an assignment target turns off
export const ixIndex = (ixUm, ixErr, unwrap, isNamed, show, NUM, STR, UNDEF, ERR, union) => (K: IxK, C: IxCtls, ot: Ty, it: Ty, e: AstNode, strict: boolean): Ty => {
  const R = strict ? K.reg : K.reg.lax, si = strict && K.reg.strictIndex;
  const out: Mut<Ty[]> = [];
  for (const m0 of ixUm(R, ot)) {
    if (m0.k === "err" || it.k === "err") { out.push(ERR); continue; }
    const m = unwrap(m0), x = R.expand(m), numeric = R.sub(it, NUM);
    if (numeric && x.k === "tup" && it.k === "lit" && typeof it.v === "number") {
      const el = x.els[it.v];
      if (el !== undefined) out.push(el);
      else { ixErr(K, C, e, "type", `tuple ${show(x)} has no element ${it.v}`); out.push(ERR); }
      continue;
    }
    if (numeric && (x.k === "arr" || x.k === "tup" || x.k === "str" || (x.k === "lit" && typeof x.v === "string") || R.isTypedArray(x) || isNamed(x, "RegExpMatchArray"))) {
      out.push(R.iterElem(x) ?? ERR);
      if (si) out.push(UNDEF);
      continue;
    }
    const index = x.k === "rec" ? x.index : undefined;
    if (R.sub(it, STR) && index) { out.push(index); if (si) out.push(UNDEF); continue; }
    if (x.k === "null" || x.k === "undef") { ixErr(K, C, e, "possibly-undefined", `index into a value that may be ${show(x)}`); out.push(ERR); continue; }
    ixErr(K, C, e, "type", `cannot index ${show(m)} with ${show(it)}`);
    out.push(ERR);
  }
  return union(out);
};

export const ixExpect = (ixHides, ixErr, ixNonUndef, members, isNamed, show, UNDEF_FIX, forgotWith, extraParamsWith) => (K: IxK, C: IxCtls, at: AstNode, t: Ty, expected: Ty, ctx: boolean): boolean => {
  if (K.reg.sub(t, expected)) return ctx || ixHides(K, C, at, t, expected, null);
  let rule = "type";
  if (K.reg.sub(ixNonUndef(K.reg, t), expected)) rule = "possibly-undefined";
  else if (members(t).some((m) => isNamed(m, "Action")) && !members(expected).some((m) => isNamed(m, "Action"))) rule = "action-pass";
  // w1 (2026-11-24): a failure by the forgetting rule (subtype.ss.ts takesRecord) says what was left out and the fix
  const PR = { isAlias: K.reg.quiet.isAlias, expand: K.reg.quiet.expand, member: K.reg.quiet.member, fnOwn: (n: string) => K.reg.quiet.fnOwn?.(n) === true };
  // open (2026-11-25): a function with a parameter its type does not declare (subtype.ss.ts fnSubWith) is [arity]
  const extra = rule === "type" ? extraParamsWith(PR)(t, expected) : null;
  const why = extra ?? (rule === "type" ? forgotWith(PR)(t, expected) : null);
  if (why !== null) rule = extra !== null ? "arity" : "forgets";
  ixErr(K, C, at, rule, `${show(t)} is not assignable to ${show(expected)}${rule === "possibly-undefined" ? UNDEF_FIX : why !== null ? `: ${why}` : ""}`);
  return false;
};

// { __proto__: v } sets the prototype, as the banned Object.setPrototypeOf does; every spelling of the key is refused
export const ixProtoKey = (ixErr) => (K: IxK, C: IxCtls, p: Property): void => {
  const k = p.key;
  if ((k.type === "Identifier" && k.name === "__proto__") || (k.type === "Literal" && k.value === "__proto__"))
    ixErr(K, C, p, "banned-member", "__proto__ as an object literal key is banned: it sets the prototype (Object.setPrototypeOf), and the prototype's members are not own properties");
};

export const ixInferOp = (ixUnary, ixBinary, ixUpdateExpr, ixLogical, ixConditional, ixAssign) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode): Ty | null => {
  switch (e.type) {
    case "UnaryExpression": return ixUnary(K, T, V, W, C, env, e);
    case "UpdateExpression": return ixUpdateExpr(K, T, V, W, C, env, e);
    case "BinaryExpression": return ixBinary(K, T, V, W, C, env, e);
    case "LogicalExpression": return ixLogical(K, T, V, W, C, env, e);
    case "ConditionalExpression": return ixConditional(K, T, V, W, C, env, e, null);
    case "AssignmentExpression": return ixAssign(K, T, V, W, C, env, e);
    default: return null;
  }
};

// As TypeScript: when the left operand decides the result on every value, the right one adds nothing
export const ixLogicalType = (ixTruthy, ixFalsy, ixNonNullish, ixUm, union) => (R: IxRegCore, op: string, lt: Ty, rt: Ty): Ty => {
  if (op === "&&") return ixTruthy(R, lt).k === "never" ? lt : union([ixFalsy(R, lt), rt]);
  if (op === "||") return ixFalsy(R, lt).k === "never" ? lt : union([ixTruthy(R, lt), rt]);
  return ixUm(R, lt).some((m) => ["null", "undef", "void", "unknown", "tv", "err"].includes(m.k)) ? union([ixNonNullish(R, lt), rt]) : lt;
};

export const ixLogical = (ixLogicalType, ixCopyFlow, ixJoin2, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: LogicalExpression): Ty => {
  const c = K.cond(K, T, V, W, C, env, e.left);
  const own = C.cur, lt = T.get(e.left.nid) ?? ERR;
  C.cur = e.operator === "&&" ? c.t : e.operator === "||" ? c.f : ixCopyFlow(W, C, own);
  const rt = K.infer(K, T, V, W, C, env, e.right);
  C.cur = ixJoin2(W, C, e.operator === "&&" ? c.f : e.operator === "||" ? c.t : own, C.cur);
  return ixLogicalType(K.reg, e.operator, lt, rt);
};

// check1's || and ??: the right side against the expected type, in the flow where it runs, and the part of the left
// side that can be the result (its truthy part, or its non-nullish part)
export const ixCheckLogical = (ixLogicalType, ixExpect, ixCopyFlow, ixJoin2, ERR, NEVER) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: LogicalExpression, expected: Ty, soft: boolean, q: boolean): Ty => {
  const c = K.cond(K, T, V, W, C, env, e.left);
  const lt = T.get(e.left.nid) ?? ERR, kept = ixLogicalType(K.reg, e.operator, lt, NEVER);
  if (!soft && kept.k !== "never") ixExpect(K, C, e.left, kept, expected, q);
  C.cur = e.operator === "||" ? c.f : ixCopyFlow(W, C, C.cur);
  const r = K.check(K, T, V, W, C, env, e.right, expected, false, false);
  C.cur = ixJoin2(W, C, c.t, c.f);
  return ixLogicalType(K.reg, e.operator, lt, r);
};

export const ixConditional = (ixJoin2, union) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: ConditionalExpression, expected: Ty | null): Ty => {
  const c = K.cond(K, T, V, W, C, env, e.test);
  C.cur = c.t;
  const a = K.check(K, T, V, W, C, env, e.consequent, expected, false, false);
  C.cur = c.f;
  const b = K.check(K, T, V, W, C, env, e.alternate, expected, false, false);
  C.cur = ixJoin2(W, C, c.t, c.f);
  return union([a, b]);
};

export const ixNumeric = (ixErr, ixNonUndef, ixFilter, show, UNDEF_FIX, NUM) => (K: IxK, C: IxCtls, at: AstNode, t: Ty): boolean => {
  if (t.k === "err" || K.reg.sub(t, NUM)) return true;
  if (K.reg.sub(ixNonUndef(K.reg, ixFilter(K.reg, t, (m) => m.k !== "null")), NUM)) ixErr(K, C, at, "possibly-undefined", `${show(t)} used as a number${UNDEF_FIX}`);
  else ixErr(K, C, at, "type", `${show(t)} used as a number`);
  return false;
};

// d1 (2026-11-24): a deleted member reads undefined, so delete takes only an optional member or an index-signature entry:
// what else it would remove (an element, a member the type requires, a member of a value that is not a record), or null
export const ixDeleteBad = (ixUm, unwrap) => (R: IxRegCore, ot: Ty, a: MemberExpression): string | null => {
  const p = a.property;
  const key = !a.computed && p.type === "Identifier" ? p.name : a.computed && p.type === "Literal" && (typeof p.value === "string" || typeof p.value === "number") ? String(p.value) : null;
  for (const u of ixUm(R, unwrap(ot))) {
    const m = R.expand(u);
    if (m.k === "arr" || m.k === "tup") return "an element";
    if (m.k !== "rec") return "a member of a value that is not a record";
    const q = key === null ? undefined : m.props.get(key);
    const req = key === null ? [...m.props].find(([, x]) => !x.opt)?.[0] : q !== undefined ? (q.opt ? undefined : key) : m.index ? undefined : key;
    if (req !== undefined) return req;
  }
  return null;
};

export const ixUnary = (ixNumeric, ixRespMut, ixDeleteBad, ixDeleteMsg, ixUnsup, ixErr, isNamed, lit, BOOL, STR, UNDEF, NUM, BIGINT, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: UnaryExpression): Ty => {
  const a = e.argument;
  if (e.operator === "delete") {
    if (a.type !== "MemberExpression") { ixErr(K, C, e, "no-delete", "delete"); return BOOL; }
    const ot = K.infer(K, T, V, W, C, env, a.object);
    if (!isNamed(ot, "Mut") || ixRespMut(ot)) { ixErr(K, C, e, "no-delete", "delete on a value that is not Mut"); return BOOL; }
    K.infer(K, T, V, W, C, env, a);
    const bad = ixDeleteBad(K.reg, ot, a);
    if (bad !== null) ixErr(K, C, e, "no-delete", ixDeleteMsg(bad, a.object.type === "Identifier" ? a.object.name : "o"));
    return BOOL;
  }
  if (e.operator === "!") { K.cond(K, T, V, W, C, env, a); return BOOL; }
  const t = K.infer(K, T, V, W, C, env, a);
  if (t.k === "err" && e.operator !== "typeof") return ERR;
  switch (e.operator) {
    case "typeof": return STR;
    case "void": return UNDEF;
    case "-": case "+": case "~":
      if (e.operator === "-" && a.type === "Literal" && typeof a.value === "number") return lit(-a.value);
      if (e.operator !== "+" && K.reg.sub(t, BIGINT)) return BIGINT;
      if (e.operator !== "+") ixNumeric(K, C, a, t);
      return NUM;
  }
  ixUnsup(K, C, e, `unary ${e.operator}`);
  return ERR;
};

export const ixUpdateExpr = (ixLvalue, ixLookup, ixDropRoot, ixErr, show, NUM) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: UpdateExpression): Ty => {
  const t = ixLvalue(K, T, V, W, C, env, e.argument, e);
  const a = e.argument;
  if (a.type === "Identifier") { const b = ixLookup(V, env, a.name); if (b) ixDropRoot(W, C.cur, b); }
  if (t.k !== "err" && !K.reg.sub(t, NUM)) ixErr(K, C, e, "type", `${e.operator} on ${show(t)}`);
  // open part 5 (LI): x++ is x = x + 1, so the number it stores is checked against x's type
  else if (t.k !== "err" && !K.reg.sub(NUM, t)) ixErr(K, C, e, "type", `${e.operator} stores a number, and number is not assignable to ${show(t)}`);
  return NUM;
};

// TypeScript's "no overlap" comparison error, for operands that are unions of primitives only
export const ixNoOverlap = (ixUm) => (R: IxRegCore, a: Ty, b: Ty): boolean => {
  const prim = (m: Ty) => ["num", "str", "bigint", "null", "undef", "void", "lit"].includes(m.k);
  const ma = ixUm(R, a).map((m) => R.expand(m)), mb = ixUm(R, b).map((m) => R.expand(m));
  if (!ma.every(prim) || !mb.every(prim)) return false;
  const nul = (m: Ty) => m.k === "null" || m.k === "undef" || m.k === "void";
  if (ma.some(nul) || mb.some(nul)) return false;
  return !ma.some((x) => mb.some((y) => R.sub(x, y) || R.sub(y, x)));
};

export const ixOrder = (ixErr, ixNumeric, ixNonUndef, show, STR, BIGINT) => (K: IxK, C: IxCtls, e: BinaryExpression, a: Ty, b: Ty): void => {
  const na = ixNonUndef(K.reg, a), nb = ixNonUndef(K.reg, b);
  const dom = [STR, BIGINT].find((d) => K.reg.sub(na, d) && K.reg.sub(nb, d));
  if (!dom) { ixNumeric(K, C, e.left, a); ixNumeric(K, C, e.right, b); return; }
  const sides: [AstNode, Ty][] = [[e.left, a], [e.right, b]];
  for (const [x, t] of sides) if (!K.reg.sub(t, dom)) ixErr(K, C, x, "possibly-undefined", `${show(t)} compared with ${e.operator}`);
};

export const ixInOp = (ixErr, ixUm, isPrimitive, show, STR) => (K: IxK, C: IxCtls, e: BinaryExpression, a: Ty, b: Ty): void => {
  if (!K.reg.sub(a, STR)) ixErr(K, C, e.left, "type", `in with a ${show(a)} key`);
  for (const m of ixUm(K.reg, b)) {
    if (m.k === "unknown" || m.k === "tv") { ixErr(K, C, e.right, "type", `in on ${show(m)}, which may be a primitive; narrow it with typeof first`); return; }
    if (isPrimitive(m) && m.k !== "err") { ixErr(K, C, e.right, m.k === "null" || m.k === "undef" ? "possibly-undefined" : "type", `in on a value that may be ${show(m)}`); return; }
  }
};

export const ixBinary = (ixErr, ixUnsup, ixNumeric, ixOrder, ixInOp, ixNoOverlap, ixUm, isPrimitive, show, BOOL, STR, NUM, BIGINT, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: BinaryExpression): Ty => {
  const op = e.operator;
  if (op === "instanceof") { ixUnsup(K, C, e, "instanceof"); return BOOL; }
  const a = K.infer(K, T, V, W, C, env, e.left), b = K.infer(K, T, V, W, C, env, e.right);
  if ((a.k === "err" || b.k === "err") && !["===", "!==", "==", "!=", "<", ">", "<=", ">=", "in"].includes(op)) return ERR;
  switch (op) {
    case "===": case "!==": case "==": case "!=":
      if (!ixUm(K.reg, a).every((m) => isPrimitive(m)) && !ixUm(K.reg, b).every((m) => isPrimitive(m))) ixErr(K, C, e, "strict-eq-object", `${op} on two non-primitive operands; use equals(a, b)`);
      else if (ixNoOverlap(K.reg, a, b)) ixErr(K, C, e, "type", `${op} between ${show(a)} and ${show(b)}, which have no value in common`);
      return BOOL;
    case "+":
      if (K.reg.sub(a, STR) || K.reg.sub(b, STR)) return STR;
      if (K.reg.sub(a, BIGINT) && K.reg.sub(b, BIGINT)) return BIGINT;
      ixNumeric(K, C, e.left, a); ixNumeric(K, C, e.right, b);
      return NUM;
    case "<": case ">": case "<=": case ">=": ixOrder(K, C, e, a, b); return BOOL;
    case "in": ixInOp(K, C, e, a, b); return BOOL;
    default:
      if (K.reg.sub(a, BIGINT) && K.reg.sub(b, BIGINT)) return BIGINT;
      ixNumeric(K, C, e.left, a); ixNumeric(K, C, e.right, b);
      return NUM;
  }
};

// a write to obj.x / obj[i] / obj.method(): obj must have type Mut<T>
// e1 (2026-11-23): a value made in the same expression (a literal, or a call or new whose value is fresh) has no other
// name, so it may be written there ([...xs].sort()), as it may once bound to a local (S4.1)
export const ixWriteRule = (ixErr, ixWriteFix, ixRespMut, isNamed, show) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, obj: AstNode, at: AstNode, rule: string): void => {
  const ot = K.infer(K, T, V, W, C, env, obj);
  if (ixRespMut(ot)) { ixErr(K, C, at, rule, "write to a FetchResponse: its members are the response's, not data; read them"); return; }
  if (ot.k === "err" || isNamed(ot, "Mut")) return;
  if (obj.type === "ArrayExpression" || obj.type === "ObjectExpression" || C.freshAt === obj.nid) return;
  ixErr(K, C, at, rule, `write to a ${show(ot)}, which is not Mut; ${ixWriteFix(K, ot, obj, at)}`);
};

// a copy of x (of type t) that the function that makes it may write, as a message writes it
export const ixCopyText = () => (R: IxRegCore, t: Ty, x: string): string => {
  const u0 = R.expand(t), u = u0.k === "union" ? (u0.ts.find((m) => m.k !== "undef" && m.k !== "null") ?? u0) : u0;
  if (u.k === "arr" || u.k === "tup") return `[...${x}]`;
  if (u.k === "named" && (u.n === "Map" || u.n === "Set")) return `new ${u.n}(${x})`;
  return u.k === "rec" ? `{ ...${x} }` : `snapshot(${x})`;
};

export const ixWriteFix = (IX_TWINS, ixCopyText) => (K: IxK, ot: Ty, obj: AstNode, at: AstNode): string => {
  const twins: Map<string, string> = IX_TWINS, x = obj.type === "Identifier" ? obj.name : "x";
  const c = at.type === "CallExpression" ? (at.callee.type === "ChainExpression" ? at.callee.expression : at.callee) : null;
  const name = c !== null && c.type === "MemberExpression" && !c.computed && c.property.type === "Identifier" ? c.property.name : null;
  const made = ixCopyText(K.reg.quiet, ot, x), twin = name === null ? undefined : twins.get(name);
  const idx = at.type === "AssignmentExpression" && at.left.type === "MemberExpression" && at.left.computed && ["arr", "tup"].includes(K.reg.expand(ot).k);
  const copy = `a copy made in the same expression (${made}) or bound to a local (const y = ${made}) is writable`;
  if (twin !== undefined) return `${name} writes its receiver: ${twin} returns a new array instead (${x}.${twin}(...)), or ${copy}`;
  return idx ? `${x}.with(i, v) returns a new array with element i replaced, or ${copy}` : copy;
};

export const ixPropOf = (ixUm, ixMemberless, ixMemberMissing, ixErr, propT, union, show, ERR) => (K: IxK, C: IxCtls, t: Ty, k: string, at: AstNode): Ty => {
  const out: Mut<Ty[]> = [];
  for (const m of ixUm(K.reg, t)) {
    if (m.k === "err") return ERR;
    if (ixMemberless(m)) { ixErr(K, C, at, "type", `${show(m)} has no members`); return ERR; }
    const p = K.reg.member(m, k);
    if (!p) { ixMemberMissing(K, C, m, k, at, m); return ERR; }
    out.push(propT(p));
  }
  return union(out);
};

// an assignment target: its declared type, with the write rules applied
export const ixLvalue = (ixLookup, ixIdent, ixErr, ixUnsup, ixLvalueMember, ixFact, nodeKind, ERR) => {
  function lvalue(K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, t: AstNode, at: AstNode): Ty {
    if (t.type === "Identifier") {
      const b = ixLookup(V, env, t.name);
      if (!b) { ixIdent(K, T, V, W, C, env, t); return ERR; }
      ixFact(C, { k: "bind", at: t.nid, id: b.id });
      if (b.kind !== "let" && b.kind !== "param") { ixErr(K, C, at, "const-assign", `assignment to ${b.kind} ${t.name}`); return ERR; }
      return b.t;
    }
    if (t.type === "MemberExpression") return ixLvalueMember(K, T, V, W, C, env, t, at);
    if (t.type === "ArrayPattern" || t.type === "ObjectPattern") {
      const parts = t.type === "ArrayPattern" ? t.elements : t.properties.map((p) => (p.type === "Property" ? p.value : p));
      for (const p of parts) if (p !== null) lvalue(K, T, V, W, C, env, p.type === "AssignmentPattern" ? p.left : p, at);
      ixUnsup(K, C, t, "destructuring assignment");
      return ERR;
    }
    ixUnsup(K, C, t, `assignment target ${nodeKind(t)}`);
    return ERR;
  }
  return lvalue;
};

// open part 6 (HO): an index or length write, and whether the run time checks it: each one but a write to a receiver
// whose type is a typed array in every member. One entry per target, by position, as the compiler finds them (tcHoleSites)
export const ixHoleSite = (ixUm) => (K: IxK, C: IxCtls, t: MemberExpression, ot: Ty): void => {
  const p = t.property;
  if (!t.computed && !(p.type === "Identifier" && p.name === "length")) return;
  const typed = new Set(["Float32Array", "Float64Array", "Int8Array", "Uint8Array", "Uint8ClampedArray", "Int16Array", "Uint16Array", "Int32Array", "Uint32Array"]);
  const un = (x: Ty): Ty[] => ixUm(K.reg, x).flatMap((m) => (m.k === "named" && (m.n === "Mut" || m.n === "Borrowed") && m.args[0] !== undefined ? un(m.args[0]) : [K.reg.expand(m)]));
  const check = !un(ot).every((m) => m.k === "named" && typed.has(m.n));
  const was = C.holes.find((x) => x[0] === t.start);
  C.holes = [...C.holes.filter((x) => x[0] !== t.start), [t.start, check || (was !== undefined && was[1])]];
};

export const ixLvalueMember = (ixWriteRule, ixIndex, ixPropOf, ixGap, ixHoleSite, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, t: MemberExpression, at: AstNode): Ty => {
  ixWriteRule(K, T, V, W, C, env, t.object, at, "member-write");
  const ot = T.get(t.object.nid) ?? ERR, p = t.property;
  ixHoleSite(K, C, t, ot);
  let r: Ty;
  if (t.computed && !(p.type === "Literal" && typeof p.value === "string")) r = ixIndex(K, C, ot, K.infer(K, T, V, W, C, env, p), t, false);
  else if (p.type === "Literal") r = ixPropOf(K, C, ot, String(p.value), p);
  else if (p.type === "Identifier") r = ixPropOf(K, C, ot, p.name, p);
  else r = ixGap(C, "assignment to a member that is not named");
  T.set(t.nid, r);
  return r;
};

export const ixCompound = (ixUnsup, ixNumeric, STR, NUM, ERR) => (K: IxK, C: IxCtls, e: AssignmentExpression, cur: Ty, r: Ty): Ty => {
  const op = e.operator.slice(0, -1);
  if (op === "+" && (K.reg.sub(cur, STR) || K.reg.sub(r, STR))) return STR;
  if (op === "&&" || op === "||" || op === "??") { ixUnsup(K, C, e, `logical assignment ${e.operator}`); return ERR; }
  ixNumeric(K, C, e.left, cur); ixNumeric(K, C, e.right, r);
  return NUM;
};

export const ixAssign = (IX_MUTATING_OPS, ixLookup, ixLvalue, ixIdent, ixCompound, ixExpect, ixDropRoot, ixFlowSet, ixUnsup, named, isNamed, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AssignmentExpression): Ty => {
  if (!IX_MUTATING_OPS.has(e.operator)) { ixUnsup(K, C, e, `assignment ${e.operator}`); return ERR; }
  const l = e.left, b = l.type === "Identifier" ? ixLookup(V, env, l.name) : undefined;
  const decl = ixLvalue(K, T, V, W, C, env, l, e);
  let v: Ty;
  if (e.operator === "=") v = K.check(K, T, V, W, C, env, e.right, decl.k === "err" ? null : decl, false, false);
  else {
    const cur = l.type === "Identifier" ? ixIdent(K, T, V, W, C, env, l) : decl;
    v = ixCompound(K, C, e, cur, K.infer(K, T, V, W, C, env, e.right));
    if (decl.k !== "err") ixExpect(K, C, e, v, decl, false);
  }
  if (b && decl.k !== "err") {
    ixDropRoot(W, C.cur, b);
    // S4.1: a fresh value assigned to an annotated let that a fresh initializer made writable keeps it writable
    const fresh = b.kind === "let" && b.mutOwned && e.operator === "=" && v.k !== "err" && !isNamed(decl, "Mut") && K.reg.expand(decl).k !== "union" && !isNamed(v, "Mut") && (e.right.type === "ArrayExpression" || e.right.type === "ObjectExpression" || C.freshAt === e.right.nid);
    ixFlowSet(W, C.cur, "#" + b.id, fresh ? named("Mut", decl) : K.reg.sub(v, decl) ? v : decl);
  }
  return v;
};

export const ixCond = (ixCondLeaf, ixCondLogical, BOOL) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode): IxCond => {
  if (e.type === "UnaryExpression" && e.operator === "!") {
    const c = K.cond(K, T, V, W, C, env, e.argument);
    T.set(e.nid, BOOL);
    return { t: c.f, f: c.t };
  }
  if (e.type === "LogicalExpression" && (e.operator === "&&" || e.operator === "||")) return ixCondLogical(K, T, V, W, C, env, e);
  const t = K.infer(K, T, V, W, C, env, e);
  return ixCondLeaf(K, T, V, W, C, env, e, t);
};

export const ixCondLogical = (ixLogicalType, ixJoin2, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: LogicalExpression): IxCond => {
  const l = K.cond(K, T, V, W, C, env, e.left);
  const own = C.cur;
  C.cur = e.operator === "&&" ? l.t : l.f;
  const r = K.cond(K, T, V, W, C, env, e.right);
  C.cur = own;
  T.set(e.nid, ixLogicalType(K.reg, e.operator, T.get(e.left.nid) ?? ERR, T.get(e.right.nid) ?? ERR));
  return e.operator === "&&" ? { t: r.t, f: ixJoin2(W, C, l.f, r.f) } : { t: ixJoin2(W, C, l.t, r.t), f: r.f };
};

// where an optional chain's value cannot be undefined on this branch, no ?. link short-circuited
export const ixChainLinks = (ixPathKey, ixExclusion, ixNonNullish, NEVER) => (K: IxK, T: IxTypes, V: IxVars, env: IxEnv, M: Mut<IxFlow>, n: ChainExpression): void => {
  for (let x = n.expression; x.type === "MemberExpression" || x.type === "CallExpression"; x = x.type === "MemberExpression" ? x.object : x.callee) {
    const o = x.optional ? (x.type === "MemberExpression" ? x.object : x.callee) : null;
    const ok = o === null ? null : ixPathKey(V, env, o, true);
    const ot = o === null || ok === null ? undefined : M.get(ok) ?? T.get(o.nid);
    if (ok === null || ot === undefined) continue;
    M.set(ixExclusion("null", ok), NEVER);
    M.set(ixExclusion("undef", ok), NEVER);
    M.set(ok, ixNonNullish(K.reg, ot));
  }
};

// one branch's narrowing of path k: what the test cannot pass on is excluded, then the path's type is narrowed
export const ixNarrowSide = (ixExclusion, ixFilter, NULL, UNDEF, NEVER) => (K: IxK, M: Mut<IxFlow>, k: string, nt: Ty, by: IxBy, br: boolean): void => {
  for (const x of [NULL, UNDEF]) if (by(x, br).k === "never") M.set(ixExclusion(x.k, k), NEVER);
  const noNull = M.has(ixExclusion("null", k)), noUndef = M.has(ixExclusion("undef", k));
  M.set(k, ixFilter(K.reg, by(nt, br), (m) => !(m.k === "null" ? noNull : (m.k === "undef" || m.k === "void") && noUndef)));
};

export const ixNarrow = (ixChainLinks, ixNarrowSide, ixPathKey, UNDEF) => (K: IxK, T: IxTypes, V: IxVars, env: IxEnv, TT: Mut<IxFlow>, FF: Mut<IxFlow>, n: AstNode, nt: Ty | undefined, by: IxBy): void => {
  if (n.type === "ChainExpression") {
    if (by(UNDEF, true).k === "never") ixChainLinks(K, T, V, env, TT, n);
    if (by(UNDEF, false).k === "never") ixChainLinks(K, T, V, env, FF, n);
  }
  const k = ixPathKey(V, env, n, false);
  if (k === null || nt === undefined) return;
  ixNarrowSide(K, TT, k, nt, by, true);
  ixNarrowSide(K, FF, k, nt, by, false);
};

// P.f's test also narrows P to the members whose f can pass it
export const ixDiscriminant = (ixNarrow, ixNarrowByProp) => (K: IxK, T: IxTypes, V: IxVars, env: IxEnv, TT: Mut<IxFlow>, FF: Mut<IxFlow>, m0: AstNode, can: (pt: Ty, branch: boolean) => boolean): void => {
  const m = m0.type === "ChainExpression" ? m0.expression : m0;
  if (m.type !== "MemberExpression" || m.computed || m.property.type !== "Identifier") return;
  const name = m.property.name;
  ixNarrow(K, T, V, env, TT, FF, m.object, T.get(m.object.nid), (ot, branch) => ixNarrowByProp(K.reg, ot, name, (pt) => can(pt, branch)));
};

// typeof x === "tag", in either order
export const ixTypeofTest = () => (a: AstNode, b: AstNode): { arg: AstNode; tag: string } | null =>
  a.type === "UnaryExpression" && a.operator === "typeof" && b.type === "Literal" && typeof b.value === "string" ? { arg: a.argument, tag: b.value } : null;

export const ixNarrowCompare = (ixNarrow, ixDiscriminant, ixNarrowTypeof, ixNarrowEq, ixTypeofTest) => (K: IxK, T: IxTypes, V: IxVars, env: IxEnv, TT: Mut<IxFlow>, FF: Mut<IxFlow>, e: BinaryExpression): void => {
  const pos = e.operator === "===" || e.operator === "==", loose = e.operator.length === 2;
  const tag = ixTypeofTest(e.left, e.right) ?? ixTypeofTest(e.right, e.left);
  if (tag) return ixNarrow(K, T, V, env, TT, FF, tag.arg, T.get(tag.arg.nid), (pt, br) => ixNarrowTypeof(K.reg, pt, tag.tag, br === pos));
  const sides: [AstNode, AstNode][] = [[e.left, e.right], [e.right, e.left]];
  for (const [a, b] of sides) {
    const bt = T.get(b.nid);
    // open part 5 (LE): == and != narrow by null and undefined only; a loose test of a literal converts the other side
    if (!bt || (bt.k !== "lit" && bt.k !== "null" && bt.k !== "undef") || (loose && bt.k === "lit")) continue;
    ixNarrow(K, T, V, env, TT, FF, a, T.get(a.nid), (at, br) => ixNarrowEq(K.reg, at, bt, br === pos, loose));
    ixDiscriminant(K, T, V, env, TT, FF, a, (pt, br) => ixNarrowEq(K.reg, pt, bt, br === pos, loose).k !== "never");
    return;
  }
};

// Array.isArray(x), where Array is the global
export const ixIsArrayTest = (ixLookup) => (V: IxVars, env: IxEnv, e: AstNode): AstNode | null => {
  if (e.type !== "CallExpression" || e.arguments.length !== 1) return null;
  const c = e.callee;
  if (c.type !== "MemberExpression" || c.computed || c.object.type !== "Identifier" || c.object.name !== "Array") return null;
  if (c.property.type !== "Identifier" || c.property.name !== "isArray" || ixLookup(V, env, "Array")?.kind !== "global") return null;
  return e.arguments[0] ?? null;
};

export const ixCondLeaf = (ixNarrow, ixDiscriminant, ixNarrowCompare, ixIsArrayTest, ixNarrowIn, ixNarrowArray, ixTruthy, ixFalsy, ixFlowOf, ixNewFlow) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode, t: Ty): IxCond => {
  const TT: Mut<IxFlow> = new Map(ixFlowOf(W, C.cur)), FF: Mut<IxFlow> = new Map(ixFlowOf(W, C.cur));
  const arrayArg = ixIsArrayTest(V, env, e);
  if (e.type === "BinaryExpression" && ["===", "!==", "==", "!="].includes(e.operator)) ixNarrowCompare(K, T, V, env, TT, FF, e);
  else if (e.type === "BinaryExpression" && e.operator === "in" && e.left.type === "Literal" && typeof e.left.value === "string") {
    const key = e.left.value;
    ixNarrow(K, T, V, env, TT, FF, e.right, T.get(e.right.nid), (rt, br) => ixNarrowIn(K.reg, rt, key, br));
  } else if (arrayArg !== null) ixNarrow(K, T, V, env, TT, FF, arrayArg, T.get(arrayArg.nid), (at, br) => ixNarrowArray(K.reg, at, br));
  else {
    ixNarrow(K, T, V, env, TT, FF, e, t, (x, br) => (br ? ixTruthy(K.reg, x) : ixFalsy(K.reg, x)));
    ixDiscriminant(K, T, V, env, TT, FF, e, (pt, br) => (br ? ixTruthy(K.reg, pt) : ixFalsy(K.reg, pt)).k !== "never");
  }
  return { t: ixNewFlow(W, C, TT), f: ixNewFlow(W, C, FF) };
};

export const ixAnnOf = () => (p: AstNode): AstNode | null => {
  const id = p.type === "AssignmentPattern" ? p.left : p;
  const a = id.type === "Identifier" || id.type === "ObjectPattern" || id.type === "ArrayPattern" || id.type === "RestElement" ? id.typeAnnotation : null;
  return a !== null && a.type === "TSTypeAnnotation" ? a.typeAnnotation : null;
};

// the names of a type parameter declaration
export const ixTpNames = () => (n: AstNode | null): string[] =>
  n === null || n.type !== "TSTypeParameterDeclaration" ? [] : n.params.flatMap((x) => (x.type === "TSTypeParameter" ? [x.name] : []));

// the fields fnExpr reads, for the three function node types
export const ixFnParts = () => (e: AstNode): IxFnParts | null => {
  if (e.type === "ArrowFunctionExpression") return { params: e.params, body: e.body, returnType: e.returnType, typeParameters: e.typeParameters, id: null, async: e.async, generator: e.generator, decl: false };
  if (e.type === "FunctionExpression") return { params: e.params, body: e.body, returnType: e.returnType, typeParameters: e.typeParameters, id: e.id, async: e.async, generator: e.generator, decl: false };
  if (e.type === "FunctionDeclaration") return { params: e.params, body: e.body, returnType: e.returnType, typeParameters: e.typeParameters, id: e.id, async: e.async, generator: e.generator, decl: true };
  return null;
};

// the names assignments and updates under n write (patternNames over the left sides)
export const ixAssignedNames = (kidsOf) => (n: AstNode): Set<string> => {
  const out: Mut<Set<string>> = new Set();
  const names = (p: AstNode | null): void => {
    if (p === null) return;
    if (p.type === "Identifier") out.add(p.name);
    else if (p.type === "ArrayPattern") for (const x of p.elements) names(x);
    else if (p.type === "ObjectPattern") for (const x of p.properties) names(x.type === "RestElement" ? x.argument : x.type === "Property" ? x.value : null);
    else if (p.type === "AssignmentPattern") names(p.left);
    else if (p.type === "RestElement") names(p.argument);
  };
  const walk = (x: AstNode): void => {
    if (x.type === "AssignmentExpression") names(x.left);
    if (x.type === "UpdateExpression" && x.argument.type === "Identifier") out.add(x.argument.name);
    for (const k of kidsOf(x)) walk(k);
  };
  walk(n);
  return out;
};

// a function whose parameters and return type are all annotated has a signature before its body is checked
export const ixAnnotatedSig = (ixFnParts, ixAnnOf, ixDrain, ixTps, ixLookTable, isNamed, named) => (K: IxK, V: IxVars, C: IxCtls, env: IxEnv, e: AstNode): Fn | null => {
  const f = ixFnParts(e);
  if (f === null || f.returnType === null || f.typeParameters !== null || f.params.some((p) => ixAnnOf(p) === null)) return null;
  const ret = f.returnType;
  if (ret.type !== "TSTypeAnnotation") return null;
  const look = [...f.params, ret].some((p) => K.reg.hasTypeQuery(p)) ? ixLookTable(V, env) : null;
  ixDrain(K, C);
  const sig = K.reg.sig(f.params, ret.typeAnnotation, ixTps(env), look);
  K.reg.drain();
  return f.async && !f.generator && !isNamed(K.reg.expand(sig.ret), "Promise") ? { ...sig, ret: named("Promise", sig.ret) } : sig;
};

// the narrowings a closure keeps: those of const roots, functions and parameters never assigned
export const ixClosureFlow = (ixFlowOf, ixPathOf, ixFindBinding) => (V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv): IxFlow => {
  const out: Mut<IxFlow> = new Map();
  for (const [k, t] of ixFlowOf(W, C.cur)) {
    const id = Number(ixPathOf(k).slice(1).split(".")[0]);
    const b = ixFindBinding(V, env, id);
    if (b && (b.kind === "const" || b.kind === "fn" || (b.kind === "param" && !b.assigned))) out.set(k, t);
  }
  return out;
};

// a returned value, checked against the return context
// e1 (2026-11-23), B4: an async function that returns a promise resolves to what the promise resolves to, as await does
export const ixReturned = (ixAwaited, members, isNamed, named, union) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode): Ty => {
  const fi = env.fi, r = fi.retCtx, ctx = r !== null && fi.isAsync && !fi.isGen ? union([r, named("Promise", r)]) : r;
  const t = K.check(K, T, V, W, C, env, e, ctx, false, fi.retFromCtx);
  if (fi.isAsync && !fi.isGen && members(K.reg.expand(t)).some((m) => isNamed(K.reg.expand(m), "Promise"))) return ixAwaited(K.reg, t, false);
  return t;
};

// Function declarations are hoisted: bound first, their bodies checked in order (or on the first read)
// w1 (2026-11-24, S-1): each name a const or let of the block declares is bound first too, as a later binding, so a
// read before its declaration (in the block or in a function made there) is that binding and not one outside
export const ixLaterNames = () => (s: AstNode): Identifier[] => {
  const out: Mut<Identifier[]> = [];
  const pat = (p: AstNode | null): void => {
    if (p === null) return;
    if (p.type === "Identifier") out.push(p);
    else if (p.type === "ObjectPattern") { for (const x of p.properties) pat(x.type === "Property" ? x.value : x.type === "RestElement" ? x.argument : null); }
    else if (p.type === "ArrayPattern") { for (const x of p.elements) pat(x); }
    else if (p.type === "AssignmentPattern") pat(p.left);
    else if (p.type === "RestElement") pat(p.argument);
  };
  if (s.type === "VariableDeclaration" && s.kind !== "var") for (const d of s.declarations) if (d.type === "VariableDeclarator") pat(d.id);
  return out;
};

export const ixHoist = (ixAnnotatedSig, ixDeclare, ixNoExtra, ixLaterNames, ixAnnOf, ERR) => (K: IxK, V: IxVars, C: IxCtls, env: IxEnv, body: AstNode[]): void => {
  for (const s of body) for (const id of ixLaterNames(s)) {
    // p3 (2026-11-25): a const bound to an arrow or function expression, with no type on its name, can be read before
    // its declaration where ixFwdSafe allows; that read and the declaration are this one binding
    const d = s.type === "VariableDeclaration" && s.kind === "const" ? s.declarations.find((x) => x.type === "VariableDeclarator" && x.id.nid === id.nid) : undefined;
    const fn = d !== undefined && d.type === "VariableDeclarator" && ixAnnOf(id) === null && d.init !== null && (d.init.type === "ArrowFunctionExpression" || d.init.type === "FunctionExpression") ? d.init : null;
    ixDeclare(V, C, env, id.name, ERR, "const", id, ixNoExtra, { k: "later", at: id, fn, env, body, busy: false }, false, fn === null ? -1 : fn.nid);
  }
  for (const s of body) {
    if (s.type !== "FunctionDeclaration" || s.id.type !== "Identifier") continue;
    const sig = ixAnnotatedSig(K, V, C, env, s);
    ixDeclare(V, C, env, s.id.name, sig ?? ERR, "fn", s.id, ixNoExtra, sig ? { k: "none" } : { k: "hoist", fn: s, env, busy: false }, false, s.nid);
  }
};

// p3 (2026-11-25): the reads of name in the statements of a block: each identifier named name (a JSX tag name too),
// except a member's or a key's name and the identifier at nid skip (the name's declaration)
export const ixFwdUses = (kidsOf) => (body: readonly AstNode[], name: string, skip: number): AstNode[] => {
  const out: Mut<AstNode[]> = [];
  const walk = (n: AstNode): void => {
    for (const k of kidsOf(n)) {
      const key = n.type === "MemberExpression" ? !n.computed && n.property.nid === k.nid : (n.type === "Property" || n.type === "MethodDefinition") && !n.computed && n.key.nid === k.nid && n.value.nid !== k.nid;
      if ((k.type === "Identifier" || k.type === "JSXIdentifier") && k.name === name && k.nid !== skip && !key) out.push(k);
      walk(k);
    }
  };
  for (const s of body) walk(s);
  return out;
};

// p3 (2026-11-25, S2.6): a read e of g, a const function declared later in the block, is safe inside the body of a
// function f bound to a const before g when nothing can call f before g is declared: f is used before g's declarator
// only inside its own body or the body of another such function that is safe the same way, and in no function
// declaration of the block. null: safe; "": e is not inside such a body; else the function whose use is not safe
export const ixFwdSafe = (ixFwdUses) => (body: readonly AstNode[], g: AstNode, e: AstNode): string | null => {
  const fns: Mut<Map<string, { readonly id: number; readonly init: AstNode }>> = new Map(), decls = body.filter((s) => s.type === "FunctionDeclaration");
  const ins = (x: AstNode, n: AstNode): boolean => x.start <= n.start && n.end <= x.end;
  const gd = body.flatMap((s) => (s.type === "VariableDeclaration" ? s.declarations : [])).find((d) => d.type === "VariableDeclarator" && d.id.nid === g.nid);
  if (gd === undefined || gd.type !== "VariableDeclarator" || gd.init === null || ins(gd.init, e)) return gd === undefined ? "" : null;
  for (const s of body) if (s.type === "VariableDeclaration" && s.kind === "const") for (const d of s.declarations) {
    if (d.type === "VariableDeclarator" && d.id.type === "Identifier" && d.start < gd.start && d.init !== null && (d.init.type === "ArrowFunctionExpression" || d.init.type === "FunctionExpression")) fns.set(d.id.name, { id: d.id.nid, init: d.init });
  }
  const host = [...fns.entries()].find(([, d]) => ins(d.init, e));
  const bad = (name: string, seen: readonly string[]): string | null => {
    if (seen.includes(name)) return null;
    for (const r of ixFwdUses(body, name, fns.get(name)?.id ?? -1)) {
      const h = [...fns.entries()].find(([, d]) => ins(d.init, r));
      const w = h !== undefined ? bad(h[0], [...seen, name]) : decls.some((s) => ins(s, r)) || r.start < gd.start ? name : null;
      if (w !== null) return w;
    }
    return null;
  };
  return host === undefined ? "" : bad(host[0], []);
};

// p3 (2026-11-25): why a read before a declaration is refused (ixFwdSafe's why; fn: the later binding is a function)
export const ixFwdWhy = () => (name: string, why: string, fn: boolean): string => {
  const base = `${name} is read before its declaration in the same block: a const or let is in scope for its whole block, so this reads that declaration, not a binding outside it; move the declaration above this read, or give one of the two another name`;
  if (why !== "") return `${name} is read before its declaration in the same block, a call of ${why} leads to this read, and ${why} is used before ${name} is declared, so that use could run this read before ${name} exists; do not use ${why} before the declaration of ${name}, or move the declaration of ${name} above this read`;
  return fn ? `${base}; a function bound to a const can be read before its declaration only inside the body of a function bound to a const before it that nothing uses before the declaration` : base;
};

// a named function expression is bound in its own scope, so its body can call it (with annotations)
export const ixSelfName = (ixAnnotatedSig, ixDeclare, ixNoExtra, ERR) => (K: IxK, V: IxVars, C: IxCtls, inner: IxEnv, e: AstNode, f: IxFnParts): void => {
  const fid = f.id;
  if (f.decl || fid === null || fid.type !== "Identifier") return;
  const pre = ixAnnotatedSig(K, V, C, inner, e);
  ixDeclare(V, C, inner, fid.name, pre ?? ERR, "fn", fid, ixNoExtra, pre ? { k: "none" } : { k: "unsup", at: e }, false, e.nid);
};

export const ixTpBounds = (ixUnsup) => (K: IxK, C: IxCtls, f: IxFnParts): void => {
  const tp = f.typeParameters;
  if (tp === null || tp.type !== "TSTypeParameterDeclaration") return;
  for (const x of tp.params) if (x.type === "TSTypeParameter" && (x.constraint !== null || x.default !== null)) ixUnsup(K, C, x, "type parameter constraint/default");
};

// d1 (2026-11-24): the names assigned inside the functions nested anywhere in n (hoisted declarations, functions in
// initialisers, object-literal methods, at any depth): a let or parameter of that name is not narrowed (S3.11)
export const ixNestedAssigned = (ixAssignedNames, kidsOf) => (n: AstNode): Set<string> => {
  const out: Mut<Set<string>> = new Set();
  const walk = (x: AstNode): void => {
    if (x.type === "ArrowFunctionExpression" || x.type === "FunctionExpression" || x.type === "FunctionDeclaration") { for (const s of ixAssignedNames(x)) out.add(s); return; }
    for (const k of kidsOf(x)) walk(k);
  };
  walk(n);
  return out;
};

export const ixFnExpr = (ixFnParts, ixClosureFlow, ixNewFlow, ixSelfName, ixTpBounds, ixAssignedNames, ixNestedAssigned, ixParams, ixRetCtx, ixFnBody, ixFnRet, ixTpNames, ixGap) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv | null, e: AstNode, expected: Ty | null, injected: Ty[] | null): Ty => {
  const f = ixFnParts(e);
  if (f === null) return ixGap(C, `function node ${e.type}`);
  const ctxSig = expected === null ? undefined : K.reg.callSigs(expected).filter((s) => !s.tps.length)[0];
  const fi0: IxFnCtx = { fid: e.nid, parent: env?.fi ?? null, isAsync: f.async, isGen: f.generator, isCell: injected !== null, inAction: !!env?.fi.inAction, retCtx: null, retFromCtx: false, yieldCtx: null, tps: ixTpNames(f.typeParameters), writes: ixNestedAssigned(f.body), assigns: ixAssignedNames(f.body) };
  const own = C.cur, rets = C.rets, yields = C.yields;
  C.cur = ixNewFlow(W, C, env === null ? new Map() : ixClosureFlow(V, W, C, env));
  C.rets = [];
  C.yields = [];
  C.nextScope += 1;
  const inner0: IxEnv = { scope: C.nextScope, up: env === null ? { id: 0, up: null } : { id: env.scope, up: env.up }, fi: fi0, dead: false };
  ixSelfName(K, V, C, inner0, e, f);
  const ps = ixParams(K, T, V, W, C, inner0, f.params, ctxSig, injected, ixAssignedNames(f.body));
  const rc = ixRetCtx(K, T, V, W, C, inner0, f, ctxSig);
  const inner: IxEnv = { ...inner0, fi: rc.fi };
  const reachable = ixFnBody(K, T, V, W, C, inner, f.body);
  const ret = ixFnRet(K, C, e, f, rc, reachable);
  ixTpBounds(K, C, f);
  C.cur = own;
  C.rets = rets;
  C.yields = yields;
  return { k: "fn", tps: ixTpNames(f.typeParameters), ps: ps.ps, rest: ps.rest, ret };
};

export const ixFnBody = (ixHoist, ixStmts, ixReturned) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, body: AstNode): boolean => {
  if (body.type === "BlockStatement") {
    ixHoist(K, V, C, env, body.body);
    return ixStmts(K, T, V, W, C, env, body.body);
  }
  const t = ixReturned(K, T, V, W, C, env, body);
  C.rets = [...C.rets, t];
  return false;
};

export const ixParams = (ixParam) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, params: AstNode[], ctxSig: Fn | undefined, injected: Ty[] | null, assigned: Set<string>): IxParamsOut => {
  const ps: Mut<Param[]> = [];
  let rest: Ty | undefined;
  for (const [i, p] of params.entries()) {
    const r = ixParam(K, T, V, W, C, env, p, i, ctxSig, injected, assigned);
    if (r.rest) rest = r.t;
    else ps.push({ n: r.n, t: r.t, opt: r.opt });
  }
  return { ps: ps, rest };
};

// one parameter: its type from the annotation, the cell's injection or the context; then bound
export const ixParamType = (ixAnnOf, ixConvert, ixErr, show, arr, UNKNOWN, UNDEF, ERR) => (K: IxK, V: IxVars, C: IxCtls, env: IxEnv, p: AstNode, i: number, ctxSig: Fn | undefined, injected: Ty[] | null): Ty => {
  const ann = ixAnnOf(p);
  let t: Ty;
  if (ann !== null) t = ixConvert(K, V, env, ann);
  else if (injected !== null) t = injected[i] ?? ERR;
  else if (ctxSig) {
    if (i >= ctxSig.ps.length && !ctxSig.rest && p.type !== "RestElement") ixErr(K, C, p, "arity", `callback takes more parameters than its context provides: remove the parameters after the first ${ctxSig.ps.length}`);
    t = p.type === "RestElement" ? arr(ctxSig.rest ?? UNKNOWN) : (ctxSig.ps[i]?.t ?? ctxSig.rest ?? UNDEF);
  } else { ixErr(K, C, p, "untyped-parameter", "parameter has no type and no contextual type"); t = ERR; }
  const ct = ctxSig && ann !== null && injected === null ? ctxSig.ps[i]?.t : undefined;
  if (ct && !K.reg.sub(ct, t)) ixErr(K, C, p, "type", `parameter ${show(t)} does not accept ${show(ct)}`);
  return t;
};

export const ixParam = (ixParamType, union, UNDEF, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, p: AstNode, i: number, ctxSig: Fn | undefined, injected: Ty[] | null, assigned: Set<string>): { n: string; t: Ty; opt: boolean; rest: boolean } => {
  const t = ixParamType(K, V, C, env, p, i, ctxSig, injected);
  if (p.type === "RestElement") {
    K.bind(K, T, V, W, C, env, p.argument, t, "param", { assigned: false, cellParam: false });
    return { n: "", t: t.k === "arr" ? t.el : ERR, opt: false, rest: true };
  }
  const optional = p.type === "Identifier" && p.optional === true;
  const pt = optional ? union([t, UNDEF]) : t;
  const id = p.type === "AssignmentPattern" ? p.left : p;
  if (id.type === "Identifier") K.bind(K, T, V, W, C, env, p, pt, "param", { cellParam: injected !== null, assigned: assigned.has(id.name) });
  else K.bind(K, T, V, W, C, env, p, t, "param", { assigned: true, cellParam: false });
  return { n: p.type === "Identifier" ? p.name : `p${i}`, t: pt, opt: p.type === "AssignmentPattern" || optional, rest: false };
};

// the return annotation, checked against async and generator, and the context the body's returns are checked against
export const ixRetCtx = (ixConvert, ixErr, ixAwaited, hasTv, isNamed, named, show, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, f: IxFnParts, ctxSig: Fn | undefined): IxRetCtx => {
  const fi = env.fi, rt = f.returnType;
  let retAnn: Ty | null = rt !== null && rt.type === "TSTypeAnnotation" ? ixConvert(K, V, env, rt.typeAnnotation) : null;
  let yieldCtx: Ty | null = null;
  if (rt !== null && retAnn !== null && fi.isAsync && !fi.isGen && retAnn.k !== "err" && !isNamed(K.reg.expand(retAnn), "Promise")) {
    ixErr(K, C, rt, "type", `an async function returns a Promise; its return type ${show(retAnn)} is not Promise<…>`);
    retAnn = named("Promise", retAnn);
  }
  if (rt !== null && retAnn !== null && fi.isGen && retAnn.k !== "err") {
    const g = K.reg.expand(retAnn);
    if (g.k === "named" && g.n === "Generator") yieldCtx = g.args[0] ?? null;
    else { ixErr(K, C, rt, "type", `a generator function returns a Generator; its return type ${show(retAnn)} is not Generator<…>`); retAnn = ERR; }
  }
  const ctxRet = retAnn === null && ctxSig && !hasTv(ctxSig.ret) ? ctxSig.ret : null;
  const declared = retAnn ?? ctxRet;
  // x1 (2026-11-24, V): a void result, declared or from the context, checks each return: void takes undefined only
  const retCtx = declared !== null && !fi.isGen ? (fi.isAsync ? ixAwaited(K.reg, declared, true) : declared) : null;
  return { fi: { ...fi, retCtx, yieldCtx, retFromCtx: retAnn === null && ctxRet !== null }, retAnn, ctxRet, declared };
};

// the function's return type: its annotation, or what its returns and yields give
export const ixFnRet = (ixErr, union, widen, named, show, UNDEF, VOID, NEVER) => (K: IxK, C: IxCtls, e: AstNode, f: IxFnParts, rc: IxRetCtx, reachable: boolean): Ty => {
  const fi = rc.fi, retAnn = rc.retAnn, rets = C.rets;
  if (fi.isGen) {
    const y = union(C.yields);
    return retAnn ?? named("Generator", y.k === "never" ? UNDEF : rc.ctxRet ? y : widen(y));
  }
  const r0 = union(reachable && rets.length ? [...rets, UNDEF] : rets.length ? rets : [reachable ? VOID : NEVER]);
  const r = rc.declared === null ? widen(r0) : r0;
  // open part 5 (AR): an async function's ending return is checked against the T of its Promise<T>
  const want = fi.isAsync ? (retAnn ? fi.retCtx : null) : retAnn;
  if (want && want.k !== "void" && reachable && f.body.type === "BlockStatement" && want.k !== "err" && !K.reg.sub(UNDEF, want) && want.k !== "never")
    ixErr(K, C, e, "type", `function lacks an ending return statement and its return type ${show(retAnn ?? want)} does not include undefined`);
  return fi.isAsync ? (retAnn ?? named("Promise", r)) : (retAnn ?? (rc.ctxRet && rc.ctxRet.k === "void" ? VOID : r));
};

// await: a member that may be a thenable other than a Promise gives unknown; declared: an async function's return
// annotation, where the member is the type returned, not awaited
export const ixAwaited = (ixUm, union, UNKNOWN) => (R: IxRegCore, t: Ty, declared: boolean): Ty =>
  union(ixUm(R, t).map((m) => (m.k === "named" && m.n === "Promise" ? m.args[0] ?? m : !declared && (m.k === "object" || R.member(m, "then")) ? UNKNOWN : m)));

export const ixStmts = (ixCopyFlow) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, list: AstNode[]): boolean => {
  let live = true;
  for (const s of list) {
    if (live) { live = K.stmt(K, T, V, W, C, env, s); continue; }
    const own = C.cur;
    C.cur = ixCopyFlow(W, C, own);
    K.stmt(K, T, V, W, C, { ...env, dead: true }, s);
    C.cur = own;
  }
  return live;
};

export const ixBlock = (ixNewScope, ixHoist, ixStmts) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, list: AstNode[]): boolean => {
  const inner = ixNewScope(C, env);
  ixHoist(K, V, C, inner, list);
  return ixStmts(K, T, V, W, C, inner, list);
};

export const ixStmt = (ixStmtSimple, ixStmtFlow, ixUnsup, ixGap, nodeKind) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, s: AstNode): boolean => {
  if (s.type === "Other") { ixGap(C, `statement ${s.kind} (Other)`); return true; }
  const r = ixStmtSimple(K, T, V, W, C, env, s) ?? ixStmtFlow(K, T, V, W, C, env, s);
  if (r !== null) return r;
  ixUnsup(K, C, s, nodeKind(s));
  return true;
};

export const ixStmtSimple = (ixBlock, ixVarDecl, ixFnDeclStmt, ixReturn, ixBreak, ixHides, ixDeclare, ixNoExtra, ixUnsup, UNKNOWN, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, s: AstNode): boolean | null => {
  switch (s.type) {
    case "BlockStatement": return ixBlock(K, T, V, W, C, env, s.body);
    case "EmptyStatement": return true;
    case "ExpressionStatement": return K.infer(K, T, V, W, C, env, s.expression).k !== "never";
    case "VariableDeclaration": for (const d of s.declarations) ixVarDecl(K, T, V, W, C, env, d, s.kind); return true;
    case "FunctionDeclaration": ixFnDeclStmt(K, T, V, W, C, env, s); return true;
    case "ReturnStatement": return ixReturn(K, T, V, W, C, env, s);
    // a catch takes it as unknown
    case "ThrowStatement": ixHides(K, C, s.argument, K.infer(K, T, V, W, C, env, s.argument), UNKNOWN, null); return false;
    case "BreakStatement": case "ContinueStatement": return ixBreak(K, W, C, env, s);
    case "ClassDeclaration": if (s.id.type === "Identifier") ixDeclare(V, C, env, s.id.name, ERR, "const", s.id, ixNoExtra, { k: "none" }, false, -1); return true;
    case "ForInStatement": ixUnsup(K, C, s, "for...in"); return true;
    case "LabeledStatement": ixUnsup(K, C, s, "label"); return true;
    case "TSTypeAliasDeclaration": case "TSInterfaceDeclaration": ixUnsup(K, C, s, "local type declaration"); return true;
    default: return null;
  }
};

export const ixStmtFlow = (ixIf, ixLoop, ixForOf, ixTry, ixSwitch) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, s: AstNode): boolean | null => {
  switch (s.type) {
    case "IfStatement": return ixIf(K, T, V, W, C, env, s);
    case "WhileStatement": case "DoWhileStatement": case "ForStatement": return ixLoop(K, T, V, W, C, env, s);
    case "ForOfStatement": return ixForOf(K, T, V, W, C, env, s);
    case "TryStatement": return ixTry(K, T, V, W, C, env, s);
    case "SwitchStatement": return ixSwitch(K, T, V, W, C, env, s);
    default: return null;
  }
};

export const ixReturn = (ixReturned, ixErr, show, UNDEF) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, s: ReturnStatement): boolean => {
  const a = s.argument, ctx = env.fi.retCtx;
  const t = a !== null ? ixReturned(K, T, V, W, C, env, a) : UNDEF;
  if (a === null && ctx !== null && !K.reg.sub(UNDEF, ctx)) ixErr(K, C, s, "type", `return without a value from a function returning ${show(ctx)}`);
  C.rets = [...C.rets, t];
  return false;
};

// a break of the innermost switch takes the flow with it; a loop's exit flow is its head
export const ixBreak = (ixUnsup, ixCopyFlow) => (K: IxK, W: IxFlows, C: IxCtls, env: IxEnv, s: AstNode): boolean => {
  const label = s.type === "BreakStatement" || s.type === "ContinueStatement" ? s.label : null;
  const top = C.breaks;
  if (label !== null) ixUnsup(K, C, s, "labelled break/continue");
  else if (s.type === "BreakStatement" && !env.dead && top !== null && top.exits !== null) C.breaks = { exits: [...top.exits, ixCopyFlow(W, C, C.cur)], next: top.next };
  return false;
};

// a function declaration's body, checked where it stands unless a read checked it first
export const ixFnDeclStmt = (ixLookup, ixUpdate, ixCopyFlow) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, s: FunctionDeclaration): void => {
  const b = s.id.type === "Identifier" ? ixLookup(V, env, s.id.name) : undefined;
  if (!b || b.checked) return;
  ixUpdate(V, C, { ...b, checked: true });
  const own = C.cur;
  C.cur = ixCopyFlow(W, C, own);
  const f = K.fnExpr(K, T, V, W, C, env, s, null, null);
  C.cur = own;
  ixUpdate(V, C, { ...b, checked: true, t: b.t.k === "err" ? f : b.t, lazy: { k: "none" } });
};

// an annotation under which a fresh value is writable (S4.1): an array or tuple type, a type literal with no readonly
// member, or one of the mutable intrinsics; any other (readonly, a union, an alias, Readonly<…>, typeof) is not
export const ixWritableAnn = () => (ann: AstNode): boolean => {
  if (ann.type === "TSArrayType" || ann.type === "TSTupleType") return true;
  // e1 (2026-11-23), B4: an index signature with no readonly is writable as a property is
  if (ann.type === "TSTypeLiteral") return ann.members.every((m) => (m.type === "TSPropertySignature" || m.type === "TSIndexSignature") && m.readonly !== true);
  const names = ["Array", "Map", "Set", "WeakMap", "WeakSet", "Record", "Int8Array", "Uint8Array", "Uint8ClampedArray", "Int16Array", "Uint16Array", "Int32Array", "Uint32Array", "Float32Array", "Float64Array", "BigInt64Array", "BigUint64Array"];
  return ann.type === "TSTypeReference" && ann.typeName.type === "Identifier" && names.includes(ann.typeName.name);
};

export const ixVarDecl = (ixAnnOf, ixWritableAnn, ixConvert, ixVarFn, ixDeclare, ixNoExtra, ixLookup, ixFlowSet, ixErr, ixUnsup, widen, named, isNamed, unwrap, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, d: AstNode, kind: string): void => {
  if (d.type !== "VariableDeclarator") { ixUnsup(K, C, d, `declarator ${d.type}`); return; }
  const k: IxKind = kind === "const" ? "const" : "let", id = d.id, init = d.init;
  const ann = ixAnnOf(id), declared = ann !== null ? ixConvert(K, V, env, ann) : null;
  const fnInit = init !== null && (init.type === "ArrowFunctionExpression" || init.type === "FunctionExpression");
  if (id.type === "Identifier" && init !== null && fnInit && k === "const") return ixVarFn(K, T, V, W, C, env, id, init, declared, init, init.nid);
  // const f = memo((…): R => …): bound before the call is checked, so the memoised function can call itself (S2.13)
  const m = init !== null && init.type === "CallExpression" && init.callee.type === "Identifier" && init.callee.name === "memo" && ixLookup(V, env, "memo")?.kind === "prelude" ? init.arguments[0] : undefined;
  if (id.type === "Identifier" && init !== null && m !== undefined && (m.type === "ArrowFunctionExpression" || m.type === "FunctionExpression") && k === "const") return ixVarFn(K, T, V, W, C, env, id, init, declared, m, -1);
  if (init === null) {
    if (k === "const") ixErr(K, C, d, "type", "const without initializer");
    if (declared === null) ixUnsup(K, C, d, "let without a type or initializer");
    K.bind(K, T, V, W, C, env, id, declared ?? ERR, k, ixNoExtra);
    return;
  }
  const t0 = K.check(K, T, V, W, C, env, init, declared, false, false);
  // S4.1: a fresh value (a literal, new or a call of a fresh intrinsic) bound to a local is a Mut, annotated or not
  const fresh = (declared === null || ann === null || (!isNamed(declared, "Mut") && ixWritableAnn(ann))) && t0.k !== "err" && !isNamed(t0, "Mut") && (init.type === "ArrayExpression" || init.type === "ObjectExpression" || C.freshAt === init.nid);
  const t = fresh ? named("Mut", declared ?? (k === "let" ? widen(t0) : t0)) : t0;
  const isMut = fresh || (init.type === "CallExpression" && init.callee.type === "Identifier" && init.callee.name === "mut" && ixLookup(V, env, "mut")?.kind === "prelude");
  if (id.type !== "Identifier") return K.bind(K, T, V, W, C, env, id, declared ?? unwrap(t0), k, ixNoExtra);
  const b = ixDeclare(V, C, env, id.name, declared !== null ? (fresh && k === "const" ? t : declared) : k === "let" && !fresh ? widen(t) : t, k, id, ixNoExtra, { k: "none" }, isMut, fnInit ? init.nid : -1);
  if (k === "let" && declared !== null) ixFlowSet(W, C.cur, "#" + b.id, K.reg.sub(t, declared) ? t : declared);
};

// const f = (…) => …: bound before its body is checked, so it can call itself (with annotations); sig: the function
// whose annotations give the type (init, or the function memo(...) is given); fnNode: the function f names, or -1
export const ixVarFn = (ixAnnotatedSig, ixDeclare, ixNoExtra, ixUpdate, ixLookup, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, id: Identifier, init: AstNode, declared: Ty | null, sig: AstNode, fnNode: number): void => {
  // p3 (2026-11-25): the binding ixHoist made for a const function, kept, so a read before this and the declaration are
  // one binding; its body is not checked again when a read before this checked it
  const o = ixLookup(V, env, id.name), re = o !== undefined && o.nid === id.nid && o.lazy.k === "later" && o.lazy.fn !== null ? o : null;
  if (re !== null && re.checked) { ixUpdate(V, C, { ...re, lazy: { k: "none" } }); return; }
  const pre = declared ?? (re !== null && re.t.k !== "err" ? re.t : ixAnnotatedSig(K, V, C, env, sig));
  const lz: IxLazy = pre ? { k: "none" } : { k: "unsup", at: sig };
  const b: IxBinding = re !== null ? { ...re, t: pre ?? ERR, lazy: lz } : ixDeclare(V, C, env, id.name, pre ?? ERR, "const", id, ixNoExtra, lz, false, fnNode);
  if (re !== null) ixUpdate(V, C, b);
  const t = K.check(K, T, V, W, C, env, init, declared, false, false);
  ixUpdate(V, C, { ...b, t: declared ?? t, lazy: { k: "none" } });
};

export const ixIf = (ixSub1, ixJoin2) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, s: IfStatement): boolean => {
  const c = K.cond(K, T, V, W, C, env, s.test);
  const own = C.cur;
  C.cur = c.t;
  const la = ixSub1(K, T, V, W, C, env, s.consequent);
  const af = C.cur;
  C.cur = c.f;
  const alt = s.alternate;
  const lb = alt !== null ? ixSub1(K, T, V, W, C, env, alt) : true;
  const bf = C.cur;
  if (!la && !lb) { C.cur = own; return false; }
  C.cur = la && lb ? ixJoin2(W, C, af, bf) : la ? af : bf;
  return true;
};

export const ixInvalidate = (ixAssignedNames, ixLookup, ixDropRoot) => (V: IxVars, W: IxFlows, env: IxEnv, id: number, n: AstNode): void => {
  for (const name of ixAssignedNames(n)) {
    const b = ixLookup(V, env, name);
    if (b) ixDropRoot(W, id, b);
  }
};

// an unlabelled break of this loop (not of a nested loop or switch)
export const ixHasBreak = (kidsOf, isFnNode) => {
  function hasBreak(n: AstNode): boolean {
    if (n.type === "BreakStatement" && n.label === null) return true;
    if (isFnNode(n) || ["WhileStatement", "DoWhileStatement", "ForStatement", "ForOfStatement", "ForInStatement", "SwitchStatement"].includes(n.type)) return false;
    return kidsOf(n).some((c) => hasBreak(c));
  }
  return hasBreak;
};

export const ixPopBreaks = () => (C: IxCtls): number[] => {
  const top = C.breaks;
  C.breaks = top?.next ?? null;
  return top?.exits ?? [];
};

export const ixLoopInit = (ixVarDecl, ixErr) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, inner: IxEnv, s: IxLoopNode): void => {
  const init = s.type === "ForStatement" ? s.init : null;
  if (init === null) return;
  if (init.type !== "VariableDeclaration") { K.infer(K, T, V, W, C, inner, init); return; }
  if (init.kind === "var") ixErr(K, C, init, "no-var", "var");
  for (const d of init.declarations) ixVarDecl(K, T, V, W, C, inner, d, init.kind);
};

// the loop body, and the flow where the loop's test is false (null when it has none)
export const ixLoopBody = (ixSub1, ixInvalidate, ixCopyFlow) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, inner: IxEnv, s: IxLoopNode, head: number): number | null => {
  if (s.type === "DoWhileStatement") {
    C.cur = ixCopyFlow(W, C, head);
    ixSub1(K, T, V, W, C, inner, s.body);
    ixInvalidate(V, W, inner, C.cur, s);
    return K.cond(K, T, V, W, C, inner, s.test).f;
  }
  const test = s.test;
  let F: number | null = null;
  let body = ixCopyFlow(W, C, head);
  if (test !== null) { const c = K.cond(K, T, V, W, C, inner, test); body = c.t; F = c.f; }
  C.cur = body;
  ixSub1(K, T, V, W, C, inner, s.body);
  if (s.type === "ForStatement" && s.update !== null) K.infer(K, T, V, W, C, inner, s.update);
  return F;
};

export const ixLoop = (ixNewScope, ixLoopInit, ixLoopBody, ixInvalidate, ixCopyFlow, ixPushBreaks, ixPopBreaks, ixHasBreak) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, s: IxLoopNode): boolean => {
  const own = C.cur, inner = ixNewScope(C, env);
  ixLoopInit(K, T, V, W, C, inner, s);
  ixInvalidate(V, W, inner, C.cur, s);
  const head = ixCopyFlow(W, C, C.cur);
  ixPushBreaks(C, null);
  const F = ixLoopBody(K, T, V, W, C, inner, s, head);
  ixPopBreaks(C);
  const test = s.test;
  const infinite = (s.type !== "DoWhileStatement" && test === null) || (test !== null && test.type === "Literal" && test.value === true);
  const brk = ixHasBreak(s.body);
  if (infinite && !brk) { C.cur = own; return false; }
  C.cur = brk || F === null ? head : F;
  return true;
};

export const ixForOf = (ixNewScope, ixInvalidate, ixCopyFlow, ixPushBreaks, ixPopBreaks, ixSub1, ixErr, ixUnsup, show, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, s: ForOfStatement): boolean => {
  if (s.await) { ixUnsup(K, C, s, "for await"); return true; }
  const inner = ixNewScope(C, env);
  const rt = K.infer(K, T, V, W, C, inner, s.right);
  const el = K.reg.iterElem(rt);
  if (!el) ixErr(K, C, s.right, "type", `for...of over non-iterable ${show(rt)}`);
  ixInvalidate(V, W, inner, C.cur, s);
  const head = ixCopyFlow(W, C, C.cur);
  const left = s.left;
  if (left.type === "VariableDeclaration") {
    const d = left.declarations[0];
    if (left.kind === "var") ixErr(K, C, left, "no-var", "var");
    if (d !== undefined && d.type === "VariableDeclarator") K.bind(K, T, V, W, C, inner, d.id, el ?? ERR, left.kind === "const" ? "const" : "let", { assigned: false, cellParam: false });
  } else ixUnsup(K, C, left, "for...of over an existing binding");
  ixPushBreaks(C, null);
  ixSub1(K, T, V, W, C, inner, s.body);
  ixPopBreaks(C);
  C.cur = head;
  return true;
};

export const ixTry = (ixInvalidate, ixCopyFlow, ixJoin2, ixBlock, ixNewScope, ixGap, UNKNOWN) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, s: TryStatement): boolean => {
  const before = ixCopyFlow(W, C, C.cur);
  ixInvalidate(V, W, env, C.cur, s.block);
  const pre = ixCopyFlow(W, C, C.cur), blk = s.block, h = s.handler, fin = s.finalizer;
  if (blk.type !== "BlockStatement") { ixGap(C, "try without a block"); return true; }
  C.cur = ixCopyFlow(W, C, pre);
  const la = ixBlock(K, T, V, W, C, env, blk.body);
  const af = C.cur;
  let lb = false;
  const b = ixNewScope(C, env);
  C.cur = ixCopyFlow(W, C, pre);
  if (h !== null && h.type === "CatchClause" && h.body.type === "BlockStatement") {
    if (h.param !== null) K.bind(K, T, V, W, C, b, h.param, UNKNOWN, "let", { assigned: false, cellParam: false });
    lb = ixBlock(K, T, V, W, C, b, h.body.body);
  } else if (h !== null) ixGap(C, "catch clause");
  const bf = C.cur;
  C.cur = la && lb ? ixJoin2(W, C, af, bf) : la ? af : lb ? bf : before;
  if (fin === null || fin.type !== "BlockStatement") return la || lb;
  const kept = C.cur;
  C.cur = ixCopyFlow(W, C, pre);
  const lf = ixBlock(K, T, V, W, C, env, fin.body);
  C.cur = kept;
  return lf && (la || lb);
};

// the diagnostics written since mark whose node lies inside span: the discriminant is read again for each case, and
// its own problems were reported by the first read
export const ixDropWithin = (ixDrain, ixPush) => (K: IxK, C: IxCtls, mark: { d: IxLog | null; u: IxLog | null }, span: AstNode): void => {
  ixDrain(K, C);
  const keep = (log: IxLog | null, base: IxLog | null): IxLog | null => {
    const added: Mut<IxDiag[]> = [];
    for (let x = log; x !== null && x.n > (base?.n ?? 0); x = x.next) added.unshift(x.d);
    let out = base;
    for (const d of added) if (!(d.start >= span.start && d.end <= span.end)) out = ixPush(out, d);
    return out;
  };
  C.diags = keep(C.diags, mark.d);
  C.unsup = keep(C.unsup, mark.u);
};

// each case is checked as the condition d === test, in the flow where every earlier test was false; rest: the values
// of d that no case has taken, for exhaustiveness
export const ixSwitchTests = (ixMark, ixDropWithin, ixPathKey, ixNoOverlap, ixNarrowEq, ixErr, show) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, s: SwitchStatement, dt: Ty, none0: number): IxCases => {
  const d = s.discriminant, own = C.cur, taken: Mut<(number | null)[]> = [];
  let rest = dt, none = none0;
  for (const c of s.cases) {
    const test = c.type === "SwitchCase" ? c.test : null;
    if (test === null) { taken.push(null); continue; }
    C.nextNid += 1;
    const eq: AstNode = { type: "BinaryExpression", nid: C.nextNid, start: test.start, end: test.end, line: test.line, left: d, operator: "===", right: test };
    const mark = ixMark(K, C);
    C.cur = none;
    const r = K.cond(K, T, V, W, C, env, eq);
    C.cur = own;
    ixDropWithin(K, C, mark, d);
    taken.push(r.t);
    none = r.f;
    const bt = T.get(test.nid);
    if (bt && !ixPathKey(V, env, d, false) && !ixNoOverlap(K.reg, dt, bt) && ixNoOverlap(K.reg, rest, bt))
      ixErr(K, C, test, "type", `case ${show(bt)}: no value of ${show(dt)} is left for it after the earlier cases`);
    if (bt && (bt.k === "lit" || bt.k === "null" || bt.k === "undef")) rest = ixNarrowEq(K.reg, rest, bt, false, false);
  }
  return { taken: taken, none, rest };
};

export const ixSwitch = (ixSwitchTests, ixSwitchBodies, ixCopyFlow, ixJoin2) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, s: SwitchStatement): boolean => {
  const d = s.discriminant, dt = K.infer(K, T, V, W, C, env, d);
  const cases = ixSwitchTests(K, T, V, W, C, env, s, dt, ixCopyFlow(W, C, C.cur));
  T.set(d.nid, dt);
  const exits = ixSwitchBodies(K, T, V, W, C, env, s, cases);
  const first = exits[0];
  if (first === undefined) return false;
  let out = first;
  for (const x of exits.slice(1)) out = ixJoin2(W, C, out, x);
  C.cur = out;
  return true;
};

export const ixSwitchBodies = (ixJoin, ixNewScope, ixHoist, ixStmts, ixPushBreaks, ixPopBreaks, ixCopyFlow, ixErr) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, s: SwitchStatement, cases: IxCases): number[] => {
  const own = C.cur;
  let into: number | null = null;
  ixPushBreaks(C, []);
  for (const [i, c] of s.cases.entries()) {
    if (c.type !== "SwitchCase") continue;
    const flow = ixJoin(W, C, into, cases.taken[i] ?? cases.none) ?? cases.none;
    for (const st of c.consequent) if (st.type === "VariableDeclaration" || st.type === "FunctionDeclaration" || st.type === "ClassDeclaration")
      ixErr(K, C, st, "switch-declaration", "a declaration directly in a case is visible to every case of the switch; put the case's statements in a block { … }");
    if (!c.consequent.length) { into = flow; continue; }
    const inner = ixNewScope(C, env);
    C.cur = ixCopyFlow(W, C, flow);
    ixHoist(K, V, C, inner, c.consequent);
    const end = ixStmts(K, T, V, W, C, inner, c.consequent);
    if (end && i < s.cases.length - 1) ixErr(K, C, c, "switch-fallthrough", "this case falls through into the next one; end it with break, return, throw or continue");
    into = end ? C.cur : null;
  }
  const exits = ixPopBreaks(C);
  C.cur = own;
  const tail: number[] = [...(into !== null ? [into] : []), ...(!s.cases.some((c) => c.type === "SwitchCase" && c.test === null) && cases.rest.k !== "never" ? [cases.none] : [])];
  return [...exits, ...tail];
};

export const ixNotOwn = (ixErr) => (K: IxK, C: IxCtls, r: Rec, at: AstNode): void => {
  const k = [...r.props].find(([, p]) => p.flags?.intrinsic)?.[0];
  if (k !== undefined) ixErr(K, C, at, "type", `${at.type === "RestElement" ? "rest" : "spread"} of a built-in object: its member ${k} is not an own property, so the copy would not have it`);
};

// the record members of the expected type, and whether a property it does not name is an excess one
export const ixObjCtx = (ixUm, isNamed) => (R: IxRegCore, expected: Ty | null): { recs: Rec[]; exact: boolean } => {
  if (expected === null) return { recs: [], exact: false };
  const recs = ixUm(R, expected).map((m) => R.expand(isNamed(m, "Mut") && m.k === "named" ? m.args[0] ?? m : m)).flatMap((m) => (m.k === "rec" ? [m] : []));
  const exact = recs.length > 0 && recs.length === ixUm(R, expected).filter((m) => m.k !== "null" && m.k !== "undef").length && recs.every((x) => !x.index);
  return { recs, exact };
};

// open part 6 (SW): a record type may omit members its value has, so a spread of a value whose type is not exact may
// replace a member an earlier part of the literal gave; an optional member the spread may lack keeps the earlier one
export const ixObjSpread = (ixUm, ixUnsup, ixNotOwn, ixErr, union, unwrap, show) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, p: SpreadElement, props: Mut<Map<string, Prop>>): void => {
  const st = K.infer(K, T, V, W, C, env, p.argument);
  const ms = ixUm(K.reg, unwrap(st)).filter((m) => m.k !== "undef" && m.k !== "null");
  const m0 = ms[0];
  if (ms.length !== 1 || m0 === undefined) { if (st.k !== "err") ixUnsup(K, C, p, `object spread of ${show(st)}`); return; }
  const x = K.reg.expand(m0);
  if (x.k !== "rec" || x.index) { if (x.k !== "err") ixUnsup(K, C, p, `object spread of ${show(x)}`); return; }
  ixNotOwn(K, C, x, p);
  const hid = x.exact === true ? undefined : [...props.keys()].find((k) => !x.props.has(k));
  if (hid !== undefined) ixErr(K, C, p, "forgets", `the spread of ${show(x)} comes after ${hid}, and its type does not declare ${hid}: a value of that type may have a member ${hid} of another type, which would replace the earlier ${hid}; put the spread first, or declare ${hid} in the type of the spread`);
  for (const [k, v] of x.props) { const was = props.get(k); props.set(k, was !== undefined && v.opt ? { ...v, t: union([was.t, v.t]), opt: was.opt } : v); }
};

export const ixObjLit = (ixObjCtx, ixObjSpread, ixProtoKey, ixErr, ixUnsup, ixGap, union, widen, show) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: ObjectExpression, expected: Ty | null): Ty => {
  const props: Mut<Map<string, Prop>> = new Map();
  const { recs, exact } = ixObjCtx(K.reg, expected);
  let closed = true;
  for (const p of e.properties) {
    if (p.type === "SpreadElement") { closed = false; ixObjSpread(K, T, V, W, C, env, p, props); continue; }
    if (p.type !== "Property") { ixGap(C, `object member ${p.type}`); continue; }
    if (p.kind !== "init") { ixUnsup(K, C, p, `${p.kind} accessor`); continue; }
    if (p.computed) { ixUnsup(K, C, p, "computed property"); continue; }
    ixProtoKey(K, C, p);
    const key = p.key, k = key.type === "Identifier" ? key.name : key.type === "Literal" ? String(key.value) : null;
    if (k === null) { ixGap(C, `object key ${key.type}`); continue; }
    const cs = recs.flatMap((x) => { const c = x.props.get(k)?.t ?? x.index; return c ? [c] : []; });
    const ctx = cs.length ? union(cs) : null;
    if (exact && ctx === null && expected !== null) ixErr(K, C, p, "excess-property", `property ${k} is not in ${show(expected)}`);
    const t = K.check(K, T, V, W, C, env, p.value, ctx, false, false);
    props.set(k, { t: expected === null ? widen(t) : t, opt: false });
  }
  return closed ? { k: "rec", props: props, exact: true } : { k: "rec", props: props };
};

// the element context of an array literal: an array's element, an iterable's
export const ixElCtx = (union, NEVER) => (ms: Ty[]): Ty | null => {
  const c = union(ms.map((m) => (m.k === "arr" ? m.el : m.k === "named" && (m.n === "Iterable" || m.n === "ArrayLike") ? m.args[0] ?? NEVER : NEVER)));
  return c.k === "never" ? null : c;
};

export const ixArrLit = (ixUm, ixElCtx, ixErr, ixUnsup, union, widen, arr, show, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: ArrayExpression, expected: Ty | null): Ty => {
  const ms = expected === null ? [] : ixUm(K.reg, expected).map((m) => K.reg.expand(m));
  const tup = ms.find((m) => m.k === "tup" && m.els.length === e.elements.length);
  const noSpread = e.elements.every((x) => x !== null && x.type !== "SpreadElement");
  if (tup !== undefined && tup.k === "tup" && noSpread) {
    const ts: Mut<Ty[]> = [];
    for (const [i, x] of e.elements.entries()) if (x !== null) ts.push(K.check(K, T, V, W, C, env, x, tup.els[i] ?? null, false, false));
    return { k: "tup", els: ts };
  }
  const ctx = expected === null ? null : ixElCtx(ms);
  const els: Mut<Ty[]> = [];
  for (const x of e.elements) {
    if (x === null) { ixUnsup(K, C, e, "array hole"); continue; }
    if (x.type === "SpreadElement") {
      const st = K.infer(K, T, V, W, C, env, x.argument), el = K.reg.iterElem(st);
      if (!el) ixErr(K, C, x, "type", `spread of non-iterable ${show(st)}`);
      els.push(el ?? ERR);
      continue;
    }
    els.push(K.check(K, T, V, W, C, env, x, ctx, false, false));
  }
  const el = union(els);
  return arr(ctx !== null ? el : widen(el));
};

export const ixConstLit = (ixUnsup, ixProtoKey, ERR) => {
  function constLit(K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode): Ty {
    if (e.type === "ArrayExpression") {
      const els: Mut<Ty[]> = [];
      for (const x of e.elements) {
        if (x !== null && x.type !== "SpreadElement") els.push(constLit(K, T, V, W, C, env, x));
        else { ixUnsup(K, C, e, "as const with spread"); els.push(ERR); }
      }
      const t: Ty = { k: "tup", els: els };
      T.set(e.nid, t);
      return t;
    }
    if (e.type !== "ObjectExpression") return K.infer(K, T, V, W, C, env, e);
    const props: Mut<Map<string, Prop>> = new Map();
    for (const p of e.properties) {
      if (p.type !== "Property" || p.computed || p.kind !== "init" || p.method) { ixUnsup(K, C, p, "as const object member"); continue; }
      ixProtoKey(K, C, p);
      const key = p.key;
      props.set(key.type === "Identifier" ? key.name : key.type === "Literal" ? String(key.value) : "undefined", { t: constLit(K, T, V, W, C, env, p.value), opt: false });
    }
    const r: Ty = { k: "rec", props: props };
    T.set(e.nid, r);
    return r;
  }
  return constLit;
};

// ---- patterns ----
export const ixBind = (ixDeclare, ixBindObject, ixBindArray, ixNonUndef, ixUnsup, ixGap, widen, union) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, p: AstNode, t: Ty, kind: IxKind, extra: IxExtra): void => {
  switch (p.type) {
    case "Identifier": ixDeclare(V, C, env, p.name, kind === "let" ? widen(t) : t, kind, p, extra, { k: "none" }, false, -1); return;
    case "AssignmentPattern": {
      const nt = ixNonUndef(K.reg, t);
      const dt = K.check(K, T, V, W, C, env, p.right, nt, false, false);
      K.bind(K, T, V, W, C, env, p.left, K.reg.sub(dt, nt) && nt.k !== "never" ? nt : union([nt, dt]), kind, extra);
      return;
    }
    case "ObjectPattern": ixBindObject(K, T, V, W, C, env, p, t, kind, extra); return;
    case "ArrayPattern": ixBindArray(K, T, V, W, C, env, p, t, kind, extra); return;
    case "Other": ixGap(C, `pattern ${p.kind} (Other)`); return;
    default: ixUnsup(K, C, p, `pattern ${p.type}`);
  }
};

export const ixBindObject = (ixBindRest, ixUm, ixErr, ixUnsup, ixInActionOnly, ixPropOf, ixFact, ixGap, isNamed, unwrap, PROTO_NAMES) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, p: ObjectPattern, t: Ty, kind: IxKind, extra: IxExtra): void => {
  const used: Mut<string[]> = [];
  for (const prop of p.properties) {
    if (prop.type === "RestElement") { ixBindRest(K, T, V, W, C, env, prop, t, [...used], kind, extra); continue; }
    if (prop.type !== "Property") { ixGap(C, `object pattern member ${prop.type}`); continue; }
    const key = prop.key;
    if (prop.computed || (key.type !== "Identifier" && key.type !== "Literal")) { ixUnsup(K, C, prop, "computed destructuring key"); continue; }
    const k = key.type === "Identifier" ? key.name : String(key.value);
    used.push(k);
    if (ixUm(K.reg, t).some((m) => m.k !== "err" && K.reg.member(m, k)?.flags?.banned)) ixErr(K, C, prop, "banned-member", `${k} is banned`);
    else if (PROTO_NAMES.has(k) && ixUm(K.reg, t).some((m) => { const x = K.reg.expand(unwrap(m)); return x.k === "rec" && x.index !== undefined; })) ixErr(K, C, prop, "banned-member", `${k} on a record with an index signature is Object.prototype's ${k}, not an entry`);
    if (ixUm(K.reg, t).some((m) => isNamed(unwrap(m), "State") && K.reg.member(m, k))) {
      ixInActionOnly(K, C, env, prop, "state-write", `State.${k} outside action(...)`);
      ixFact(C, { k: "stateProp", at: prop.nid });
    }
    K.bind(K, T, V, W, C, env, prop.value, ixPropOf(K, C, t, k, prop), kind, extra);
  }
};

export const ixBindRest = (ixUnsup, ixNotOwn, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, prop: RestElement, t: Ty, used: string[], kind: IxKind, extra: IxExtra): void => {
  const base = K.reg.expand(t);
  if (base.k !== "rec") { ixUnsup(K, C, prop, "object rest of a non-record"); K.bind(K, T, V, W, C, env, prop.argument, ERR, kind, extra); return; }
  // the names taken out are known not to be members of the rest
  const r: Rec = { k: "rec", props: new Map([...base.props].filter(([k]) => !used.includes(k))), without: used };
  ixNotOwn(K, C, r, prop);
  K.bind(K, T, V, W, C, env, prop.argument, r, kind, extra);
};

export const ixBindArray = (ixIndexOf, arr, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, p: ArrayPattern, t: Ty, kind: IxKind, extra: IxExtra): void => {
  for (const [i, el] of p.elements.entries()) {
    if (el === null) continue;
    if (el.type !== "RestElement") { K.bind(K, T, V, W, C, env, el, ixIndexOf(K, C, t, i, el), kind, extra); continue; }
    const e = K.reg.expand(t);
    K.bind(K, T, V, W, C, env, el.argument, e.k === "tup" ? { k: "tup", els: e.els.slice(i) } : arr(K.reg.iterElem(t) ?? ERR), kind, extra);
  }
};

export const ixIndexOf = (ixUm, ixErr, unwrap, union, show, UNDEF, ERR) => (K: IxK, C: IxCtls, t: Ty, i: number, at: AstNode): Ty => {
  const out: Mut<Ty[]> = [];
  for (const m0 of ixUm(K.reg, t)) {
    const m = unwrap(m0), e = K.reg.expand(m);
    if (e.k === "tup") {
      const x = e.els[i];
      if (x === undefined) { ixErr(K, C, at, "type", `tuple ${show(e)} has no element ${i}`); return ERR; }
      out.push(x);
      continue;
    }
    const el = K.reg.iterElem(e);
    if (!el) { ixErr(K, C, at, "type", `${show(m)} is not indexable`); return ERR; }
    out.push(el);
    if (K.reg.strictIndex) out.push(UNDEF);
  }
  return union(out);
};

export const ixBail = (ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, args: AstNode[], spread: boolean): Ty => {
  for (const a of args) K.infer(K, T, V, W, C, env, spread && a.type === "SpreadElement" ? a.argument : a);
  return ERR;
};

export const ixTypeArgs = (ixConvert) => (K: IxK, V: IxVars, env: IxEnv, n: AstNode | null): Ty[] | null => {
  if (n === null || n.type !== "TSTypeParameterInstantiation") return null;
  const out: Mut<Ty[]> = [];
  for (const t of n.params) out.push(ixConvert(K, V, env, t));
  return out;
};

export const ixCall = (ixFlatMapArg, ixSplitLiteral, ixLookup, ixPreludeCall, ixCompileCall, ixNewSigs, ixCallSigs, ixApplyAll, ixFact, ixGap, ixJsonArg) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode, expected: Ty | null): Ty => {
  if (e.type !== "CallExpression" && e.type !== "NewExpression") return ixGap(C, `call node ${e.type}`);
  const callee = e.callee;
  if (e.type === "CallExpression" && callee.type === "Identifier") {
    const b = ixLookup(V, env, callee.name);
    if (b?.kind === "prelude") return ixPreludeCall(K, T, V, W, C, env, e, callee.name, expected);
    if (b?.kind === "param" && b.t.k === "named" && b.t.n === "Compile") return ixCompileCall(K, T, V, W, C, env, e);
    if (b && (b.kind === "fn" || b.kind === "const") && b.fnNode >= 0) ixFact(C, { k: "helper", at: e.nid, id: b.id });
  }
  const found = e.type === "NewExpression" ? ixNewSigs(K, T, V, W, C, env, e) : ixCallSigs(K, T, V, W, C, env, e, expected);
  if (found.k === "done") return found.t;
  const t = ixApplyAll(K, T, V, W, C, env, e, found.sigs, expected, found.view);
  ixJsonArg(K, T, V, C, env, e);
  ixFlatMapArg(K, T, C, e);
  return ixSplitLiteral(K, T, e, t);
};

// open part 5 (SG): split by a regexp literal with no capture group gives strings only (intrinsics.ts types a RegExp
// separator's result (string | undefined)[]); the groups are counted by the regexp itself: a match of "" by p|
export const ixSplitLiteral = (STR) => (K: IxK, T: IxTypes, e: AstNode, t: Ty): Ty => {
  if (e.type !== "CallExpression" || t.k !== "arr") return t;
  const c = e.callee, a = e.arguments[0];
  if (c.type !== "MemberExpression" || c.computed || c.property.type !== "Identifier" || c.property.name !== "split" || a === undefined || a.type !== "Literal" || a.regex === null) return t;
  const recv = T.get(c.object.nid);
  if (recv === undefined || !K.reg.sub(recv, STR)) return t;
  let groups = 1;
  try { groups = (new RegExp(`${a.regex.pattern}|`, a.regex.flags.replace(/[gy]/g, "")).exec("")?.length ?? 2) - 1; } catch { groups = 1; }
  return groups === 0 ? { ...t, el: STR } : t;
};

// open part 5 (FM): flatMap flattens a callback result that is an array; a result typed by a type parameter may be one
// at run time, where U | readonly U[] took it as one element
export const ixFlatMapArg = (ixUm, ixErr, show) => (K: IxK, T: IxTypes, C: IxCtls, e: AstNode): void => {
  if (e.type !== "CallExpression") return;
  const c = e.callee, a = e.arguments[0], ft = a === undefined ? undefined : T.get(a.nid);
  if (c.type !== "MemberExpression" || c.computed || c.property.type !== "Identifier" || c.property.name !== "flatMap" || ft === undefined || ft.k !== "fn") return;
  const recv = T.get(c.object.nid), un = (t: Ty): Ty[] => ixUm(K.reg, t.k === "named" && (t.n === "Mut" || t.n === "Borrowed") ? t.args[0] ?? t : t);
  if (recv === undefined || !un(recv).some((m) => m.k === "arr" || m.k === "tup")) return;
  const tv = un(ft.ret).find((m) => m.k === "tv");
  if (a !== undefined && tv !== undefined) ixErr(K, C, a, "type", `flatMap flattens a callback result that is an array, and ${show(tv)} is a type parameter, which may be an array: return [x] for one element`);
};

// w1 (2026-11-24, A-4): JSON.stringify of undefined or a function gives undefined, not the string it is typed as; an
// argument that may be one is refused
export const ixJsonArg = (ixLookup, ixErr, show, jsonGapWith) => (K: IxK, T: IxTypes, V: IxVars, C: IxCtls, env: IxEnv, e: AstNode): void => {
  if (e.type !== "CallExpression") return;
  const c = e.callee, a = e.arguments[0];
  if (c.type !== "MemberExpression" || c.computed || c.object.type !== "Identifier" || c.object.name !== "JSON" || c.property.type !== "Identifier" || c.property.name !== "stringify" || ixLookup(V, env, "JSON")?.kind !== "global") return;
  const at = a === undefined ? undefined : T.get(a.nid);
  const w = at === undefined ? null : jsonGapWith({ isAlias: K.reg.quiet.isAlias, expand: K.reg.quiet.expand, member: K.reg.quiet.member })(at);
  if (a !== undefined && at !== undefined && w !== null) ixErr(K, C, a, "type", `JSON.stringify gives undefined, not a string, for undefined or a function, and its argument ${show(at)} may be ${w}: give it a value that is neither (JSON.stringify(x ?? null) when x may be undefined)`);
};

export const ixNewSigs = (ixLookup, ixErr, ixUnsup, ixBail) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: NewExpression): IxSigs => {
  const callee = e.callee;
  if (callee.type !== "Identifier" || ixLookup(V, env, callee.name)?.kind !== "global") {
    ixErr(K, C, e, "new-non-intrinsic", "new on something that is not an allowed intrinsic");
    return { k: "done", t: ixBail(K, T, V, W, C, env, e.arguments, false) };
  }
  const x = K.reg.expand(K.infer(K, T, V, W, C, env, callee));
  const sigs = x.k === "rec" ? (x.ctors ?? []) : [];
  if (!sigs.length) { ixUnsup(K, C, e, `new ${callee.name}`); return { k: "done", t: ixBail(K, T, V, W, C, env, e.arguments, false) }; }
  return { k: "sigs", sigs, view: false };
};

// Object.assign and Object.freeze on the global Object, and structuredClone, have rules of their own
export const ixSpecialCall = (ixLookup, ixObjectAssign, ixObjectFreeze, ixCloneCall) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: CallExpression, expected: Ty | null): Ty | null => {
  const callee = e.callee;
  if (callee.type === "MemberExpression" && callee.object.type === "Identifier" && callee.object.name === "Object" && !callee.computed && ixLookup(V, env, "Object")?.kind === "global" && callee.property.type === "Identifier") {
    if (callee.property.name === "assign") return ixObjectAssign(K, T, V, W, C, env, e);
    if (callee.property.name === "freeze") return ixObjectFreeze(K, T, V, W, C, env, e, expected);
  }
  if (callee.type === "Identifier" && callee.name === "structuredClone" && ixLookup(V, env, callee.name)?.kind === "global") return ixCloneCall(K, T, V, W, C, env, e, callee, expected);
  return null;
};

// open part 5 (TP): a mutating method on a tuple: one that changes the length, or one that moves or writes elements
// when the tuple's element types differ, leaves a type at an index that does not hold there
export const ixTupleMutates = (ixUm, ixErr, show) => (K: IxK, C: IxCtls, at: AstNode, recv: Ty, name: string): void => {
  const un = (t: Ty): Ty[] => ixUm(K.reg, t.k === "named" && (t.n === "Mut" || t.n === "Borrowed") ? t.args[0] ?? t : t);
  for (const t of un(recv)) {
    if (t.k !== "tup") continue;
    const same = t.els.every((x) => t.els.every((y) => K.reg.sub(x, y)));
    const length = ["push", "pop", "shift", "unshift", "splice"].includes(name);
    if (length || !same) {
      ixErr(K, C, at, "mutating-method", `${name} on the tuple ${show(t)} ${length ? "changes its length" : "moves or writes elements of different types"}, and the tuple type gives each index its own type: copy it first (toSorted, toReversed, [...t]), or give it an array type`);
      return;
    }
  }
};

export const ixCallSigs = (ixSpecialCall, ixWriteRule, ixTupleMutates, ixBail, ixUm, ixNonNullish, ixInActionOnly, ixActionFn, ixNotCallable, ixErr, show, isNamed) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: CallExpression, expected: Ty | null): IxSigs => {
  const special = ixSpecialCall(K, T, V, W, C, env, e, expected);
  if (special !== null) return { k: "done", t: special };
  const callee = e.callee, calleeT = K.infer(K, T, V, W, C, env, callee);
  const m = callee.type === "ChainExpression" ? callee.expression : callee;
  const fl = m.type === "MemberExpression" && C.flagsAt === m.nid ? C.flags : undefined;
  if (m.type === "MemberExpression" && fl?.mutates) ixWriteRule(K, T, V, W, C, env, m.object, e, "mutating-method");
  if (m.type === "MemberExpression" && fl?.mutates && !m.computed && m.property.type === "Identifier") ixTupleMutates(K, C, e, T.get(m.object.nid) ?? { k: "err" }, m.property.name);
  if (calleeT.k === "err") return { k: "done", t: ixBail(K, T, V, W, C, env, e.arguments, true) };
  const isShort = e.optional === true || C.short.has(callee.nid);
  if (isShort) C.short = new Set([...C.short, e.nid]);
  const ms = ixUm(K.reg, isShort ? ixNonNullish(K.reg, calleeT) : calleeT);
  const view = m.type === "MemberExpression" && !!fl?.view && isNamed(T.get(m.object.nid) ?? { k: "err" }, "Borrowed");
  const act = ms.find((x) => isNamed(x, "Action"));
  if (act !== undefined && act.k === "named") {
    ixInActionOnly(K, C, env, e, "action-call", "an Action called outside action(...)");
    return { k: "sigs", sigs: [ixActionFn(act.args[0] ?? { k: "tup", els: [] })], view };
  }
  const m0 = ms[0];
  if (ms.length !== 1 || m0 === undefined) { ixErr(K, C, e, "type", `call of ${show(calleeT)}`); return { k: "done", t: ixBail(K, T, V, W, C, env, e.arguments, false) }; }
  const sigs = K.reg.callSigs(m0);
  if (sigs.length) return { k: "sigs", sigs, view };
  ixNotCallable(K, C, e, m0);
  return { k: "done", t: ixBail(K, T, V, W, C, env, e.arguments, false) };
};

export const ixNotCallable = (ixErr, show) => (K: IxK, C: IxCtls, e: AstNode, m: Ty): void => {
  if (m.k === "null" || m.k === "undef") ixErr(K, C, e, "possibly-undefined", `call of a value that may be ${show(m)}`);
  else ixErr(K, C, e, "type", `${show(m)} is not callable`);
};

// one signature, or each overload in turn until one gives no new diagnostic (the others are rolled back)
export const ixApplyAll = (ixTypeArgs, ixApply, ixMark, ixCopyFlow, named, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: CallExpression | NewExpression, sigs: Fn[], expected: Ty | null, view: boolean): Ty => {
  const explicit = ixTypeArgs(K, V, env, e.typeArguments);
  let t: Ty = ERR;
  if (sigs.length > 1) C.tries += 1;
  for (const [i, sig] of sigs.entries()) {
    const mark = ixMark(K, C), flow = ixCopyFlow(W, C, C.cur);
    t = ixApply(K, T, V, W, C, env, e, sig, expected, explicit);
    const fl = sig.flags;
    C.freshAt = fl !== undefined && !!fl.intrinsic && !!fl.fresh && !fl.view && !view ? e.nid : -1;
    if (sigs.length === 1) break;
    const now = ixMark(K, C);
    if ((now.d?.n ?? 0) === (mark.d?.n ?? 0) && (now.u?.n ?? 0) === (mark.u?.n ?? 0)) break;
    if (i < sigs.length - 1) { C.diags = mark.d; C.unsup = mark.u; C.cur = flow; }
  }
  if (sigs.length > 1) C.tries -= 1;
  return view ? named("Borrowed", t) : t;
};

export const ixCloneCall = (ixApply, ixErr, show, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: CallExpression, callee: Identifier, expected: Ty | null): Ty => {
  C.clones = new Set([...C.clones, callee.nid]);
  const sig = K.reg.callSigs(K.infer(K, T, V, W, C, env, callee))[0];
  if (sig === undefined) return ERR;
  const t = ixApply(K, T, V, W, C, env, e, sig, expected, null);
  const a = e.arguments[0], at = a === undefined ? undefined : T.get(a.nid);
  const w = a !== undefined && at !== undefined ? K.reg.cloneProblem(at) : null;
  if (a !== undefined && at !== undefined && w) ixErr(K, C, a, "type", `structuredClone of ${show(at)}, which ${w}: the clone would throw or lose it`);
  C.freshAt = e.nid;
  return t;
};

export const ixObjectAssign = (ixErr, ixUnsup, isNamed, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: CallExpression): Ty => {
  const target = e.arguments[0];
  const tt = target !== undefined ? K.infer(K, T, V, W, C, env, target) : ERR;
  if (target === undefined || (target.type !== "ObjectExpression" && !isNamed(tt, "Mut"))) ixErr(K, C, e, "object-assign", "Object.assign onto an existing value");
  for (const s of e.arguments.slice(1)) K.infer(K, T, V, W, C, env, s);
  ixUnsup(K, C, e, "Object.assign");
  return ERR;
};

// Object.freeze of a literal: the value is the cell's own, so freezing it changes nothing another cell holds
export const ixObjectFreeze = (ixErr, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: CallExpression, expected: Ty | null): Ty => {
  const a = e.arguments[0];
  if (e.arguments.length === 1 && a !== undefined && (a.type === "ObjectExpression" || a.type === "ArrayExpression")) return K.check(K, T, V, W, C, env, a, expected, false, false);
  ixErr(K, C, e, "object-freeze", "Object.freeze takes one object or array literal");
  for (const x of e.arguments) K.infer(K, T, V, W, C, env, x.type === "SpreadElement" ? x.argument : x);
  return ERR;
};

// compile({ inputs, refs, outputs, options }): typed from the cell graph by core.ts; the port infers the options
export const ixCompileCall = (ixUnsup, ixGap, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: CallExpression): Ty => {
  const hook = K.reg.compile;
  if (hook === null) { ixUnsup(K, C, e, "compile outside a module check"); return ERR; }
  const first = hook(e, null);
  if (first.k === "done") return first.t;
  const second = hook(e, K.infer(K, T, V, W, C, env, first.at));
  return second.k === "done" ? second.t : ixGap(C, "compile hook asked for a second type");
};

// the substitution so far with what the expected return type gave for the variables it has not solved
export const ixCtxSubst = (subst) => (t: Ty, m: Map<string, Ty>, fromRet: Map<string, Ty>): Ty => {
  const cm: Mut<Map<string, Ty>> = new Map(m);
  for (const [k, v] of fromRet) if (!cm.has(k)) cm.set(k, v);
  return subst(t, cm);
};

// a contextual type with unresolved variables replaced by unknown (keeps tuple and record shape for literals)
export const ixCtxOnly = (subst, UNKNOWN) => (t: Ty, tvs: Set<string>): Ty | null => {
  const r = subst(t, new Map([...tvs].map((n): [string, Ty] => [n, UNKNOWN])));
  return r.k === "unknown" ? null : r;
};

export const ixWidenFree = (widen) => (m: Mut<Map<string, Ty>>, fixed: Set<string>): void => {
  for (const [k, v] of [...m]) if (!fixed.has(k)) m.set(k, widen(v));
};

export const ixArity = (ixErr) => (K: IxK, C: IxCtls, e: AstNode, args: AstNode[], sig: Fn): void => {
  const required = sig.ps.filter((p) => !p.opt).length;
  // e1 (2026-11-23), B4: reduce takes its start value as a required argument (ergonomics1 30)
  const c = e.type === "CallExpression" ? e.callee : null, m = c !== null && c.type === "MemberExpression" && !c.computed && c.property.type === "Identifier" ? c.property.name : "";
  const reduce = m === "reduce" && args.length === 1 ? "; a start value is required as reduce's second argument (xs.reduce((acc, v) => acc + v, 0)): with none, reduce throws on an empty array" : "";
  if (args.length < required && !args.some((a) => a.type === "SpreadElement")) ixErr(K, C, e, "arity", `expected at least ${required} arguments, got ${args.length}${reduce}`);
  if (args.length > sig.ps.length && !sig.rest) ixErr(K, C, e, "arity", `expected at most ${sig.ps.length} arguments, got ${args.length}`);
};

export const ixSpreadArg = (ixErr, ixUnsup, ixHides, subst, show) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, A: IxApp, a: SpreadElement, i: number, m: Map<string, Ty>): void => {
  const st = K.infer(K, T, V, W, C, env, a.argument), el = K.reg.iterElem(st), rest = A.sig.rest;
  if (!el) ixErr(K, C, a, "type", `spread of non-iterable ${show(st)}`);
  else if (rest === undefined || i < A.sig.ps.length) ixUnsup(K, C, a, "spread argument to a non-rest parameter");
  else if (!K.reg.sub(el, subst(rest, m))) ixErr(K, C, a, "type", `spread element ${show(el)} is not assignable to ${show(subst(rest, m))}`);
  else ixHides(K, C, a, el, rest, A.opaque);
};

// the first pass over one argument: its type, or "defer" for a callback whose parameters wait on type variables
export const ixFirstArg = (ixSpreadArg, ixParamAt, ixCtxSubst, ixCtxOnly, ixAnnOf, subst, hasTv, union, UNDEF, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, A: IxApp, a: AstNode, i: number, m: Mut<Map<string, Ty>>, fromRet: Map<string, Ty>): Ty | "defer" | null => {
  const p = ixParamAt(A.sig, i);
  if (a.type === "SpreadElement") { ixSpreadArg(K, T, V, W, C, env, A, a, i, new Map(m)); return ERR; }
  if (p === undefined) { K.infer(K, T, V, W, C, env, a); return null; }
  const fnArg = a.type === "ArrowFunctionExpression" || a.type === "FunctionExpression";
  const lam = (a.type === "ArrowFunctionExpression" || a.type === "FunctionExpression") && a.params.some((q) => ixAnnOf(q) === null);
  const pc = subst(p, new Map(m));
  if (lam && hasTv(pc, A.tvSet)) return "defer";
  // e1 (2026-11-23), B4: a callback with every parameter annotated gives the type variables of its parameters itself
  if (fnArg && hasTv(pc, A.tvSet) && K.reg.callSigs(pc).some((s) => s.ps.some((q) => hasTv(q.t, A.tvSet)))) { const t = K.infer(K, T, V, W, C, env, a); K.reg.unify(p, t, m, A.tvSet); return t; }
  if (!hasTv(pc, A.tvSet)) return K.check(K, T, V, W, C, env, a, A.sig.ps[i]?.opt && !fnArg ? union([pc, UNDEF]) : pc, false, false);
  const t = K.check(K, T, V, W, C, env, a, ixCtxOnly(ixCtxSubst(p, new Map(m), fromRet), A.tvSet), true, false);
  K.reg.unify(p, t, m, A.tvSet);
  return t;
};

// a deferred callback, checked once the arguments before it fixed its parameters' types
export const ixDeferredArg = (ixParamAt, ixCtxSubst, ixUnsup, ixWidenFree, hasTv, UNKNOWN, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, A: IxApp, a: AstNode, i: number, m: Mut<Map<string, Ty>>, fromRet: Map<string, Ty>): Ty => {
  const p = ixParamAt(A.sig, i) ?? ERR;
  const pc = ixCtxSubst(p, new Map(m), fromRet);
  const ps = K.reg.callSigs(pc)[0];
  if (ps && ps.ps.some((q) => hasTv(q.t, A.tvSet))) { ixUnsup(K, C, a, "callback whose parameter types are not inferred before it"); return ERR; }
  const ctx: Ty = ps ? { ...ps, ret: !hasTv(ps.ret, A.tvSet) ? ps.ret : UNKNOWN } : pc;
  const t = K.fnExpr(K, T, V, W, C, env, a, ctx, null);
  T.set(a.nid, t);
  K.reg.unify(p, t, m, A.tvSet);
  ixWidenFree(m, A.fixed);
  return t;
};

// each argument against its parameter under the solved substitution
export const ixFinalArgs = (ixParamAt, ixExpect, ixHides, subst, hasTv) => (K: IxK, C: IxCtls, A: IxApp, args: AstNode[], argT: (Ty | null)[], deferred: number[], m: Map<string, Ty>): void => {
  for (const [i, a] of args.entries()) {
    const p = ixParamAt(A.sig, i), t = argT[i] ?? null;
    if (p === undefined || t === null || a.type === "SpreadElement") continue;
    const pc = subst(p, m);
    if ((hasTv(p, A.tvSet) || deferred.includes(i)) && ixExpect(K, C, a, t, pc, false) && A.opaque && hasTv(p, A.tvSet)) ixHides(K, C, a, t, p, A.opaque);
  }
};

export const ixSolve = (widen, UNKNOWN) => (m: Mut<Map<string, Ty>>, fromRet: Map<string, Ty>, A: IxApp): void => {
  for (const n of A.tvs) {
    if (A.fixed.has(n)) continue;
    const c = m.get(n) ?? fromRet.get(n);
    m.set(n, c ? (m.has(n) ? widen(c) : c) : UNKNOWN);
  }
};

// the explicit type arguments into the substitution, with the arity check
export const ixExplicit = (ixErr) => (K: IxK, C: IxCtls, e: AstNode, tvs: string[], explicit: Ty[] | null, m: Mut<Map<string, Ty>>): void => {
  if (explicit === null) return;
  if (explicit.length !== tvs.length) ixErr(K, C, e, "type", `expected ${tvs.length} type arguments, got ${explicit.length}`);
  for (const [i, n] of tvs.entries()) { const x = explicit[i]; if (x) m.set(n, x); }
};

export const ixApply = (ixArity, ixExplicit, ixFirstArg, ixDeferredArg, ixWidenFree, ixSolve, ixFinalArgs, ixSettled, ixPlainResult, ixFact, instantiate, subst, hasTv) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: CallExpression | NewExpression, sig0: Fn, expected: Ty | null, explicit: Ty[] | null): Ty => {
  const inst = instantiate(sig0, C.fresh);
  C.fresh += sig0.tps.length;
  const tvSet = new Set(inst.tvs), m: Mut<Map<string, Ty>> = new Map(), fromRet: Mut<Map<string, Ty>> = new Map();
  ixExplicit(K, C, e, inst.tvs, explicit, m);
  const A: IxApp = { sig: inst.f, tvs: inst.tvs, tvSet, opaque: sig0.flags?.intrinsic ? null : tvSet, fixed: new Set(m.keys()) };
  ixArity(K, C, e, e.arguments, A.sig);
  const decl = sig0.decl ?? sig0, fl = sig0.flags;
  ixFact(C, { k: "sig", at: e.nid, sig: fl ? { ...inst.f, decl, flags: fl } : { ...inst.f, decl } });
  if (expected !== null && hasTv(A.sig.ret, tvSet)) K.reg.unify(A.sig.ret, expected, fromRet, tvSet);
  const ret = new Map(fromRet), argT: Mut<(Ty | null)[]> = [], deferred: Mut<number[]> = [];
  for (const [i, a] of e.arguments.entries()) {
    const t = ixFirstArg(K, T, V, W, C, env, A, a, i, m, ret);
    if (t === "defer") deferred.push(i);
    argT.push(t === "defer" ? null : t);
  }
  ixWidenFree(m, A.fixed);
  for (const i of deferred) { const a = e.arguments[i]; if (a !== undefined) argT[i] = ixDeferredArg(K, T, V, W, C, env, A, a, i, m, ret); }
  ixSolve(m, ret, A);
  ixFinalArgs(K, C, A, e.arguments, argT, deferred, new Map(m));
  return ixPlainResult(K, C, e, sig0, ixSettled(K.reg, subst(A.sig.ret, new Map(m))));
};

// x1 (2026-11-24): a built-in flagged @plain builds a record whose keys come from run-time data (Object.fromEntries); a
// key may be then, toJSON or toString, which the run time calls, so what it holds must be plain data. y1: a part typed
// unknown or object is not (attack 13 U: an Action joined with unknown, under toJSON)
export const ixPlainResult = (plainWith, ixErr, show) => (K: IxK, C: IxCtls, e: AstNode, sig0: Fn, r: Ty): Ty => {
  const R = K.reg.quiet;
  if (sig0.flags?.plain && !plainWith({ isAlias: R.isAlias, expand: R.expand, member: R.member })(r))
    ixErr(K, C, e, "type", `this call builds ${show(r)}, a record whose keys come from run-time data: a key may be then, toJSON or toString, which the run time calls, so the values must be plain data (no function, Action, handle, Mut, promise, iterator or response): to keep a function, write the record as an object literal`);
  return r;
};

// a promise never fulfils with a promise-like: resolving with one adopts what it settles to
export const ixSettled = (ixUm, ixAwaited, union, named, isNamed) => (R: IxRegCore, t: Ty): Ty => {
  const deep = (x: Ty, d: number): Ty => (d > 10 ? x : union(ixUm(R, x).map((m) => (m.k === "named" && m.n === "Promise" ? deep(m.args[0] ?? m, d + 1) : ixAwaited(R, m, false)))));
  return t.k === "union" || isNamed(t, "Promise") ? union(ixUm(R, t).map((m) => (m.k === "named" && m.n === "Promise" ? named("Promise", deep(m.args[0] ?? m, 0)) : m))) : t;
};

export const ixInferRest = (ixObjLit, ixArrLit, ixMember, ixAwait, ixYield, ixJsx, ixUnsup, union, UNDEF, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode): Ty | null => {
  switch (e.type) {
    case "ObjectExpression": return ixObjLit(K, T, V, W, C, env, e, null);
    case "ArrayExpression": return ixArrLit(K, T, V, W, C, env, e, null);
    case "ArrowFunctionExpression": case "FunctionExpression": return K.fnExpr(K, T, V, W, C, env, e, null, null);
    case "MemberExpression": return ixMember(K, T, V, W, C, env, e);
    case "ChainExpression": {
      const t = K.infer(K, T, V, W, C, env, e.expression);
      return C.short.has(e.expression.nid) ? union([t, UNDEF]) : t;
    }
    case "CallExpression": case "NewExpression": return K.call(K, T, V, W, C, env, e, null);
    case "AwaitExpression": return ixAwait(K, T, V, W, C, env, e);
    case "YieldExpression": return ixYield(K, T, V, W, C, env, e);
    case "JSXElement": case "JSXFragment": return ixJsx(K, T, V, W, C, env, e);
    case "SequenceExpression": ixUnsup(K, C, e, "comma expression"); return ERR;
    case "TaggedTemplateExpression": ixUnsup(K, C, e, "tagged template"); return ERR;
    default: return null;
  }
};

export const ixAwait = (ixErr, ixAwaited) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AwaitExpression): Ty => {
  if (!env.fi.isAsync) ixErr(K, C, e, "type", "await outside an async function");
  else if (env.fi.inAction) ixErr(K, C, e, "action-async", "await in an action body: an action is synchronous; wait in an async cell and give the result to an action (S6.12)");
  return ixAwaited(K.reg, K.infer(K, T, V, W, C, env, e.argument), false);
};

export const ixYield = (ixErr, ixUnsup, show, UNDEF, UNKNOWN, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: YieldExpression): Ty => {
  if (!env.fi.isGen) ixErr(K, C, e, "type", "yield outside a generator");
  if (e.delegate) { ixUnsup(K, C, e, "yield*"); return ERR; }
  const t = K.check(K, T, V, W, C, env, e.argument, env.fi.yieldCtx, false, false);
  C.yields = [...C.yields, t];
  return UNKNOWN;
};

export const ixPreludeCall = (ixTypeArgs, ixErr, ixSnapshotCall, ixStateCall, ixActionCall, ixReadCall, ixOnCall, ixMemoCall, ixCastCall, ixFact, BOOL, STR, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: CallExpression, name: string, expected: Ty | null): Ty => {
  ixFact(C, { k: "prelude", at: e.nid, name });
  const args = e.arguments, explicit = ixTypeArgs(K, V, env, e.typeArguments);
  if (name === "on") return ixOnCall(K, T, V, W, C, env, e);
  if (name === "cast") return ixCastCall(K, T, V, W, C, env, e, explicit);
  if (name === "equals") {
    if (args.length !== 2) ixErr(K, C, e, "arity", "equals takes two arguments");
    for (const a of args) K.infer(K, T, V, W, C, env, a);
    return BOOL;
  }
  if (name === "messageOf") {
    if (args.length !== 1) ixErr(K, C, e, "arity", "messageOf takes one argument");
    for (const a of args) K.infer(K, T, V, W, C, env, a);
    return STR;
  }
  if (!["snapshot", "state", "action", "read", "memo"].includes(name)) return ERR;
  if (args.length !== 1) ixErr(K, C, e, "arity", `${name} takes one argument`);
  const a = args[0] ?? null;
  if (name === "memo") return ixMemoCall(K, T, V, W, C, env, e, a, expected);
  if (name === "state") return ixStateCall(K, T, V, W, C, env, a, expected, explicit);
  if (name === "action") return ixActionCall(K, T, V, W, C, env, e, a, expected);
  if (name === "read") return ixReadCall(K, T, V, W, C, env, e, a);
  return ixSnapshotCall(K, T, V, W, C, env, e, a);
};

// e1 (2026-11-23), S9.8: cast<T>(v) gives a Cast<T>; T is the one type argument and must have a run-time shape
// (shape.ss.ts shapeAt, the boundary's). The shape of each call is kept by the callee's position, for the compiler
export const ixCastCall = (ixErr, shapeAt, show, named, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: CallExpression, explicit: Ty[] | null): Ty => {
  if (e.arguments.length !== 1) ixErr(K, C, e, "arity", "cast takes one argument: cast<T>(v)");
  for (const a of e.arguments) K.infer(K, T, V, W, C, env, a);
  const t = explicit !== null && explicit.length === 1 ? explicit[0] : undefined;
  if (t === undefined) { ixErr(K, C, e, "cast-type", "cast needs the type to check against as its one type argument: cast<T>(v)"); return ERR; }
  if (t.k === "err") return ERR;
  const s = shapeAt(t, { expand: K.reg.expand, isAlias: K.reg.isAlias });
  if (s.k === "error") { ixErr(K, C, e, "cast-type", `cast<${show(t)}> cannot be checked at run time: it is or holds ${s.error}; cast to plain data (numbers, strings, booleans, null, literal types, arrays, tuples and records of them) and make the rest from it`); return ERR; }
  C.casts = [...C.casts.filter((x) => x[0] !== e.callee.start), [e.callee.start, s]];
  return named("Cast", t);
};

// snapshot(x): a copy of x (structuredClone, or slice for a typed array), so a fresh value: its type is x's with no Mut
export const ixSnapshotCall = (owStripMut, unwrap, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode, a: AstNode | null): Ty => {
  const t = a !== null ? K.infer(K, T, V, W, C, env, a) : ERR;
  if (t.k === "err") return ERR;
  C.freshAt = e.nid;
  return owStripMut(K.reg.quiet, unwrap(t));
};

export const ixStateCall = (named, isNamed, widen, inexact, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, a: AstNode | null, expected: Ty | null, explicit: Ty[] | null): Ty => {
  const inner = explicit?.[0] ?? (expected !== null && expected.k === "named" && isNamed(expected, "StateCell") ? expected.args[0] ?? null : null);
  const t = a !== null ? K.check(K, T, V, W, C, env, a, inner, false, false) : ERR;
  return named("StateCell", inner ?? inexact(widen(t)));
};

export const ixActionCall = (ixErr, ixUnsup, ixPromiseIn, ixActionFn, ixFact, named, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode, a: AstNode | null, expected: Ty | null): Ty => {
  if (a === null || (a.type !== "ArrowFunctionExpression" && a.type !== "FunctionExpression")) { ixUnsup(K, C, e, "action(...) of a non-literal function"); return ERR; }
  const args = expected !== null && expected.k === "named" && expected.n === "Action" ? expected.args[0] : undefined;
  const ctx = args !== undefined && args.k === "tup" ? ixActionFn(args) : null;
  ixFact(C, { k: "action", at: a.nid });
  if (a.async || a.generator) ixErr(K, C, a, "action-async", `the function given to action(...) is ${a.async ? "async" : "a generator"}; an action is synchronous (S6.12)`);
  const f = K.fnExpr(K, T, V, W, C, { ...env, fi: { ...env.fi, inAction: true } }, a, ctx, null);
  if (f.k !== "fn") return ERR;
  const p = a.async || a.generator ? null : ixPromiseIn(K.reg, f.ret, 0);
  if (p) ixErr(K, C, a, "action-async", `the function given to action(...) returns ${p}; an action is synchronous (S6.12)`);
  T.set(a.nid, f);
  return named("Action", { k: "tup", els: f.ps.map((q) => q.t) });
};

// memo(f) (S2.13): the type of f, a function literal that is neither async nor a generator; what f may use and take is
// checked after inference (mdMemoErrs)
export const ixMemoCall = (ixErr, ixUnsup, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode, a: AstNode | null, expected: Ty | null): Ty => {
  if (a === null) return ERR;
  if (a.type !== "ArrowFunctionExpression" && a.type !== "FunctionExpression") {
    K.infer(K, T, V, W, C, env, a);
    ixUnsup(K, C, e, "memo(...) of a non-literal function");
    return ERR;
  }
  if (a.async || a.generator) ixErr(K, C, a, "memo-pure", `the function given to memo(...) is ${a.async ? "async" : "a generator"}; a stored promise or generator would be shared by every call`);
  return K.check(K, T, V, W, C, env, a, expected, false, false);
};

// read(s): the value as of this point in the call order; only inside an action body
export const ixReadCall = (ixInActionOnly, ixErr, show, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode, a: AstNode | null): Ty => {
  ixInActionOnly(K, C, env, e, "read-outside-action", "read(...) is only for an action body; a cell takes the value as a parameter");
  const t = a !== null ? K.infer(K, T, V, W, C, env, a) : ERR;
  if (t.k === "err" || a === null) return ERR;
  if (t.k !== "named" || t.n !== "State") { ixErr(K, C, a, "type", `read needs a State<T>, got ${show(t)}`); return ERR; }
  return t.args[0] ?? ERR;
};

export const ixOnCall = (ixErr, named, show, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: CallExpression): Ty => {
  const [h, act] = e.arguments;
  if (e.arguments.length !== 2 || h === undefined || act === undefined) { ixErr(K, C, e, "arity", "on takes an events handle and an action"); return named("Listener"); }
  const s = K.infer(K, T, V, W, C, env, h);
  if (s.k === "err") return named("Listener");
  if (s.k !== "named" || s.n !== "Events") { ixErr(K, C, h, "type", `on needs an Events<T>, got ${show(s)}`); return named("Listener"); }
  K.check(K, T, V, W, C, env, act, named("Action", { k: "tup", els: [s.args[0] ?? ERR] }), false, false);
  return named("Listener");
};

export const ixAt = () => (C: IxCtls, n: AstNode): IxSpan => {
  C.nextNid += 1;
  return { nid: C.nextNid, start: n.start, end: n.end, line: n.line };
};

// a text child as the string literal it gives; null for whitespace that holds a line break
export const ixJsxText = (ixAt) => (C: IxCtls, c: JSXText): AstNode | null => {
  const t = c.value.replace(/\s*\n\s*/g, " ");
  if (t.trim() === "" && c.value.includes("\n")) return null;
  return { ...ixAt(C, c), type: "Literal", value: t, raw: JSON.stringify(t), regex: null, bigint: null };
};

export const ixJsxChildren = (ixJsxText, ixUnsup, ixGap) => (K: IxK, C: IxCtls, e: JSXElement | JSXFragment): AstNode[] | null => {
  const out: Mut<AstNode[]> = [];
  for (const c of e.children) {
    if (c.type === "Other") { ixGap(C, `jsx child ${c.kind} (Other)`); return null; }
    if (c.type === "JSXText") { const t = ixJsxText(C, c); if (t !== null) out.push(t); }
    else if (c.type === "JSXExpressionContainer") { if (c.expression.type !== "JSXEmptyExpression") out.push(c.expression); }
    else if (c.type === "JSXElement" || c.type === "JSXFragment") out.push(c);
    else { ixUnsup(K, C, c, c.type); return null; }
  }
  return out;
};

// a bare attribute (<a b/>) is true
export const ixJsxProps = (ixJsxProp, ixAt, ixUnsup, ixGap) => (K: IxK, C: IxCtls, op: JSXOpeningElement): AstNode[] | null => {
  const out: Mut<AstNode[]> = [];
  for (const a of op.attributes) {
    if (a.type === "Other") { ixGap(C, `jsx attribute ${a.kind} (Other)`); return null; }
    if (a.type !== "JSXAttribute" || a.name.type !== "JSXIdentifier") { ixUnsup(K, C, a, a.type === "JSXAttribute" ? "namespaced attribute" : "spread attribute"); return null; }
    const raw = a.value;
    let v: AstNode;
    if (raw === null) v = { ...ixAt(C, a), type: "Literal", value: true, raw: "true", regex: null, bigint: null };
    else if (raw.type === "Literal") v = raw;
    else if (raw.type === "JSXExpressionContainer" && raw.expression.type !== "JSXEmptyExpression") v = raw.expression;
    else { ixUnsup(K, C, a, "attribute value"); return null; }
    out.push(ixJsxProp(C, a, a.name, a.name.name, v));
  }
  return out;
};

// e1 (2026-11-23), B4: key is the renderer's, as on an element (CommonProps), and is not given to the component; a9
// (2026-11-23), B-1: h does not pass it (lite/jsx/h.ts), so a component whose props declare key is rejected after the call
export const ixJsxGiven = (ixAt, union, STR, NUM) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, op: AstNode, all: AstNode[]): AstNode => {
  const isKey = (x: AstNode): boolean => x.type === "Property" && x.key.type === "Identifier" && x.key.name === "key";
  for (const k of all.filter(isKey)) if (k.type === "Property") K.check(K, T, V, W, C, env, k.value, union([STR, NUM]), false, false);
  return { ...ixAt(C, op), type: "ObjectExpression", properties: all.filter((x) => !isKey(x)) };
};

export const ixJsxKeyProp = (ixUm, ixErr) => (K: IxK, T: IxTypes, C: IxCtls, e: AstNode, callee: AstNode, name: string): void => {
  const ct = T.get(callee.nid);
  if (ct === undefined || ct.k === "err") return;
  const declares = K.reg.callSigs(ct).some((s) => { const p = s.ps[0]?.t; return p !== undefined && ixUm(K.reg, p).some((m) => m.k !== "err" && K.reg.member(m, "key") !== undefined); });
  if (declares) ixErr(K, C, e, "type", `component ${name}'s props declare key, which JSX keeps for the renderer and does not pass to a component: rename the prop (for example id) and pass it as id={...}`);
};

export const ixJsx = (ixJsxChildren, ixJsxProps, ixJsxProp, ixJsxGiven, ixJsxKeyProp, ixAt, ixUnsup, ixErr, ixGap, named, show, ERR) => (K: IxK, T: IxTypes, V: IxVars, W: IxFlows, C: IxCtls, env: IxEnv, e: AstNode): Ty => {
  const ELEM = named("Elem");
  if (e.type !== "JSXElement" && e.type !== "JSXFragment") return ixGap(C, `jsx ${e.type}`);
  const children = ixJsxChildren(K, C, e);
  if (children === null) return ERR;
  if (e.type === "JSXFragment") { for (const k of children) K.check(K, T, V, W, C, env, k, named("Child"), false, false); return ELEM; }
  const op = e.openingElement;
  if (op.type !== "JSXOpeningElement") return ixGap(C, `jsx opening ${op.type}`);
  const props = ixJsxProps(K, C, op);
  if (props === null) return ERR;
  const all = children.length ? [...props, ixJsxProp(C, e, e, "children", { ...ixAt(C, e), type: "ArrayExpression", elements: children })] : props;
  const obj: AstNode = { ...ixAt(C, op), type: "ObjectExpression", properties: all };
  const name = op.name;
  if (name.type !== "JSXIdentifier") { ixUnsup(K, C, name, "member or namespaced element name"); return ERR; }
  if (/^[a-z]/.test(name.name)) {
    const p = K.reg.member(named("IntrinsicElements"), name.name);
    if (!p) { ixErr(K, C, name, "no-member", `<${name.name}> is not a declared element`); K.infer(K, T, V, W, C, env, obj); return ERR; }
    K.check(K, T, V, W, C, env, obj, p.t, false, false);
    return ELEM;
  }
  const callee: AstNode = { ...ixAt(C, name), type: "Identifier", name: name.name, optional: null, typeAnnotation: null };
  const t = K.call(K, T, V, W, C, env, { ...ixAt(C, e), type: "CallExpression", optional: false, callee, arguments: [ixJsxGiven(K, T, V, W, C, env, op, all)], typeArguments: null }, ELEM);
  if (t.k !== "err" && !K.reg.sub(t, ELEM)) ixErr(K, C, e, "type", `component ${name.name} returns ${show(t)}, not Elem`);
  ixJsxKeyProp(K, T, C, e, callee, name.name);
  return ELEM;
};

export const ixFreshCtl = () => (count: number): IxCtl => ({
  cur: 0, nextFlow: 0, diags: null, unsup: null, rets: [], yields: [], quiet: 0, nextId: 0, nextScope: 0, nextNid: count,
  fresh: 1000000, short: new Set(), clones: new Set(), breaks: null, flagsAt: -1, flags: undefined, freshAt: -1, tries: 0, gap: null, facts: null, probe: null, casts: [], holes: [], fnw: new Map(),
});

export const ixCheckFn = (ixKnot, ixFreshCtl, ixDrain, ixOut, ixFoldFacts) => (reg: IxReg, input: IxInput): IxOutput => {
  const K: IxK = ixKnot(reg, input.src, input.cellNames, input.allowed, null);
  const T: IxTypes = new Map(), V: IxVars = new Map(), W: IxFlows = new Map([[0, new Map()]]);
  const C: IxCtls = { ...ixFreshCtl(input.count) };
  C.nextFlow = 1;
  for (const g of input.globals) {
    C.nextId += 1;
    V.set(`0:${g.name}`, { id: C.nextId, scope: 0, name: g.name, t: g.t, kind: g.kind, nid: -1, fi: -1, fnNode: -1, mutOwned: false, assigned: false, cellParam: false, checked: true, lazy: { k: "none" } });
  }
  const fn = K.fnExpr(K, T, V, W, C, null, input.fn, null, input.injected);
  ixDrain(K, C);
  return { fn, diags: ixOut(C.diags), unsup: ixOut(C.unsup), gap: C.gap, facts: ixFoldFacts(T, V, C.facts) };
};

export const ixFactList = () => (log: IxFactLog | null): IxFact[] => {
  const out: Mut<IxFact[]> = [];
  for (let x = log; x !== null; x = x.next) out.push(x.f);
  out.reverse();
  return out;
};

// bindingOf in insertion order; each binding as last written; the globals as scope 0 holds them
export const ixFoldBindings = () => (V: IxVars, fs: IxFact[]): IxBindingFacts => {
  const of: Mut<Map<number, number>> = new Map(), bs: Mut<Map<number, IxBinding>> = new Map();
  for (const b of V.values()) if (b.scope === 0) bs.set(b.id, b);
  for (const f of fs) {
    if (f.k === "binding") bs.set(f.b.id, f.b);
    else if (f.k === "bind") of.set(f.at, f.id);
  }
  return { bindingOf: of, bindings: bs };
};

// a helper or prelude fact replaces the call's entry; a signature is merged into it
export const ixFoldCalls = (IX_NO_CALL) => (fs: IxFact[]): Map<number, IxCallFact> => {
  const out: Mut<Map<number, IxCallFact>> = new Map();
  for (const f of fs) {
    if (f.k === "helper") out.set(f.at, { ...IX_NO_CALL, helper: f.id });
    else if (f.k === "prelude") out.set(f.at, { ...IX_NO_CALL, prelude: f.name });
    else if (f.k === "sig") out.set(f.at, { ...(out.get(f.at) ?? IX_NO_CALL), sig: f.sig });
  }
  return out;
};

export const ixFoldFlags = () => (fs: IxFact[]): Map<number, Flags | null> => {
  const out: Mut<Map<number, Flags | null>> = new Map();
  for (const f of fs) if (f.k === "flags") out.set(f.at, f.flags);
  return out;
};

// an in-action use is kept when its function was not an action body when the use was met
export const ixFoldActions = () => (fs: IxFact[]): IxActionFacts => {
  const bodies: Mut<Set<number>> = new Set(), props: Mut<Set<number>> = new Set(), uses: Mut<IxUse[]> = [];
  for (const f of fs) {
    if (f.k === "action") bodies.add(f.at);
    else if (f.k === "stateProp") props.add(f.at);
    else if (f.k === "use" && !bodies.has(f.fi)) uses.push({ fi: f.fi, at: f.at, rule: f.rule, msg: f.msg });
  }
  return { actionBodies: bodies, inActionUses: uses, stateProps: props };
};

export const ixFoldFacts = (ixFactList, ixFoldBindings, ixFoldCalls, ixFoldFlags, ixFoldActions) => (T: IxTypes, V: IxVars, log: IxFactLog | null): IxFacts => {
  const fs = ixFactList(log);
  const b = ixFoldBindings(V, fs), a = ixFoldActions(fs);
  return { ...a, types: new Map(T), bindingOf: b.bindingOf, bindings: b.bindings, calls: ixFoldCalls(fs), memberFlags: ixFoldFlags(fs) };
};

export type OwTree = {
  readonly fn: AstNode; readonly parent: Map<number, AstNode>; readonly byNid: Map<number, AstNode>;
  readonly all: AstNode[]; readonly fns: AstNode[]; readonly refs: Map<number, AstNode[]>; readonly other: string | null;
};

// per function: the Mut and Borrowed bindings it captures, those of them it writes, the let and param bindings it
// assigns, the helpers it calls
export type OwCap = { readonly mut: number[]; readonly wmut: number[]; readonly let: number[]; readonly read: number[]; readonly calls: number[] };

// ---- the flow check ----
// the bindings used up by a freeze, an await or a yield on the way to a point
export type OwSt = Set<number>;

export type OwK = {
  readonly expr: (K: OwK, O: OwCtx, W: OwW, X: OwX, P: OwFlowFn, n: AstNode, st: OwSt) => OwSt;
  readonly stmt: (K: OwK, O: OwCtx, W: OwW, X: OwX, P: OwFlowFn, s: AstNode, st: OwSt) => OwSt | null;
};

export const owIndex = (kidsOf, isFnNode) => (F: IxFacts, cellFn: AstNode): OwTree => {
  const parent: Mut<Map<number, AstNode>> = new Map(), byNid: Mut<Map<number, AstNode>> = new Map();
  const all: Mut<AstNode[]> = [], fns: Mut<AstNode[]> = [], refs: Mut<Map<number, AstNode[]>> = new Map();
  const todo: Mut<AstNode[]> = [cellFn];
  let other: string | null = null;
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    all.push(n);
    byNid.set(n.nid, n);
    if (n.type === "Other" && other === null) other = `node ${n.kind} (Other)`;
    if (isFnNode(n)) fns.push(n);
    const id = n.type === "Identifier" ? F.bindingOf.get(n.nid) : undefined;
    const b = id === undefined ? undefined : F.bindings.get(id);
    if (b !== undefined && b.nid !== n.nid) refs.set(b.id, [...(refs.get(b.id) ?? []), n]);
    const ks = kidsOf(n);
    for (const k of ks) parent.set(k.nid, n);
    for (const k of ks.toReversed()) todo.push(k);
  }
  return { fn: cellFn, parent: parent, byNid: byNid, all: all, fns: fns, refs: refs, other };
};

// the function around n, or the cell's
export const owEncl = (isFnNode) => (O: OwCtx, n: AstNode): AstNode => {
  let p = O.T.parent.get(n.nid);
  while (p !== undefined && !isFnNode(p)) p = O.T.parent.get(p.nid);
  return p ?? O.T.fn;
};

export const owBindingAt = () => (O: OwCtx, n: AstNode): IxBinding | undefined => {
  const id = O.F.bindingOf.get(n.nid);
  return id === undefined ? undefined : O.F.bindings.get(id);
};

// a global's declaration is in another source; no use of inside can tell it from one outside f
export const owInside = () => (O: OwCtx, b: IxBinding, f: AstNode): boolean => {
  const d = O.T.byNid.get(b.nid);
  return d !== undefined && d.start >= f.start && d.end <= f.end;
};

export const owIsCallee = () => (O: OwCtx, r: AstNode): boolean => {
  const p = O.T.parent.get(r.nid);
  return p !== undefined && p.type === "CallExpression" && p.callee.nid === r.nid;
};

// bindingOfFn: over the bindings bindingOf holds, in the order first met, the last naming each function
export const owBindingOfFn = () => (F: IxFacts): Map<number, number> => {
  const seen: Mut<Set<number>> = new Set(), out: Mut<Map<number, number>> = new Map();
  for (const id of F.bindingOf.values()) {
    if (seen.has(id)) continue;
    seen.add(id);
    const b = F.bindings.get(id);
    if (b !== undefined && b.fnNode >= 0) out.set(b.fnNode, id);
  }
  return out;
};

// the binding of a function that is a const or a function declaration and only called
// every name of f only called; a function expression also bound to a const (its own name alone is not a helper's)
export const owHelper = (owIsCallee) => (O: OwCtx, byFn: Map<number, number>, f: AstNode): IxBinding | undefined => {
  const id = byFn.get(f.nid), b = id === undefined ? undefined : O.F.bindings.get(id);
  if (b === undefined || (b.kind !== "const" && b.kind !== "fn")) return undefined;
  let bound = f.type !== "FunctionExpression";
  for (const x of O.F.bindings.values()) {
    if (x.fnNode !== f.nid) continue;
    if (x.kind === "const") bound = true;
    if (!(O.T.refs.get(x.id) ?? []).every((r) => owIsCallee(O, r))) return undefined;
  }
  return bound ? b : undefined;
};

export const owErr = (ixPush) => (W: OwW, at: AstNode, rule: string, msg: string): void => {
  const k = `${at.start}:${rule}`;
  if (W.seen.has(k)) return;
  W.seen = new Set([...W.seen, k]);
  W.errs = ixPush(W.errs, { start: at.start, end: at.end, rule, msg });
};

export const owUnsup = (ixPush) => (W: OwW, at: AstNode, what: string): void => {
  W.unsup = ixPush(W.unsup, { start: at.start, end: at.end, rule: "unsupported", msg: what });
};

// the declared (uninstantiated) type of argument i of a resolved call
export const owDeclParam = () => (O: OwCtx, call: AstNode, i: number, rest: boolean): Ty | undefined => {
  const sig = O.F.calls.get(call.nid)?.sig ?? null;
  if (sig === null) return undefined;
  const d = sig.decl ?? sig, p = i < d.ps.length ? d.ps[i] : undefined;
  return i < d.ps.length ? p?.t : rest ? d.rest : undefined;
};

export const owNonRetainingArg = (owDeclParam) => (O: OwCtx, call: AstNode, i: number): boolean => {
  const flags = O.F.calls.get(call.nid)?.sig?.flags;
  const dp = owDeclParam(O, call, i, true);
  return !!flags?.intrinsic && !flags.retains && dp !== undefined && dp.k !== "tv";
};

export const owMutParamArg = (owDeclParam, isNamed) => (O: OwCtx, call: AstNode, i: number): boolean => {
  const dp = owDeclParam(O, call, i, false);
  return dp !== undefined && isNamed(dp, "Mut");
};

export const owTyKids = () => (t: Ty): Ty[] => {
  switch (t.k) {
    case "arr": return [t.el];
    case "tup": return t.els;
    case "union": return t.ts;
    case "rec": return [...[...t.props.values()].map((p) => p.t), ...(t.index ? [t.index] : [])];
    default: return [];
  }
};

export const owIterIn = (show, owTyKids) => {
  function iterIn(R: IxRegCore, t: Ty, depth: number, none: Mut<Map<string, number>>): string | null {
    if (depth > 12) return null;
    switch (t.k) {
      case "tv": return `the type parameter ${show(t)}`;
      case "arr": case "tup": case "union": case "rec": return inner(R, owTyKids(t), depth, none);
      case "named": {
        // d1 (2026-11-24): a FetchResponse's body can be read once, so it is one-shot as an iterator is
        if (t.n === "Iterable" || t.n === "Generator" || t.n === "FetchResponse") return show(t);
        if (t.n === "Action" || t.n === "State" || t.n === "Events") return null;
        if (!R.isAlias(t.n)) return inner(R, t.args, depth, none);
        const plain = !t.args.length, at = none.get(t.n);
        if (plain && at !== undefined && at <= depth) return null;
        const w = iterIn(R, R.expand(t), depth + 1, none);
        if (!w && plain) none.set(t.n, depth);
        return w;
      }
      default: return null;
    }
  }
  function inner(R: IxRegCore, ts: Ty[], depth: number, none: Mut<Map<string, number>>): string | null {
    for (const x of ts) { const w = iterIn(R, x, depth + 1, none); if (w) return w; }
    return null;
  }
  return iterIn;
};

export const owIter = (owIterIn) => (R: IxRegCore, t: Ty): string | null => {
  const none: Mut<Map<string, number>> = new Map();
  return owIterIn(R, t, 0, none);
};

// where a type holds Mut<…>: through arrays, tuples, unions, records, type arguments and aliases; not inside a function
// type (its parameters are its callers'; a result can hold only a Mut the caller gave it, as a registry's memo)
export const owMutIn = (show, owTyKids) => {
  function mutIn(R: IxRegCore, t: Ty, depth: number, none: Mut<Map<string, number>>): string | null {
    if (depth > 12) return null;
    switch (t.k) {
      case "arr": case "tup": case "union": case "rec": return inner(R, owTyKids(t), depth, none);
      case "named": {
        if (t.n === "Mut") return show(t);
        if (!R.isAlias(t.n)) return inner(R, t.args, depth, none);
        const plain = !t.args.length, at = none.get(t.n);
        if (plain && at !== undefined && at <= depth) return null;
        const w = mutIn(R, R.expand(t), depth + 1, none);
        if (!w && plain) none.set(t.n, depth);
        return w;
      }
      default: return null;
    }
  }
  function inner(R: IxRegCore, ts: Ty[], depth: number, none: Mut<Map<string, number>>): string | null {
    for (const x of ts) { const w = mutIn(R, x, depth + 1, none); if (w) return w; }
    return null;
  }
  return mutIn;
};

// rule set R (r2; k1, 2026-11-23): where a value of type t lets its holder reach a Mut: record fields, elements, unions,
// type arguments, aliases, and the result of a function or of a record's call or construct signature, not a parameter
// (what the holder gives). R-K, R-Y and R-A take a binding whose type this finds. A part already walked, or an alias met
// again with the same arguments, adds nothing; more than 12 expansions of generic aliases on one path, or more than
// 200 levels, count as holding one
export const owMutDeep = (show, typeKey, owTyKids) => (R: IxRegCore, t0: Ty): string | null => {
  const seen: Mut<Set<string>> = new Set(), done: Mut<Set<Ty>> = new Set();
  function step(t: Ty, d: number, g: number): string | null {
    const inner = (ts: Ty[]): string | null => { for (const x of ts) { const w = deep(x, d + 1, g); if (w) return w; } return null; };
    if (t.k === "fn") return inner([t.ret]);
    if (t.k === "rec") return inner([...owTyKids(t), ...[...(t.calls ?? []), ...(t.ctors ?? [])].map((c) => c.ret)]);
    if (t.k !== "named") return inner(owTyKids(t));
    if (t.n === "Mut") return show(t);
    if (!R.isAlias(t.n)) return inner(t.args);
    const key = typeKey(t);
    if (seen.has(key)) return null;
    seen.add(key);
    return deep(R.expand(t), d + 1, t.args.length ? g + 1 : g);
  }
  function deep(t: Ty, d: number, g: number): string | null {
    if (done.has(t)) return null;
    if (d > 200 || g > 12) return `a part nested more deeply than the checker looks (${show(t)})`;
    const w = step(t, d, g);
    done.add(t);
    return w;
  }
  return deep(t0, 0, 0);
};

// a local of an enclosing function whose type holds a Mut (owMutDeep): not a cell input, a global, a prelude name or a
// function declaration, which R-K, R-Y and R-A do not follow
export const owLocalHoldsMut = (owMutDeep) => (O: OwCtx, b: IxBinding): boolean =>
  !b.cellParam && b.kind !== "global" && b.kind !== "prelude" && b.kind !== "fn" && owMutDeep(O.R, b.t) !== null;

export const owMut = (owMutIn) => (R: IxRegCore, t: Ty): string | null => {
  const none: Mut<Map<string, number>> = new Map();
  return owMutIn(R, t, 0, none);
};

// S4.4 (k1, 2026-11-23): what a cell exposes, with every Mut<X> that owMutDeep finds read as X, at any depth (inside a
// function's result too, not in a parameter). An alias met again inside itself, or a part deeper than owMutDeep looks,
// that holds a Mut is unknown
export const owStripMut = (owMutDeep, typeKey, union, UNKNOWN) => (R: IxRegCore, t0: Ty): Ty => {
  const open: Mut<Set<string>> = new Set(), done: Mut<Map<string, Ty>> = new Map();
  function named(t: Named, d: number, g: number): Ty {
    if (t.n === "Mut") return strip(t.args[0] ?? UNKNOWN, d + 1, g);
    if (!R.isAlias(t.n)) return { k: "named", n: t.n, args: t.args.map((x) => strip(x, d + 1, g)) };
    const key = typeKey(t), hit = done.get(key);
    if (hit !== undefined || open.has(key)) return hit ?? UNKNOWN;
    open.add(key);
    const r = strip(R.expand(t), d + 1, t.args.length ? g + 1 : g);
    open.delete(key); done.set(key, r);
    return r;
  }
  function strip(t: Ty, d: number, g: number): Ty {
    if (owMutDeep(R, t) === null) return t;
    if (d > 200 || g > 12) return UNKNOWN;
    const s = (x: Ty): Ty => strip(x, d + 1, g);
    if (t.k === "arr") return { k: "arr", el: s(t.el) };
    if (t.k === "tup") return { k: "tup", els: t.els.map((x) => s(x)) };
    if (t.k === "union") return union(t.ts.map((x) => s(x)));
    if (t.k === "fn") return { ...t, ret: s(t.ret) };
    if (t.k === "named") return named(t, d, g);
    if (t.k !== "rec") return t;
    return { ...t, props: new Map([...t.props].map(([k, p]): [string, Prop] => [k, { ...p, t: s(p.t) }])), index: t.index ? s(t.index) : t.index, calls: t.calls?.map((c): Fn => ({ ...c, ret: s(c.ret) })), ctors: t.ctors?.map((c): Fn => ({ ...c, ret: s(c.ret) })) };
  }
  return strip(t0, 0, 0);
};

// r is written: an assignment's or update's target, or a destructuring target
export const owAssignedRef = () => (O: OwCtx, r: AstNode): boolean => {
  const p = O.T.parent.get(r.nid);
  if (p === undefined) return false;
  if (p.type === "AssignmentExpression") return p.left.nid === r.nid;
  if (p.type === "UpdateExpression") return p.argument.nid === r.nid;
  if (p.type === "ArrayPattern") return true;
  if (p.type === "Property") return O.T.parent.get(p.nid)?.type === "ObjectPattern";
  return p.type === "AssignmentPattern" && p.left.nid === r.nid;
};

// r writes the value its binding holds: the object of a member write, an update or a delete, the receiver of a
// mutating method (through a chain of members), or an argument to a parameter typed Mut<…>
export const owWriteRef = (owArgIndex, owMutParamArg) => (O: OwCtx, r: AstNode): boolean => {
  let cur = r;
  for (let p = O.T.parent.get(cur.nid); p !== undefined; p = O.T.parent.get(cur.nid)) {
    if (p.type === "CallExpression") return p.callee.nid !== cur.nid && owMutParamArg(O, p, owArgIndex(p.arguments, cur));
    if (p.type !== "MemberExpression" || p.object.nid !== cur.nid) return false;
    const up = O.T.parent.get(p.nid);
    if (up !== undefined && up.type === "CallExpression" && up.callee.nid === p.nid) return !!O.F.memberFlags.get(p.nid)?.mutates;
    if (up !== undefined && ((up.type === "AssignmentExpression" && up.left.nid === p.nid) || up.type === "UpdateExpression" || (up.type === "UnaryExpression" && up.operator === "delete"))) return true;
    cur = p;
  }
  return false;
};

// e1 (2026-11-23): a copy keeps a type parameter, so for a type that holds one the fix is not a copy
export const owIterMsg = (hasTv) => (b: IxBinding, it: string): string => it === "FetchResponse"
  ? `${b.name} holds a FetchResponse, captured by a nested function: a response's body can be read once, so the function may find it used up; read what the function needs before it (const ok = ${b.name}.ok, or const data = await ${b.name}.json()) and capture that`
  : hasTv(b.t)
  ? `${b.name} may hold an iterator (${it}: a type parameter may be one), which reading uses up, so a function that captures it may give a different result for the same call; a copy has the same type, so read ${b.name} without a nested function that captures it (a for loop in place of a callback), or give it a type with no type parameter`
  : `${b.name} may hold an iterator (${it}), which reading uses up, so a function that captures it may give a different result for the same call; copy it into an array where it is made, under a read-only type, and capture that (const c: readonly T[] = [...${b.name}], T its element type)`;

// e1 (2026-11-23): a typed array or URL cannot be frozen, and a copy of one is one too: what a kept function may capture
// is the data copied out (S4.10)
export const owUnfreezableFix = () => (n: string, name: string): string => n === "URL"
  ? `its text (const c = ${name}.href)`
  : `its elements as a read-only array (const c: readonly number[] = [...${name}])`;

// one reference, for each function from the innermost out to the first that declares the binding
export const owCaptureRef = (owEncl, owInside, owIsMut, owIsBor, owIter, owIterMsg, owErr, owAssignedRef, owWriteRef, owIsCallee, owAdd) => (O: OwCtx, W: OwW, caps: OwCaps, b: IxBinding, r: AstNode): void => {
  for (let f = owEncl(O, r); f.nid !== O.T.fn.nid; f = owEncl(O, f)) {
    if (owInside(O, b, f)) break;
    const c = caps.get(f.nid) ?? { mut: [], wmut: [], let: [], read: [], calls: [] };
    const it = b.kind !== "global" && b.kind !== "prelude" ? owIter(O.R, b.t) : null;
    if (it) owErr(W, r, "iterator-capture", owIterMsg(b, it));
    const lets = owAssignedRef(O, r) && (b.kind === "let" || b.kind === "param");
    caps.set(f.nid, {
      mut: owIsMut(b) || owIsBor(b) ? owAdd(c.mut, b.id) : c.mut,
      wmut: owIsMut(b) && owWriteRef(O, r) ? owAdd(c.wmut, b.id) : c.wmut,
      let: lets ? owAdd(c.let, b.id) : c.let,
      read: b.kind !== "global" && b.kind !== "prelude" ? owAdd(c.read, b.id) : c.read,
      calls: b.fnNode >= 0 && owIsCallee(O, r) ? owAdd(c.calls, b.id) : c.calls,
    });
  }
};

// a helper's captures are its caller's, except what the caller declares; one pass over the functions
export const owCapPass = (owInside) => (O: OwCtx, caps: OwCaps): boolean => {
  let changed = false;
  for (const f of O.T.fns) for (const h of caps.get(f.nid)?.calls ?? []) {
    const hb = O.F.bindings.get(h), hc = hb === undefined ? undefined : caps.get(hb.fnNode);
    if (hb === undefined || hb.fnNode < 0 || hc === undefined) continue;
    const fc = caps.get(f.nid) ?? { mut: [], wmut: [], let: [], read: [], calls: [] };
    const take = (from: number[], into: number[]): number[] => [...into, ...from.filter((id) => {
      const b = O.F.bindings.get(id);
      return b !== undefined && !owInside(O, b, f) && !into.includes(id);
    })];
    const mutT = take(hc.mut, fc.mut), wT = take(hc.wmut, fc.wmut), letT = take(hc.let, fc.let), rT = take(hc.read, fc.read);
    if (mutT.length !== fc.mut.length || wT.length !== fc.wmut.length || letT.length !== fc.let.length || rT.length !== fc.read.length) { changed = true; caps.set(f.nid, { mut: mutT, wmut: wT, let: letT, read: rT, calls: fc.calls }); }
  }
  return changed;
};

export const owCaptures = (owCaptureRef, owCapPass) => (O: OwCtx, W: OwW): Map<number, OwCap> => {
  const caps: OwCaps = new Map();
  for (const f of O.T.fns) caps.set(f.nid, { mut: [], wmut: [], let: [], read: [], calls: [] });
  for (const [id, rs] of O.T.refs) {
    const b = O.F.bindings.get(id);
    if (b !== undefined) for (const r of rs) owCaptureRef(O, W, caps, b, r);
  }
  for (let changed = true; changed; ) changed = owCapPass(O, caps);
  return caps;
};

// a function the cell keeps (returned, stored, passed on; not a local helper that is only called, nor a callback an
// intrinsic runs before it returns) may read a captured Mut, which is then frozen where the function is made (the
// compiler emits the freeze): it may not write it, nor may the body write it after the function; a typed array cannot
// be frozen, so it may not be captured. It may not assign a captured let either.
export const owKept = (owHelper, owNonRetainingArg, owArgIndex) => (O: OwCtx, byFn: Map<number, number>, f: AstNode): boolean => {
  const p = O.T.parent.get(f.nid);
  if (p !== undefined && p.type === "CallExpression" && p.callee.nid !== f.nid && owNonRetainingArg(O, p, owArgIndex(p.arguments, f))) return false;
  return owHelper(O, byFn, f) === undefined;
};

// a write r to a binding a kept function f captures may run after f is made: it is not before f in the text, or it is
// inside a function, or inside a loop that also holds f (no run-time freeze at f is emitted yet: holes5)
export const owLateWrite = (isFnNode) => (O: OwCtx, r: AstNode, f: AstNode): boolean => {
  if (r.start > f.end) return true;
  for (let p = O.T.parent.get(r.nid); p !== undefined && p.nid !== O.T.fn.nid; p = O.T.parent.get(p.nid)) {
    if (isFnNode(p)) return true;
    const loop = p.type === "ForStatement" || p.type === "ForOfStatement" || p.type === "ForInStatement" || p.type === "WhileStatement" || p.type === "DoWhileStatement";
    if (loop && p.start <= f.start && f.end <= p.end) return true;
  }
  return false;
};

// where t holds a typed array (which cannot be frozen): through what owTyKids looks into, Mut, type arguments, aliases
// whether a value of type t holds a promise (not through a function type): a function the cell keeps cannot capture one,
// as the promise settles after the function is published (freeze.ts throws at publish; holes8, 2026-11-22)
// perf2 (2026-11-27): per walk, the least depth an alias without type arguments was found to hold nothing from, as
// owIterIn keeps; from as deep the walk finds nothing again. The answers are the same; a captured AstNode walked 3249536
// aliases before
export const owPromiseIn = (owTyKids) => {
  function promiseIn(R: IxRegCore, t: Ty, depth: number, none: Mut<Map<string, number>>): boolean {
    if (depth > 12) return false;
    if (t.k === "named" && t.n === "Promise") return true;
    if (t.k === "named" && R.isAlias(t.n)) {
      const plain = !t.args.length, at = none.get(t.n);
      if (plain && at !== undefined && at <= depth) return false;
      const w = promiseIn(R, R.expand(t), depth + 1, none);
      if (!w && plain) none.set(t.n, depth);
      return w;
    }
    for (const x of t.k === "named" ? t.args : owTyKids(t)) if (promiseIn(R, x, depth + 1, none)) return true;
    return false;
  }
  return (R: IxRegCore, t: Ty): boolean => {
    const none: Mut<Map<string, number>> = new Map();
    return promiseIn(R, t, 0, none);
  };
};

export const owTypedIn = (owTyKids, OW_UNFREEZABLE) => {
  function typedIn(R: IxRegCore, t: Ty, depth: number, none: Mut<Map<string, number>>): string | null {
    if (depth > 12) return null;
    const U: Set<string> = OW_UNFREEZABLE;
    if (t.k === "named" && U.has(t.n)) return t.n;
    if (t.k === "named" && R.isAlias(t.n)) {
      const plain = !t.args.length, at = none.get(t.n);
      if (plain && at !== undefined && at <= depth) return null;
      const w = typedIn(R, R.expand(t), depth + 1, none);
      if (w === null && plain) none.set(t.n, depth);
      return w;
    }
    for (const x of t.k === "named" ? t.args : owTyKids(t)) { const w = typedIn(R, x, depth + 1, none); if (w !== null) return w; }
    return null;
  }
  return (R: IxRegCore, t: Ty): string | null => {
    const none: Mut<Map<string, number>> = new Map();
    return typedIn(R, t, 0, none);
  };
};

// a binding no one else can write: a cell input, or a const typed read-only whose initializer is a fresh copy
export const owTypedSafeB = (owFresh, isNamed) => (O: OwCtx, b: IxBinding): boolean => {
  if (b.cellParam) return true;
  const d = O.T.parent.get(b.nid);
  return b.kind === "const" && !isNamed(b.t, "Mut") && d !== undefined && d.type === "VariableDeclarator" && d.init !== null && owFresh(O, d.init);
};

// an expression that holds no typed array a name in this cell can still write: a fresh copy, a safe binding, a
// literal of such, or a type with no typed array in it
export const owTypedSafe = (owTypedSafeB, owTypedIn, owFresh) => {
  function safe(O: OwCtx, e: AstNode): boolean {
    if (owFresh(O, e) && e.type !== "ArrayExpression" && e.type !== "ObjectExpression") return true;
    if (e.type === "ArrayExpression") return e.elements.every((x) => x === null || safe(O, x.type === "SpreadElement" ? x.argument : x));
    if (e.type === "ObjectExpression") return e.properties.every((p) => (p.type === "SpreadElement" ? safe(O, p.argument) : p.type !== "Property" || safe(O, p.value)));
    const t = O.F.types.get(e.nid);
    if (t === undefined || owTypedIn(O.R, t) === null) return true;
    const id = e.type === "Identifier" ? O.F.bindingOf.get(e.nid) : undefined, b = id === undefined ? undefined : O.F.bindings.get(id);
    return b !== undefined && owTypedSafeB(O, b);
  }
  return safe;
};

// a let (or parameter) a kept function reads, assigned where it may run after the function is made
export const owLateLet = (owAssignedRef, owLateWrite, owErr) => (O: OwCtx, W: OwW, f: AstNode, b: IxBinding): void => {
  if (b.kind !== "let" && b.kind !== "param") return;
  for (const r of O.T.refs.get(b.id) ?? [])
    if ((r.start < f.start || r.start > f.end) && owAssignedRef(O, r) && owLateWrite(O, r, f)) owErr(W, r, "let-capture", `${b.kind} ${b.name} is assigned where it may run after a function the cell keeps read it: that function sees its captures unchanged`);
};

// a write site: n writes the value of expression x (a member assignment, update or delete; a mutating method's receiver)
export const owWriteSite = () => (O: OwCtx, n: AstNode): AstNode | null => {
  const p = O.T.parent.get(n.nid);
  if (n.type !== "MemberExpression" || p === undefined) return null;
  if (p.type === "CallExpression" && p.callee.nid === n.nid) return O.F.memberFlags.get(n.nid)?.mutates ? n.object : null;
  const w = (p.type === "AssignmentExpression" && p.left.nid === n.nid) || p.type === "UpdateExpression" || (p.type === "UnaryExpression" && p.operator === "delete");
  return w ? n.object : null;
};

// n is inside an async or generator function the cell makes: it may run after the cell has returned
export const owInLateFn = (ixFnParts) => (O: OwCtx, n: AstNode): boolean => {
  for (let p = O.T.parent.get(n.nid); p !== undefined && p.nid !== O.T.fn.nid; p = O.T.parent.get(p.nid)) {
    const fp = ixFnParts(p);
    if (fp !== null && (fp.async || fp.generator)) return true;
  }
  return false;
};

// a kept function f can be seen while the cell still runs (a generator cell between yields, an async or generator
// function it made, after it returned): no Mut (under any name, or from a call) is written there after f is made; f
// may have captured it (no run-time freeze at f is emitted yet: holes5)
export const owGenLateWrites = (owWriteSite, owLateWrite, owInLateFn, owErr, ixFnParts, isNamed) => (O: OwCtx, W: OwW, f: AstNode, b: IxBinding): void => {
  const cf = ixFnParts(O.T.fn), gen = cf !== null && cf.generator;
  for (const n of O.T.all) {
    const x = owWriteSite(O, n), t = x === null ? undefined : O.F.types.get(x.nid);
    if (x !== null && t !== undefined && isNamed(t, "Mut") && (n.start < f.start || n.start > f.end) && (gen ? owLateWrite(O, n, f) : owInLateFn(O, n)))
      owErr(W, n, "mut-capture", `a Mut is written where it may run after ${b.name}'s reader, a function the cell keeps, is yielded: it may be what that function captured`);
  }
};

// r is (part of) what f returns or yields: through parentheses, conditional branches, logical operands, a sequence's
// last, a cast, an array or object literal and a spread, up to f's return, its expression body, or a yield in f
export const owFlowsOut = (owEncl) => (O: OwCtx, r: AstNode, f: AstNode): boolean => {
  let cur = r;
  for (let p = O.T.parent.get(cur.nid); p !== undefined; p = O.T.parent.get(cur.nid)) {
    if (p.nid === f.nid) return f.type === "ArrowFunctionExpression" && f.body.nid === cur.nid;
    if (p.type === "ReturnStatement" || p.type === "YieldExpression") return owEncl(O, p).nid === f.nid;
    const through = p.type === "ParenthesizedExpression" || p.type === "ArrayExpression" || p.type === "SpreadElement" || p.type === "ObjectExpression"
      || (p.type === "Property" && p.value.nid === cur.nid) || (p.type === "ConditionalExpression" && p.test.nid !== cur.nid) || p.type === "LogicalExpression"
      || (p.type === "SequenceExpression" && p.expressions.at(-1)?.nid === cur.nid) || p.type === "TSAsExpression" || p.type === "TSNonNullExpression" || p.type === "TSSatisfiesExpression";
    if (!through) return false;
    cur = p;
  }
  return false;
};

// R-K (2026-11-22): a function the cell keeps can run after the cell has given its value, so it captures no Mut and no
// let of an enclosing function, reads included; what to bind instead
export const owKeptReadMsg = (owStripMut, show, isNamed, owMutDeep) => (O: OwCtx, b: IxBinding): string => b.kind !== "let" && !isNamed(b.t, "Mut")
  ? `${b.name}, whose type holds ${owMutDeep(O.R, b.t)}, captured by a function the cell keeps, which can run after the cell has given its value; bind it under a type with no Mut before the function (const c: ${show(owStripMut(O.R, b.t))} = ${b.name}) and capture that, or make it inside the function`
  : isNamed(b.t, "Mut")
  ? `Mut ${b.name} captured by a function the cell keeps, which can run after the cell has given its value; bind it under its plain type before the function (const c: ${show(owStripMut(O.R, b.t))} = ${b.name}) and capture that, or make it inside the function`
  : `let ${b.name} captured by a function the cell keeps, which can run after the cell has given its value; bind its value to a const before the function (const c = ${b.name}) and capture that`;

export const owCaptureErrs = (owKept, owIsBor, owWriteRef, owLateWrite, owLateLet, owGenLateWrites, owFlowsOut, owTypedIn, owTypedSafeB, owPromiseIn, owKeptReadMsg, owLocalHoldsMut, owUnfreezableFix, owStripMut, ixCopyText, owErr, show, unwrap, OW_UNFREEZABLE, owIter) => (O: OwCtx, W: OwW, caps: Map<number, OwCap>, byFn: Map<number, number>): void => {
  const holds: Mut<Map<number, boolean>> = new Map();
  for (const f of O.T.fns) {
    const c = caps.get(f.nid);
    if (f.nid === O.T.fn.nid || c === undefined || !owKept(O, byFn, f)) continue;
    for (const b of c.mut.flatMap((id) => O.F.bindings.get(id) ?? []).filter((x) => owIter(O.R, x.t) !== "FetchResponse")) {
      const u = O.R.expand(unwrap(b.t)), U: Set<string> = OW_UNFREEZABLE;
      if (owIsBor(b)) owErr(W, f, "borrowed-escape", `Borrowed ${b.name} captured by a nested function`);
      else if (c.wmut.includes(b.id)) owErr(W, f, "mut-capture", `Mut ${b.name} written by a function the cell keeps (not a local helper that is only called): it is frozen where the function is made, so the write would throw; make ${b.name} inside the function, or keep it in a state cell that an action writes`);
      else if (u.k === "named" && U.has(u.n)) owErr(W, f, "mut-capture", `Mut ${b.name} (${u.n}) captured by a function the cell keeps: a typed array or URL cannot be frozen, nor can a copy of one; capture ${owUnfreezableFix(u.n, b.name)}`);
      else if ((O.T.refs.get(b.id) ?? []).some((r) => r.start > f.start && r.end <= f.end && owFlowsOut(O, r, f))) owErr(W, f, "mut-capture", `Mut ${b.name} returned or yielded by a function the cell keeps: whoever calls it could write ${b.name}; bind it under its plain type before the function (const c: ${show(owStripMut(O.R, b.t))} = ${b.name}) and return a copy of that (${ixCopyText(O.R, owStripMut(O.R, b.t), "c")})`);
      else { owGenLateWrites(O, W, f, b); for (const r of O.T.refs.get(b.id) ?? []) if ((r.start < f.start || r.start > f.end) && owWriteRef(O, r) && owLateWrite(O, r, f)) owErr(W, r, "mut-capture", `${b.name} may be written after a function the cell keeps captured it (later in the text, in a loop that makes the function, or in a function): a function the cell keeps sees its captures unchanged`); owErr(W, f, "mut-capture", owTypedIn(O.R, b.t) !== null ? `Mut ${b.name} holds a ${owTypedIn(O.R, b.t)}, captured by a function the cell keeps: a typed array or URL cannot be frozen, nor can a copy of one; copy the data out of it before the function and capture that (for the ${owTypedIn(O.R, b.t)} x, ${owUnfreezableFix(owTypedIn(O.R, b.t) ?? "", "x")})` : owKeptReadMsg(O, b)); }
    }
    for (const b of c.let.flatMap((id) => O.F.bindings.get(id) ?? [])) owErr(W, f, "let-capture", `${b.kind} ${b.name} assigned from a function that escapes`);
    for (const b of c.read.flatMap((id) => O.F.bindings.get(id) ?? []).filter((x) => owIter(O.R, x.t) !== "FetchResponse")) {
      owLateLet(O, W, f, b);
      if (b.kind === "let") owErr(W, f, "let-capture", owKeptReadMsg(O, b));
      else if (!c.mut.includes(b.id) && (holds.get(b.id) ?? holds.set(b.id, owLocalHoldsMut(O, b)).get(b.id))) owErr(W, f, "mut-capture", owKeptReadMsg(O, b));
      const ta = c.mut.includes(b.id) ? null : owTypedIn(O.R, b.t);
      if (owPromiseIn(O.R, b.t)) owErr(W, f, "mut-capture", `${b.name} holds a promise, captured by a function the cell keeps: it settles after the function is published, so it cannot be frozen with it; make the promise inside the function, or publish the promise itself`);
      if (ta !== null && !owTypedSafeB(O, b)) owErr(W, f, "mut-capture", `${b.name} holds a ${ta} that a name in this cell can still write, captured by a function the cell keeps: a typed array or URL cannot be frozen, nor can a copy of one; copy the data out of the ${ta} before the function and capture that (for the ${ta} x, ${owUnfreezableFix(ta, "x")})`);
    }
  }
};

export const owNamePlace = (nodeKind) => (O: OwCtx, n: AstNode): boolean => {
  const p = O.T.parent.get(n.nid);
  if (p === undefined) return true;
  if (p.type === "CallExpression") return p.callee.nid === n.nid;
  if (p.type === "MemberExpression") return p.property.nid === n.nid && !p.computed;
  if (p.type === "Property") return p.key.nid === n.nid && !p.computed && !p.shorthand;
  return nodeKind(p).startsWith("TS");
};

export const owOnRead = (owNamePlace, owBindingAt, owErr) => (O: OwCtx, W: OwW, n: AstNode): void => {
  if (n.type !== "Identifier" || (n.name !== "on" && n.name !== "read")) return;
  const b = owBindingAt(O, n);
  if ((b !== undefined && b.kind !== "prelude") || owNamePlace(O, n)) return;
  if (n.name === "on") owErr(W, n, "listener-placement", "on is only called, as the whole value of a cell; it is not a value");
  else owErr(W, n, "read-outside-action", "read is only called, in an action body; it is not a value");
};

// a literal, a spread copy, new on an intrinsic, or an intrinsic marked @fresh
export const owFresh = () => {
  function fresh(O: OwCtx, a: AstNode): boolean {
    switch (a.type) {
      case "ArrayExpression": case "ObjectExpression": return true;
      case "ConditionalExpression": return fresh(O, a.consequent) && fresh(O, a.alternate);
      case "NewExpression": case "CallExpression": {
        const s = O.F.calls.get(a.nid)?.sig ?? null;
        return s !== null && !!s.flags?.intrinsic && !!s.flags.fresh && !s.flags.view;
      }
      default: return false;
    }
  }
  return fresh;
};

// on(...): the cell's whole value, through parentheses and the branches of a conditional
export const owOnWhole = (owEncl) => (O: OwCtx, body: AstNode, n: AstNode): boolean => {
  let cur = n, p = O.T.parent.get(n.nid);
  while (p !== undefined && (p.type === "ParenthesizedExpression" || (p.type === "ConditionalExpression" && p.test.nid !== cur.nid))) { cur = p; p = O.T.parent.get(p.nid); }
  return body.nid === cur.nid || (p !== undefined && p.type === "ReturnStatement" && owEncl(O, p).nid === O.T.fn.nid);
};

export const owCellPlace = (owEncl, owOnWhole, owErr, ixFnParts) => (O: OwCtx, W: OwW, n: AstNode, pre: string): void => {
  const f = ixFnParts(O.T.fn), p = O.T.parent.get(n.nid);
  if (f === null) return;
  if (pre === "borrow") {
    if (!(p !== undefined && p.type === "YieldExpression" && owEncl(O, n).nid === O.T.fn.nid && f.generator)) owErr(W, n, "borrow-placement", "borrow(x) only as the operand of yield in a generator cell");
  } else if (pre === "state") {
    const okRet = p !== undefined && p.type === "ReturnStatement" && O.T.parent.get(p.nid)?.nid === f.body.nid;
    if (!(f.body.nid === n.nid || okRet) || f.async || f.generator) owErr(W, n, "state-placement", "state(...) only as the returned value of a sync, non-generator cell");
  } else if (pre === "on") {
    if (!owOnWhole(O, f.body, n) || f.async || f.generator) owErr(W, n, "listener-placement", "on(...) only as the whole value of a sync, non-generator cell (what it returns, or a branch of a conditional that it returns)");
  }
};

// a prelude function only as the callee of a call (on and read have rules of their own); no binding named like one of
// the ownership functions, mut, freeze, borrow, snapshot (pre)
// an identifier with no binding fact is taken for the prelude's when it has a prelude name, as owOnRead does (a
// shorthand property's key is not: its value carries the binding)
export const owPreludeName = (owNamePlace, owBindingAt, owErr) => (O: OwCtx, W: OwW, pre: Set<string>, all: Set<string>, n: AstNode): void => {
  if (n.type !== "Identifier") return;
  const p = O.T.parent.get(n.nid), key = p !== undefined && p.type === "Property" && p.key.nid === n.nid && p.value.nid !== n.nid;
  const b = owBindingAt(O, n), isPre = b === undefined ? all.has(n.name) && !key : b.kind === "prelude";
  if (isPre && n.name !== "on" && n.name !== "read" && !owNamePlace(O, n)) owErr(W, n, "prelude-value", `${n.name} is only called, as ${n.name}(...); as a value its calls would skip the rules of ${n.name}`);
  if (b !== undefined && b.kind !== "prelude" && b.kind !== "global" && b.nid === n.nid && pre.has(n.name)) owErr(W, n, "prelude-shadow", `${n.name} names a prelude function; a binding of that name would hide it from the rules of ${n.name}(...)`);
};

// a regexp that may have the g or y flag keeps lastIndex, which test, exec, match and replace read or write: it is
// used only where it is made, as a member's object or an argument an intrinsic does not keep (a String method's)
export const owRegexpPlace = (owNonRetainingArg, owArgIndex, owErr) => (O: OwCtx, W: OwW, n: AstNode): void => {
  const gy = (f: string) => f.includes("g") || f.includes("y");
  const flags = n.type === "NewExpression" && n.callee.type === "Identifier" && n.callee.name === "RegExp" ? n.arguments[1] : undefined;
  const lit = n.type === "Literal" && n.regex !== null && gy(n.regex.flags);
  const made = n.type === "NewExpression" && flags !== undefined && !(flags.type === "Literal" && typeof flags.value === "string" && !gy(flags.value));
  if (!lit && !made) return;
  const p = O.T.parent.get(n.nid);
  if (p !== undefined && p.type === "MemberExpression" && p.object.nid === n.nid) return;
  if (p !== undefined && p.type === "CallExpression" && p.callee.nid !== n.nid && owNonRetainingArg(O, p, owArgIndex(p.arguments, n))) return;
  owErr(W, n, "regexp-state", "a regexp that may have the g or y flag keeps lastIndex, which test, exec, match and replace write: use it only where it is made, as the receiver of a call or a String method's argument");
};

// the names a key may be: its string literals, [] for a number, null for any string
export const owKeyNames = (ixUm) => (O: OwCtx, k: AstNode, computed: boolean): string[] | null => {
  if (!computed && k.type === "Identifier") return [k.name];
  if (k.type === "Literal") return typeof k.value === "string" ? [k.value] : [];
  const t = O.F.types.get(k.nid);
  if (t === undefined) return null;
  const ms: Ty[] = ixUm(O.R, t);
  if (!ms.every((m) => m.k === "num" || m.k === "lit")) return null;
  return ms.flatMap((m) => (m.k === "lit" && typeof m.v === "string" ? [m.v] : []));
};

// a record with an index signature types every key it is read at by the signature; a key that names a member of
// Object.prototype reads that member instead (a function, or the prototype). d1 (2026-11-24): a key that may be any
// string (not a literal, a union of literals or a number) is refused, since it may name one
export const owProtoRead = (owKeyNames, PROTO_NAMES, ixUm, unwrap, owErr) => (O: OwCtx, W: OwW, n: AstNode): void => {
  const at = n.type === "MemberExpression" ? { o: n.object, k: n.property, c: n.computed } : n.type === "BinaryExpression" && n.operator === "in" ? { o: n.right, k: n.left, c: true } : null;
  if (at === null) return;
  const t = O.F.types.get(at.o.nid);
  if (t === undefined || !ixUm(O.R, t).some((m) => { const x = O.R.expand(unwrap(m)); return x.k === "rec" && x.index !== undefined; })) return;
  const names = owKeyNames(O, at.k, at.c), P: Set<string> = PROTO_NAMES;
  if (names === null) return owErr(W, n, "banned-member", "a key known only at run time, on a record with an index signature, can name an inherited member such as toString or __proto__, which is not an entry; keep the entries in a Map<string, T> (m.get(k), m.set(k, v), m.has(k), m.delete(k)), or use a literal key");
  const k = names.find((x) => P.has(x));
  if (k !== undefined) owErr(W, n, "banned-member", `${k} on a record with an index signature is Object.prototype's ${k}, not an entry`);
};

// includes, indexOf and lastIndexOf compare by identity, as === does: an element and an argument that may both be
// objects. (Object.is and a Map or Set keyed by objects are identity too; not checked, holes step 7)
export const owIdentityOp = (owMayObject, owErr) => (O: OwCtx, W: OwW, n: AstNode): void => {
  const sig = O.F.calls.get(n.nid)?.sig;
  if (n.type !== "CallExpression" || n.callee.type !== "MemberExpression" || n.callee.computed || n.callee.property.type !== "Identifier" || sig === null || sig === undefined || !sig.flags?.intrinsic) return;
  const m = n.callee.property.name, a0 = n.arguments[0];
  if (a0 === undefined || !["includes", "indexOf", "lastIndexOf"].includes(m)) return;
  if (owMayObject(O, sig.ps[0]?.t) && owMayObject(O, O.F.types.get(a0.nid))) owErr(W, n, "strict-eq-object", `${m} on an element and an argument that may both be objects compares by identity, as === does; use equals(a, b) with some or findIndex`);
};

// S4: a generator cell keeps running after a value is out, and a typed array cannot be frozen: a Mut typed array it
// yields must be a fresh copy at the yield (buf.slice()). An async cell's body has ended when its value is out.
export const owTypedOut = (owEncl, owTypedSafe, owTypedIn, owErr, ixFnParts) => (O: OwCtx, W: OwW, n: AstNode): void => {
  const f = ixFnParts(O.T.fn);
  if (f === null || !f.generator || n.type !== "YieldExpression") return;
  const a = n.argument;
  if (a === null || owEncl(O, n).nid !== O.T.fn.nid) return;
  const t = O.F.types.get(a.nid), w = t === undefined ? null : owTypedIn(O.R, t);
  const u = { n: w ?? "" };
  if (w !== null && !owTypedSafe(O, a)) owErr(W, a, "mut-yield", `a ${u.n} the cell may still write, yielded: a typed array or URL cannot be frozen; yield a copy (${u.n === "ArrayBuffer" || u.n === "DataView" ? "snapshot(x)" : "x.slice()"})`);
};

export const owPlacement = (owOnRead, owPreludeName, owRegexpPlace, owProtoRead, owIdentityOp, owCellPlace, owTypedOut, owPrelude) => (O: OwCtx, W: OwW): void => {
  // open part 6: every prelude name of S2.6
  const preNames = new Set(["state", "action", "mut", "freeze", "borrow", "snapshot", "equals", "on", "read", "messageOf", "memo", "cast"]);
  const allPre = new Set([...O.F.bindings.values()].filter((b) => b.kind === "prelude").map((b) => b.name));
  for (const n of O.T.all) {
    owOnRead(O, W, n);
    owPreludeName(O, W, preNames, allPre, n);
    owRegexpPlace(O, W, n);
    owProtoRead(O, W, n);
    owIdentityOp(O, W, n);
    owTypedOut(O, W, n);
    if (n.type !== "CallExpression") continue;
    const pre = owPrelude(O, n);
    if (pre !== null) owCellPlace(O, W, n, pre);
  }
};

export const owJoin = (owUnion) => (ss: (OwSt | null)[]): OwSt | null => {
  let out: OwSt | null = null;
  for (const s of ss) if (s !== null) out = out === null ? s : owUnion(out, s);
  return out;
};

// inside a try block every state met is one the handler may start from
export const owSeen = (owUnion) => (X: OwX, st: OwSt): void => {
  const acc = X.acc;
  if (acc !== null) X.acc = owUnion(acc, st);
};

export const owStmt = (owSeen, owBlockFlow, owVarFlow, owIfFlow, owJump, owLoop, owTryFlow, owSwitchFlow, owUnsup, isFnNode, kidsOf) => (K: OwK, O: OwCtx, W: OwW, X: OwX, P: OwFlowFn, s: AstNode, st0: OwSt): OwSt | null => {
  owSeen(X, st0);
  switch (s.type) {
    case "BlockStatement": return owBlockFlow(K, O, W, X, P, s.body, st0);
    case "VariableDeclaration": return owVarFlow(K, O, W, X, P, s, st0);
    case "FunctionDeclaration": case "EmptyStatement": return st0;
    case "ExpressionStatement": return K.expr(K, O, W, X, P, s.expression, st0);
    case "ReturnStatement": if (s.argument !== null) K.expr(K, O, W, X, P, s.argument, st0); return null;
    case "ThrowStatement": K.expr(K, O, W, X, P, s.argument, st0); return null;
    case "IfStatement": return owIfFlow(K, O, W, X, P, s, st0);
    case "BreakStatement": case "ContinueStatement": return owJump(W, X, s, st0);
    case "WhileStatement": case "DoWhileStatement": case "ForStatement": case "ForOfStatement": return owLoop(K, O, W, X, P, s, st0);
    case "TryStatement": return owTryFlow(K, O, W, X, P, s, st0);
    case "SwitchStatement": return owSwitchFlow(K, O, W, X, P, s, st0);
    case "LabeledStatement": owUnsup(W, s, "LabeledStatement in a function holding a Mut/Borrowed"); return st0;
    default: {
      let st = st0;
      for (const c of kidsOf(s)) st = isFnNode(c) ? st : K.expr(K, O, W, X, P, c, st);
      return st;
    }
  }
};

export const owBlockFlow = () => (K: OwK, O: OwCtx, W: OwW, X: OwX, P: OwFlowFn, body: AstNode[], st: OwSt): OwSt | null => {
  let cur: OwSt | null = st;
  for (const x of body) { if (cur === null) return null; cur = K.stmt(K, O, W, X, P, x, cur); }
  return cur;
};

// a declaration starts its binding afresh
export const owVarFlow = (owBindingAt, kidsOf) => (K: OwK, O: OwCtx, W: OwW, X: OwX, P: OwFlowFn, s: VariableDeclaration, st0: OwSt): OwSt => {
  let st = st0;
  for (const d of s.declarations) {
    if (d.type !== "VariableDeclarator") continue;
    if (d.init !== null) st = K.expr(K, O, W, X, P, d.init, st);
    for (const c of kidsOf(d.id)) st = K.expr(K, O, W, X, P, c, st);
    const b = d.id.type === "Identifier" ? owBindingAt(O, d.id) : undefined;
    if (b !== undefined && P.tracked.has(b.id)) st = new Set([...st].filter((id) => id !== b.id));
  }
  return st;
};

export const owIfFlow = (owJoin) => (K: OwK, O: OwCtx, W: OwW, X: OwX, P: OwFlowFn, s: IfStatement, st: OwSt): OwSt | null => {
  const t = K.expr(K, O, W, X, P, s.test, st), alt = s.alternate;
  return owJoin([K.stmt(K, O, W, X, P, s.consequent, t), alt !== null ? K.stmt(K, O, W, X, P, alt, t) : t]);
};

// a continue goes to the innermost loop, past any switch
export const owPushCont = () => {
  function push(l: OwLoops | null, st: OwSt): OwLoops | null {
    if (l === null) return null;
    return l.isSwitch ? { ...l, next: push(l.next, st) } : { ...l, conts: [...l.conts, st] };
  }
  return push;
};

export const owJump = (owUnsup, owPushCont) => (W: OwW, X: OwX, s: BreakStatement | ContinueStatement, st: OwSt): null => {
  if (s.label !== null) { owUnsup(W, s, "labelled break/continue in a function holding a Mut/Borrowed"); return null; }
  const top = X.loops;
  if (s.type === "ContinueStatement") X.loops = owPushCont(top, st);
  else if (top !== null) X.loops = { ...top, breaks: [...top.breaks, st] };
  return null;
};

export const owTryFlow = (owUnsup, owSeen, owJoin) => (K: OwK, O: OwCtx, W: OwW, X: OwX, P: OwFlowFn, s: TryStatement, st: OwSt): OwSt | null => {
  if (s.finalizer !== null) { owUnsup(W, s, "try/finally in a function holding a Mut/Borrowed"); return st; }
  const outer = X.acc;
  X.acc = st;
  const a = K.stmt(K, O, W, X, P, s.block, st);
  const seen = X.acc ?? st;
  X.acc = outer;
  owSeen(X, seen);
  const h = s.handler;
  const c = h !== null && h.type === "CatchClause" ? K.stmt(K, O, W, X, P, h.body, seen) : null;
  return owJoin([a, c]);
};

// every test may run before a body is entered; a body is entered by its case or from the body before it
export const owSwitchFlow = (owJoin) => (K: OwK, O: OwCtx, W: OwW, X: OwX, P: OwFlowFn, s: SwitchStatement, st: OwSt): OwSt | null => {
  let tests = K.expr(K, O, W, X, P, s.discriminant, st);
  for (const c of s.cases) if (c.type === "SwitchCase" && c.test !== null) tests = K.expr(K, O, W, X, P, c.test, tests);
  X.loops = { breaks: [], conts: [], isSwitch: true, next: X.loops };
  let prev: OwSt | null = null;
  for (const c of s.cases) {
    let cur: OwSt | null = owJoin([tests, prev]);
    if (c.type === "SwitchCase") for (const x of c.consequent) { if (cur === null) break; cur = K.stmt(K, O, W, X, P, x, cur); }
    prev = cur;
  }
  const ctx = X.loops;
  X.loops = ctx === null ? null : ctx.next;
  const dflt = s.cases.some((c) => c.type === "SwitchCase" && c.test === null);
  return owJoin([prev, ...(ctx === null ? [] : ctx.breaks), dflt ? null : tests]);
};

export const owLoopParts = () => (s: AstNode): OwLoopParts | null => {
  switch (s.type) {
    case "WhileStatement": case "DoWhileStatement": return { test: s.test, body: s.body };
    case "ForStatement": return { test: s.test, body: s.body };
    case "ForOfStatement": return { test: null, body: s.body };
    default: return null;
  }
};

export const owLoopEntry = () => (K: OwK, O: OwCtx, W: OwW, X: OwX, P: OwFlowFn, s: AstNode, st: OwSt): OwSt => {
  if (s.type === "ForStatement" && s.init !== null) return s.init.type === "VariableDeclaration" ? K.stmt(K, O, W, X, P, s.init, st) ?? st : K.expr(K, O, W, X, P, s.init, st);
  if (s.type === "ForOfStatement") return K.expr(K, O, W, X, P, s.right, st);
  return st;
};

// the body of a for...of starts its declared binding afresh
export const owForOfIn = (owBindingAt) => (O: OwCtx, P: OwFlowFn, s: AstNode, cur: OwSt): OwSt => {
  const left = s.type === "ForOfStatement" ? s.left : null;
  const d = left !== null && left.type === "VariableDeclaration" ? left.declarations[0] : undefined;
  const b = d !== undefined && d.type === "VariableDeclarator" && d.id.type === "Identifier" ? owBindingAt(O, d.id) : undefined;
  return b !== undefined && P.tracked.has(b.id) ? new Set([...cur].filter((id) => id !== b.id)) : cur;
};

export const owLoopOnce = (owForOfIn, owJoin) => (K: OwK, O: OwCtx, W: OwW, X: OwX, P: OwFlowFn, s: AstNode, L: OwLoopParts, entry: OwSt, cur: OwSt): OwLoopStep => {
  X.loops = { breaks: [], conts: [], isSwitch: false, next: X.loops };
  let afterTest = cur, bodyIn = cur;
  if (s.type !== "DoWhileStatement" && L.test !== null) { afterTest = K.expr(K, O, W, X, P, L.test, cur); bodyIn = afterTest; }
  if (s.type === "ForOfStatement") bodyIn = owForOfIn(O, P, s, cur);
  const end = K.stmt(K, O, W, X, P, L.body, bodyIn);
  const ctx = X.loops;
  X.loops = ctx === null ? null : ctx.next;
  let back = owJoin([end, ...(ctx === null ? [] : ctx.conts)]);
  if (back !== null && s.type === "ForStatement" && s.update !== null) back = K.expr(K, O, W, X, P, s.update, back);
  if (back !== null && s.type === "DoWhileStatement") { afterTest = K.expr(K, O, W, X, P, s.test, back); back = afterTest; }
  const t = L.test, infinite = s.type !== "ForOfStatement" && (t === null || (t.type === "Literal" && t.value === true));
  const exit = owJoin([infinite ? null : s.type === "ForOfStatement" ? cur : afterTest, ...(ctx === null ? [] : ctx.breaks)]);
  return { exit, next: owJoin([entry, back]) ?? entry };
};

export const owLoop = (owLoopParts, owLoopEntry, owLoopOnce) => (K: OwK, O: OwCtx, W: OwW, X: OwX, P: OwFlowFn, s: AstNode, st: OwSt): OwSt | null => {
  const L = owLoopParts(s);
  if (L === null) return st;
  const entry = owLoopEntry(K, O, W, X, P, s, st);
  let cur = entry, exit: OwSt | null = null;
  for (let iter = 0; iter < 20; iter++) {
    const r = owLoopOnce(K, O, W, X, P, s, L, entry, cur);
    exit = r.exit;
    if (r.next.size === cur.size) break;
    cur = r.next;
  }
  return exit;
};

export const owEnclFn = (isFnNode) => (O: OwCtx, n: AstNode): AstNode | null => {
  let p = O.T.parent.get(n.nid);
  while (p !== undefined && !isFnNode(p)) p = O.T.parent.get(p.nid);
  return p ?? null;
};

export const owIsState = (ixUm, isNamed, unwrap) => (O: OwCtx, n: AstNode): boolean => {
  const t = O.F.types.get(n.nid);
  return t !== undefined && ixUm(O.R, t).some((m) => isNamed(unwrap(m), "State"));
};

// a built-in calls at once a function given to a parameter of function type that it does not keep; State.update too
export const owCallsAtOnce = (owArgIndex, owIsState) => (O: OwCtx, p: CallExpression | NewExpression, x: AstNode): boolean => {
  const sig = O.F.calls.get(p.nid)?.sig ?? null, fl = sig?.flags;
  const d = sig === null ? null : sig.decl ?? sig, i = owArgIndex(p.arguments, x);
  const dp = d === null ? undefined : i < d.ps.length ? d.ps[i]?.t : d.rest;
  if (fl?.intrinsic && !fl.retains && dp !== undefined && O.R.callSigs(dp).length) return true;
  const c = p.callee;
  return p.type === "CallExpression" && c.type === "MemberExpression" && !c.computed && (c.property.type === "Identifier" || c.property.type === "PrivateIdentifier") && c.property.name === "update" && owIsState(O, c.object);
};

// every function from f out to `to` (exclusive) runs in the call
export const owChain = (owEnclFn) => (K: OwWhyK, O: OwCtx, M: Mut<Map<number, string | null>>, f: AstNode | null, to: AstNode): string | null => {
  for (let g = f; g !== null && g.nid !== to.nid; g = owEnclFn(O, g)) {
    if (O.F.actionBodies.has(g.nid)) return "it is called from another action's body";
    const w = K.why(K, O, M, g);
    if (w) return w;
  }
  return null;
};

// each reference of b is a direct call from a function that runs while the one holding b's declaration does
export const owOnlyCalled = (owEnclFn, owChain, owIsCallee) => (K: OwWhyK, O: OwCtx, M: Mut<Map<number, string | null>>, b: IxBinding, decl: AstNode): string | null => {
  const home = owEnclFn(O, decl) ?? O.T.fn;
  for (const r of O.T.refs.get(b.id) ?? []) {
    if (!owIsCallee(O, r)) return `${b.name} is used other than by a direct call`;
    const w = owChain(K, O, M, owEnclFn(O, r), home);
    if (w) return `${b.name} is called from a function that may run after the call (${w})`;
  }
  return null;
};

// a helper that calls itself is decided by its other uses
export const owWhy = (owWhy1) => (K: OwWhyK, O: OwCtx, M: Mut<Map<number, string | null>>, f: AstNode): string | null => {
  const hit = M.get(f.nid);
  if (hit !== undefined) return hit;
  M.set(f.nid, null);
  const r = owWhy1(K, O, M, f);
  M.set(f.nid, r);
  return r;
};

// the const or function declaration naming f, as own.ts finds it
export const owDeclaredBy = (owBindingAt) => (O: OwCtx, p: AstNode, f: AstNode): IxBinding | undefined => {
  const decl = O.T.parent.get(p.nid);
  const id = p.type === "VariableDeclarator" && p.init !== null && p.init.nid === f.nid && p.id.type === "Identifier" && decl !== undefined && decl.type === "VariableDeclaration" && decl.kind === "const" ? p.id
    : f.type === "FunctionDeclaration" ? f.id : null;
  return id === null ? undefined : owBindingAt(O, id);
};

export const owWhy1 = (owCallsAtOnce, owOnlyCalled, owDeclaredBy, owArgIndex, ixFnParts) => (K: OwWhyK, O: OwCtx, M: Mut<Map<number, string | null>>, f: AstNode): string | null => {
  const parts = ixFnParts(f);
  if (parts !== null && (parts.async || parts.generator)) return `it is ${parts.async ? "async" : "a generator"}, so it may resume after the call has finished`;
  const p = O.T.parent.get(f.nid);
  if (p === undefined) return "it is not called where it is made";
  if (p.type === "CallExpression" && p.callee.nid === f.nid) return null;
  if ((p.type === "CallExpression" || p.type === "NewExpression") && owArgIndex(p.arguments, f) >= 0) return owCallsAtOnce(O, p, f) ? null : "it is passed to a function that may keep it";
  const b = owDeclaredBy(O, p, f);
  if (b !== undefined && b.fnNode === f.nid) return owOnlyCalled(K, O, M, b, f);
  return "it is kept: returned, stored, or placed where it may be called later";
};

// a set or update read as a value (a member read or a destructured property): where it may be called
export const owMethodValue = (owCallsAtOnce, owOnlyCalled, owBindingAt, owArgIndex) => (K: OwWhyK, O: OwCtx, M: Mut<Map<number, string | null>>, x: AstNode): string | null => {
  const p = O.T.parent.get(x.nid), d = p === undefined ? undefined : O.T.parent.get(p.nid);
  if (p === undefined) return "it is kept: bound where the checker does not follow it";
  const constDecl = (n: AstNode | undefined) => n !== undefined && n.type === "VariableDeclaration" && n.kind === "const";
  if (x.type === "MemberExpression") {
    if (p.type === "CallExpression" && p.callee.nid === x.nid) return null;
    if ((p.type === "CallExpression" || p.type === "NewExpression") && owArgIndex(p.arguments, x) >= 0) return owCallsAtOnce(O, p, x) ? null : "it is passed to a function that may keep it";
    if (p.type === "VariableDeclarator" && p.init !== null && p.init.nid === x.nid && p.id.type === "Identifier" && constDecl(d)) {
      const b = owBindingAt(O, p.id);
      return b ? owOnlyCalled(K, O, M, b, p) : "it is bound to a name the checker does not follow";
    }
    return "it is kept: returned, stored, or placed where it may be called later";
  }
  const v = x.type === "Property" ? x.value : null;
  if (v !== null && v.type === "Identifier" && d !== undefined && d.type === "VariableDeclarator" && d.id.nid === p.nid && constDecl(O.T.parent.get(d.nid))) {
    const b = owBindingAt(O, v);
    return b ? owOnlyCalled(K, O, M, b, d) : "it is bound to a name the checker does not follow";
  }
  return "it is kept: bound where the checker does not follow it";
};

// the action body around n, or null outside any
export const owActionRoot = (owEnclFn) => (O: OwCtx, n: AstNode | null): AstNode | null => {
  let root = n;
  while (root !== null && !O.F.actionBodies.has(root.nid)) root = owEnclFn(O, root);
  return root;
};

// a node the facts name that is not in the tree reaches the comparison as a report of its own, never as silence
export const owActionUses = (owActionRoot, owChain, OW_WHY_K) => (O: OwCtx, M: Mut<Map<number, string | null>>): IxDiag[] => {
  const out: Mut<IxDiag[]> = [];
  for (const u of O.F.inActionUses) {
    const fi = O.T.byNid.get(u.fi), at = O.T.byNid.get(u.at);
    if (fi === undefined || at === undefined) { out.push({ start: 0, end: 0, rule: "ow-internal", msg: `in-action use at nid ${u.at} outside the tree` }); continue; }
    const w = owChain(OW_WHY_K, O, M, fi, owActionRoot(O, fi) ?? O.T.fn);
    if (w) out.push({ start: at.start, end: at.end, rule: u.rule, msg: `${u.msg}: the function it is in was made in an action body and may run after the call, because ${w}` });
  }
  return out;
};

// the name of a member read or a destructured property, as own.ts reads it
export const owMemberName = () => (x: AstNode): string | null => {
  const key = x.type === "MemberExpression" ? x.property : x.type === "Property" ? x.key : null;
  const computed = x.type === "MemberExpression" || x.type === "Property" ? x.computed : true;
  if (key === null) return null;
  if (!computed && key.type === "Identifier") return key.name;
  return key.type === "Literal" ? String(key.value) : null;
};

export const owStateWrites = (owMemberName, owIsState, owEnclFn, owActionRoot, owMethodValue, OW_WHY_K) => (O: OwCtx, M: Mut<Map<number, string | null>>): IxDiag[] => {
  const out: Mut<IxDiag[]> = [];
  for (const x of O.T.all) {
    const isMember = x.type === "MemberExpression";
    if (!isMember && !O.F.stateProps.has(x.nid)) continue;
    const name = owMemberName(x);
    if (x.type === "MemberExpression" && ((name !== "set" && name !== "update") || !owIsState(O, x.object))) continue;
    // outside any action: [state-write] where it is read
    if (owActionRoot(O, owEnclFn(O, x)) === null) continue;
    const w = owMethodValue(OW_WHY_K, O, M, x);
    if (w) out.push({ start: x.start, end: x.end, rule: "state-write", msg: `State.${name ?? "member"} taken as a value in an action body may write after the call, because ${w}` });
  }
  return out;
};

export const owActionEscapes = (owActionUses, owStateWrites) => (O: OwCtx): IxDiag[] => {
  if (!O.F.actionBodies.size) return [];
  const M: Mut<Map<number, string | null>> = new Map();
  const uses = owActionUses(O, M);
  return [...uses, ...owStateWrites(O, M)];
};

// an identifier that does not read a binding: a property or key name, or a label
export const owNotARef = () => (parent: AstNode | null, key: string): boolean => {
  if (parent === null) return false;
  switch (parent.type) {
    case "MemberExpression": return key === "property" && !parent.computed;
    case "Property": case "MethodDefinition": case "PropertyDefinition": return key === "key" && !parent.computed;
    case "LabeledStatement": case "BreakStatement": case "ContinueStatement": return true;
    default: return false;
  }
};

// the identifiers under n that read a binding, outside type positions, in field order
export const owRefsOf = (owNotARef, childrenOf, TYPE_FIELDS) => {
  function walk(n: AstNode, out: Mut<AstNode[]>, parent: AstNode | null, key: string): void {
    if (n.type === "Identifier") { if (!owNotARef(parent, key)) out.push(n); return; }
    if (n.type === "JSXIdentifier") return;
    for (const k of childrenOf(n)) if (!TYPE_FIELDS.has(k.key)) walk(k.node, out, n, k.key);
  }
  return (n: AstNode): AstNode[] => {
    const out: Mut<AstNode[]> = [];
    walk(n, out, null, "");
    return out;
  };
};

// the names a pattern binds
export const owBound = () => {
  function bound(p: AstNode | null, out: Mut<Set<string>>): void {
    if (p === null) return;
    switch (p.type) {
      case "Identifier": out.add(p.name); return;
      case "ObjectPattern": for (const q of p.properties) bound(q.type === "RestElement" ? q.argument : q.type === "Property" ? q.value : null, out); return;
      case "ArrayPattern": for (const q of p.elements) bound(q, out); return;
      case "RestElement": bound(p.argument, out); return;
      case "AssignmentPattern": bound(p.left, out); return;
      case "TSParameterProperty": bound(p.parameter, out); return;
      default: return;
    }
  }
  return bound;
};

export const owBoundNames = (owBound) => (p: AstNode | null): Set<string> => {
  const out: Mut<Set<string>> = new Set();
  owBound(p, out);
  return out;
};

// every name declared anywhere inside fn: its parameters, locals, nested functions' names and parameters
export const owDeclaredIn = (owBound, ixFnParts, isFnNode, kidsOf) => (fn: AstNode): Set<string> => {
  const out: Mut<Set<string>> = new Set();
  const parts = ixFnParts(fn);
  if (parts === null) return out;
  for (const p of parts.params) owBound(p, out);
  const todo: Mut<AstNode[]> = [parts.body];
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    if (n.type === "VariableDeclarator") owBound(n.id, out);
    if ((n.type === "FunctionDeclaration" || n.type === "FunctionExpression") && n.id !== null && n.id.type === "Identifier") out.add(n.id.name);
    const np = isFnNode(n) ? ixFnParts(n) : null;
    if (np !== null) for (const p of np.params) owBound(p, out);
    if (n.type === "CatchClause") owBound(n.param, out);
    if (n.type === "ClassDeclaration" && n.id.type === "Identifier") out.add(n.id.name);
    for (const k of kidsOf(n)) todo.push(k);
  }
  return out;
};

// the cell's locals outside any action body, each with what its value is computed from
export const owLocals = (owIsActionCall, owBoundNames, kidsOf) => (body: AstNode): OwLocal[] => {
  const out: Mut<OwLocal[]> = [];
  const todo: Mut<AstNode[]> = [body];
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    if (owIsActionCall(n)) continue;
    if (n.type === "VariableDeclarator" && n.init !== null) out.push({ names: owBoundNames(n.id), from: n.init });
    if (n.type === "FunctionDeclaration" && n.id.type === "Identifier") out.push({ names: new Set([n.id.name]), from: n.body });
    for (const k of kidsOf(n).toReversed()) todo.push(k);
  }
  return out;
};

// the first reference in from to a tainted name
export const owFirstTainted = (owRefsOf) => (taint: Mut<Map<string, string>>, from: AstNode): string | null => {
  for (const r of owRefsOf(from)) if (r.type === "Identifier" && taint.has(r.name)) return r.name;
  return null;
};

export const owTaintPass = (owFirstTainted) => (taint: Mut<Map<string, string>>, locals: OwLocal[]): boolean => {
  let changed = false;
  for (const l of locals) {
    let all = true;
    for (const x of l.names) if (!taint.has(x)) all = false;
    const hit = all ? null : owFirstTainted(taint, l.from);
    if (hit === null) continue;
    for (const x of l.names) if (!taint.has(x)) { taint.set(x, `computed from ${hit}`); changed = true; }
  }
  return changed;
};

// the uses in one action body of tainted names it does not declare; a parameter's default is read each call
export const owActionTaint = (owDeclaredIn, owRefsOf, ixFnParts) => (taint: Mut<Map<string, string>>, f: AstNode, out: Mut<OwCapture[]>): void => {
  const parts = ixFnParts(f);
  if (parts === null) return;
  const own = owDeclaredIn(f), seen: Mut<Set<string>> = new Set();
  for (const r of owRefsOf(parts.body)) {
    const why = r.type === "Identifier" ? taint.get(r.name) : undefined;
    if (r.type !== "Identifier" || why === undefined || own.has(r.name) || seen.has(r.name)) continue;
    seen.add(r.name);
    out.push({ at: r, name: r.name, why, opaque: false });
  }
  for (const p of parts.params) for (const r of owRefsOf(p)) {
    const why = r.type === "Identifier" ? taint.get(r.name) : undefined;
    if (r.type === "Identifier" && why !== undefined && !own.has(r.name)) out.push({ at: r, name: r.name, why, opaque: false });
  }
};

export const owTaintCaptures = (owLocals, owTaintPass, owActionTaint, owIsActionCall, isFnNode, ixFnParts, kidsOf) => (fn: AstNode, tainted: Map<string, string>): OwCapture[] => {
  const parts = ixFnParts(fn);
  if (parts === null) return [];
  const taint: Mut<Map<string, string>> = new Map(tainted), locals = owLocals(parts.body);
  for (let changed = true; changed; ) changed = owTaintPass(taint, locals);
  const out: Mut<OwCapture[]> = [];
  if (!taint.size) return out;
  const todo: Mut<AstNode[]> = [parts.body];
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    if (n.type === "CallExpression" && owIsActionCall(n)) {
      const f = n.arguments[0];
      if (f !== undefined && isFnNode(f)) owActionTaint(taint, f, out);
      continue;
    }
    for (const k of kidsOf(n).toReversed()) todo.push(k);
  }
  return out;
};

// identifiers in preorder, and JSX component names (a capitalised or member name), which have no binding in the facts
export const owIdsAndComps = (owIsUpper) => (O: OwCtx): { ids: AstNode[]; comps: AstNode[] } => {
  const ids: Mut<AstNode[]> = [], comps: Mut<AstNode[]> = [];
  for (const n of O.T.all) {
    if (n.type === "Identifier") ids.push(n);
    const p = O.T.parent.get(n.nid);
    if (p !== undefined && p.type === "JSXOpeningElement" && p.name.nid === n.nid && (n.type !== "JSXIdentifier" || owIsUpper(n.name))) comps.push(n);
  }
  return { ids: ids, comps: comps };
};

// the local bindings referenced inside span from outside it
export const owFree = (owBindingAt, owIsLocal, owWithin) => (O: OwCtx, Q: OwOpaque, span: AstNode[]): IxBinding[] => Q.ids.flatMap((r) => {
  const b = owBindingAt(O, r), d = b === undefined ? undefined : O.T.byNid.get(b.nid);
  return b !== undefined && owIsLocal(b) && b.nid !== r.nid && span.some((s) => owWithin(r, s)) && !(d !== undefined && span.some((s) => owWithin(d, s))) ? [b] : [];
});

// what a const's value is computed from: its function, its declarator, or a for...of's declaration and iterable
export const owSpanOf = () => (O: OwCtx, b: IxBinding): AstNode[] | null => {
  const fnNode = O.T.byNid.get(b.fnNode);
  if (fnNode !== undefined) return [fnNode];
  const node = O.T.byNid.get(b.nid);
  let d = node === undefined ? undefined : O.T.parent.get(node.nid);
  while (d !== undefined && d.type !== "VariableDeclarator") d = O.T.parent.get(d.nid);
  const decl = d === undefined ? undefined : O.T.parent.get(d.nid), loop = decl === undefined ? undefined : O.T.parent.get(decl.nid);
  if (loop !== undefined && decl !== undefined && loop.type === "ForOfStatement" && loop.left.nid === decl.nid) return [decl, loop.right];
  return d !== undefined && d.type === "VariableDeclarator" && d.init !== null ? [d] : null;
};

// open (2026-11-25, S6.9): a parameter of a callback that a built-in calls before it returns (owCallsAtOnce, the
// S6.19 test) gets values from the receiver and the call's other arguments, so it is computed from them, and from the
// callback itself when the declared type of the parameter is the callback's result's (reduce's accumulator); null for
// a parameter of any other function, and of State.update's function, which is given the state
export const owCallbackSpan = (owEnclFn, owCallsAtOnce, owIsState, owArgIndex, ixFnParts, owWithin, ERR) => (O: OwCtx, b: IxBinding): AstNode[] | null => {
  const node = O.T.byNid.get(b.nid), f = node === undefined ? null : owEnclFn(O, node);
  const p = f === null ? undefined : O.T.parent.get(f.nid);
  if (node === undefined || f === null || p === undefined || p.type !== "CallExpression" || owArgIndex(p.arguments, f) < 0 || !owCallsAtOnce(O, p, f)) return null;
  const c = p.callee, sig = O.F.calls.get(p.nid)?.sig ?? null, d = sig === null ? null : sig.decl ?? sig;
  if (c.type !== "MemberExpression" || owIsState(O, c.object)) return null;
  const cs = d === null ? undefined : O.R.callSigs(d.ps[owArgIndex(p.arguments, f)]?.t ?? d.rest ?? ERR)[0];
  const k = (ixFnParts(f)?.params ?? []).findIndex((q) => owWithin(node, q)), fed = cs?.ps[k]?.t;
  const acc = cs !== undefined && fed !== undefined && fed.k === "tv" && cs.ret.k === "tv" && fed.n === cs.ret.n;
  return [c.object, ...p.arguments.filter((a) => a.nid !== f.nid || acc)];
};

export const owOpaqueWhy = (owIsLocal, owOpaqueWhy1) => (K: OwWhyB, O: OwCtx, Q: OwOpaque, B: OwB, b: IxBinding): string | null => {
  if (!owIsLocal(b)) return null;
  if (b.cellParam) return Q.tainted.get(b.name) ?? null;
  const hit = B.bad.get(b.id);
  if (hit !== undefined) return hit;
  if (B.visiting.has(b.id)) return null;
  B.visiting = new Set([...B.visiting, b.id]);
  const w = owOpaqueWhy1(K, O, Q, B, b);
  B.visiting = new Set([...B.visiting].filter((x) => x !== b.id));
  if (w || !B.visiting.size) B.bad = new Map([...B.bad, [b.id, w]]);
  return w;
};

export const owOpaqueWhy1 = (owSpanOf, owCallbackSpan, owFree, owWithin) => (K: OwWhyB, O: OwCtx, Q: OwOpaque, B: OwB, b: IxBinding): string | null => {
  const cb = b.kind === "param" ? owCallbackSpan(O, b) : null;
  if (b.kind === "param" && cb === null) return "is a parameter of an enclosing function, so a caller may pass it a value that depends on state";
  if (b.kind === "let") return "is a let or a catch binding, so its value is not fixed where it is declared";
  if (b.mutOwned) return "is a Mut, which the cell may change after the action is made";
  const span = cb ?? owSpanOf(O, b);
  if (span === null) return "is bound where the checker does not follow its value";
  if (Q.comps.some((j) => span.some((s) => owWithin(j, s)))) return "is computed from a JSX component, which the checker does not follow";
  for (const c of owFree(O, Q, span)) {
    const w = K.why(K, O, Q, B, c);
    if (w) return `is computed from ${c.name}, which ${w.startsWith("is ") ? w : `depends on state (${w})`}`;
  }
  return null;
};

// skip: the references the by-name rule already reported
export const owOpaqueCaptures = (owCapturesIn) => (O: OwCtx, tainted: Map<string, string>, skip: Set<number>): OwCapture[] =>
  O.F.actionBodies.size ? owCapturesIn(O, tainted, skip, [...O.F.actionBodies].flatMap((id) => O.T.byNid.get(id) ?? [])) : [];

// the same rule over any functions: action bodies, or the functions given to memo (S2.13)
export const owCapturesIn = (owIdsAndComps, owBindingAt, owIsLocal, owWithin, OW_WHY_B) => (O: OwCtx, tainted: Map<string, string>, skip: Set<number>, bodies: AstNode[]): OwCapture[] => {
  const Q: OwOpaque = { ...owIdsAndComps(O), tainted }, B: OwB = { bad: new Map(), visiting: new Set() };
  const out: Mut<OwCapture[]> = [], seen: Mut<Set<string>> = new Set();
  for (const r of Q.ids) {
    const b = owBindingAt(O, r), d = b === undefined ? undefined : O.T.byNid.get(b.nid);
    if (skip.has(r.nid) || b === undefined || !owIsLocal(b) || b.nid === r.nid || r.type !== "Identifier") continue;
    const a = bodies.find((a) => owWithin(r, a) && !(d !== undefined && owWithin(d, a)));
    const w = a === undefined ? null : OW_WHY_B.why(OW_WHY_B, O, Q, B, b);
    if (a === undefined || !w || seen.has(`${a.start}:${b.id}`)) continue;
    seen.add(`${a.start}:${b.id}`);
    out.push({ at: r, name: b.name, why: w, opaque: !b.cellParam });
  }
  for (const j of Q.comps) if (bodies.some((a) => owWithin(j, a))) out.push({ at: j, name: `<${j.type === "JSXIdentifier" ? j.name : "component"}>`, why: "is a JSX component, which the checker does not follow", opaque: true, fix: "an action body may not use one; make the element in a cell that reads the state, and let the action change only the state" });
  return out;
};

// g's values may be seen before g ends: g is a generator, or g is nested in the cell (r2: every nested function, awaited
// or not; whether its promise is awaited is not followed). Only a plain async cell's own body is not visible
export const owVisibleFn = (ixFnParts) => (O: OwCtx, byFn: Map<number, number>, g: AstNode): boolean => {
  const fp = ixFnParts(g);
  return (fp !== null && fp.generator) || g.nid !== O.T.fn.nid;
};

// the points of g after which its values may have been seen: its yields, and its awaits when g is visible
export const owLatePoints = (owEncl, owVisibleFn, ixFnParts) => (O: OwCtx, byFn: Map<number, number>, g: AstNode): AstNode[] => {
  const fp = ixFnParts(g);
  if (fp === null || (!fp.async && !fp.generator)) return [];
  const aw = fp.async && owVisibleFn(O, byFn, g);
  return O.T.all.filter((n) => owEncl(O, n).nid === g.nid && (n.type === "YieldExpression" || (aw && (n.type === "AwaitExpression" || (n.type === "ForOfStatement" && n.await)))));
};

// b's uses: its references, then each call of a function whose captures read b (write: that function writes b)
export const owUsesOf = (owAssignedRef, owWriteRef, owIsCallee) => (O: OwCtx, caps: Map<number, OwCap>, byFn: Map<number, number>, b: IxBinding): OwUse[] => {
  const direct = (O.T.refs.get(b.id) ?? []).map((r): OwUse => ({ at: r, write: owAssignedRef(O, r) || owWriteRef(O, r) }));
  const calls = [...caps].flatMap(([fnid, c]): OwUse[] => {
    const hid = c.read.includes(b.id) ? byFn.get(fnid) : undefined, hb = hid === undefined ? undefined : O.F.bindings.get(hid);
    if (hb === undefined) return [];
    return (O.T.refs.get(hb.id) ?? []).flatMap((r): OwUse[] => {
      const p = O.T.parent.get(r.nid);
      return p !== undefined && owIsCallee(O, r) ? [{ at: p, write: c.wmut.includes(b.id) || c.let.includes(b.id) }] : [];
    });
  });
  return [...direct, ...calls];
};

// the call, assignment, update or delete a write through r is made by: up through members, patterns and properties
export const owWriteAt = () => (O: OwCtx, r: AstNode): AstNode | null => {
  let cur = r;
  for (let p = O.T.parent.get(cur.nid); p !== undefined; p = O.T.parent.get(cur.nid)) {
    if (p.type === "CallExpression" || p.type === "AssignmentExpression" || p.type === "UpdateExpression" || (p.type === "UnaryExpression" && p.operator === "delete")) return p;
    const up = (p.type === "MemberExpression" && p.object.nid === cur.nid) || p.type === "ArrayPattern" || p.type === "ObjectPattern" || p.type === "Property" || p.type === "AssignmentPattern";
    if (!up) return null;
    cur = p;
  }
  return null;
};

// a loop's body
export const owLoopBody = () => (l: AstNode): AstNode | null => {
  switch (l.type) {
    case "ForStatement": case "ForOfStatement": case "ForInStatement": case "WhileStatement": case "DoWhileStatement": return l.body;
    default: return null;
  }
};

// the loops around n inside g, innermost first (not through a function)
export const owLoopsOut = (isFnNode, owLoopBody) => (O: OwCtx, n: AstNode, g: AstNode): AstNode[] => {
  const out: Mut<AstNode[]> = [];
  for (let p = O.T.parent.get(n.nid); p !== undefined && p.nid !== g.nid && !isFnNode(p); p = O.T.parent.get(p.nid)) if (owLoopBody(p) !== null) out.push(p);
  return out;
};

// a use u of a binding declared at d is after the point p of g: later in the text (a for await's iterable is before it),
// a write whose expression holds p, or in a loop around p whose body does not declare it (captured: d is outside g)
export const owAfter = (owWriteAt, owLoopsOut, owLoopBody) => (O: OwCtx, g: AstNode, d: AstNode, captured: boolean, u: OwUse, p: AstNode): boolean => {
  if (!captured && d.start >= p.start) return false;
  const r = u.at, inside = (a: AstNode, b: AstNode) => a.start >= b.start && a.end <= b.end;
  const right = p.type === "ForOfStatement" ? p.right : null, inRight = right !== null && inside(r, right);
  if (r.start >= (right === null ? p.end : right.end) && !inRight) return true;
  const we = u.write ? owWriteAt(O, r) : null;
  if (we !== null && inside(p, we)) return true;
  const l = [...(right === null ? [] : [p]), ...owLoopsOut(O, p, g)].find((x) => inside(r, x) && !(x.nid === p.nid && inRight));
  const body = l === undefined ? null : owLoopBody(l);
  return l !== undefined && (captured || body === null || !inside(d, body));
};

// what to do instead, by what the binding holds
export const owLateMsg = (show, isNamed, owMutDeep, owStripMut) => (O: OwCtx, b: IxBinding, p: AstNode): string => {
  const w0 = owMutDeep(O.R, b.t), top = isNamed(b.t, "Mut");
  const what = top ? `Mut ${b.name}` : w0 !== null ? `${b.name}, whose type holds ${w0},` : `let ${b.name} of type ${show(b.t)}`;
  const at = p.type === "YieldExpression" ? "a yield" : "an await in a function whose values may be seen before it ends";
  const w = p.type === "YieldExpression" ? "yield" : "await";
  return `${what} is declared before ${at} and used after it, and the code after it runs once a value has been given; declare it in the loop body that holds the ${w}, or build the value in a helper call (const v = make(k)); to only read it there, bind it under its plain type before the ${w} (const c: ${show(owStripMut(O.R, b.t))} = ...) and read c${w0 !== null ? "" : "; a let of a primitive type may be used across it"}`;
};

// R-Y and R-A over every function of the cell with a point, each binding owLateCand takes, declared in g before a
// point or read by g from an encloser (then only uses inside g count); one report per binding and g, at its first use after
export const owLateUses = (owLatePoints, owLateCand, owUsesOf, owAfter, owLateMsg, owEncl, owErr) => (O: OwCtx, W: OwW, caps: Map<number, OwCap>, byFn: Map<number, number>): void => {
  for (const g of O.T.fns) {
    const ps: AstNode[] = owLatePoints(O, byFn, g);
    if (!ps.length) continue;
    for (const id of O.T.refs.keys()) {
      const b = O.F.bindings.get(id), d = b === undefined ? undefined : O.T.byNid.get(b.nid);
      if (b === undefined || d === undefined || !owLateCand(O, b)) continue;
      const captured = owEncl(O, d).nid !== g.nid;
      if (captured && !(caps.get(g.nid)?.read ?? []).includes(b.id)) continue;
      for (const u of owUsesOf(O, caps, byFn, b)) {
        if (u.at.nid === b.nid || (captured && !(u.at.start >= g.start && u.at.end <= g.end))) continue;
        const p = ps.find((x) => owAfter(O, g, d, captured, u, x));
        if (p === undefined) continue;
        owErr(W, u.at, p.type === "YieldExpression" ? "mut-yield" : "mut-await", owLateMsg(O, b, p));
        break;
      }
    }
  }
};

// R-M (2026-11-23, m1 step 2): the const bindings of the cell bound to memo(...), the memoised functions it knows (S2.13)
export const owMemoFns = () => (O: OwCtx): Set<number> => {
  const out: Mut<Set<number>> = new Set();
  for (const n of O.T.all) {
    if (n.type !== "VariableDeclarator" || n.init === null || n.id.type !== "Identifier" || n.init.type !== "CallExpression" || O.F.calls.get(n.init.nid)?.prelude !== "memo") continue;
    const b = O.F.bindings.get(O.F.bindingOf.get(n.id.nid) ?? -1);
    if (b !== undefined && b.kind === "const") out.add(b.id);
  }
  return out;
};

// R-M: a Mut local, of the function that makes the call, named in an argument of a call of a memoised function the cell
// knows (owMemoFns) is not written after that call ("after" as owAfter): a miss froze it in place (S2.13). Not seen: the
// local under a second name, and a memoised function that comes from another cell, where the write throws at run time
export const owMemoArgs = (owMemoFns, owEncl, owUsesOf, owAfter, owWriteAt, owErr, isNamed) => (O: OwCtx, W: OwW, caps: Map<number, OwCap>, byFn: Map<number, number>): void => {
  const memos = owMemoFns(O), inside = (a: AstNode, b: AstNode) => a.start >= b.start && a.end <= b.end;
  if (!memos.size) return;
  // a name inside snapshot(…) in the argument gives the memoised function a copy
  const snaps = O.T.all.filter((n) => n.type === "CallExpression" && O.F.calls.get(n.nid)?.prelude === "snapshot");
  const given = (r: AstNode, a: AstNode) => inside(r, a) && !snaps.some((s) => inside(r, s) && inside(s, a));
  for (const c of O.T.all) {
    if (c.type !== "CallExpression" || c.callee.type !== "Identifier" || !memos.has(O.F.bindingOf.get(c.callee.nid) ?? -1)) continue;
    const g = owEncl(O, c), name = c.callee.name;
    for (const [id, rs] of O.T.refs) {
      const b = O.F.bindings.get(id), d = b === undefined ? undefined : O.T.byNid.get(b.nid);
      if (b === undefined || d === undefined || b.cellParam || !(b.mutOwned || isNamed(b.t, "Mut")) || owEncl(O, d).nid !== g.nid) continue;
      if (!rs.some((r) => c.arguments.some((a) => given(r, a)) && owEncl(O, r).nid === g.nid)) continue;
      const u = owUsesOf(O, caps, byFn, b).find((x: OwUse) => x.write && owAfter(O, g, d, false, x, c));
      if (u === undefined) continue;
      const w = u.at.type === "CallExpression" ? u.at : owWriteAt(O, u.at);
      owErr(W, u.at, w !== null && w.type === "CallExpression" ? "mutating-method" : "member-write", `${b.name} is written after it was given to the memoised function ${name}, which froze it in place, so the write would throw; write it before the call, or give ${name} a copy (snapshot(${b.name}))`);
    }
  }
};

// R-P (p1, 2026-11-23): n publishes a value to a holder while its function still runs (S4.11): a State's set or update,
// called or read as a value (const st = s.set, [f].forEach(s.set)); an action called with arguments, or passed to a call
// that may call it. A memoised function is not one: a miss whose arguments reach a function stores nothing (S2.13)
export const owPubNode = (owIsState, ixUm, isNamed, unwrap, owArgIndex) => (O: OwCtx, n: AstNode): boolean => {
  const isAct = (x: AstNode) => { const t = O.F.types.get(x.nid); return t !== undefined && ixUm(O.R, t).some((m) => isNamed(unwrap(m), "Action")); };
  const p = O.T.parent.get(n.nid);
  if (n.type === "MemberExpression" && !n.computed && n.property.type === "Identifier" && (n.property.name === "set" || n.property.name === "update")) return owIsState(O, n.object);
  if (n.type === "CallExpression") return n.arguments.length > 0 && isAct(n.callee);
  return (n.type === "Identifier" || n.type === "MemberExpression") && p !== undefined && (p.type === "CallExpression" || p.type === "NewExpression") && owArgIndex(p.arguments, n) >= 0 && isAct(n);
};

// R-P: the points of each function after which a value it published may be seen: a publish (owPubNode) in its own body;
// a call of a helper bound to a const or declared with function, at each call; a callback a built-in calls at once, at
// that call. A publish in a kept function is a point of that function only
export const owPubPoints = (owPubNode, owEnclFn, owCallsAtOnce, owDeclaredBy, owIsCallee) => (O: OwCtx): Map<number, AstNode[]> => {
  const out: Mut<Map<number, AstNode[]>> = new Map(), seen: Mut<Set<string>> = new Set();
  const todo: Mut<AstNode[]> = O.T.all.filter((n) => owPubNode(O, n));
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    const e = owEnclFn(O, n) ?? O.T.fn, k = `${e.nid}:${n.nid}`;
    if (seen.has(k)) continue;
    seen.add(k);
    out.set(e.nid, [...(out.get(e.nid) ?? []), n]);
    const p = O.T.parent.get(e.nid);
    if (p === undefined || e.nid === O.T.fn.nid) continue;
    if (p.type === "CallExpression" && (p.callee.nid === e.nid || owCallsAtOnce(O, p, e))) { todo.push(p); continue; }
    const b = owDeclaredBy(O, p, e);
    if (b !== undefined && b.fnNode === e.nid) for (const r of O.T.refs.get(b.id) ?? []) { const c = O.T.parent.get(r.nid); if (c !== undefined && owIsCallee(O, r)) todo.push(c); }
  }
  return out;
};

// R-P: a point as the message names it: the name called or read (s.set, put0, sq), or the call's callee
export const owPubWhat = () => (p: AstNode): string => {
  const n = p.type === "CallExpression" ? p.callee : p;
  if (n.type === "Identifier") return `${n.name}(…)`;
  if (n.type === "MemberExpression" && !n.computed && n.property.type === "Identifier") return n.object.type === "Identifier" ? `${n.object.name}.${n.property.name}${p.type === "CallExpression" ? "(…)" : ""}` : `….${n.property.name}(…)`;
  return "a call";
};

// R-P: a local whose type holds a Mut (or a Mut the function owns), declared in g before a point of g or read by g from
// an encloser, is not written after the point ("after" as owAfter; a call of a helper that writes it, and passing it
// to a Mut parameter, are writes): a function published there may read it through a read-only name (S4.10)
export const owPubWrites = (owPubPoints, owPubWhat, owLocalHoldsMut, owUsesOf, owAfter, owWriteAt, owEncl, owErr, isNamed) => (O: OwCtx, W: OwW, caps: Map<number, OwCap>, byFn: Map<number, number>): void => {
  const pts = owPubPoints(O);
  for (const g of [O.T.fn, ...O.T.fns]) {
    const ps = pts.get(g.nid) ?? [];
    if (!ps.length) continue;
    for (const id of O.T.refs.keys()) {
      const b = O.F.bindings.get(id), d = b === undefined ? undefined : O.T.byNid.get(b.nid);
      if (b === undefined || d === undefined || b.cellParam || !(b.mutOwned || isNamed(b.t, "Mut") || owLocalHoldsMut(O, b))) continue;
      const captured = owEncl(O, d).nid !== g.nid;
      if (captured && !(caps.get(g.nid)?.read ?? []).includes(b.id)) continue;
      for (const u of owUsesOf(O, caps, byFn, b)) {
        if (!u.write || (captured && !(u.at.start >= g.start && u.at.end <= g.end))) continue;
        const p = ps.find((x) => owAfter(O, g, d, captured, u, x));
        if (p === undefined) continue;
        const w = u.at.type === "CallExpression" ? u.at : owWriteAt(O, u.at);
        owErr(W, u.at, w !== null && w.type === "CallExpression" ? "mutating-method" : "member-write", `${b.name} is written after a value is published at ${owPubWhat(p)} in the same run of this function; a function published there may read ${b.name} through a read-only name (S4.10) and would see the write (S4.11); finish every write to ${b.name} before ${owPubWhat(p)}`);
        break;
      }
    }
  }
};

// f1 (2026-11-23, S4.12): a type that holds a function: a function type, a record with a call or construct signature,
// an Action, at any depth (an alias expanded once per key; past 400 parts it is taken to hold none: this check is
// ergonomics, the run-time throw is the guarantee)
export const owTyFn = (owTyKids, typeKey) => (R: IxRegCore, t0: Ty): boolean => {
  const seen: Mut<Set<string>> = new Set(), todo: Mut<Ty[]> = [t0];
  let n = 0;
  for (let t = todo.pop(); t !== undefined && n < 400; t = todo.pop()) {
    n++;
    if (t.k === "fn" || (t.k === "rec" && ((t.calls ?? []).length > 0 || (t.ctors ?? []).length > 0))) return true;
    if (t.k !== "named") { todo.push(...owTyKids(t)); continue; }
    if (t.n === "Action") return true;
    if (!R.isAlias(t.n)) { todo.push(...t.args); continue; }
    const key = typeKey(t);
    if (!seen.has(key)) { seen.add(key); todo.push(R.expand(t)); }
  }
  return false;
};

// f1: a function the argument a makes in g: a function literal, one inside an array, object, conditional or
// parenthesised argument, or the value of a const of g bound to such an expression
export const owMadeFn = (owEncl) => (O: OwCtx, g: AstNode, a: AstNode): AstNode | null => {
  const todo: Mut<AstNode[]> = [a], seen: Mut<Set<number>> = new Set();
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    if (seen.has(n.nid)) continue;
    seen.add(n.nid);
    if (n.type === "ArrowFunctionExpression" || n.type === "FunctionExpression") return n;
    if (n.type === "ArrayExpression") for (const e of n.elements) { if (e !== null) todo.push(e.type === "SpreadElement" ? e.argument : e); }
    else if (n.type === "ObjectExpression") { for (const p of n.properties) if (p.type === "SpreadElement") todo.push(p.argument); else if (p.type === "Property") todo.push(p.value); }
    else if (n.type === "ConditionalExpression") todo.push(n.consequent, n.alternate);
    else if (n.type === "ParenthesizedExpression" || n.type === "TSAsExpression" || n.type === "TSSatisfiesExpression" || n.type === "TSNonNullExpression") { const e = n.expression; if (e !== null) todo.push(e); }
    else if (n.type === "Identifier") {
      const b = O.F.bindings.get(O.F.bindingOf.get(n.nid) ?? -1), d = b === undefined ? undefined : O.T.byNid.get(b.nid);
      const v = d === undefined ? undefined : O.T.parent.get(d.nid), decl = v === undefined ? undefined : O.T.parent.get(v.nid);
      if (d !== undefined && v !== undefined && v.type === "VariableDeclarator" && v.init !== null && decl !== undefined && decl.type === "VariableDeclaration" && decl.kind === "const" && owEncl(O, d).nid === g.nid) todo.push(v.init);
    }
  }
  return null;
};

// f1 (S4.12): a state's set, or an action called, given at a parameter whose type holds a function (owTyFn) a function
// the calling function makes (owMadeFn): the run-time freeze throws there (prelude noBodyFn), so the checker says so
export const owFnPubs = (owIsState, owMadeFn, owTyFn, owEncl, ixUm, isNamed, unwrap, owErr) => (O: OwCtx, W: OwW): void => {
  for (const n of O.T.all) {
    if (n.type !== "CallExpression" || n.arguments.length === 0) continue;
    const c = n.callee, t = O.F.types.get(c.nid);
    const key = c.type === "MemberExpression" && !c.computed && c.property.type === "Identifier" ? c.property.name : "";
    const set = (key === "set" || key === "update") && c.type === "MemberExpression" && owIsState(O, c.object);
    if (!set && !(t !== undefined && ixUm(O.R, t).some((m) => isNamed(unwrap(m), "Action")))) continue;
    const sig = O.F.calls.get(n.nid)?.sig ?? null, d = sig === null ? null : sig.decl ?? sig;
    const ot = set && c.type === "MemberExpression" ? O.F.types.get(c.object.nid) : undefined;
    const st = ot === undefined ? undefined : ixUm(O.R, ot).map((m) => unwrap(m)).find((m) => isNamed(m, "State"));
    const what = c.type === "Identifier" ? `${c.name}(…)` : c.type === "MemberExpression" && c.object.type === "Identifier" ? `${c.object.name}.${key}` : "this call";
    // update's argument is called at once: what it returns is given (an arrow with an expression body)
    const args = key !== "update" ? n.arguments : n.arguments.flatMap((a) => (a.type === "ArrowFunctionExpression" && a.body.type !== "BlockStatement" ? [a.body] : []));
    args.forEach((a, i) => {
      const dp = st !== undefined && st.k === "named" ? st.args[0] : d === null ? undefined : i < d.ps.length ? d.ps[i]?.t : d.rest;
      const m = a.type === "SpreadElement" || dp === undefined || !owTyFn(O.R, dp) ? null : owMadeFn(O, owEncl(O, n), a);
      if (m !== null) owErr(W, m, "fn-publish", `a function made in this function is given to ${what} while the function still runs; at run time that throws (S4.12), since the function could still write what it reads. Give data and make the function where the value is read, or make the function in a cell of its own and take that cell as an input`);
    });
  }
};

// owCheck over a tree index already made (the module check makes one per cell)
export const owCheckIn = (owBindingOfFn, owCaptures, owCaptureErrs, owPlacement, owLateUses, owMemoArgs, owPubWrites, owFnPubs, owActionEscapes, ixOut) => (R: IxRegCore, F: IxFacts, T: OwTree): OwOutput => {
  const O: OwCtx = { T, F, R };
  const W: OwW = { errs: null, seen: new Set(), unsup: null };
  const caps = owCaptures(O, W);
  const byFn = owBindingOfFn(F);
  owCaptureErrs(O, W, caps, byFn);
  owPlacement(O, W);
  owLateUses(O, W, caps, byFn);
  owMemoArgs(O, W, caps, byFn);
  owPubWrites(O, W, caps, byFn);
  owFnPubs(O, W);
  return { diags: ixOut(W.errs), actions: owActionEscapes(O), unsup: ixOut(W.unsup), gap: T.other };
};

// capture.ts's two passes as core.ts runs them: by name before the check, by binding after, skipping what the first reported
export const owCaptureCheck = (owIndex, owTaintCaptures, owOpaqueCaptures) => (R: IxRegCore, F: IxFacts, fn: AstNode, tainted: Map<string, string>): OwCaptureOut => {
  const T = owIndex(F, fn);
  const byName = owTaintCaptures(fn, tainted);
  const skip = new Set(byName.map((c) => c.at.nid));
  return { byName, opaque: owOpaqueCaptures({ T, F, R }, tainted, skip), gap: T.other };
};

// core.ts's fed rule (S11.9): a cell fed a function from another language may not yield from an events cell, nor hold in
// a state cell, a value whose type may be or hold a function; the cell's value type as core.ts takes it from fnT
export const owFedKept = (ixMayHoldFn, ixFnParts, isNamed, show, ERR) => (R: IxRegCore, fn: AstNode, fnT: Ty, name: string, fedBy: string): string[] => {
  const parts = ixFnParts(fn);
  if (parts === null) return [];
  let ret: Ty = fnT.k === "fn" ? fnT.ret : ERR;
  if (parts.async && ret.k === "named" && isNamed(ret, "Promise")) ret = ret.args[0] ?? ERR;
  if (parts.generator && ret.k === "named" && isNamed(ret, "Generator")) ret = ret.args[0] ?? ERR;
  const msg = (what: string, t: Ty, then: string) => `${what} ${show(t)}, which may be or hold a function from another language (${name} ${fedBy}); ${then}`;
  const out: Mut<string[]> = [];
  if (parts.generator && !parts.async && ixMayHoldFn(R, ret)) out.push(msg("an events cell yields", ret, "a listener's action would receive it"));
  const held = ret.k === "named" && isNamed(ret, "StateCell") ? ret.args[0] ?? ERR : null;
  if (held !== null && ixMayHoldFn(R, held)) out.push(msg("a state cell holds", held, "an action that reads the state cell could call it"));
  return out;
};

// one cell's registry (ix-types IxReg), and the same with core.ts's compile hook, whose reports the glue puts back in
// the registry's report buffer
export type MdCellReg = { readonly ix: IxReg; readonly withHook: (hook: (e: AstNode, options: Ty | null) => MdCompiled) => IxReg };

// the registry as the module check calls it (core.ts). loadUser reads the declarations from the tree the check parsed;
// cell takes the start of the cell's function, so the glue knows which cell a report or a gap belongs to
export type MdReg = {
  readonly builtin: Set<string>;
  readonly loadForeign: (text: string) => MdForeign;
  readonly loadUser: (ast: Ast, jsx: boolean, clash: number[]) => MdReport[];
  readonly cell: (at: number) => MdCellReg;
  // an annotation converted with nothing reported or kept, an alias expanded once (core.ts shellFn)
  readonly peekType: (n: AstNode) => Ty;
  readonly ops: RegOps;
  readonly globals: { name: string; t: Ty; kind: IxKind }[];
  readonly allowed: Set<string>;
  // CAPABILITIES' names and types
  readonly capabilities: Map<string, string>;
  // t1 (2026-11-24): Object.prototype's own names, read when the checker loads (core.ts PROTO_MEMBERS); the names a
  // compiled cell takes from outside the module by name, a capability or a global (core.ts RESERVED_INPUTS)
  readonly proto: Set<string>;
  readonly inputs: Set<string>;
};

export type MdSources = {
  readonly cells: string; readonly tsx: boolean; readonly foreign: string | null; readonly shell: string | null;
  readonly name: string | null; readonly outside: MdOutside[]; readonly probe: IxProbeAsk | null;
  // d1 (2026-11-24): the prelude names a compiled cell of this module binds from the runtime module (none in it)
  readonly bound: string[];
};

export type MdCellRec = {
  readonly name: string; readonly status: MdStatus; readonly line: number; readonly errors: MdErr[]; readonly unsupported: MdErr[];
  readonly blockedBy: string[]; readonly value: string | null;
  // the problems the cell's Checker held (ch.diags, ch.unsup), with their spans
  readonly ch: IxDiag[]; readonly chUnsup: IxDiag[];
  // e1 (2026-11-23): the shapes of the cell's cast calls, in source order
  readonly casts: TypeShape[];
  // open part 6 (HO): for each index or length write in source order, whether the run time checks it
  readonly holes: boolean[];
  // y1 (2026-11-24): whether the cell's value type names a promise (md-value.ss.ts), once its value rules ran
  readonly promises?: boolean;
  // where the cell's function starts (the harness pairs the records with core.ts's Checkers by it)
  readonly at: number;
};

// facts.ts CellInfo
export type MdInfo = {
  readonly name: string; readonly span: number[]; readonly params: MdParamInfo[]; readonly returnsRef: boolean;
  readonly generator: boolean; readonly compiles: IslandSpec[]; readonly casts: TypeShape[]; readonly holes: boolean[];
  // y1 (2026-11-24): the cell's value type names no promise, so the run time refuses one in it (null: not known)
  readonly strict: boolean | null;
};

// what every cell's check reads of the module
export type MdCtx = {
  readonly R: MdReg; readonly src: string; readonly count: number; readonly line: (pos: number) => number;
  readonly defs: MdDef[]; readonly byName: Map<string, MdDef>; readonly cellNames: Set<string>; readonly shellNames: Set<string>;
  readonly foreign: Map<string, MdForeignValue>; readonly outside: Map<string, MdOutside>; readonly takenAsEvents: Set<string>; readonly probe: IxProbeAsk | null;
  readonly bound: string[];
};

// the tables core.ts's cell loop writes and later cells read
export type MdTables = {
  value: Map<string, Ty | null>; refInner: Map<string, Ty>; eventsInner: Map<string, Ty>; listeners: Set<string>;
  stateful: Map<string, string>; fnFed: Map<string, string>; boundaries: Map<string, Map<string, MdBoundary>>;
  viewTypes: Map<string, { readonly ty: Ty; readonly cell: string }>; out: Map<string, MdCellRec>; probe: IxProbe | null;
};

export const mdDistinct = (parseTree, nameAt, standIn) => (src: string, jsx: boolean): { parse: Parse; text: string; dups: MdDup[] } => {
  let text = src;
  const dups: Mut<MdDup[]> = [];
  for (;;) {
    const p = parseTree(text, jsx);
    const name = p.ok || !p.message.includes("has already been declared") ? "" : nameAt(text, p.pos);
    const ph = p.ok || name === "" ? null : standIn(dups.length, name.length);
    if (p.ok || ph === null || dups.some((d) => d.ph === ph)) return { parse: p, text, dups: dups };
    dups.push({ ph, name: src.slice(p.pos, p.pos + name.length), pos: p.pos });
    text = text.slice(0, p.pos) + ph + text.slice(p.pos + name.length);
  }
};

// the tree of a text that must parse: checkSources throws the parser's error
export const mdMustParse = (parseTree) => (text: string, jsx: boolean): Ast => {
  const p = parseTree(text, jsx);
  if (!p.ok) throw new Error(p.message);
  return p.ast;
};

// shell.ts: the names it exports, a const or let declarator's or a function's
export const mdShellNames = (mdMustParse) => (text: string): Set<string> => {
  const out: Mut<Set<string>> = new Set();
  const prog = mdMustParse(text, false).program;
  if (prog.type !== "Program") return out;
  for (const st of prog.body) {
    const d = st.type === "ExportNamedDeclaration" ? st.declaration : null;
    if (d !== null && d.type === "VariableDeclaration") {
      for (const x of d.declarations) if (x.type === "VariableDeclarator" && x.id.type === "Identifier") out.add(x.id.name);
    } else if (d !== null && d.type === "FunctionDeclaration" && d.id.type === "Identifier") out.add(d.id.name);
  }
  return out;
};

export const mdForeignErrs = (mdLoadErr) => (F: MdForeign): MdErr[] => [
  ...F.reports.map(mdLoadErr),
  ...F.rest.map((r) => ({ rule: "module-level", line: r.line, msg: `foreign.d.ts: ${r.kind} is not a declaration` })),
  ...F.values.filter((v) => v.marker === null).map((v) => ({ rule: "foreign-unmarked", line: v.line, msg: `foreign ${v.name} has no /** pure */ or /** effect */` })),
];

// each such comment: an error of the first cell whose statement holds it, else of the module
export const mdIgnores = (mdTsIgnore, MD_NO_TS_IGNORE) => (ast: Ast, defs: MdDef[], line: (pos: number) => number): { cell: Map<string, MdErr[]>; module: MdErr[] } => {
  const cell: Mut<Map<string, MdErr[]>> = new Map();
  const module: Mut<MdErr[]> = [];
  for (const cm of ast.comments) {
    if (!mdTsIgnore(cm.text)) continue;
    const c = defs.find((d) => d.stmt.start <= cm.start && cm.start < d.stmt.end);
    const e = { rule: "no-ts-ignore", line: line(cm.start), msg: MD_NO_TS_IGNORE };
    if (c === undefined) module.push(e);
    else cell.set(c.name, [...(cell.get(c.name) ?? []), e]);
  }
  return { cell: cell, module: module };
};

// errors at positions: each to the cell whose statement holds it, after what cell already has, else to the module
export const mdByCell = () => (defs: MdDef[], es: { at: number; e: MdErr }[], cell: Map<string, MdErr[]>): { cell: Map<string, MdErr[]>; module: MdErr[] } => {
  const out: Mut<Map<string, MdErr[]>> = new Map(cell), module: Mut<MdErr[]> = [];
  for (const x of es) {
    const d = defs.find((c) => c.stmt.start <= x.at && x.at < c.stmt.end);
    if (d === undefined) module.push(x.e);
    else out.set(d.name, [...(out.get(d.name) ?? []), x.e]);
  }
  return { cell: out, module };
};

// a cell's record before its check: the line of its statement and the errors made before the cell loop
export const mdFreshRec = () => (d: MdDef, line: number, errors: MdErr[]): MdCellRec => ({
  name: d.name, status: "ok", line, errors, unsupported: [], blockedBy: [], value: null, ch: [], chUnsup: [], casts: [], holes: [], at: d.fn.start,
});

// the cells and the module's errors, in core.ts's order: foreign.d.ts, built-in type names, the user's declarations,
// statements that are not cells, duplicates, then the ignore comments with no cell
// t1 (B-1): each top-level type or interface statement that declares a member mdProtoMembers finds, once, at the statement
export const mdTypeProto = (mdProtoMembers, PROTO_MEMBER_MSG) => (prog: AstNode, proto: Set<string>): ModErr[] => {
  if (prog.type !== "Program") return [];
  const out: Mut<ModErr[]> = [];
  for (const st of prog.body) {
    const d = st.type === "ExportNamedDeclaration" && st.declaration !== null ? st.declaration : st;
    if (d.type !== "TSTypeAliasDeclaration" && d.type !== "TSInterfaceDeclaration") continue;
    const m = mdProtoMembers(d, proto)[0];
    if (m !== undefined) out.push({ at: d, rule: "banned-member", msg: PROTO_MEMBER_MSG(m.name, m.opt) });
  }
  return out;
};

export const mdModuleLevel = (moduleShape, mutPlaces, mdForeignErrs, mdLoadErr, mdIgnores, mdByCell, mdTypeProto) => (R: MdReg, ast: Ast, text: string, jsx: boolean, F: MdForeign | null, shellNames: Set<string>, line: (pos: number) => number): MdModuleLevel => {
  const shape = moduleShape(ast.program, R.builtin, shellNames);
  const modErr = (e: ModErr): MdErr => ({ rule: e.rule, line: line(e.at.start), msg: e.msg });
  // t1 (B-1): a type or interface declaring a banned member is a clash too: it is not loaded, so a cell that uses it is rejected
  const bad: ModErr[] = [...shape.clashes, ...mdTypeProto(ast.program, R.proto)];
  const clashes = bad.map(modErr);
  const user = R.loadUser(ast, jsx, bad.map((c) => c.at.start)).map(mdLoadErr);
  const defs: MdDef[] = shape.cells.map((c) => ({ name: c.name, fn: c.fn, stmt: c.stmt }));
  const ig = mdIgnores(ast, defs, line), mutRule = mdByCell(defs, mutPlaces(ast.program).map((e) => ({ at: e.at.start, e: modErr(e) })), ig.cell);
  return { defs, module: [...(F === null ? [] : mdForeignErrs(F)), ...clashes, ...user, ...shape.errors.map(modErr), ...ig.module, ...mutRule.module], ignores: mutRule.cell };
};

// a literal array of strings, or null
export const mdNames = () => (v: AstNode): string[] | null => {
  if (v.type !== "ArrayExpression") return null;
  const out: Mut<string[]> = [];
  for (const el of v.elements) {
    if (el === null || el.type !== "Literal" || typeof el.value !== "string") return null;
    out.push(el.value);
  }
  return out;
};

// island.ts specOf: compile({ inputs, refs, outputs, options }) with literal arrays of cell names, or null
export const mdSpecOf = (mdNames) => (call: AstNode): MdSpec | null => {
  if (call.type !== "CallExpression" || call.arguments.length !== 1) return null;
  const arg = call.arguments[0];
  if (arg === undefined || arg.type !== "ObjectExpression") return null;
  let inputs: string[] = [], refs: string[] = [], outputs: string[] = [];
  let options: AstNode | null = null;
  for (const p of arg.properties) {
    if (p.type !== "Property" || p.computed || p.key.type !== "Identifier") return null;
    const k = p.key.name;
    if (k === "options") { options = p.value; continue; }
    const xs = k === "inputs" || k === "refs" || k === "outputs" ? mdNames(p.value) : null;
    if (xs === null) return null;
    if (k === "inputs") inputs = [...inputs, ...xs];
    else if (k === "refs") refs = [...refs, ...xs];
    else outputs = [...outputs, ...xs];
  }
  return outputs.length ? { inputs, refs, outputs, options } : null;
};

// island.ts compileCalls: the compile(...) calls in the body of a cell whose parameters include compile
export const mdCompileCalls = (kidsOf) => (fn: FnNode): AstNode[] => {
  if (!fn.params.some((p) => p.type === "Identifier" && p.name === "compile")) return [];
  const out: Mut<AstNode[]> = [];
  const todo: Mut<AstNode[]> = [fn.body];
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    if (n.type === "CallExpression" && n.callee.type === "Identifier" && n.callee.name === "compile") out.push(n);
    for (const k of kidsOf(n).toReversed()) todo.push(k);
  }
  return out;
};

// the cells a cell is checked after: its parameters that name cells, then the cells its compile(...) calls name
export const mdDeps = (mdCompileCalls, mdSpecOf) => (d: MdDef, cellNames: Set<string>): string[] => {
  const ps = d.fn.params.flatMap((p) => (p.type === "Identifier" && cellNames.has(p.name) ? [p.name] : []));
  const named = mdCompileCalls(d.fn).flatMap((call) => {
    const sp = mdSpecOf(call);
    return sp === null ? [] : [...sp.inputs, ...sp.refs, ...sp.outputs].filter((n) => cellNames.has(n));
  });
  return [...ps, ...named];
};

// one step of core.ts visit: a cell on the stack again closes a cycle, which every cell on it reports
export const mdVisit = () => {
  function visit(S: Mut<MdVisit>, deps: Map<string, string[]>, byName: Map<string, MdDef>, lines: Map<string, number>, n: string, stack: string[]): void {
    const st = S.state.get(n);
    if (st === 2) return;
    if (st === 1) {
      const cyc = stack.slice(stack.indexOf(n));
      const msg = `dependency cycle ${[...cyc, n].join(" -> ")}`;
      for (const x of cyc) S.cycles = new Map([...S.cycles, [x, [...(S.cycles.get(x) ?? []), { rule: "cycle", line: lines.get(x) ?? 0, msg }]]]);
      return;
    }
    S.state = new Map([...S.state, [n, 1]]);
    for (const d of deps.get(n) ?? []) visit(S, deps, byName, lines, d, [...stack, n]);
    S.state = new Map([...S.state, [n, 2]]);
    const def = byName.get(n);
    if (def !== undefined) S.order = [...S.order, def];
  }
  return visit;
};

// the order the cells are checked in, and each cell's cycle errors
export const mdOrder = (mdDeps, mdVisit) => (defs: MdDef[], byName: Map<string, MdDef>, cellNames: Set<string>, lines: Map<string, number>): { order: MdDef[]; cycles: Map<string, MdErr[]> } => {
  const deps = new Map(defs.map((d): [string, string[]] => [d.name, mdDeps(d, cellNames)]));
  const S: Mut<MdVisit> = { state: new Map(), order: [], cycles: new Map() };
  for (const d of defs) mdVisit(S, deps, byName, lines, d.name, []);
  return { order: S.order, cycles: S.cycles };
};

export const mdAnn = () => (p: AstNode): AstNode | null => {
  const a = p.type === "Identifier" || p.type === "ObjectPattern" || p.type === "ArrayPattern" || p.type === "RestElement" ? p.typeAnnotation : null;
  return a !== null && a.type === "TSTypeAnnotation" ? a.typeAnnotation : null;
};

// the plain name of a type reference (ann.typeName.name)
export const mdRefName = () => (ann: AstNode | null): string | null =>
  ann !== null && ann.type === "TSTypeReference" && ann.typeName.type === "Identifier" ? ann.typeName.name : null;

// diag: an error of the cell's record at a node's line
export const mdDiag = () => (X: MdCtx, L: MdL, at: AstNode, rule: string, msg: string): void => {
  L.errors = [...L.errors, { rule, line: X.line(at.start), msg }];
};

// a handle parameter (State<T>, Events<T>) naming a cell: the cell's inner type must be T both ways
export const mdInjectHandle = (mdDiag, isNamed, show, ixGap) => (K: IxK, C: IxCtls, X: MdCtx, M: MdMod, L: MdL, p: Identifier, ann: AstNode, wrapper: string): Ty => {
  const st = wrapper === "State", name = p.name;
  const inner = (st ? M.refInner : M.eventsInner).get(name);
  const want = K.reg.convert(ann, [], null);
  const wrapped = want.k === "named" && isNamed(want, wrapper);
  const a0 = want.k === "named" && wrapped ? want.args[0] : undefined;
  // core.ts reads want.args[0] unguarded
  if (wrapped && a0 === undefined) return ixGap(C, "State or Events with no type argument");
  // e1 (2026-11-23), B4: a state cell is written and read, so its type is T both ways; an events cell's values only
  // reach the listener, so what it yields must be a T (a yielded object literal is exact and not the other way)
  const ok = inner !== undefined && a0 !== undefined && K.reg.sub(inner, a0) && (!st || K.reg.sub(a0, inner));
  if (!ok) mdDiag(X, L, p, st ? "inject-state" : "inject-events", `${name} is not a ${st ? "state cell" : "sync generator cell"} ${st ? `of ${show(want)}` : `yielding ${show(a0 ?? want)}`}`);
  return want;
};

// a parameter that names a cell of the module: its value type (null when it takes it as it is), or ERR
export const mdInjectCell = (mdDiag, mdInjectHandle, ERR) => (K: IxK, C: IxCtls, X: MdCtx, M: MdMod, L: MdL, p: Identifier, ann: AstNode | null, wrapper: string | null): { t: Ty; done: boolean } => {
  const name = p.name, v = M.value.get(name);
  if (v === null || v === undefined) { L.blockedBy = [...L.blockedBy, name]; return { t: ERR, done: true }; }
  if (wrapper !== null && ann !== null) return { t: mdInjectHandle(K, C, X, M, L, p, ann, wrapper), done: true };
  if (M.listeners.has(name)) { mdDiag(X, L, p, "listener-placement", `${name} is a listener; no cell may take one, so it ends only when ${name} runs again`); return { t: ERR, done: true }; }
  if (X.takenAsEvents.has(name)) { mdDiag(X, L, p, "inject-events", `${name} is taken as Events elsewhere, so a reader gets the handle; type this parameter Events<...>`); return { t: ERR, done: true }; }
  return { t: v, done: false };
};

// a parameter that names a foreign value
export const mdInjectForeign = (mdDiag, owIter, show) => (K: IxK, X: MdCtx, L: MdL, p: Identifier, fv: MdForeignValue): Ty => {
  if (fv.marker === "effect") mdDiag(X, L, p, "foreign-effect", `checked cell takes /** effect */ foreign ${p.name}`);
  const fit = owIter(K.reg, fv.t);
  if (fit !== null) mdDiag(X, L, p, "iterator-cell", `foreign ${p.name}: ${show(fv.t)} may hold an iterator (${fit}); every cell that takes it would use up the same one`);
  return fv.t;
};

// the boundary's rules on a parameter's annotation (the last two of the cell in another language's branch)
export const mdBoundaryRules = (mdDiag, boundaryShapeAt, show) => (K: IxK, X: MdCtx, M: MdMod, L: MdL, cell: string, p: Identifier, inner: Ty, st: boolean): MdBoundary | null => {
  const shape = boundaryShapeAt(inner, { expand: K.reg.expand, isAlias: K.reg.isAlias }, !st);
  if (shape.k === "error") { mdDiag(X, L, p, "boundary-type", `${p.name}: ${show(inner)} cannot cross from another language: it is or holds ${shape.error}`); return null; }
  if (!st) return { shape, ref: false };
  const first = M.viewTypes.get(p.name);
  if (first !== undefined && !(K.reg.sub(first.ty, inner) && K.reg.sub(inner, first.ty))) {
    mdDiag(X, L, p, "boundary-state", `viewof ${p.name} is taken as State<${show(first.ty)}> by ${first.cell}; every State to one view has the same type`);
    return null;
  }
  if (first === undefined) M.viewTypes = new Map([...M.viewTypes, [p.name, { ty: inner, cell }]]);
  return { shape, ref: true };
};

// a cell in another language (or a shell cell): the annotation is the type, checked when a value crosses
export const mdInjectBoundary = (mdDiag, mdBoundaryRules, hasErrWith, isNamed, ixGap, ERR) => (K: IxK, C: IxCtls, X: MdCtx, M: MdMod, L: MdL, cell: string, p: Identifier, ann: AstNode | null, wrapper: string | null): Ty => {
  const name = p.name;
  if (ann === null) { mdDiag(X, L, p, "boundary-unannotated", `${name} is a cell in another language; annotate the parameter with the type it must have, e.g. ${name}: number`); return ERR; }
  if (wrapper === "Events") { mdDiag(X, L, p, "boundary-type", `${name} is a cell in another language; it cannot be taken as Events`); return ERR; }
  const view = X.outside.get(name)?.view ?? false;
  if (wrapper === "State" && !view) { mdDiag(X, L, p, "boundary-state", `${name} has no viewof; only an Observable JavaScript view, or a SoundScript state cell imported with its viewof, can be taken as State`); return ERR; }
  const want = K.reg.convert(ann, [], null);
  const st = wrapper === "State";
  const isState = want.k === "named" && isNamed(want, "State");
  const a0 = want.k === "named" && isState ? want.args[0] : undefined;
  if (st && isState && a0 === undefined) return ixGap(C, "State with no type argument");
  const inner = st && a0 !== undefined ? a0 : want;
  if (hasErrWith(X.R.ops)(inner)) return ERR;
  const b = mdBoundaryRules(K, X, M, L, cell, p, inner, st);
  if (b === null) return ERR;
  const mine: Map<string, MdBoundary> = M.boundaries.get(cell) ?? new Map();
  M.boundaries = new Map([...M.boundaries, [cell, new Map([...mine, [name, b]])]]);
  return want;
};

// the annotation of a parameter given a value type: the value must be assignable to it, and not hide an Action
export const mdInjectAnn = (mdDiag, ixHides, isNamed, show, forgotWith, extraParamsWith) => (K: IxK, C: IxCtls, X: MdCtx, L: MdL, p: Identifier, ann: AstNode | null, vt: Ty): Ty => {
  if (ann === null) return vt;
  const want = K.reg.convert(ann, [], null);
  const widenBorrow = vt.k === "named" && isNamed(vt, "Borrowed") && !(want.k === "named" && isNamed(want, "Borrowed"));
  // w1 (2026-11-24): a failure by the forgetting rule says what was left out (subtype.ss.ts forgotWith); open
  // (2026-11-25): one by the parameter count says which parameters to remove (extraParamsWith)
  const PR = { isAlias: K.reg.quiet.isAlias, expand: K.reg.quiet.expand, member: K.reg.quiet.member, fnOwn: (n: string) => K.reg.quiet.fnOwn?.(n) === true };
  const why = widenBorrow || K.reg.sub(vt, want) ? null : extraParamsWith(PR)(vt, want) ?? forgotWith(PR)(vt, want);
  if (widenBorrow || why !== null || !K.reg.sub(vt, want)) mdDiag(X, L, p, "inject-type", `${p.name}: ${show(vt)} is not assignable to ${show(want)}${why !== null ? `: ${why}` : ""}`);
  else ixHides(K, C, p, vt, want, null);
  return want;
};

// one parameter's injected type, by what it names: a cell, a foreign value, a shell cell, a capability, a cell in
// another language; a handle (State, Events) only of a cell
export const mdInjectParam = (mdAnn, mdRefName, mdDiag, mdInjectCell, mdInjectForeign, mdShellFn, mdInjectBoundary, mdInjectAnn, named, UNKNOWN, ERR) => (K: IxK, C: IxCtls, X: MdCtx, M: MdMod, L: MdL, cell: string, p: AstNode): Ty => {
  if (p.type !== "Identifier") { mdDiag(X, L, p, "inject-pattern", "an injected parameter must be a plain identifier"); return ERR; }
  const name = p.name, ann = mdAnn(p), ref = mdRefName(ann);
  if (ref === "Source" || ref === "Sub") {
    mdDiag(X, L, p, "inject-events", ref === "Source" ? "Source was renamed Events: type this parameter Events<...>" : "Sub was renamed Listener, and no cell may take a listener");
    return ERR;
  }
  const wrapper = ref === "State" || ref === "Events" ? ref : null;
  let vt: Ty = ERR;
  if (X.cellNames.has(name)) {
    const r = mdInjectCell(K, C, X, M, L, p, ann, wrapper);
    if (r.done) return r.t;
    vt = r.t;
  } else {
    const fv = X.foreign.get(name), cap = X.R.capabilities.get(name), shell = X.shellNames.has(name);
    if (fv !== undefined) vt = mdInjectForeign(K, X, L, p, fv);
    else if (shell && !mdShellFn(X, ann, wrapper)) vt = UNKNOWN;
    else if (cap !== undefined && !shell) vt = named(cap);
    else if (X.outside.has(name) || shell) return mdInjectBoundary(K, C, X, M, L, cell, p, ann, wrapper);
    else { mdDiag(X, L, p, "inject-unknown", `parameter ${name} names no cell, foreign or capability`); return ERR; }
  }
  if (wrapper !== null) { mdDiag(X, L, p, wrapper === "State" ? "inject-state" : "inject-events", `${name} is not a ${wrapper === "State" ? "state cell" : "sync generator cell"}`); return ERR; }
  return mdInjectAnn(K, C, X, L, p, ann, vt);
};

// every parameter's type, then the parameters whose type holds one lite does not understand
export const mdInject = (mdInjectParam, mdDiag, owMut, hasErrWith) => (K: IxK, C: IxCtls, X: MdCtx, M: MdMod, L: MdL, d: MdDef): Ty[] => {
  const injected: Mut<Ty[]> = [];
  for (const p of d.fn.params) injected.push(mdInjectParam(K, C, X, M, L, d.name, p));
  const hasErr = hasErrWith(X.R.ops);
  for (const [i, t] of injected.entries()) {
    const p = d.fn.params[i], mt = owMut(K.reg, t);
    // an input is never a Mut, annotated so or given one (a foreign value typed Mut<…> included)
    if (mt !== null && p !== undefined && p.type === "Identifier") mdDiag(X, L, p, "mut-cell", `input ${p.name}: ${mt}; an input is never a Mut: the cell it comes from and every other cell that takes it share it`);
    if (t.k !== "err" && hasErr(t) && p !== undefined && p.type === "Identifier") L.blockedBy = [...L.blockedBy, `${p.name} (type not understood)`];
  }
  return injected;
};

export const mdTaintOf = (mdAnn, mdRefName, isNamed) => (X: MdCtx, M: MdMod, p: AstNode): string | null => {
  if (p.type !== "Identifier") return null;
  const wrapper = mdRefName(mdAnn(p));
  if (wrapper === "State" || wrapper === "Events") return null;
  const name = p.name, caps = X.R.capabilities.has(name);
  if (X.cellNames.has(name)) {
    const t = M.value.get(name);
    if (t !== null && t !== undefined && t.k === "named" && isNamed(t, "Action")) return null;
    if (M.refInner.has(name)) return `the value of the state cell ${name}`;
    if (X.byName.get(name)?.fn.generator === true) return `the latest value of the events cell ${name}`;
    const why = M.stateful.get(name);
    return why === undefined ? null : `${name} ${why}`;
  }
  if (X.shellNames.has(name)) return `a shell cell's value`;
  if (X.outside.has(name) && !caps) return `the value of ${name}, a cell in another language`;
  // log writes nothing the program reads back; invalidation is the cell's own lifetime
  return caps && name !== "invalidation" && name !== "log" ? `capability ${name}` : null;
};

export const mdTainted = (mdTaintOf) => (X: MdCtx, M: MdMod, d: MdDef): Map<string, string> => {
  const out: Mut<Map<string, string>> = new Map();
  for (const p of d.fn.params) {
    const why = mdTaintOf(X, M, p);
    if (why !== null && p.type === "Identifier") out.set(p.name, why);
  }
  return out;
};

// the first parameter that feeds the cell a function from another language, and how
export const mdFedBy = () => (M: MdMod, d: MdDef): string | null => {
  for (const p of d.fn.params) {
    if (p.type !== "Identifier") continue;
    if (M.boundaries.get(d.name)?.get(p.name)?.shape.k === "fn") return `takes ${p.name}, a function from another language`;
    const via = M.fnFed.get(p.name);
    if (via !== undefined) return `takes ${p.name}, which ${via}`;
  }
  return null;
};

// what the cell records of its own state-dependence and feeding, for the cells after it
export const mdMarkStateful = () => (M: MdMod, d: MdDef, tainted: Map<string, string>, fedBy: string | null): void => {
  if (fedBy !== null) M.fnFed = new Map([...M.fnFed, [d.name, fedBy]]);
  const first = [...tainted.entries()][0];
  if (first !== undefined) M.stateful = new Map([...M.stateful, [d.name, first[1].startsWith("capability ") ? `takes the ${first[1]}` : `reads ${first[0]}`]]);
  if (d.fn.generator) M.stateful = new Map([...M.stateful, [d.name, "is a generator"]]);
};

export type MdIsland = {
  readonly X: MdCtx; readonly value: Map<string, Ty | null>; readonly refInner: Map<string, Ty>; readonly out: Map<string, MdCellRec>;
};

// ch.err / ch.unsupported in the hook: after what the registry reported so far
export const mdHookErr = () => (R: IxReg, H: Mut<MdHookLog>, at: AstNode, rule: string, msg: string): void => {
  H.out = [...H.out, ...R.drain(), { start: at.start, end: at.end, rule, msg }];
};

// the problems of the island: what island.ss.ts finds, and island cells that are async, generators or not ok
export const mdIslandProblems = (mdHookErr, islandWith) => (S: MdIsland, R: IxReg, H: Mut<MdHookLog>, e: AstNode, sp: MdSpec): boolean => {
  const cells = S.X.defs.map((d) => ({ name: d.name, params: d.fn.params.map((p) => (p.type === "Identifier" ? p.name : "")), refCell: S.refInner.has(d.name) }));
  const isl = islandWith(new Set(S.X.R.capabilities.keys()))(cells, { inputs: sp.inputs, refs: sp.refs, outputs: sp.outputs });
  let bad = false;
  for (const p of isl.problems) { mdHookErr(R, H, e, "compile-island", p.msg); bad = true; }
  for (const n of isl.order) {
    const d = S.X.byName.get(n), r = S.out.get(n);
    if (d === undefined || r === undefined) continue;
    if (d.fn.async || d.fn.generator) { mdHookErr(R, H, e, "compile-island", `island cell ${n} is ${d.fn.async ? "async" : "a generator"}; an island runs synchronously`); bad = true; }
    if (r.status !== "ok" || r.errors.length) { mdHookErr(R, H, e, "compile-island", `island cell ${n} is ${r.status === "ok" ? "rejected" : r.status}`); bad = true; }
  }
  return bad;
};

// one side of the call: each named cell's value type, which must cross to a worker
export const mdIslandSide = (mdHookErr, uncloneableWith, show) => (S: MdIsland, R: IxReg, H: Mut<MdHookLog>, e: AstNode, names: string[]): { t: Rec; bad: boolean } => {
  const props: Mut<Map<string, Prop>> = new Map();
  let bad = false;
  for (const n of names) {
    const t = S.value.get(n);
    if (t === null || t === undefined) { if (S.X.cellNames.has(n)) mdHookErr(R, H, e, "compile-island", `${n} has no usable type`); bad = true; continue; }
    const why = uncloneableWith(S.X.R.ops)(t);
    if (why) { mdHookErr(R, H, e, "compile-boundary", `${n}: ${show(t)} cannot cross to a worker (${why})`); bad = true; }
    props.set(n, { t, opt: false });
  }
  return { t: { k: "rec", props: props }, bad };
};

// the hook: asks for the options' type first when the call has options, then types the call
export const mdCompileType = (mdSpecOf, mdHookErr, mdIslandProblems, mdIslandSide, named, show, ERR) => (S: MdIsland, R: IxReg, e: AstNode, options: Ty | null): MdCompiled => {
  const H: Mut<MdHookLog> = { out: [] };
  const sp = mdSpecOf(e);
  if (sp === null) {
    H.out = [...H.out, ...R.drain(), { start: e.start, end: e.end, rule: "unsupported", msg: "compile takes { inputs, refs, outputs, options } with literal arrays of cell names" }];
    return { res: { k: "done", t: ERR }, out: H.out };
  }
  const at = sp.options;
  if (at !== null && options === null) return { res: { k: "options", at }, out: [] };
  if (at !== null && options !== null && options.k !== "err" && !R.sub(options, { k: "rec", props: new Map([["runtime", { t: named("Pool"), opt: true }]]) }))
    mdHookErr(R, H, at, "compile-options", `${show(options)} is not assignable to { runtime?: Pool }`);
  const bad0 = mdIslandProblems(S, R, H, e, sp);
  const args = mdIslandSide(S, R, H, e, sp.inputs), refs = mdIslandSide(S, R, H, e, sp.refs), res = mdIslandSide(S, R, H, e, sp.outputs);
  const t: Ty = bad0 || args.bad || refs.bad || res.bad ? ERR : { k: "fn", tps: [], ps: [{ n: "args", t: args.t, opt: false }], ret: named("Promise", res.t) };
  return { res: { k: "done", t }, out: [...H.out, ...R.drain()] };
};

export const mdValueType = (isNamed, ERR) => (fn: FnNode, fnT: Ty): { ret: Ty; gen: boolean; gap: string | null } => {
  let ret: Ty = fnT.k === "fn" ? fnT.ret : ERR;
  // core.ts reads args[0] unguarded
  if (fn.async && ret.k === "named" && isNamed(ret, "Promise")) { const a = ret.args[0]; if (a === undefined) return { ret, gen: false, gap: "Promise with no type argument" }; ret = a; }
  if (!fn.generator || ret.k !== "named" || !isNamed(ret, "Generator")) return { ret, gen: false, gap: null };
  const y = ret.args[0];
  return y === undefined ? { ret, gen: false, gap: "Generator with no type argument" } : { ret: y, gen: true, gap: null };
};

// core.ts fnKept: a cell fed a function from another language may not keep a value that may hold one
export const mdKept = (ixMayHoldFn, show) => (R: IxRegCore, name: string, fedBy: string | null, line: number, what: string, t: Ty, then: string): MdErr[] =>
  fedBy !== null && ixMayHoldFn(R, t) ? [{ rule: "action-capture", line, msg: `${what} ${show(t)}, which may be or hold a function from another language (${name} ${fedBy}); ${then}` }] : [];

// a state cell's content: not undefined, no State or StateCell in it, no function from another language
export const mdStateRules = (mdKept, admitsUndefinedWith, holdsWith, show) => (R: IxReg, X: MdCtx, name: string, fedBy: string | null, line: number, inner: Ty): MdErr[] => {
  const nested = holdsWith(X.R.ops)(inner, ["State", "StateCell"]);
  return [
    ...(admitsUndefinedWith(X.R.ops)(inner) ? [{ rule: "state-undefined", line, msg: `a state cell's value may not be undefined (its type is ${show(inner)}): Observable skips an undefined value, so the cell would never have one. Use null` }] : []),
    ...(nested ? [{ rule: "state-in-state", line, msg: `a state cell holds ${show(inner)}, which contains ${nested}; a state cell's content may not contain a State or StateCell` }] : []),
    ...mdKept(R, name, fedBy, line, "a state cell holds", inner, "an action that reads the state cell could call it"),
  ];
};

// a value with a callable then (holes7): the runtime, and an async cell's own return, call then and give the cells that
// take the value what then passes on, not this type
export const mdThenable = () => (t: Ty): boolean => {
  const todo: Mut<Ty[]> = [t];
  for (let u = todo.pop(); u !== undefined; u = todo.pop()) {
    if (u.k === "union") todo.push(...u.ts);
    else if (u.k === "rec" && u.props.get("then")?.t.k === "fn") return true;
  }
  return false;
};

// a9 (2026-11-23), B-3: the runtime awaits a cell's value (a sync cell's promise, a promise a generator yields or a
// state cell holds), so the cells that take it get what it settles to: every Promise level is taken off, in each
// member of a union. A promise inside a record is not awaited and keeps its type; State<T> and Events<T> keep theirs
export const mdSettled = (ixUm, union, isNamed) => (R: IxRegCore, t: Ty): Ty => {
  const isP = (m: Ty): boolean => m.k === "named" && isNamed(m, "Promise") && m.args[0] !== undefined;
  const go = (x: Ty, d: number): Ty => (d > 16 || !ixUm(R, x).some(isP) ? x : union(ixUm(R, x).map((m) => (isP(m) && m.k === "named" ? go(m.args[0] ?? m, d + 1) : m))));
  return go(t, 0);
};

// promises (y1, 2026-11-24): the value type, before the run time awaits it, names a promise (where the run time lets one
// stay), or is not known (an error)
export type MdValueOut = { readonly errors: MdErr[]; readonly value: Ty; readonly events: Ty | null; readonly ref: Ty | null; readonly listener: boolean; readonly gap: string | null; readonly promises: boolean };

// the rules in core.ts's order: events, state cell, iterator, listener; and what the cell gives the cells after it
export const mdValueRules = (mdValueType, mdSettled, mdKept, mdStateRules, owIter, owStripMut, holdsWith, isNamed, show, mdThenable) => (R: IxReg, X: MdCtx, d: MdDef, fnT: Ty, fedBy: string | null): MdValueOut => {
  const v = mdValueType(d.fn, fnT);
  const line = X.line(d.fn.start), sync = d.fn.generator && !d.fn.async;
  // S4: a cell's value, each value it yields and a state's value are the read-only view (frozen at run time)
  let ret = owStripMut(R, v.ret);
  const events = v.gen && sync ? ret : null;
  const errs = sync ? mdKept(R, d.name, fedBy, line, "an events cell yields", ret, "a listener's action would receive it") : [];
  const sc = ret.k === "named" && isNamed(ret, "StateCell");
  const inner = ret.k === "named" && sc ? ret.args[0] : undefined;
  if (sc && inner === undefined) return { errors: errs, value: ret, events, ref: null, listener: false, gap: "StateCell with no type argument", promises: true };
  const stateErrs = inner === undefined ? [] : mdStateRules(R, X, d.name, fedBy, line, inner);
  if (inner !== undefined) ret = inner;
  const it = owIter(R, ret);
  const iter = it === null ? [] : it === "FetchResponse" ? [{ rule: "iterator-cell", line, msg: `value ${show(ret)} holds a FetchResponse: a response's body can be read once, so the cells that take it would find it used up, depending on the order they run in; read the body in this cell and give the data (const data = async (fetch: Fetch) => (await fetch(url)).json())` }] : [{ rule: "iterator-cell", line, msg: `value ${show(ret)} may hold an iterator (${it}); every cell that takes it would use up the same one, so what each computes would depend on the order the cells run in. Make it an array` }];
  const then = mdThenable(ret) ? [{ rule: "type", line, msg: `value ${show(ret)} has a callable then: the runtime would call it and give the cells that take it what then passes on, not this type. Rename then` }] : [];
  const isL = (t: Ty): boolean => t.k === "named" && isNamed(t, "Listener");
  const listener = isL(ret) || (ret.k === "union" && ret.ts.every(isL));
  const held = listener ? null : holdsWith(X.R.ops)(ret, ["Listener"]);
  const place = held ? [{ rule: "listener-placement", line, msg: `value ${show(ret)} holds a Listener; a listener is only the whole value of a cell` }] : [];
  return { errors: [...errs, ...stateErrs, ...iter, ...then, ...place], value: mdSettled(R, ret), events, ref: inner ?? null, listener, gap: v.gap, promises: ret.k === "err" || holdsWith(X.R.ops)(ret, ["Promise"]) !== null };
};

// ixCheckFn on a log the injection already wrote to: the globals bound in scope 0, then the cell's function
export const mdInferFn = (ixFoldFacts) => (K: IxK, C: IxCtls, X: MdCtx, fn: FnNode, injected: Ty[]): { fnT: Ty; facts: IxFacts } => {
  const T: IxTypes = new Map(), V: IxVars = new Map(), W: IxFlows = new Map([[0, new Map()]]);
  for (const g of X.R.globals) {
    C.nextId += 1;
    V.set(`0:${g.name}`, { id: C.nextId, scope: 0, name: g.name, t: g.t, kind: g.kind, nid: -1, fi: -1, fnNode: -1, mutOwned: false, assigned: false, cellParam: false, checked: true, lazy: { k: "none" } });
  }
  const fnT = K.fnExpr(K, T, V, W, C, null, fn, null, injected);
  return { fnT, facts: ixFoldFacts(T, V, C.facts) };
};

// ownership and actionEscapes, then the captures by binding (opaqueCaptures) and memo's rules, over one index of the cell's tree
export const mdAfterInfer = (owIndex, owCheckIn, owOpaqueCaptures, mdMemoErrs, ixDrain, ixPush, captureMessage) => (K: IxK, C: IxCtls, X: MdCtx, F: IxFacts, fn: FnNode, tainted: Map<string, string>, skip: Set<number>): string | null => {
  const T = owIndex(F, fn);
  const own = owCheckIn(K.reg, F, T);
  ixDrain(K, C);
  for (const d of [...own.diags, ...own.actions]) C.diags = ixPush(C.diags, d);
  for (const u of own.unsup) C.unsup = ixPush(C.unsup, u);
  const opaque = owOpaqueCaptures({ T, F, R: K.reg }, tainted, skip);
  ixDrain(K, C);
  for (const c of opaque) C.diags = ixPush(C.diags, { start: c.at.start, end: c.at.end, rule: "action-capture", msg: captureMessage(c) });
  for (const d of mdMemoErrs(K, X, { T, F, R: K.reg }, tainted)) C.diags = ixPush(C.diags, d);
  ixDrain(K, C);
  return T.other;
};

// what a parameter of memo's function may not hold (no freeze reaches these, or they are state), and what its result may
// not hold (every call would share it)
export const MEMO_PARAM_BAD = () => ["Mut", "Borrowed", "State", "StateCell", "Action", "Events", "Listener", "Promise", "Generator", "AsyncGenerator", "Pool", "Compile", "Elem", "FetchResponse", "URLSearchParams", "DataView"];

// memo(f) (S2.13): each parameter of f takes data, and f's result holds no shared state
export const mdMemoSig = (holdsWith, ixFnParts, show, owIter, MEMO_PARAM_BAD, MEMO_RESULT_BAD) => (K: IxK, X: MdCtx, O: OwCtx, f: AstNode): IxDiag[] => {
  const t = O.F.types.get(f.nid), parts = ixFnParts(f), holds = holdsWith(X.R.ops);
  if (t === undefined || t.k !== "fn" || parts === null || parts.async || parts.generator) return [];
  const out: Mut<IxDiag[]> = [];
  const err = (at: AstNode, msg: string) => out.push({ start: at.start, end: at.end, rule: "memo-pure", msg });
  t.ps.forEach((p, i) => {
    const at = parts.params[i] ?? f, w = holds(p.t, MEMO_PARAM_BAD);
    if (K.reg.mayHide(p.t)) err(at, `a parameter of memo's function is ${show(p.t)}, which may be or hold a function: a function may read a capability, so the stored result could be stale; take data`);
    else if (w === "Mut") err(at, `a parameter of memo's function is ${show(p.t)}: memo freezes its arguments, so take it under its plain type`);
    else if (w !== null) err(at, `a parameter of memo's function holds a ${w}, which memo cannot freeze or which is state; take data`);
  });
  const r = holds(t.ret, MEMO_RESULT_BAD);
  if (r !== null) err(f, `memo's function returns a value that holds a ${r}, which every call would share`);
  const it = r === null ? owIter(K.reg, t.ret) : null;
  if (it) err(f, `memo's function returns a value that may hold an iterator (${it}), which every call would share and reading uses up; return an array`);
  return out;
};

// memo(f) (S2.13): from outside itself f uses only what an action body may (owCapturesIn), no capability, and no
// state handle or action; a let or a Mut it captures is R-K's ([let-capture], [mut-capture])
export const mdMemoUses = (owCapturesIn, owFree, owIdsAndComps, holdsWith, isNamed) => (X: MdCtx, O: OwCtx, tainted: Map<string, string>, f: AstNode): IxDiag[] => {
  const err = (at: AstNode, msg: string): IxDiag => ({ start: at.start, end: at.end, rule: "memo-pure", msg });
  const tail = "; a memoised function may use from outside itself only inputs that hold no state and the consts and functions made from them, since a stored result would not see a change: pass the value as an argument";
  const rk = (b: IxBinding) => b.kind === "let" || b.mutOwned || isNamed(b.t, "Mut");
  const out: Mut<IxDiag[]> = [], seen: Mut<Set<string>> = new Set();
  for (const c of owCapturesIn(O, tainted, new Set(), [f])) {
    const b = O.F.bindings.get(O.F.bindingOf.get(c.at.nid) ?? -1);
    seen.add(c.name);
    const why = c.opaque ? c.why.replace("after the action is made", "after memo's function is made") : c.why.startsWith("capability ") ? "is a capability" : `depends on state (${c.why})`;
    if (b === undefined || !rk(b)) out.push(err(c.at, `${c.name} ${why}${tail}`));
  }
  const holds = holdsWith(X.R.ops);
  for (const b of new Set(owFree(O, { ...owIdsAndComps(O), tainted }, [f]))) {
    if (seen.has(b.name)) continue;
    seen.add(b.name);
    const w = b.cellParam && X.R.capabilities.has(b.name) ? `the capability ${b.name}` : holds(b.t, ["State", "StateCell", "Action", "Events", "Listener"]);
    if (w !== null) out.push(err(f, `memo's function uses ${b.name}, which is or holds ${w.startsWith("the ") ? w : (w === "Action" || w === "Events" ? "an " : "a ") + w}: a call that gives a stored result would skip what it does${tail}`));
  }
  return out;
};

// each memo(f) of the cell: the prelude's memo (the call's fact), f a function literal
export const mdMemoErrs = (mdMemoSig, mdMemoUses, isFnNode) => (K: IxK, X: MdCtx, O: OwCtx, tainted: Map<string, string>): IxDiag[] =>
  O.T.all.flatMap((n) => {
    if (n.type !== "CallExpression" || O.F.calls.get(n.nid)?.prelude !== "memo") return [];
    const f = n.arguments[0];
    return f !== undefined && isFnNode(f) ? [...mdMemoSig(K, X, O, f), ...mdMemoUses(X, O, tainted, f)] : [];
  });

// the try: a throw keeps what the log holds and becomes an unsupported item at the cell's function
export const mdRunChecks = (mdInferFn, mdAfterInfer, ixDrain, ixUnsup, ERR) => (K: IxK, C: IxCtls, X: MdCtx, d: MdDef, injected: Ty[], tainted: Map<string, string>, skip: Set<number>): MdRun => {
  let fnT: Ty = ERR, facts: IxFacts | null = null, gap: string | null = null;
  try {
    const r = mdInferFn(K, C, X, d.fn, injected);
    fnT = r.fnT;
    facts = r.facts;
    gap = mdAfterInfer(K, C, X, r.facts, d.fn, tainted, skip);
  } catch (e) {
    ixDrain(K, C);
    const msg = messageOf(e);
    ixUnsup(K, C, d.fn, `checker crashed: ${msg}`);
    return { fnT, facts, crash: msg, gap: C.gap };
  }
  ixDrain(K, C);
  return { fnT, facts, crash: null, gap: C.gap ?? gap };
};

// core.ts dedupe: the first of each line, rule and message
export const mdDedupe = () => (es: MdErr[]): MdErr[] => {
  const seen: Mut<Set<string>> = new Set();
  const out: Mut<MdErr[]> = [];
  for (const e of es) {
    const k = `${e.line}:${e.rule}:${e.msg}`;
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(e);
  }
  return out;
};

// t1 (2026-11-24), F-1/F-2: a cell named after a capability or a global a compiled cell takes by name; F-3: a $ in a
// cell name (runCells names a state cell's handle x$ref), and a binding h in a cell with JSX (JSX lowers to h(...))
export const RESERVED_INPUT_MSG = () => (name: string): string =>
  `${name} is reserved as a cell name: a compiled cell takes ${name} (a capability or a global) by that name from outside the module, so a reader of a cell named ${name} gets that and not the cell; give the cell another name`;

export const PROTO_MEMBER_MSG = () => (name: string, opt: boolean): string => opt
  ? `${name} may not be a member's name: it is a member of Object.prototype or one a conversion calls (a template string, +, ==, String(), JSON.stringify, join, sort and await call toString, valueOf, toJSON and then), so a conversion would run a value's own ${name} or read the inherited one; give the member another name`
  : `__proto__ may not be declared as a member: it is the object's prototype, not a member; give the member another name`;

// w1 (2026-11-24, F-4): each name bound under n (a declarator, a function's name or parameters, a catch parameter) that
// JavaScript reads as a keyword although the parser bound it (the TS plugin takes const this = …): parsed alone as an
// expression, the name is not an Identifier
export const mdKeywordNames = (parseTree, childrenOf) => (n: AstNode): Identifier[] => {
  const out: Mut<Identifier[]> = [];
  const keyword = (name: string): boolean => {
    const p = parseTree(`(${name});`, false), s = p.ok && p.ast.program.type === "Program" ? p.ast.program.body[0] : undefined;
    return s === undefined || s.type !== "ExpressionStatement" || s.expression.type !== "Identifier";
  };
  const pat = (p: AstNode | null): void => {
    if (p === null) return;
    if (p.type === "Identifier") { if (keyword(p.name)) out.push(p); }
    else if (p.type === "ObjectPattern") { for (const x of p.properties) pat(x.type === "Property" ? x.value : x.type === "RestElement" ? x.argument : null); }
    else if (p.type === "ArrayPattern") { for (const x of p.elements) pat(x); }
    else if (p.type === "AssignmentPattern") pat(p.left);
    else if (p.type === "RestElement") pat(p.argument);
  };
  const walk = (x: AstNode): void => {
    if (x.type === "VariableDeclarator") pat(x.id);
    if (x.type === "CatchClause") pat(x.param);
    if (x.type === "FunctionDeclaration" || x.type === "FunctionExpression" || x.type === "ArrowFunctionExpression") { pat(x.id); for (const q of x.params) pat(q); }
    for (const c of childrenOf(x)) walk(c.node);
  };
  walk(n);
  return out;
};

export const mdSyntax = (syntaxBans, mdDiag, ixUnsup, reservedCellName, RESERVED_CELL_MSG, RESERVED_PRELUDE_MSG, reservedText, RESERVED_TEXT_MSG, RESERVED_INPUT_MSG, RESERVED_DOLLAR_MSG, RESERVED_JSX_H_MSG, mdJsxH, mdProtoMembers, PROTO_MEMBER_MSG, mdKeywordNames, KEYWORD_NAME_MSG) => (K: IxK, C: IxCtls, X: MdCtx, L: MdL, d: MdDef): void => {
  for (const s of syntaxBans(d.fn)) {
    if (s.unsup) ixUnsup(K, C, s.at, s.msg);
    else mdDiag(X, L, s.at, s.rule, s.msg);
  }
  if (reservedCellName(d.name)) mdDiag(X, L, d.fn, "reserved-name", RESERVED_CELL_MSG(d.name));
  else if (X.bound.includes(d.name)) mdDiag(X, L, d.fn, "reserved-name", RESERVED_PRELUDE_MSG(d.name));
  else if (X.R.inputs.has(d.name)) mdDiag(X, L, d.fn, "reserved-name", RESERVED_INPUT_MSG(d.name));
  else if (d.name.includes("$")) mdDiag(X, L, d.fn, "reserved-name", RESERVED_DOLLAR_MSG(d.name));
  const h = mdJsxH(d.stmt);
  if (h !== null) mdDiag(X, L, h, "reserved-name", RESERVED_JSX_H_MSG);
  for (const p of mdProtoMembers(d.stmt, X.R.proto)) mdDiag(X, L, p.at, "banned-member", PROTO_MEMBER_MSG(p.name, p.opt));
  for (const k of mdKeywordNames(d.stmt)) mdDiag(X, L, k, "reserved-name", KEYWORD_NAME_MSG(k.name));
  const m = reservedText(X.src.slice(d.stmt.start, d.stmt.end));
  if (m !== null) mdDiag(X, L, d.fn, "reserved-name", RESERVED_TEXT_MSG(d.name, m));
};

// F-3: the first binding named h (a declarator, parameter, function name or catch parameter, in any pattern) of a
// statement that holds JSX, or null
export const mdJsxH = (kidsOf) => (n: AstNode): AstNode | null => {
  const st: Mut<{ jsx: boolean; at: AstNode | null }> = { jsx: false, at: null };
  const pat = (p: AstNode | null): void => {
    if (p === null || st.at !== null) return;
    if (p.type === "Identifier") { if (p.name === "h") st.at = p; }
    else if (p.type === "ArrayPattern") for (const x of p.elements) pat(x);
    else if (p.type === "ObjectPattern") for (const x of p.properties) pat(x.type === "RestElement" ? x.argument : x.type === "Property" ? x.value : null);
    else if (p.type === "AssignmentPattern") pat(p.left);
    else if (p.type === "RestElement") pat(p.argument);
  };
  const walk = (x: AstNode): void => {
    if (x.type === "JSXElement" || x.type === "JSXFragment") st.jsx = true;
    if (x.type === "VariableDeclarator") pat(x.id);
    if (x.type === "ArrowFunctionExpression" || x.type === "FunctionExpression" || x.type === "FunctionDeclaration") { pat(x.id); for (const p of x.params) pat(p); }
    if (x.type === "CatchClause") pat(x.param);
    for (const k of kidsOf(x)) walk(k);
  };
  walk(n);
  return st.jsx ? st.at : null;
};

// B-1: each member signature under n (in type positions too) named __proto__ or, w1 (2026-11-24, Step 2), named in
// proto (Object.prototype's names and the conversion members, core.ts PROTO_MEMBERS), optional or not; and each key of
// an object literal named in proto (__proto__ as a key is ix-expr.ss.ts ixProtoKey's)
export const mdProtoMembers = (childrenOf) => (n: AstNode, proto: Set<string>): { at: AstNode; name: string; opt: boolean }[] => {
  const out: Mut<{ at: AstNode; name: string; opt: boolean }[]> = [];
  const nameOf = (k: AstNode): string | null => (k.type === "Identifier" ? k.name : k.type === "Literal" && typeof k.value === "string" ? k.value : null);
  const walk = (x: AstNode): void => {
    if (x.type === "TSPropertySignature" || x.type === "TSMethodSignature") {
      const name = x.computed === true ? null : nameOf(x.key);
      if (name !== null && (name === "__proto__" || proto.has(name))) out.push({ at: x, name, opt: name !== "__proto__" });
    }
    if (x.type === "ObjectExpression") for (const p of x.properties) if (p.type === "Property" && !p.computed) { const name = nameOf(p.key); if (name !== null && name !== "__proto__" && proto.has(name)) out.push({ at: p, name, opt: true }); }
    for (const k of childrenOf(x)) walk(k.node);
  };
  walk(n);
  return out;
};

// the compile hook of this cell's check: the module's tables as they are now, and this cell's errors so far
export const mdHookOf = (mdCompileType) => (ix: IxReg, X: MdCtx, value: Map<string, Ty | null>, refInner: Map<string, Ty>, out: Map<string, MdCellRec>, me: MdCellRec) =>
  (e: AstNode, options: Ty | null): MdCompiled => mdCompileType({ X, value, refInner, out: new Map([...out, [me.name, me]]) }, ix, e, options);

// the record: the errors written straight to it, then the Checker's, each list deduplicated; the value rules after
export const mdRecord = (mdDedupe) => (X: MdCtx, L: MdL, rec: MdCellRec, ch: IxDiag[], chUnsup: IxDiag[]): MdCellRec => ({
  ...rec,
  errors: mdDedupe([...L.errors, ...ch.map((x) => ({ rule: x.rule, line: X.line(x.start), msg: x.msg }))]),
  unsupported: mdDedupe(chUnsup.map((x) => ({ rule: "unsupported", line: X.line(x.start), msg: x.msg }))),
  blockedBy: L.blockedBy, ch, chUnsup,
});

// what the cell gives the cells after it: its value type when usable, its inner types, and whether it is a listener
export const mdKeep = (hasErrWith, show) => (X: MdCtx, M: MdMod, d: MdDef, rec: MdCellRec, v: MdValueOut): MdCellRec => {
  // [mut-cell] on a value is a backstop: a Mut reaches a value only past a rule that already reported in the cell
  const errors = [...rec.errors, ...v.errors.filter((e) => e.rule !== "mut-cell" || rec.errors.length === 0)];
  const usable = !hasErrWith(X.R.ops)(v.value) && (rec.unsupported.length === 0 || d.fn.returnType !== null);
  M.value = new Map([...M.value, [d.name, usable ? v.value : null]]);
  const ev = v.events;
  if (ev !== null) M.eventsInner = new Map([...M.eventsInner, [d.name, ev]]);
  const ref = v.ref;
  if (ref !== null) {
    M.refInner = new Map([...M.refInner, [d.name, ref]]);
    M.stateful = new Map([...M.stateful, [d.name, "is a state cell"]]);
  }
  if (v.listener) M.listeners = new Set([...M.listeners, d.name]);
  const status: MdStatus = errors.length ? "rejected" : rec.unsupported.length ? "unsupported" : rec.blockedBy.length ? "blocked" : "ok";
  return { ...rec, errors, value: show(v.value), status, promises: v.promises };
};

// one cell's check; the first thing the port does not implement, or null
export const mdCell = (ixKnot, ixFreshCtl, ixDrain, mdSyntax, mdInject, mdTainted, mdFedBy, mdMarkStateful, owTaintCaptures, captureMessage, mdDiag, mdHookOf, mdRunChecks, ixOut, mdRecord, mdValueRules, mdKeep) => (X: MdCtx, M: MdMod, d: MdDef): string | null => {
  const rec = M.out.get(d.name);
  if (M.value.has(d.name) || rec === undefined) return null;
  const R = X.R.cell(d.fn.start);
  const K: IxK = ixKnot(R.ix, X.src, X.cellNames, X.R.allowed, X.probe);
  const C: IxCtls = { ...ixFreshCtl(X.count) };
  C.nextFlow = 1;
  const L: MdL = { errors: rec.errors, ch: [], chUnsup: [], blockedBy: [] };
  mdSyntax(K, C, X, L, d);
  const injected = mdInject(K, C, X, M, L, d);
  const tainted = mdTainted(X, M, d), fedBy = mdFedBy(M, d);
  mdMarkStateful(M, d, tainted, fedBy);
  const byName = owTaintCaptures(d.fn, tainted);
  for (const cap of byName) mdDiag(X, L, cap.at, "action-capture", captureMessage(cap));
  ixDrain(K, C);
  const hook = mdHookOf(R.ix, X, M.value, M.refInner, M.out, { ...rec, errors: L.errors });
  const K2: IxK = ixKnot(R.withHook(hook), X.src, X.cellNames, X.R.allowed, X.probe);
  const run = mdRunChecks(K2, C, X, d, injected, tainted, new Set(byName.map((c) => c.at.nid)));
  const r1 = mdRecord(X, L, rec, ixOut(C.diags), ixOut(C.unsup));
  const v = mdValueRules(K2.reg, X, d, run.fnT, fedBy);
  // what the registry reports from here on reaches the Checker but not the record (core.ts copies the lists above)
  ixDrain(K2, C);
  if (M.probe === null) M.probe = C.probe;
  M.out = new Map([...M.out, [d.name, { ...mdKeep(X, M, d, r1, v), ch: ixOut(C.diags), chUnsup: ixOut(C.unsup), casts: C.casts.toSorted((a, b) => a[0] - b[0]).map((x) => x[1]), holes: C.holes.toSorted((a, b) => a[0] - b[0]).map((x) => x[1]) }]]);
  return run.gap ?? v.gap;
};

export const mdBinds = () => {
  function binds(p: AstNode | null, name: string): boolean {
    if (p === null) return false;
    if (p.type === "Identifier") return p.name === name;
    if (p.type === "ObjectPattern") {
      for (const x of p.properties) if (binds(x.type === "RestElement" ? x.argument : x.type === "Property" ? x.value : null, name)) return true;
      return false;
    }
    if (p.type === "ArrayPattern") { for (const x of p.elements) if (binds(x, name)) return true; return false; }
    if (p.type === "AssignmentPattern") return binds(p.left, name);
    return p.type === "RestElement" && binds(p.argument, name);
  }
  return binds;
};

// a statement that declares name
export const mdDeclares = (mdBinds) => (st: AstNode, name: string): boolean => {
  if (st.type === "VariableDeclaration") return st.declarations.some((d) => d.type === "VariableDeclarator" && mdBinds(d.id, name));
  if (st.type === "FunctionDeclaration" || st.type === "ClassDeclaration") return st.id.type === "Identifier" && st.id.name === name;
  return false;
};

// a node under which name is bound again, so no use of it there is free
export const mdRebinds = (mdBinds, mdDeclares) => (n: AstNode, name: string): boolean => {
  const decl = (x: AstNode | null): boolean => x !== null && x.type === "VariableDeclaration" && mdDeclares(x, name);
  switch (n.type) {
    case "ArrowFunctionExpression": case "FunctionDeclaration": return n.params.some((p) => mdBinds(p, name));
    case "FunctionExpression": return n.params.some((p) => mdBinds(p, name)) || (n.id !== null && n.id.type === "Identifier" && n.id.name === name);
    case "BlockStatement": case "StaticBlock": return n.body.some((s) => mdDeclares(s, name));
    case "SwitchStatement": return n.cases.some((c) => c.type === "SwitchCase" && c.consequent.some((s) => mdDeclares(s, name)));
    case "CatchClause": return mdBinds(n.param, name);
    case "ForStatement": return decl(n.init);
    case "ForInStatement": case "ForOfStatement": return decl(n.left);
    default: return false;
  }
};

// facts.ts preludeCalls: the calls of the bare name the cell does not bind, as nids
export const mdPreludeCalls = (mdRebinds, kidsOf) => (fn: AstNode, name: string): Set<number> => {
  const out: Mut<Set<number>> = new Set();
  const todo: Mut<AstNode[]> = [fn];
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    if (mdRebinds(n, name)) continue;
    if (n.type === "CallExpression" && n.callee.type === "Identifier" && n.callee.name === name) out.add(n.nid);
    for (const k of kidsOf(n).toReversed()) todo.push(k);
  }
  return out;
};

// a returned expression that is a state(...) call, through parentheses and casts
export const mdIsRefCall = () => (calls: Set<number>, e0: AstNode | null): boolean => {
  let e = e0;
  while (e !== null && (e.type === "ParenthesizedExpression" || e.type === "TSAsExpression")) e = e.expression;
  return e !== null && calls.has(e.nid);
};

export const mdReturnsRef = (mdPreludeCalls, mdIsRefCall, mdRefName) => (fn: FnNode): boolean => {
  const rt = fn.returnType !== null && fn.returnType.type === "TSTypeAnnotation" ? fn.returnType.typeAnnotation : null;
  if (mdRefName(rt) === "StateCell") return true;
  const calls = mdPreludeCalls(fn, "state");
  const b = fn.body;
  return b.type === "BlockStatement" ? b.body.some((s) => s.type === "ReturnStatement" && mdIsRefCall(calls, s.argument)) : mdIsRefCall(calls, b);
};

// factsOf with core.ts's boundary shapes
export const mdFactsOf = (mdReturnsRef, mdCompileCalls, mdSpecOf, mdAnn, mdRefName) => (name: string, d: MdDef, bounds: Map<string, MdBoundary> | null, casts: TypeShape[], holes: boolean[], promises: boolean | null): MdInfo => {
  const compiles = mdCompileCalls(d.fn).flatMap((c) => { const sp = mdSpecOf(c); return sp === null ? [] : [{ inputs: sp.inputs, refs: sp.refs, outputs: sp.outputs }]; });
  const params = d.fn.params.map((p) => {
    const ref = mdRefName(mdAnn(p)), pname = p.type === "Identifier" ? p.name : "";
    return { name: pname, refTyped: ref === "State", eventsTyped: ref === "Events", boundary: bounds?.get(pname) ?? null };
  });
  return { name, span: [d.stmt.start, d.stmt.end], params, returnsRef: mdReturnsRef(d.fn), generator: d.fn.generator, compiles, casts, holes, strict: promises === null ? null : !promises };
};

export const mdShownNames = () => (dups: MdDup[], out: Map<string, MdCellRec>, cellNames: Set<string>): Map<string, string> => {
  const shown: Mut<Map<string, string>> = new Map();
  for (const d of dups) {
    if (!out.has(d.ph)) continue;
    let k = 2;
    while (cellNames.has(`${d.name} (${k})`) || [...shown.values()].includes(`${d.name} (${k})`)) k++;
    shown.set(d.ph, `${d.name} (${k})`);
  }
  return shown;
};

// the text with each stand-in replaced: by the name its cell shows, then by the name it stands for
export const mdUnPh = () => (shown: Map<string, string>, dups: MdDup[], x0: string): string => {
  let x = x0;
  for (const [ph, n] of shown) x = x.split(ph).join(n);
  for (const d of dups) x = x.split(d.ph).join(d.name);
  return x;
};

// duplicate-cell for every name declared again: first in that cell's errors, or of the module when it is no cell
export const mdDupErrs = () => (dups: MdDup[], defs: MdDef[], out: Map<string, MdCellRec>, line: (pos: number) => number): { module: MdErr[]; cell: Map<string, MdErr> } => {
  const module: Mut<MdErr[]> = [];
  const cell: Mut<Map<string, MdErr>> = new Map();
  for (const d of dups) {
    const first = defs.find((c) => c.name === d.name);
    const at = first === undefined ? null : out.get(first.name)?.line ?? null;
    const msg = `${d.name} is already defined${at ? ` at line ${at}` : ""}`;
    const mine = out.get(d.ph);
    if (mine === undefined) module.push({ rule: "duplicate-cell", line: line(d.pos), msg });
    else cell.set(d.ph, { rule: "duplicate-cell", line: mine.line, msg });
  }
  return { module: module, cell: cell };
};

// the records with the names declared again given back
export const mdRenamed = (mdShownNames, mdUnPh, mdDupErrs) => (X: MdCtx, dups: MdDup[], out: Map<string, MdCellRec>): { module: MdErr[]; out: Map<string, MdCellRec>; shown: Map<string, string> } => {
  const errs = mdDupErrs(dups, X.defs, out, X.line);
  const shown = mdShownNames(dups, out, X.cellNames);
  const un = (x: string): string => mdUnPh(shown, dups, x);
  const fix = (e: MdErr): MdErr => (dups.length ? { ...e, msg: un(e.msg) } : e);
  const renamed = new Map([...out].map(([k, c]): [string, MdCellRec] => {
    const dup = errs.cell.get(k);
    const errors = dup === undefined ? c.errors : [dup, ...c.errors];
    return [k, {
      ...c, name: shown.get(c.name) ?? c.name, status: dup === undefined ? c.status : "rejected", errors: errors.map(fix), unsupported: c.unsupported.map(fix),
      blockedBy: dups.length ? c.blockedBy.map(un) : c.blockedBy, value: dups.length && c.value ? un(c.value) : c.value,
    }];
  }));
  return { module: errs.module, out: renamed, shown };
};

// the module's context for its cells' checks
export const mdContext = (mdAnn, mdRefName) => (R: MdReg, src: string, count: number, line: (pos: number) => number, defs: MdDef[], shellNames: Set<string>, F: MdForeign | null, outside: MdOutside[], probe: IxProbeAsk | null, bound: string[]): MdCtx => ({
  R, src, count, line, defs, shellNames, probe, bound,
  byName: new Map(defs.map((d): [string, MdDef] => [d.name, d])), cellNames: new Set(defs.map((d) => d.name)),
  foreign: new Map((F?.values ?? []).map((v): [string, MdForeignValue] => [v.name, v])),
  outside: new Map(outside.map((o): [string, MdOutside] => [o.name, o])),
  takenAsEvents: new Set(defs.flatMap((d) => d.fn.params.flatMap((p) => (p.type === "Identifier" && mdRefName(mdAnn(p)) === "Events" ? [p.name] : [])))),
});

// checkSources: the module level, the order, every cell in it, the renaming and the facts
export const mdCheckSources = (mdDistinct, mdShellNames, lineAt, mdModuleLevel, mdContext, mdFreshRec, mdOrder, mdCell, mdRenamed, mdFactsOf) => (R: MdReg, S: MdSources): MdResult => {
  const dist = mdDistinct(S.cells, S.tsx);
  const p = dist.parse;
  if (!p.ok) throw new Error(p.message);
  const F = S.foreign !== null && S.foreign !== "" ? R.loadForeign(S.foreign) : null;
  const shellNames = S.shell !== null && S.shell !== "" ? mdShellNames(S.shell) : new Set<string>();
  const line = lineAt(dist.text);
  const ml = mdModuleLevel(R, p.ast, dist.text, S.tsx, F, shellNames, line);
  const X = mdContext(R, dist.text, p.ast.count, line, ml.defs, shellNames, F, S.outside, S.probe, S.bound);
  const lines = new Map(ml.defs.map((d): [string, number] => [d.name, line(d.stmt.start)]));
  const { order, cycles } = mdOrder(ml.defs, X.byName, X.cellNames, lines);
  const fresh = ml.defs.map((d): [string, MdCellRec] => [d.name, mdFreshRec(d, lines.get(d.name) ?? 0, [...(ml.ignores.get(d.name) ?? []), ...(cycles.get(d.name) ?? [])])]);
  const M: MdMod = { value: new Map(), refInner: new Map(), eventsInner: new Map(), listeners: new Set(), stateful: new Map(), fnFed: new Map(), boundaries: new Map(), viewTypes: new Map(), out: new Map(fresh), probe: null };
  let gap: string | null = null;
  for (const d of order) {
    const g = mdCell(X, M, d);
    if (gap === null) gap = g;
  }
  const rn = mdRenamed(X, dist.dups, M.out);
  const cells = ml.defs.flatMap((d) => { const c = rn.out.get(d.name); return c === undefined ? [] : [c]; });
  const module = [...ml.module, ...rn.module];
  const bounds = M.boundaries;
  const facts = ml.defs.map((d) => mdFactsOf(rn.shown.get(d.name) ?? d.name, d, bounds.get(d.name) ?? null, M.out.get(d.name)?.casts ?? [], M.out.get(d.name)?.holes ?? [], M.out.get(d.name)?.promises ?? null));
  return { port: S.name ?? "cells", file: S.tsx ? "cells.tsx" : "cells.ts", ok: module.length === 0 && cells.every((c) => c.status === "ok"), module, cells, facts, gap, probe: M.probe };
};

// mode: keep reports, drop them (peek), or only note that one came (trial)
export type RgCtl = {
  mode: "keep" | "mute" | "loud"; loud: boolean; peeks: number; undo: RgUndo | null; log: RgLog | null;
  strict: boolean; fresh: number; gap: string | null; building: RgNames | null; aliases: RgAlias | null;
};

// the recursive entry points; isAlias, memberOf, subOps and at are the subtype cells bound to these tables (rg-index.ts)
export type RgK = {
  readonly convert: (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, n: AstNode, c: RgCtx) => Ty;
  readonly expand: (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, t: Ty) => Ty;
  readonly ifaceRec: (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, name: string) => Rec;
  readonly sig: (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, params: AstNode[], ret: AstNode | null, tp: AstNode | null, c: RgCtx, flags: Flags | null) => Fn;
  readonly literal: (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, ms: AstNode[], c: RgCtx) => Rec;
  readonly quietGo: (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, K: RgQuietKeys, S: Mut<Set<string>>, x: Ty) => boolean;
  readonly isAlias: (n: string) => boolean;
  readonly memberOf: (s: Ty, t: Ty) => boolean;
  readonly subOps: (s: Ty, t: Ty, seen: Mut<Set<string>>) => boolean;
  readonly at: (ts: Ty[], i: number) => Ty;
};

export const rgFreshCtl = () => (strict: boolean): RgCtl => ({
  mode: "keep", loud: false, peeks: 0, undo: null, log: null, strict, fresh: 0, gap: null, building: null, aliases: null,
});

// onErr / onUnsup as the handler in force sees them
export const rgReport = () => (Q: RgCtls, at: AstNode, rule: string, msg: string): void => {
  if (Q.mode === "keep") Q.log = { r: { start: at.start, end: at.end, line: at.line, rule, msg }, next: Q.log };
  else if (Q.mode === "loud") Q.loud = true;
};

export const rgUnsup = (rgReport, ERR) => (Q: RgCtls, at: AstNode, what: string): Ty => {
  rgReport(Q, at, "unsupported", what);
  return ERR;
};

// the port does not read this node as registry.ts does: the result is NOT COVERED, never a silent answer
export const rgGap = (ERR) => (Q: RgCtls, what: string): Ty => {
  if (Q.gap === null) Q.gap = what;
  return ERR;
};

// the reports since the last call, oldest first
export const rgTake = () => (Q: RgCtls): RgReport[] => {
  const out: Mut<RgReport[]> = [];
  for (let x = Q.log; x !== null; x = x.next) out.unshift(x.r);
  Q.log = null;
  return out;
};

export const rgUndoPush = () => (Q: RgCtls, memoFn: "expand" | "iface", key: string): void => {
  if (Q.peeks > 0) Q.undo = { memo: memoFn, key, n: (Q.undo?.n ?? 0) + 1, next: Q.undo };
};

export const rgPeekOpen = () => (Q: RgCtls): RgPeek => {
  const was: RgPeek = { mode: Q.mode, loud: Q.loud, peeks: Q.peeks, undo: Q.undo };
  Q.mode = "mute";
  Q.peeks += 1;
  return was;
};

// the memo entries the peek added go, the handlers in force before it come back
export const rgPeekClose = () => (E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, was: RgPeek): void => {
  const floor = was.undo?.n ?? 0;
  for (let u = Q.undo; u !== null && u.n > floor; u = u.next) {
    if (u.memo === "expand") E.delete(u.key);
    else I.delete(u.key);
  }
  Q.mode = was.mode;
  Q.loud = was.loud;
  Q.peeks = was.peeks;
  Q.undo = was.undo;
};

// t expanded with nothing kept: its expansion, or null when expanding it reports a problem
export const rgTrial = (rgPeekOpen, rgPeekClose) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, t: Ty): Ty | null => {
  const was = rgPeekOpen(Q);
  Q.mode = "loud";
  Q.loud = false;
  let e: Ty = t;
  try {
    e = G.expand(G, Y, E, I, Q, t);
  } catch (x) {
    rgPeekClose(E, I, Q, was);
    throw x;
  }
  const loud = Q.loud;
  rgPeekClose(E, I, Q, was);
  return loud ? null : e;
};

// RegOps.fresh: one counter per registry, as long-lived as the memo its names reach
export const rgFresh = () => (Q: RgCtls): number => {
  Q.fresh += 1;
  return Q.fresh;
};

export const RG_KEYWORDS = (NUM, STR, BOOL, BIGINT, NULL, UNDEF, VOID, NEVER, UNKNOWN, OBJECT, SYMBOL, ERR) => new Map<string, Ty>([
  ["TSNumberKeyword", NUM], ["TSStringKeyword", STR], ["TSBooleanKeyword", BOOL], ["TSBigIntKeyword", BIGINT],
  ["TSNullKeyword", NULL], ["TSUndefinedKeyword", UNDEF], ["TSVoidKeyword", VOID], ["TSNeverKeyword", NEVER],
  ["TSUnknownKeyword", UNKNOWN], ["TSObjectKeyword", OBJECT], ["TSSymbolKeyword", SYMBOL], ["TSAnyKeyword", ERR],
]);

// an Other node where registry.ts reads a field: a gap
export const rgOther = (rgGap, nodeKind) => (Q: RgCtls, n: AstNode | null): boolean => {
  if (n === null || n.type !== "Other") return false;
  rgGap(Q, `${nodeKind(n)} held as Other`);
  return true;
};

export const rgConvert = (RG_KEYWORDS, rgConvertTs, rgOtherType, rgUnsup) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, n: AstNode, c: RgCtx): Ty => {
  const kw = RG_KEYWORDS.get(n.type);
  if (kw !== undefined) return kw;
  if (n.type === "Other") return rgOtherType(Q, n);
  const t = rgConvertTs(G, Y, E, I, Q, n, c);
  return t !== null ? t : rgUnsup(Q, n, `${n.type.startsWith("TS") ? n.type.slice(2) : n.type} type`);
};

// the cases of convert's switch; null for the default
export const rgConvertTs = (union, arr, rgLitType, rgTuple, rgTypeQuery, rgTypeRef, rgUnsup, rgAnn) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, n: AstNode, c: RgCtx): Ty | null => {
  switch (n.type) {
    case "TSParenthesizedType": return G.convert(G, Y, E, I, Q, n.typeAnnotation, c);
    case "TSLiteralType": return rgLitType(Q, n);
    case "TSUnionType": {
      const ts: Mut<Ty[]> = [];
      for (const x of n.types) ts.push(G.convert(G, Y, E, I, Q, x, c));
      return union(ts);
    }
    case "TSArrayType": return arr(G.convert(G, Y, E, I, Q, n.elementType, c));
    case "TSTupleType": return rgTuple(G, Y, E, I, Q, n, c);
    case "TSTypeOperator": return n.operator === "readonly" ? G.convert(G, Y, E, I, Q, n.typeAnnotation, c) : rgUnsup(Q, n, `type operator ${n.operator}`);
    case "TSFunctionType": return G.sig(G, Y, E, I, Q, n.parameters, rgAnn(Q, n.typeAnnotation), n.typeParameters, c, null);
    case "TSTypeLiteral": return G.literal(G, Y, E, I, Q, n.members, c);
    case "TSTypeQuery": return rgTypeQuery(Q, n, c);
    case "TSTypeReference": return rgTypeRef(G, Y, E, I, Q, n, c);
    default: return null;
  }
};

// an Other node: registry.ts's default message when convert would not read it, else a gap
export const rgOtherType = (RG_CONVERTED, RG_KEYWORDS, nodeKind, rgUnsup, rgGap) => (Q: RgCtls, n: AstNode): Ty => {
  const k = nodeKind(n);
  if (RG_CONVERTED.has(k) || RG_KEYWORDS.has(k)) return rgGap(Q, `convert: ${k} held as Other`);
  return rgUnsup(Q, n, `${k.startsWith("TS") ? k.slice(2) : k} type`);
};

export const rgLitType = (lit, rgUnsup, rgGap, rgOther, ERR) => (Q: RgCtls, n: AstNode): Ty => {
  if (n.type !== "TSLiteralType") return rgGap(Q, "literal type node");
  const l = n.literal;
  if (rgOther(Q, l)) return ERR;
  if (l.type === "Literal" && (typeof l.value === "string" || typeof l.value === "number" || typeof l.value === "boolean")) return lit(l.value);
  if (l.type === "UnaryExpression" && rgOther(Q, l.argument)) return ERR;
  if (l.type === "UnaryExpression" && l.operator === "-" && l.argument.type === "Literal" && typeof l.argument.value === "number") return lit(-l.argument.value);
  if (l.type === "TemplateLiteral" && l.expressions.length === 0) {
    const q = l.quasis[0];
    if (q === undefined || q.type !== "TemplateElement" || q.value.cooked === null) return rgGap(Q, "template literal type");
    return lit(q.value.cooked);
  }
  return rgUnsup(Q, n, "literal type");
};

export const rgTuple = (nodeKind, ERR, rgUnsup) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, n: AstNode, c: RgCtx): Ty => {
  if (n.type !== "TSTupleType") return ERR;
  const els: Mut<Ty[]> = [];
  for (const e of n.elementTypes) {
    const k = nodeKind(e);
    if (k === "TSNamedTupleMember" || k === "TSOptionalType" || k === "TSRestType") return rgUnsup(Q, e, k);
    els.push(G.convert(G, Y, E, I, Q, e, c));
  }
  return { k: "tup", els: els };
};

export const rgTypeQuery = (rgUnsup, rgOther, ERR) => (Q: RgCtls, n: AstNode, c: RgCtx): Ty => {
  if (n.type === "TSTypeQuery" && rgOther(Q, n.exprName)) return ERR;
  if (n.type === "TSTypeQuery" && n.exprName.type === "Identifier" && c.look !== null) {
    const t = c.look.get(n.exprName.name);
    if (t !== undefined) return t;
  }
  return rgUnsup(Q, n, "typeof type query");
};

// the type arguments, converted before the name is looked at
export const rgArgs = (rgGap) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, ta: AstNode | null, c: RgCtx): Ty[] => {
  const out: Mut<Ty[]> = [];
  if (ta === null) return out;
  if (ta.type !== "TSTypeParameterInstantiation") { rgGap(Q, `type arguments held as ${ta.type}`); return out; }
  for (const x of ta.params) out.push(G.convert(G, Y, E, I, Q, x, c));
  return out;
};

// t1 (2026-11-24): or an alias or interface with a banned member ([banned-member], md-shape.ss.ts mdTypeProto).
// a9 (2026-11-23): an alias of the user's that names itself is [type-cycle] once, for the module, and is not loaded; a use
// of it rejects the cell and says why (it was "unknown type A"); a cell that uses it must not be ok
export const rgUnloaded = () => (c: RgCtx, name: string): boolean => {
  const body = c.origin === "user" && c.ast.program.type === "Program" ? c.ast.program.body : [];
  return body.some((st) => { const d = st.type === "ExportNamedDeclaration" && st.declaration !== null ? st.declaration : st; return (d.type === "TSTypeAliasDeclaration" || d.type === "TSInterfaceDeclaration") && d.id.type === "Identifier" && d.id.name === name; });
};

export const rgTypeRef = (rgOther, rgArgs, rgNamedRef, RG_ONE_ARG, WRAPPERS, UNKNOWN, ERR, arr, named, rgUnsup, rgReport, rgUnloaded) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, n: AstNode, c: RgCtx): Ty => {
  if (n.type !== "TSTypeReference") return ERR;
  if (rgOther(Q, n.typeName)) return ERR;
  if (n.typeName.type !== "Identifier") return rgUnsup(Q, n, "qualified type name");
  const name = n.typeName.name;
  const args = rgArgs(G, Y, E, I, Q, n.typeArguments, c);
  if (c.tps.has(name)) return { k: "tv", n: name };
  if (name === "Js") return UNKNOWN;
  if (name === "Array" || name === "ReadonlyArray") return arr(args[0] ?? UNKNOWN);
  const a0 = args[0];
  if (name === "Record" && args.length === 2 && a0 !== undefined && a0.k === "str") return { k: "rec", props: new Map(), index: args[1] };
  if (name === "Action") return named("Action", a0 ?? { k: "tup", els: [] });
  if (RG_ONE_ARG.has(name) && args.length !== 1) {
    rgReport(Q, n, "type", `${name} takes one type argument, as ${name}<T>`);
    return ERR;
  }
  if (WRAPPERS.has(name) || Y.has(name)) return rgNamedRef(G, Y, E, I, Q, name, args);
  if (name === "ValueOf") return rgUnsup(Q, n, "ValueOf in checked cells");
  rgReport(Q, n, "unknown-type", rgUnloaded(c, name) ? `type ${name} cannot be used: it is not loaded: it is defined by itself ([type-cycle]) or declares a member no type may declare ([banned-member])` : `unknown type ${name}`);
  return ERR;
};

// a declared or wrapper name; an alias of Mut<T> or Borrowed<T> is that type, so the ownership rules see it
export const rgNamedRef = (WRAPPERS, named, isNamed, nodeKind, rgGap) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, name: string, args: Ty[]): Ty => {
  const t = named(name, ...args), d = Y.get(name);
  const body = d !== undefined && d.kind === "alias" ? d.nodes[0] : undefined;
  const ofRef = !WRAPPERS.has(name) && body !== undefined && body.type === "TSTypeAliasDeclaration" && nodeKind(body.typeAnnotation) === "TSTypeReference";
  if (ofRef && body !== undefined && body.type === "TSTypeAliasDeclaration" && body.typeAnnotation.type === "Other") return rgGap(Q, "alias body held as Other");
  const e = ofRef ? G.expand(G, Y, E, I, Q, t) : t;
  return isNamed(e, "Mut") || isNamed(e, "Borrowed") ? e : t;
};

// flagsOf: the flags a declaration's leading comments name, and intrinsic for the intrinsics; null for none
export const rgFlags = (RG_FLAG_NAMES, leadingComments) => (ast: Ast, n: AstNode, origin: RgOrigin): Flags | null => {
  const f: Mut<Flags> = {};
  let any = false;
  for (const c of leadingComments(ast, n.start)) for (const k of RG_FLAG_NAMES) {
    if (!c.text.includes("@" + k)) continue;
    any = true;
    if (k === "mutates") f.mutates = true; else if (k === "fresh") f.fresh = true; else if (k === "view") f.view = true; else if (k === "retains") f.retains = true; else if (k === "plain") f.plain = true; else f.banned = true;
  }
  if (origin === "intrinsic") { f.intrinsic = true; any = true; }
  return any ? f : null;
};

// the names of a type parameter declaration
export const rgTpNames = (rgGap) => (Q: RgCtls, tp: AstNode | null): string[] => {
  if (tp === null) return [];
  if (tp.type !== "TSTypeParameterDeclaration") { rgGap(Q, `type parameters held as ${tp.type}`); return []; }
  for (const x of tp.params) if (x.type !== "TSTypeParameter") rgGap(Q, `type parameter held as ${x.type}`);
  return tp.params.flatMap((x) => (x.type === "TSTypeParameter" ? [x.name] : []));
};

export const rgTpChecks = (rgUnsup) => (Q: RgCtls, tp: AstNode | null): void => {
  if (tp === null || tp.type !== "TSTypeParameterDeclaration") return;
  for (const x of tp.params) if (x.type === "TSTypeParameter" && (x.constraint !== null || x.default !== null)) rgUnsup(Q, x, "type parameter constraint/default");
};

export const rgSig = (rgTpNames, rgTpChecks, rgSigParam, VOID) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, params: AstNode[], ret: AstNode | null, tp: AstNode | null, c: RgCtx, flags: Flags | null): Fn => {
  const tps = rgTpNames(Q, tp);
  rgTpChecks(Q, tp);
  const inner: RgCtx = { ...c, tps: new Set([...c.tps, ...tps]) };
  const ps: Mut<Param[]> = [];
  let rest: Ty | undefined = undefined;
  for (const q of params) {
    const o = rgSigParam(G, Y, E, I, Q, q, inner);
    if (o.k === "param") ps.push(o.p);
    else if (o.k === "rest") rest = o.t;
  }
  const r = ret !== null ? G.convert(G, Y, E, I, Q, ret, inner) : VOID;
  return flags !== null ? { k: "fn", tps, ps: ps, rest, ret: r, flags } : { k: "fn", tps, ps: ps, rest, ret: r };
};

// the annotation of a parameter's name or pattern
export const rgParamAnn = (rgAnn, rgOther) => (Q: RgCtls, id: AstNode): AstNode | null =>
  rgOther(Q, id) ? null : id.type === "Identifier" || id.type === "ObjectPattern" || id.type === "ArrayPattern" || id.type === "RestElement" ? rgAnn(Q, id.typeAnnotation) : null;

export const rgSigParam = (rgParamAnn, rgUnsup, rgGap, RG_PARAMS, nodeKind, UNKNOWN, ERR) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, q: AstNode, c: RgCtx): RgParamOut => {
  if (q.type === "RestElement") {
    const a = rgParamAnn(Q, q) ?? rgParamAnn(Q, q.argument);
    const t = a !== null ? G.convert(G, Y, E, I, Q, a, c) : UNKNOWN;
    return { k: "rest", t: t.k === "arr" ? t.el : rgUnsup(Q, q, "rest parameter type") };
  }
  if (q.type === "Identifier" || q.type === "ObjectPattern" || q.type === "ArrayPattern" || q.type === "AssignmentPattern") {
    const id = q.type === "AssignmentPattern" ? q.left : q;
    const a = rgParamAnn(Q, id);
    const t = a !== null ? G.convert(G, Y, E, I, Q, a, c) : rgUnsup(Q, q, "untyped parameter in a signature");
    const opt = (id.type === "Identifier" && id.optional === true) || q.type === "AssignmentPattern";
    return { k: "param", p: { n: id.type === "Identifier" ? id.name : "_", t, opt } };
  }
  if (RG_PARAMS.has(nodeKind(q))) { rgGap(Q, `parameter ${nodeKind(q)} held as Other`); return { k: "param", p: { n: "_", t: ERR, opt: false } }; }
  rgUnsup(Q, q, `parameter ${nodeKind(q)}`);
  return { k: "none" };
};

export const rgLiteral = (rgMember) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, ms: AstNode[], c: RgCtx): Rec => {
  const props: Mut<Map<string, Prop>> = new Map();
  const over: Mut<Map<string, Fn[]>> = new Map();
  let acc: RgAcc = { index: undefined, calls: undefined, ctors: undefined };
  for (const m of ms) acc = rgMember(G, Y, E, I, Q, props, over, m, c, acc);
  return { k: "rec", props: props, index: acc.index, calls: acc.calls, ctors: acc.ctors };
};

export const rgMember = (rgFlags, rgPropSig, rgMethodSig, rgIndexSig, rgAnn, RG_MEMBERS, nodeKind, rgUnsup, rgGap) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, props: Mut<Map<string, Prop>>, over: Mut<Map<string, Fn[]>>, m: AstNode, c: RgCtx, acc: RgAcc): RgAcc => {
  const fl = rgFlags(c.ast, m, c.origin);
  if (m.type === "TSPropertySignature") rgPropSig(G, Y, E, I, Q, props, m, c, fl);
  else if (m.type === "TSMethodSignature") rgMethodSig(G, Y, E, I, Q, props, over, m, c, fl);
  else if (m.type === "TSIndexSignature") return { ...acc, index: rgIndexSig(G, Y, E, I, Q, m, c) ?? acc.index };
  else if (m.type === "TSCallSignatureDeclaration") return { ...acc, calls: [...(acc.calls ?? []), G.sig(G, Y, E, I, Q, m.parameters, rgAnn(Q, m.typeAnnotation), m.typeParameters, c, fl)] };
  else if (m.type === "TSConstructSignatureDeclaration") return { ...acc, ctors: [...(acc.ctors ?? []), G.sig(G, Y, E, I, Q, m.parameters, rgAnn(Q, m.typeAnnotation), m.typeParameters, c, fl)] };
  else if (RG_MEMBERS.has(nodeKind(m))) rgGap(Q, `member ${nodeKind(m)} held as Other`);
  else rgUnsup(Q, m, nodeKind(m));
  return acc;
};

export const rgPropSig = (rgKeyName, rgAnn, rgProp, rgUnsup, UNKNOWN, rgOther) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, props: Mut<Map<string, Prop>>, m: AstNode, c: RgCtx, fl: Flags | null): void => {
  if (m.type !== "TSPropertySignature" || rgOther(Q, m.key)) return;
  const k = rgKeyName(m.key);
  if (m.computed || k === null) { rgUnsup(Q, m, "computed property signature"); return; }
  const a = rgAnn(Q, m.typeAnnotation);
  props.set(k, rgProp(a !== null ? G.convert(G, Y, E, I, Q, a, c) : UNKNOWN, m.optional === true, fl));
};

// overloads of one name make a record of call signatures
export const rgMethodSig = (rgKeyName, rgAnn, rgProp, rgUnsup, rgOther) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, props: Mut<Map<string, Prop>>, over: Mut<Map<string, Fn[]>>, m: AstNode, c: RgCtx, fl: Flags | null): void => {
  if (m.type !== "TSMethodSignature" || rgOther(Q, m.key)) return;
  const k = rgKeyName(m.key);
  if (m.computed || k === null || (m.kind !== "" && m.kind !== "method")) { rgUnsup(Q, m, "computed/accessor method signature"); return; }
  const f = G.sig(G, Y, E, I, Q, m.parameters, rgAnn(Q, m.typeAnnotation), m.typeParameters, c, fl);
  const list = [...(over.get(k) ?? []), f];
  over.set(k, list);
  const only = list[0];
  props.set(k, rgProp(list.length === 1 && only !== undefined ? only : { k: "rec", props: new Map(), calls: list }, m.optional === true, fl));
};

// a string index signature's value type; undefined when it is not one
export const rgIndexSig = (rgAnn, rgUnsup, rgGap, rgOther) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, m: AstNode, c: RgCtx): Ty | undefined => {
  if (m.type !== "TSIndexSignature") return undefined;
  const p0 = m.parameters[0];
  if (p0 !== undefined && rgOther(Q, p0)) return undefined;
  const kt = p0 !== undefined && p0.type === "Identifier" ? rgAnn(Q, p0.typeAnnotation) : null;
  if (kt === null || kt.type !== "TSStringKeyword") { rgUnsup(Q, m, "non-string index signature"); return undefined; }
  const a = rgAnn(Q, m.typeAnnotation);
  if (a === null) { rgGap(Q, "index signature without a type"); return undefined; }
  return G.convert(G, Y, E, I, Q, a, c);
};

export const rgExpand = (typeKey, subst, ERR, rgUnsup, rgGap, rgUndoPush, rgIsBuilding, rgAliasAdd) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, t: Ty): Ty => {
  if (t.k !== "named" || !G.isAlias(t.n)) return t;
  const key = typeKey(t);
  const hit = E.get(key);
  if (hit !== undefined) return hit;
  const d = Y.get(t.n), at = d?.nodes[0];
  if (d === undefined || at === undefined) return rgGap(Q, `expand: no declaration of ${t.n}`);
  if (d.tps.length !== t.args.length && d.tps.length > 0) return rgUnsup(Q, at, `generic type ${t.n} used with ${t.args.length} arguments`);
  // a directly self-referential alias expands to ERR (unsupported)
  E.set(key, ERR);
  rgUndoPush(Q, "expand", key);
  const m: Subst = new Map(d.tps.map((n, i): [string, Ty] => [n, G.at(t.args, i)]));
  if (d.kind === "alias") {
    const body = at.type === "TSTypeAliasDeclaration" ? G.convert(G, Y, E, I, Q, at.typeAnnotation, { tps: new Set(d.tps), look: null, ast: d.ast, origin: d.origin }) : rgGap(Q, "alias declaration held as Other");
    const out = subst(body, m);
    E.set(key, out);
    return out;
  }
  const building = rgIsBuilding(Q, t.n);
  const out = subst(G.ifaceRec(G, Y, E, I, Q, t.n), m);
  if (building && d.tps.length === 0) rgAliasAdd(Q, t.n, key);
  E.set(key, out);
  return out;
};

export const rgIsBuilding = () => (Q: RgCtls, name: string): boolean => {
  for (let b = Q.building; b !== null; b = b.next) if (b.name === name) return true;
  return false;
};

export const rgAliasAdd = () => (Q: RgCtls, name: string, key: string): void => {
  Q.aliases = { name, key, next: Q.aliases };
};

// the record of an interface being built, as filled so far, in its memo and in each expansion key that holds it
export const rgLiveSet = () => (E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, name: string, r: Rec): void => {
  if (I.has(name)) I.set(name, r);
  for (let a = Q.aliases; a !== null; a = a.next) if (a.name === name && E.has(a.key)) E.set(a.key, r);
};

// the interface is built: it leaves the building list and its keys need no more updates
export const rgBuilt = () => (Q: RgCtls, name: string): void => {
  const keep: Mut<RgAlias[]> = [];
  for (let a = Q.aliases; a !== null; a = a.next) if (a.name !== name) keep.push(a);
  let out: RgAlias | null = null;
  for (let i = keep.length - 1; i >= 0; i--) { const a = keep[i]; if (a !== undefined) out = { name: a.name, key: a.key, next: out }; }
  Q.aliases = out;
  const b = Q.building;
  if (b !== null && b.name === name) Q.building = b.next;
};

export const rgIfaceRec = (rgIfaceExtends, rgIfaceOwn, rgLiveSet, rgBuilt, rgUndoPush, rgGap) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, name: string): Rec => {
  const hit = I.get(name);
  if (hit !== undefined) return hit;
  const d = Y.get(name);
  let r: Rec = { k: "rec", props: new Map() };
  if (d === undefined) { rgGap(Q, `ifaceRec: no declaration of ${name}`); return r; }
  I.set(name, r);
  rgUndoPush(Q, "iface", name);
  Q.building = { name, next: Q.building };
  for (const node of d.nodes) r = rgIfaceExtends(G, Y, E, I, Q, name, node, r);
  const c: RgCtx = { tps: new Set(d.tps), look: null, ast: d.ast, origin: d.origin };
  for (const node of d.nodes) {
    r = rgIfaceOwn(G, Y, E, I, Q, node, c, r);
    rgLiveSet(E, I, Q, name, r);
  }
  rgBuilt(Q, name);
  return r;
};

// the bases an interface declaration extends, merged in: what r has stays, call signatures add up
export const rgIfaceExtends = (named, ERR, rgUnsup, rgLiveSet, rgGap) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, name: string, node: AstNode, r0: Rec): Rec => {
  if (node.type !== "TSInterfaceDeclaration") { rgGap(Q, "interface declaration held as Other"); return r0; }
  let r = r0;
  for (const h of node.extends) {
    if (h.type === "Other" || (h.type === "TSExpressionWithTypeArguments" && h.expression.type === "Other")) { rgGap(Q, "extends clause held as Other"); continue; }
    const base = h.type === "TSExpressionWithTypeArguments" && h.expression.type === "Identifier" ? G.expand(G, Y, E, I, Q, named(h.expression.name)) : ERR;
    if (base.k !== "rec") { rgUnsup(Q, h, "interface extends a non-object type"); continue; }
    const props: Mut<Map<string, Prop>> = new Map(r.props);
    for (const [k, v] of base.props) if (!props.has(k)) props.set(k, v);
    const calls = base.calls !== undefined ? [...(r.calls ?? []), ...base.calls] : r.calls;
    r = { k: "rec", props: props, index: r.index ?? base.index, calls, ctors: r.ctors };
    rgLiveSet(E, I, Q, name, r);
  }
  return r;
};

// an interface declaration's own members over what r has
export const rgIfaceOwn = (rgGap) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, node: AstNode, c: RgCtx, r: Rec): Rec => {
  if (node.type !== "TSInterfaceDeclaration" || node.body.type !== "TSInterfaceBody") { rgGap(Q, "interface body held as Other"); return r; }
  const own = G.literal(G, Y, E, I, Q, node.body.body, c);
  const props: Mut<Map<string, Prop>> = new Map(r.props);
  for (const [k, v] of own.props) props.set(k, v);
  const calls = own.calls !== undefined ? [...(r.calls ?? []), ...own.calls] : r.calls;
  return { k: "rec", props: props, index: own.index ?? r.index, calls, ctors: own.ctors ?? r.ctors };
};

// expanding t, or any alias it reaches, reports no problem; keys found quiet are kept for later calls
export const rgQuiet = () => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, K: RgQuietKeys, t: Ty): boolean => {
  const seen: Mut<Set<string>> = new Set();
  const ok = G.quietGo(G, Y, E, I, Q, K, seen, t);
  if (ok) for (const k of seen) K.add(k);
  return ok;
};

export const rgQuietGo = (typeKey, rgTrial, rgQuietAll) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, K: RgQuietKeys, S: Mut<Set<string>>, x: Ty): boolean => {
  switch (x.k) {
    case "named": {
      if (!G.isAlias(x.n)) return rgQuietAll(G, Y, E, I, Q, K, S, x.args);
      const key = typeKey(x);
      if (K.has(key) || S.has(key)) return true;
      if (S.size > 1000) return false;
      S.add(key);
      const e = E.get(key) ?? rgTrial(G, Y, E, I, Q, x);
      return e !== null && e.k !== "err" && G.quietGo(G, Y, E, I, Q, K, S, e);
    }
    case "arr": return G.quietGo(G, Y, E, I, Q, K, S, x.el);
    case "tup": return rgQuietAll(G, Y, E, I, Q, K, S, x.els);
    case "union": return rgQuietAll(G, Y, E, I, Q, K, S, x.ts);
    case "rec": return rgQuietAll(G, Y, E, I, Q, K, S, [...x.props.values()].map((p) => p.t)) && (x.index === undefined || G.quietGo(G, Y, E, I, Q, K, S, x.index)) && rgQuietAll(G, Y, E, I, Q, K, S, [...(x.calls ?? []), ...(x.ctors ?? [])]);
    case "fn": return rgQuietAll(G, Y, E, I, Q, K, S, x.ps.map((p) => p.t)) && G.quietGo(G, Y, E, I, Q, K, S, x.ret);
    default: return true;
  }
};

export const rgQuietAll = () => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, K: RgQuietKeys, S: Mut<Set<string>>, xs: Ty[]): boolean => {
  for (const x of xs) if (!G.quietGo(G, Y, E, I, Q, K, S, x)) return false;
  return true;
};

// the scan memberOf skips would record pairs in a seen of the caller's, and convert aliases, which may report
export const rgSub = (rgQuiet) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, K: RgQuietKeys, s: Ty, t: Ty): boolean => {
  if (rgQuiet(G, Y, E, I, Q, K, s) && rgQuiet(G, Y, E, I, Q, K, t) && G.memberOf(s, t)) return true;
  const seen: Mut<Set<string>> = new Set();
  return G.subOps(s, t, seen);
};

export const rgMarker = (leadingComments) => (ast: Ast, n: AstNode): "pure" | "effect" | null => {
  for (const c of leadingComments(ast, n.start)) {
    if (!c.block) continue;
    const t = c.text.trim();
    if (!t.startsWith("*")) continue;
    const w = t.slice(1).trim();
    if (w === "pure") return "pure";
    if (w === "effect") return "effect";
  }
  return null;
};

// the statements of a parse; skip: the nids of declarations not to load (a user type with a built-in name)
export const rgLoad = (rgLoadStmt, rgLoadFns) => (G: RgK, Y: RgTypes, V: RgValues, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, ast: Ast, origin: RgOrigin, typesOnly: boolean, skip: Set<number>): AstNode[] => {
  const rest: Mut<AstNode[]> = [];
  const fns: Mut<Map<string, AstNode[]>> = new Map();
  const body = ast.program.type === "Program" ? ast.program.body : [];
  for (const st of body) {
    const r = rgLoadStmt(G, Y, V, E, I, Q, fns, ast, origin, typesOnly, skip, st);
    if (r !== null) rest.push(r);
  }
  rgLoadFns(G, Y, V, E, I, Q, fns, ast, origin);
  return rest;
};

// one statement: loaded, grouped as a declared function, skipped, or left (returned)
export const rgLoadStmt = (rgDeclType, rgDeclVars, RG_DECLS, nodeKind, rgGap) => (G: RgK, Y: RgTypes, V: RgValues, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, fns: Mut<Map<string, AstNode[]>>, ast: Ast, origin: RgOrigin, typesOnly: boolean, skip: Set<number>, st: AstNode): AstNode | null => {
  if (st.type === "Other" && st.kind === "ExportNamedDeclaration") { rgGap(Q, "export held as Other"); return null; }
  const inner = st.type === "ExportNamedDeclaration" ? st.declaration : null;
  const typeKind = (x: AstNode) => nodeKind(x) === "TSTypeAliasDeclaration" || nodeKind(x) === "TSInterfaceDeclaration";
  const d = inner !== null && typeKind(inner) ? inner : st;
  if (typesOnly && !typeKind(d)) return st;
  if (d.type === "Other" && RG_DECLS.has(d.kind)) { rgGap(Q, `declaration ${d.kind} held as Other`); return null; }
  const isType = d.type === "TSTypeAliasDeclaration" || d.type === "TSInterfaceDeclaration";
  if (skip.has(d.nid)) return null;
  if (isType) rgDeclType(Y, Q, d, ast, origin);
  else if (d.type === "TSDeclareFunction" && d.id.type === "Identifier") fns.set(d.id.name, [...(fns.get(d.id.name) ?? []), d]);
  else if (d.type === "TSDeclareFunction") rgGap(Q, "declared function without a name");
  else if (d.type === "VariableDeclaration" && d.declare === true) rgDeclVars(G, Y, V, E, I, Q, d, ast, origin);
  else return st;
  return null;
};

// an interface declared again in the same origin adds its members; any other declaration of the name replaces it
export const rgDeclType = (rgTpNames, rgGap) => (Y: RgTypes, Q: RgCtls, d: AstNode, ast: Ast, origin: RgOrigin): void => {
  if (d.type !== "TSTypeAliasDeclaration" && d.type !== "TSInterfaceDeclaration") return;
  if (d.id.type !== "Identifier") { rgGap(Q, "type declaration without a name"); return; }
  const name = d.id.name, kind = d.type === "TSTypeAliasDeclaration" ? "alias" : "iface";
  const tps = rgTpNames(Q, d.typeParameters);
  const prev = Y.get(name);
  if (prev !== undefined && prev.kind === "iface" && kind === "iface" && prev.origin === origin) Y.set(name, { ...prev, nodes: [...prev.nodes, d] });
  else Y.set(name, { kind, tps, nodes: [d], origin, ast });
};

export const rgDeclVars = (rgConvertIn, rgMarker, rgFlags, rgAnn, rgGap, UNKNOWN) => (G: RgK, Y: RgTypes, V: RgValues, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, d: AstNode, ast: Ast, origin: RgOrigin): void => {
  if (d.type !== "VariableDeclaration") return;
  for (const v of d.declarations) {
    if (v.type !== "VariableDeclarator" || v.id.type !== "Identifier") { rgGap(Q, "declare without a plain name"); continue; }
    const ann = rgAnn(Q, v.id.typeAnnotation);
    const t = ann !== null ? rgConvertIn(G, Y, E, I, Q, ann, ast, origin) : UNKNOWN;
    V.set(v.id.name, { t, origin, node: d, marker: rgMarker(ast, d), flags: rgFlags(ast, d, origin) });
  }
};

// convert with no type parameters in scope
export const rgConvertIn = (rgBareCtx) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, n: AstNode, ast: Ast, origin: RgOrigin): Ty =>
  G.convert(G, Y, E, I, Q, n, rgBareCtx(ast, origin));

// declared functions, after the other statements: one signature, or overloads as a record of call signatures
export const rgLoadFns = (rgBareCtx, rgFlags, rgMarker, rgAnn) => (G: RgK, Y: RgTypes, V: RgValues, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, fns: Mut<Map<string, AstNode[]>>, ast: Ast, origin: RgOrigin): void => {
  for (const [name, list] of fns) {
    const sigs: Mut<Fn[]> = [];
    for (const d of list) if (d.type === "TSDeclareFunction") sigs.push(G.sig(G, Y, E, I, Q, d.params, rgAnn(Q, d.returnType), d.typeParameters, rgBareCtx(ast, origin), rgFlags(ast, d, origin)));
    const first = list[0], one = sigs[0];
    if (first === undefined) continue;
    const t: Ty = sigs.length === 1 && one !== undefined ? one : { k: "rec", props: new Map(), calls: sigs };
    V.set(name, { t, origin, node: first, marker: rgMarker(ast, first), flags: null });
  }
};

// core.ts loadUser: the declarations starting at a clash, by nid
export const rgSkip = () => (ast: Ast, clash: number[]): Set<number> => {
  const at = new Set(clash), out: Mut<Set<number>> = new Set();
  const body = ast.program.type === "Program" ? ast.program.body : [];
  for (const st of body) {
    const d = st.type === "ExportNamedDeclaration" && st.declaration !== null ? st.declaration : st;
    if (at.has(d.start)) out.add(d.nid);
  }
  return out;
};

// globalsOf: the prelude functions, the allowed intrinsics and undefined, bound in a cell's scope 0
export const rgGlobals = (ERR, UNDEF) => (V: RgValues, preludeFns: Set<string>, allowed: Set<string>): { name: string; t: Ty; kind: RgKind }[] => {
  const out: Mut<Map<string, { name: string; t: Ty; kind: RgKind }>> = new Map();
  for (const name of preludeFns) out.set(name, { name, t: ERR, kind: "prelude" });
  for (const name of allowed) {
    const v = V.get(name);
    if (name === "undefined") out.set(name, { name, t: UNDEF, kind: "global" });
    else if (v !== undefined && v.origin === "intrinsic") out.set(name, { name, t: v.t, kind: "global" });
  }
  for (const name of ["equals", "messageOf"]) {
    const v = V.get(name), b = out.get(name);
    if (v !== undefined && b !== undefined) out.set(name, { ...b, t: v.t });
  }
  return [...out.values()];
};

// whether a node holds a typeof type query, remembered per node (memo)
export const rgHasTypeQuery = (childrenOf) => {
  const has = memo((x: AstNode): boolean => x.type === "TSTypeQuery" || childrenOf(x).some((k) => has(k.node)));
  return has;
};

// core.ts peekType inside its peek: the annotation converted, an alias expanded once
export const rgPeekType = (rgBareCtx) => (G: RgK, Y: RgTypes, E: RgExpandMemo, I: RgIfaceMemo, Q: RgCtls, n: AstNode, ast: Ast): Ty => {
  const t = G.convert(G, Y, E, I, Q, n, rgBareCtx(ast, "user"));
  return t.k === "named" && G.isAlias(t.n) ? G.expand(G, Y, E, I, Q, t) : t;
};

// t has, somewhere hidden walks, unknown, object, a type parameter or a function; true past a depth of generic aliases.
// Not memoised here: the registry glue (rg-registry.ts core) memoises it per core with memo, since its key holds functions
export type RgHideR = { readonly isAlias: (n: string) => boolean; readonly expand: (t: Ty) => Ty };

export const rgMayHide = () => {
  function anyHides(R: RgHideR, seen: Mut<Set<string>>, xs: Ty[], d: number): boolean {
    for (const x of xs) if (go(R, seen, x, d)) return true;
    return false;
  }
  function go(R: RgHideR, seen: Mut<Set<string>>, x: Ty, d: number): boolean {
    switch (x.k) {
      case "unknown": case "object": case "tv": case "fn": return true;
      case "named":
        if (!R.isAlias(x.n)) return anyHides(R, seen, x.args, d);
        if (x.args.length) return d > 10 || go(R, seen, R.expand(x), d + 1);
        if (seen.has(x.n)) return false;
        seen.add(x.n);
        return go(R, seen, R.expand(x), d);
      case "arr": return go(R, seen, x.el, d);
      case "tup": return anyHides(R, seen, x.els, d);
      case "union": return anyHides(R, seen, x.ts, d);
      case "rec": return !!x.calls?.length || !!x.ctors?.length || (!!x.index && go(R, seen, x.index, d)) || anyHides(R, seen, [...x.props.values()].map((p) => p.t), d);
      default: return false;
    }
  }
  return (R: RgHideR, t: Ty): boolean => go(R, new Set(), t, 0);
};

// lite/registry.ts as completion reads it; ifaceKeys: the property names of a declared interface, null when none is declared
export type CpReg = {
  readonly expand: (t: Ty) => Ty;
  readonly member: (t: Ty, k: string) => Prop | undefined;
  readonly callSigs: (t: Ty) => Fn[];
  readonly ifaceKeys: (n: string) => string[] | null;
};

// the module checks a completion runs, and the value a cell in another language suggests; each is null where
// complete.ts catches a throw or finds no probe
export type CpHost = {
  readonly probe: (cells: string, member: boolean) => CpFound | null;
  readonly cellTypes: (cells: string) => [string, string][] | null;
  readonly annotate: (name: string) => string | null;
  readonly fresh: () => CpReg;
  readonly treeAt: CpTreeAt;
};

// the bracket a node of the path leaves open: an opening child with no closer after it, or "`" for a template cut short
export const cpOpenIn = (cpCloserOf) => (n: CpLzNode): string => {
  if (n.name === "TemplateString") return n.kids.some((k) => k.name === "⚠") ? "`" : "";
  let open = "";
  for (const k of n.kids) {
    const c = cpCloserOf(k.name);
    if (c !== "") open = c;
    else if (open !== "" && (k.name === open || (open === "}" && k.name === "InterpolationEnd"))) open = "";
  }
  return open;
};

// whether the end of text sits in a comment, an unclosed string or a template's text (not in its ${…})
export const cpQuoted = () => (text: string, path: CpLzNode[]): boolean => {
  for (const n of path) {
    if (n.to < text.length) continue;
    if (n.name === "Interpolation") return false;
    if (n.name === "LineComment") return true;
    if ((n.name === "String" || n.name === "TemplateString" || n.name === "BlockComment") && n.kids.some((k) => k.name === "⚠")) return true;
    if (n.name === "⚠" && (text.charAt(n.from) === '"' || text.charAt(n.from) === "'")) return true;
  }
  return false;
};

// scan: whether the end of text is quoted, and the closers of the brackets open there, innermost first
export const cpScan = (cpQuoted, cpOpenIn) => (text: string, path: CpLzNode[]): CpScan =>
  cpQuoted(text, path) ? { quoted: true, closers: [] } : { quoted: false, closers: path.map((n) => cpOpenIn(n)).filter((c) => c !== "") };

// a spread or a number literal's dot (`1.`) just before the end, where nothing is offered
export const cpNoOffer = () => (text: string, path: CpLzNode[]): boolean => {
  const t = path[0];
  return t !== undefined && (t.name === "Spread" || (t.name === "Number" && t.to === text.length && text.charAt(t.to - 1) === "."));
};

// the node n, with its children: on the path to the position just inside it
export const cpNodeOf = () => (at: CpTreeAt, text: string, n: CpLzSpan): CpLzNode | null =>
  at(text, n.from + 1).find((m) => m.from === n.from && m.to === n.to && m.name === n.name) ?? null;

// tagAt: the end of text in `<tag attr…` after a space, outside any {…}: the tag, when it is a lowercase (builtin) one
export const cpTagAt = () => (text: string, path: CpLzNode[]): CpLzNode | null => {
  const i = path.findIndex((n) => n.name === "JSXSelfClosingTag" || n.name === "JSXOpenTag");
  const tag = path[i], leaf = path[0];
  if (tag === undefined || leaf === undefined || i === 0 || tag.to < text.length || leaf.to === text.length) return null;
  if (path.slice(0, i).some((n) => n.name === "JSXEscape" && n.to === text.length)) return null;
  return tag.kids.some((k) => k.name === "JSXBuiltin") ? tag : null;
};

// the attribute names a tag already gives a value (name=)
export const cpGivenAttrs = (cpNodeOf) => (at: CpTreeAt, text: string, tag: CpLzNode): Set<string> => {
  const out: Mut<Set<string>> = new Set();
  for (const k of tag.kids) {
    const a = k.name === "JSXAttribute" ? cpNodeOf(at, text, k) : null;
    const n = a?.kids[0];
    if (a !== null && n !== undefined && n.name === "JSXIdentifier" && a.kids[1]?.name === "Equals") out.add(text.slice(n.from, n.to));
  }
  return out;
};

// the cell's function from the init of its declaration: (…) =>, async (…) =>, function [*] [name] (…), or an unclosed "(…"
// that the grammar reads as parentheses (`(`, `([a], `) before an arrow shows it is a parameter list
export const cpHeadFn = (cpNodeOf, CP_HEAD_WORDS) => (at: CpTreeAt, text: string, decl: CpLzNode): CpHead | null => {
  const [k0, k1, k2, k3] = decl.kids;
  const named = (k0?.name === "const" || k0?.name === "let") && k1?.name === "VariableDefinition" && k2?.name === "Equals";
  const init = decl.name === "FunctionDeclaration" ? decl : named && k3 !== undefined ? cpNodeOf(at, text, k3) : null;
  if (init === null) return null;
  if (init.name === "ParenthesizedExpression") return init.kids.some((x) => x.name === ")") ? null : { decl, fn: init, list: init };
  if (init.name !== "ArrowFunction" && init.name !== "FunctionExpression" && init.name !== "FunctionDeclaration") return null;
  const i = init.kids.findIndex((x) => x.name === "ParamList"), pl = init.kids[i];
  const ok = (x: CpLzSpan) => (init.name === "ArrowFunction" ? x.name === "async" : CP_HEAD_WORDS.includes(x.name));
  const list = pl === undefined || !init.kids.slice(0, i).every(ok) ? null : cpNodeOf(at, text, pl);
  return list === null || list.kids[0]?.name !== "(" ? null : { decl, fn: init, list };
};

// the head: the first statement after comments, [export] const|let name = <function> or [export] [async] function name(…)
export const cpHeadOf = (cpNodeOf, cpHeadFn) => (at: CpTreeAt, text: string): CpHead | null => {
  const first = at(text, 1).at(-1)?.kids.find((k) => k.name !== "LineComment" && k.name !== "BlockComment");
  let decl = first === undefined ? null : cpNodeOf(at, text, first);
  if (decl !== null && decl.name === "ExportDeclaration") { const d = decl.kids[1]; decl = d === undefined ? null : cpNodeOf(at, text, d); }
  return decl !== null && (decl.name === "VariableDeclaration" || decl.name === "FunctionDeclaration") ? cpHeadFn(at, text, decl) : null;
};

// the name the cell's head declares, or null
export const cpSelfName = () => (text: string, head: CpHead | null): string | null => {
  const d = head?.decl.kids.find((k) => k.name === "VariableDefinition");
  return d === undefined ? null : text.slice(d.from, d.to);
};

// the parameters of a parameter list (or of the sequence in an unclosed "(…") that are a plain name; with rest, a rest
// parameter's name too
export const cpParamNames = () => (list: CpLzNode, rest: boolean): CpLzSpan[] => list.kids.filter((k, i) =>
  (k.name === "VariableDefinition" || k.name === "VariableName") && (i === 0 || ["(", ",", ...(rest ? ["Spread"] : [])].includes(list.kids[i - 1]?.name ?? "")));

// paramListAt: just after the "(" or a "," of the cell's own parameter list, the names already there
export const cpParamListAt = (cpSameNode, cpParamNames) => (text: string, path: CpLzNode[], head: CpHead | null): string[] | null => {
  const leaf = path[0], up = path[1];
  if (head === null || leaf === undefined || up === undefined || (leaf.name !== "(" && leaf.name !== ",")) return null;
  const inSeq = up.name === "SequenceExpression" && head.fn.name === "ParenthesizedExpression" && cpSameNode(path[2], head.list);
  return inSeq || cpSameNode(up, head.list) ? cpParamNames(up, false).map((k) => text.slice(k.from, k.to)) : null;
};

// typeAt: in the annotation of one of the cell's own parameters, or in its return type
export const cpTypeAt = (cpSameNode) => (path: CpLzNode[], head: CpHead | null): boolean => {
  if (head === null) return false;
  return path.some((up, i) => {
    const t = path[i - 1];
    return t !== undefined && t.name === "TypeAnnotation" && (cpSameNode(up, head.list) || (cpSameNode(up, head.fn) && t.from > head.list.from));
  });
};

// declared: the names of the types and interfaces a line of src starts to declare, in order
export const cpDeclared = () => (src: string): string[] => {
  const out: Mut<string[]> = [];
  let pos = 0;
  for (;;) {
    const re = pos === 0 ? /(?<all>(?:^|\n)\s*(?:export\s+)?(?:interface|type)\s+(?<n>[\w$]+))/ : /(?<all>\n\s*(?:export\s+)?(?:interface|type)\s+(?<n>[\w$]+))/;
    const m = re.exec(src.slice(pos));
    if (m === null) return out;
    out.push(m.groups?.n ?? "");
    pos += (m.index ?? 0) + (m.groups?.all ?? "").length;
  }
};

// memberNames: the names a value of type x has, before the read rules
export const cpMemberNames = (cpIfaceNames) => (reg: CpReg, x: Ty): string[] => {
  switch (x.k) {
    case "rec": return [...x.props.keys()];
    case "named": return cpIfaceNames(reg, x.n);
    case "arr": case "tup": return cpIfaceNames(reg, "Array");
    case "str": return cpIfaceNames(reg, "String");
    case "num": return cpIfaceNames(reg, "Number");
    case "lit": return cpIfaceNames(reg, typeof x.v === "string" ? "String" : typeof x.v === "number" ? "Number" : "Boolean");
    case "union": return x.ts.every((y) => y.k === "lit" && typeof y.v === "boolean") ? cpIfaceNames(reg, "Boolean") : [];
    default: return [];
  }
};

// the members one union member m offers: banned ones never, mutating ones only on a Mut receiver
export const cpOwnMembers = (cpMemberNames, cpKindOf, show, propT) => (reg: CpReg, m: Ty, x: Ty, onMut: boolean): Map<string, CpOption> => {
  const own: Mut<Map<string, CpOption>> = new Map();
  for (const name of cpMemberNames(reg, x)) {
    const p = reg.member(m, name);
    if (p === undefined || p.flags?.banned === true || (p.flags?.mutates === true && !onMut)) continue;
    own.set(name, { label: name, type: cpKindOf(reg, p.t), detail: show(propT(p)) });
  }
  return own;
};

// membersOf: the members every member of t's union offers, by label; null when t has no members to offer
export const cpMembersOf = (cpOwnMembers, CP_NO_MEMBERS, members, isNamed) => (reg: CpReg, t: Ty): CpOption[] | null => {
  const ms = members(reg.expand(t)).filter((m) => m.k !== "null" && m.k !== "undef" && m.k !== "void");
  if (ms.length === 0) return null;
  let common: Map<string, CpOption> | null = null;
  for (const m of ms) {
    if (m.k === "err" || m.k === "unknown" || m.k === "tv") return null;
    const onMut = isNamed(m, "Mut");
    const inner = m.k === "named" && (m.n === "Mut" || m.n === "Borrowed") ? m.args[0] ?? m : m;
    const x = reg.expand(inner);
    if (x.k === "named" && CP_NO_MEMBERS.has(x.n)) return [];
    const own: Map<string, CpOption> = cpOwnMembers(reg, m, x, onMut);
    common = common === null ? own : new Map([...common].filter(([k]) => own.has(k)));
  }
  return [...(common ?? new Map<string, CpOption>()).values()].toSorted((a, b) => a.label.localeCompare(b.label));
};

// scopeNames: the bindings in scope at the placeholder; read only inside an action body, the one place it is legal
export const cpScopeNames = (cpPH, show) => (reg: CpReg, names: IxScopeName[], inAction: boolean): CpOption[] => {
  const out: Mut<CpOption[]> = [];
  for (const b of names) {
    const name = b.name, kind = b.kind;
    if (name === cpPH) continue;
    if (kind === "prelude") {
      if (name !== "read" || inAction) out.push({ label: name, type: "function", detail: name === "read" ? "prelude: a state cell's value inside an action" : "prelude" });
      continue;
    }
    const calls = reg.callSigs(b.t).length > 0;
    const type = kind === "global" ? (calls ? "function" : "namespace") : kind === "fn" || calls ? "function" : "variable";
    out.push({ label: name, type, detail: kind === "global" ? "intrinsic" : show(b.t) });
  }
  return out;
};

// the types a cell may name: the prelude's, JSX's, the handle and ownership types, and the library generics
export const cpTypeNames = (cpDeclared) => (preludeDecls: string, jsxDecls: string): string[] =>
  [...new Set([...cpDeclared(preludeDecls), ...cpDeclared(jsxDecls), "Action", "StateCell", "Mut", "Borrowed", "Array", "ReadonlyArray", "Map", "Set", "Promise", "Generator", "Record", "number", "string", "boolean", "bigint", "unknown", "null", "undefined", "void", "readonly"])]
    .filter((n) => n !== "FetchResponse" && n !== "Child");

// pick: the options whose label starts with the typed word, sorted by label when asked
export const cpPick = () => (from: number, to: number, mode: CpMode, options: CpOption[], prefix: string): CpResult =>
  ({ from, to, mode, options: options.filter((o) => o.label.startsWith(prefix)) });

// <tag attr…: the tag's declared attributes not given yet, children never; null when the tag is not declared
export const cpJsxOptions = (cpMemberNames, cpGivenAttrs, cpNodeOf, cpByLabel, named, show) => (reg: CpReg, at: CpTreeAt, before: string, tag: CpLzNode): CpOption[] | null => {
  const b = tag.kids.find((k) => k.name === "JSXBuiltin"), id = b === undefined ? undefined : cpNodeOf(at, before, b)?.kids[0];
  const p = id === undefined ? undefined : reg.member(named("IntrinsicElements"), before.slice(id.from, id.to));
  if (p === undefined) return null;
  const have = cpGivenAttrs(at, before, tag);
  const opts: Mut<CpOption[]> = [];
  for (const n of cpMemberNames(reg, reg.expand(p.t))) {
    if (n === "children" || have.has(n)) continue;
    const q = reg.member(p.t, n);
    opts.push({ label: n, type: "property", detail: q === undefined ? "" : show(q.t) });
  }
  return cpByLabel(opts);
};

// in a type: the type names, and those the module's other cells declare
export const cpTypeOptions = (cpDeclared, cpByLabel) => (typeNames: string[], cells: string[], at: number): CpOption[] => {
  const own = cells.flatMap((c, i) => (i === at ? [] : cpDeclared(c)));
  const names = [...new Set([...typeNames, ...own])];
  return cpByLabel(names.map((n) => ({ label: n, type: "type", detail: own.includes(n) ? "type in this module" : "prelude" })));
};

// a cell in another language must be annotated (S11.2), so it is inserted with its colon
export const cpOutsideOption = () => (n: string, ann: string | null): CpOption =>
  ({ label: n, type: "variable", detail: ann !== null && ann !== "" ? `other language: ${ann}` : "other language: annotate its type", apply: `${n}: ${ann ?? ""}` });

// in the parameter list: the other cells with their types, the capabilities, the cells in other languages
export const cpParamOptions = (cpOutsideOption, cpByLabel) => (H: CpHost, caps: Map<string, string>, cells: string[], at: number, self: string | null, params: string[], outside: CpOutside[], prefix: string): CpOption[] => {
  const types = new Map(H.cellTypes(cells.filter((c, i) => i !== at).join("\n\n")) ?? []);
  const opts: Mut<CpOption[]> = [];
  for (const [n, t] of types) if (n !== self && !params.includes(n)) opts.push({ label: n, type: "variable", detail: `cell: ${t}` });
  for (const [n, t] of caps) if (!params.includes(n) && !types.has(n)) opts.push({ label: n, type: "variable", detail: `capability: ${t}` });
  for (const o of outside) {
    const n = o.name;
    if (n === self || params.includes(n) || types.has(n) || caps.has(n) || !n.startsWith(prefix)) continue;
    opts.push(cpOutsideOption(n, H.annotate(n)));
  }
  return cpByLabel(opts);
};

// the copies of the cell with the placeholder where the typed word is; the last: an unclosed `if (` takes a body
export const cpVariants = (cpPH, cpAfterWord) => (text: string, before: string, offset: number, closers: string[]): string[] => {
  const after = cpAfterWord(text.slice(offset)), cl = closers.join("");
  return [before + cpPH + after, before + cpPH + cl + ";", before + cpPH + ";" + cl, before + cpPH + cl.replace(")", ") {}")];
};

// names: the bindings in scope and the keywords not among them, by label
export const cpNameOptions = (cpScopeNames, CP_KEYWORDS, cpByLabel) => (reg: CpReg, names: IxScopeName[], inAction: boolean): CpOption[] => {
  const list = cpScopeNames(reg, names, inAction);
  const kw = CP_KEYWORDS.filter((k) => !list.some((x) => x.label === k)).map((k) => ({ label: k, type: "keyword" }));
  return cpByLabel([...list, ...kw]);
};

// the first copy of the module whose check reaches the placeholder answers: members, or names in scope
export const cpProbeOptions = (cpVariants, cpMembersOf, cpNameOptions, cpPick) => (H: CpHost, cells: string[], at: number, offset: number, from: number, before: string, closers: string[], member: boolean, prefix: string): CpResult => {
  for (const v of cpVariants(cells[at] ?? "", before, offset, closers)) {
    const got = H.probe(cells.map((c, i) => (i === at ? v : c)).join("\n\n"), member);
    if (got === null) continue;
    const f = got.found;
    if (f.k === "member") return cpPick(from, offset, "member", cpMembersOf(got.reg, f.t) ?? [], prefix);
    return cpPick(from, offset, "name", cpNameOptions(got.reg, f.names, f.inAction), prefix);
  }
  return { from, to: offset, options: [], mode: member ? "member" : "name" };
};

// completionsAt: the options at offset of cell at, and the range the chosen one replaces
export const cpCompletionsAt = (cpWordEnd, cpScan, cpNoOffer, cpTagAt, cpJsxOptions, cpHeadOf, cpTypeAt, cpTypeOptions, cpParamListAt, cpSelfName, cpParamOptions, cpIsMember, cpProbeOptions, cpPick) =>
  (H: CpHost, E: CpConst, cells: string[], at: number, offset: number, tsx: boolean, outside: CpOutside[]): CpResult => {
    const text = cells[at] ?? "";
    const prefix = cpWordEnd(text.slice(0, offset));
    const from = offset - prefix.length, before = text.slice(0, from);
    const none: CpResult = { from, to: offset, options: [], mode: "none" };
    const path = H.treeAt(before, from), sc = cpScan(before, path);
    if (sc.quoted || cpNoOffer(before, path)) return none;
    const tag = tsx ? cpTagAt(before, path) : null;
    if (tag !== null) { const o = cpJsxOptions(H.fresh(), H.treeAt, before, tag); return o === null ? none : cpPick(from, offset, "jsx", o, prefix); }
    const head = cpHeadOf(H.treeAt, before);
    if (cpTypeAt(path, head)) return cpPick(from, offset, "type", cpTypeOptions(E.typeNames, cells, at), prefix);
    const params = cpParamListAt(before, path, head);
    if (params !== null) return cpPick(from, offset, "param", cpParamOptions(H, E.caps, cells, at, cpSelfName(before, head), params, outside, prefix), prefix);
    const member = cpIsMember(path);
    if (!member && prefix === "") return { from, to: offset, options: [], mode: "name" };
    return cpProbeOptions(H, cells, at, offset, from, before, sc.closers, member, prefix);
  };

export const cpAddParameter = (cpHeadOf, cpParamNames) => (at: CpTreeAt, source: string, name: string, annotation: string | null): CpEdit | null => {
  const head = cpHeadOf(at, source);
  const close = head?.list.kids.find((k) => k.name === ")");
  if (head === null || close === undefined || cpParamNames(head.list, true).some((k) => source.slice(k.from, k.to) === name)) return null;
  const param = annotation !== null && annotation !== "" ? `${name}: ${annotation}` : name;
  const last = head.list.kids.filter((k) => k.to <= close.from && k.name !== "⚠").at(-1);
  if (last === undefined || last.name === "(") return { from: head.list.from + 1, to: close.from, insert: param };
  return { from: last.to, to: last.to, insert: last.name === "," ? ` ${param}` : `, ${param}` };
};

// the annotation of each element of an array, when all agree
export const cpAnnotationOfArray = () => (ann: (v: unknown, depth: number) => string | null, v: unknown[], depth: number): string | null => {
  if (v.length === 0 || v.length > 1000) return null;
  const first = ann(v[0], depth + 1);
  if (first === null || first === "") return null;
  for (let i = 1; i < v.length; i++) if (ann(v[i], depth + 1) !== first) return null;
  return `${first}[]`;
};

// annotationOf: number, string, boolean, a non-empty array whose elements agree, or a small plain object of those.
// plain: whether a value's prototype is Object.prototype or null; field: one own property's value. A cell can read neither.
export const cpAnnotationOf = (cpAnnotationOfArray) => (plain: (v: unknown) => boolean, field: (v: unknown, k: string) => unknown, v0: unknown): string | null => {
  function ann(v: unknown, depth: number): string | null {
    if (typeof v === "number") return "number";
    if (typeof v === "string") return "string";
    if (typeof v === "boolean") return "boolean";
    if (depth > 2 || v === null || typeof v !== "object") return null;
    if (Array.isArray(v)) return cpAnnotationOfArray(ann, v, depth);
    if (!plain(v)) return null;
    const keys = Object.keys(v);
    if (keys.length === 0 || keys.length > 8 || !keys.every((k) => /^[A-Za-z_$][\w$]*$/.test(k))) return null;
    const parts: Mut<string[]> = [];
    for (const k of keys) {
      const t = ann(field(v, k), depth + 1);
      if (t === null || t === "") return null;
      parts.push(`${k}: ${t}`);
    }
    const out = `{ ${parts.join("; ")} }`;
    return out.length > 120 ? null : out;
  }
  return ann(v0, 0);
};

export const cpStatementDefs = () => (st: AstNode): MdDef[] => {
  const d = st.type === "ExportNamedDeclaration" ? st.declaration : st;
  if (d === null) return [];
  if (d.type === "FunctionDeclaration") return d.id.type === "Identifier" ? [{ name: d.id.name, fn: d, stmt: st }] : [];
  if (d.type !== "VariableDeclaration") return [];
  return d.declarations.flatMap((x): MdDef[] => {
    if (x.type !== "VariableDeclarator" || x.id.type !== "Identifier" || x.init === null) return [];
    const init = x.init;
    return init.type === "ArrowFunctionExpression" || init.type === "FunctionExpression" ? [{ name: x.id.name, fn: init, stmt: st }] : [];
  });
};

// cellsOf: each cell of src with its facts, or the parse's error
export const cpCellsOf = (parseTree, cpStatementDefs, mdFactsOf) => (src: string): CpCells => {
  const p = parseTree(src, false);
  if (!p.ok) return { ok: false, message: p.message };
  const prog = p.ast.program;
  if (prog.type !== "Program") return { ok: true, cells: [] };
  return { ok: true, cells: prog.body.flatMap((st) => cpStatementDefs(st).map((d) => mdFactsOf(d.name, d, null, [], [], null))) };
};

// a key of p that names x rather than reading it: a member's property, a property's or class member's key
export const cpNamedKey = () => (x: AstNode, p: AstNode): boolean => {
  if (p.type === "MemberExpression") return !p.computed && p.property.nid === x.nid;
  if (p.type === "Property" || p.type === "MethodDefinition") return !p.computed && p.key.nid === x.nid && p.value.nid !== x.nid;
  if (p.type === "PropertyDefinition") return !p.computed && p.key.nid === x.nid && (p.value === null || p.value.nid !== x.nid);
  return false;
};

// globalRefs: the nids of the identifiers in fn that read the global name, outside every scope binding it
export const cpGlobalRefs = (mdRebinds, cpNamedKey, kidsOf) => (fn: AstNode, name: string): Set<number> => {
  const out: Mut<Set<number>> = new Set();
  const todo: Mut<{ n: AstNode; p: AstNode | null }[]> = [{ n: fn, p: null }];
  for (let e = todo.pop(); e !== undefined; e = todo.pop()) {
    const n = e.n, p = e.p;
    if (mdRebinds(n, name)) continue;
    const label = p !== null && (p.type === "LabeledStatement" || p.type === "BreakStatement" || p.type === "ContinueStatement");
    if (n.type === "Identifier" && n.name === name && !label && !(p !== null && cpNamedKey(n, p))) out.add(n.nid);
    for (const k of kidsOf(n).toReversed()) todo.push({ n: k, p: n });
  }
  return out;
};

// a piece of a cell's body: text, a reference to an input (spelled as the input, or $k in the definition for a
// viewof), or an input listed at that point that writes no text
export type TcPart = { readonly k: "text"; readonly text: string } | { readonly k: "in"; readonly input: string } | { readonly k: "mention"; readonly input: string };

// ss-toolchain.ts Context with its optional fields as null
export type TcCtx = {
  readonly generators: Set<string>; readonly events: Set<string>; readonly accepted: Set<string> | null;
  readonly facts: Map<string, TcInfo> | null; readonly why: Map<string, string[]> | null;
  readonly inputs: Map<string, string> | null; readonly module: string | null;
};

export type TcCompiled = {
  readonly comments: AstComment[]; readonly header: TcHeader; readonly headerEnd: number;
  readonly fnEnd: number; readonly hasFn: boolean; readonly callee: TcShape | null; readonly name: string | null; readonly refs: string[];
};

// fnreg.ts closure registration: a node of the cell function's walk, a work item of freeIn (pat: the node is a binding
// pattern), an edit before its final position is taken, a function's start and captures, and the result
export type TcRegNode = { readonly n: AstNode; readonly parent: AstNode | null; readonly depth: number };

export const tcUnkeep = (tcUnesc) => (s: string): string => {
  if (!s.startsWith('"')) return tcUnesc(s);
  const v = JSON.parse(tcUnesc(s));
  if (typeof v !== "string") throw new Error("tc-gap: a kept JSX original that is not a JSON string");
  return v;
};

// source with each edit's span replaced by its text; the edits do not overlap
export const tcApplyEdits = () => (src: string, edits: TcEdit[]): string => {
  let out = "", at = 0;
  for (const e of edits.toSorted((a, b) => a.from - b.from)) {
    out += src.slice(at, e.from) + e.text;
    at = e.to;
  }
  return out + src.slice(at);
};

// a capability or runtime cell -> the input that provides it: ss_<name>, except invalidation and, in the runtime module, its own cells
export const tcInputsIn = (tcCaps, tcRuntimeCells) => (runtimeModule: boolean): Map<string, string> =>
  new Map([...tcCaps, ...tcRuntimeCells].map((n) => [n, n === "invalidation" || (runtimeModule && tcRuntimeCells.includes(n)) ? n : `ss_${n}`]));

export const tcDupOf = () => (key: string): { readonly name: string; readonly n: string } | null => {
  const m = /^(?<name>[\w$]+) \((?<n>\d+)\)$/.exec(key);
  return m === null ? null : { name: m.groups?.name ?? "", n: m.groups?.n ?? "" };
};

export const tcVariableName = (tcDupOf) => (key: string): string => {
  const dup = tcDupOf(key);
  return dup !== null ? `$ss$${dup.n}$${dup.name}` : key.startsWith("type ") ? `$ss$type$${key.slice(5)}` : key;
};

export const tcKeyOfVariable = () => (name: string): string => {
  const n = name.replace(/^viewof /, "");
  const m = /^\$ss\$(?<a>type|\d+)\$(?<b>[\w$]+)$/.exec(n);
  if (m === null) return n;
  const a = m.groups?.a ?? "", b = m.groups?.b ?? "";
  return a === "type" ? `type ${b}` : `${b} (${a})`;
};

// comment-types.ts langOf: the language a {lang:"..."} first comment names
export const tcLangOf = (tcFirstOf) => (js: string): string | null => {
  const first = tcFirstOf(js);
  const m = first === null ? null : /^\{lang:"(?<l>[a-z]+)"\}$/.exec(first);
  return m === null ? null : m.groups?.l ?? null;
};

// a declaration that is all type: cut whole
export const tcWholeType = (nodeKind) => (n: AstNode): boolean => {
  if (n.type === "TSTypeAliasDeclaration" || n.type === "TSInterfaceDeclaration" || n.type === "TSDeclareFunction") return true;
  if (n.type === "ImportDeclaration") return n.importKind === "type";
  return n.type === "ExportNamedDeclaration" && n.declaration !== null && nodeKind(n.declaration).startsWith("TS");
};

// where the cut of `x as T` starts. comment: after the `)`s closing a parenthesised operand and the `ss>` block comment closing a
// lowered JSX operand. erase: at the first token that is not a `)` (erase.ts reads this with a regex over the gap)
export const tcAsFrom = (tcLexed) => (ast: Ast, at: number, to: number, mode: string): number => {
  const toks = tcLexed(ast.src.slice(at, to), 1e9);
  if (mode === "erase") {
    const kw = toks.find((t) => t.label !== ")");
    return at + (kw === undefined ? to - at : kw.start);
  }
  let from = at;
  for (const c of ast.comments) if (c.start >= at && c.end <= to && c.text === "ss>") from = Math.max(from, c.end);
  for (const t of toks) if (t.label === ")") from = Math.max(from, at + t.end);
  return from;
};

// `<T>x`: from the `<` to the `>` after T
export const tcAssertionTo = (tcLexed) => (ast: Ast, typeEnd: number, exprStart: number): number => {
  const gt = tcLexed(ast.src.slice(typeEnd, exprStart), 1e9).find((t) => t.label === "</>/<=/>=");
  if (gt === undefined) throw new Error("unsupported: a <T>x assertion whose closing > was not found");
  return typeEnd + gt.end;
};

// the `?` of an optional name: the first token after the name
export const tcOptionalCut = (tcLexed) => (ast: Ast, from: number): TcEdit[] => {
  const t = tcLexed(ast.src.slice(from), 1)[0];
  return t !== undefined && t.label === "?" ? [{ from: from + t.start, to: from + t.end, text: "" }] : [];
};

// the cuts at one node and the nodes to walk next
export const tcCutNode = (tcCutKinds, tcWholeType, tcAsFrom, tcAssertionTo, tcOptionalCut, childrenOf, TYPE_FIELDS) => (ast: Ast, n: AstNode, mode: string): { readonly cuts: TcEdit[]; readonly next: AstNode[] } => {
  if (n.type === "Other" && tcCutKinds.has(n.kind)) throw new Error(`tc-gap: an Other node of kind ${n.kind}`);
  if (tcWholeType(n)) return { cuts: [{ from: n.start, to: n.end, text: "" }], next: [] };
  if (n.type === "TSAsExpression" || n.type === "TSSatisfiesExpression")
    return { cuts: [{ from: tcAsFrom(ast, n.expression.end, n.typeAnnotation.start, mode), to: n.end, text: "" }], next: [n.expression] };
  if (n.type === "TSNonNullExpression") return { cuts: [{ from: n.end - 1, to: n.end, text: "" }], next: [n.expression] };
  if (n.type === "TSTypeAssertion" && mode === "comment")
    return { cuts: [{ from: n.start, to: tcAssertionTo(ast, n.typeAnnotation.end, n.expression.start), text: "" }], next: [n.expression] };
  const cuts: Mut<TcEdit[]> = [];
  const next: Mut<AstNode[]> = [];
  if (n.type === "ExportNamedDeclaration" && n.declaration !== null) cuts.push({ from: n.start, to: n.declaration.start, text: "" });
  if (n.type === "Identifier" && n.optional === true) cuts.push(...tcOptionalCut(ast, n.start + n.name.length));
  for (const k of childrenOf(n)) {
    if (TYPE_FIELDS.has(k.key)) cuts.push({ from: k.node.start, to: k.node.end, text: "" });
    else next.push(k.node);
  }
  return { cuts: cuts, next: next };
};

// every cut of the tree, overlapping and touching spans merged, in order
export const tcCuts = (tcCutNode) => (ast: Ast, mode: string): TcEdit[] => {
  const all: Mut<TcEdit[]> = [];
  const todo: Mut<AstNode[]> = [ast.program];
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    const r = tcCutNode(ast, n, mode);
    all.push(...r.cuts);
    todo.push(...r.next);
  }
  const merged: Mut<TcEdit[]> = [];
  for (const c of all.toSorted((a, b) => a.from - b.from)) {
    const last = merged.at(-1);
    if (last !== undefined && c.from <= last.to) merged[merged.length - 1] = { from: last.from, to: Math.max(last.to, c.to), text: "" };
    else merged.push(c);
  }
  return merged;
};

// a source's typed tree (not TSX); the parser's error is thrown as it is
export const tcMustParse = (parseTree) => (src: string, jsx: boolean): Ast => {
  const p = parseTree(src, jsx);
  if (!p.ok) throw new Error(p.message);
  return p.ast;
};

// commentTypes, with the tree it parsed: types to `ss:` block comments
export const tcCommentTypes = (tcMustParse, tcCuts, tcApplyEdits, tcEsc, tcOPEN, tcLANG) => (src: string): { readonly text: string; readonly ast: Ast } => {
  if (src.includes(tcOPEN) || src.includes(tcLANG)) throw new Error("source contains a reserved marker");
  const ast = tcMustParse(src, false);
  const edits = tcCuts(ast, "comment").map((c) => ({ from: c.from, to: c.to, text: `${tcOPEN}${tcEsc(src.slice(c.from, c.to))}*/` }));
  return { text: tcApplyEdits(src, edits), ast };
};

// uncommentTypes: each `ss:T` block comment put back as T. On the typed parse, so a text that does not parse is not covered
export const tcUncommentTypes = (parseTree, tcApplyEdits, tcUnesc) => (js: string): string => {
  const p = parseTree(js, false);
  if (!p.ok) throw new Error(`tc-gap: uncommentTypes of a text that does not parse: ${p.message}`);
  return tcApplyEdits(js, p.ast.comments.filter((c) => c.block && c.text.startsWith("ss:")).map((c) => ({ from: c.start, to: c.end, text: tcUnesc(c.text.slice(3)) })));
};

// comment-types.ts decompile: the marker (the first comment) dropped, the types put back
export const tcDecompileTypes = (tcLangOf, tcLANG, tcUncommentTypes) => (js: string): string => {
  if (tcLangOf(js) !== "ss") throw new Error(`not SoundScript: the first comment must be ${tcLANG}`);
  const head = js.indexOf(tcLANG);
  return tcUncommentTypes(js.slice(0, head) + js.slice(head + tcLANG.length));
};

export const tcNotARef = () => (p: AstNode | null, n: AstNode): boolean => {
  if (p === null) return false;
  if (p.type === "MemberExpression") return !p.computed && p.property.nid === n.nid;
  if (p.type === "Property" || p.type === "MethodDefinition" || p.type === "PropertyDefinition") return !p.computed && p.key.nid === n.nid && (p.value === null || p.value.nid !== n.nid);
  return p.type === "LabeledStatement" || p.type === "BreakStatement" || p.type === "ContinueStatement";
};

// the start of each free reference to name in fn, in walk order
export const tcGlobalRefStarts = (tcNotARef, mdRebinds, kidsOf) => (fn: AstNode, name: string): number[] => {
  const out: Mut<number[]> = [];
  const todo: Mut<{ readonly n: AstNode; readonly p: AstNode | null }[]> = [{ n: fn, p: null }];
  for (let e = todo.pop(); e !== undefined; e = todo.pop()) {
    const n = e.n;
    if (mdRebinds(n, name)) continue;
    if (n.type === "Identifier" && n.name === name && !tcNotARef(e.p, n)) out.push(n.start);
    for (const k of kidsOf(n).toReversed()) todo.push({ n: k, p: n });
  }
  return out;
};

// the JSX elements and fragments not inside another, in source order
export const tcJsxRoots = (kidsOf) => (ast: Ast): AstNode[] => {
  const out: Mut<AstNode[]> = [];
  const todo: Mut<AstNode[]> = [ast.program];
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    if (n.type === "JSXElement" || n.type === "JSXFragment") { out.push(n); continue; }
    for (const k of kidsOf(n).toReversed()) todo.push(k);
  }
  return out;
};

// keepJsx: the function's text lowered, each `ss<` block comment rewritten to hold its element's original as kept text
export const tcKeepJsx = (tcMustParse, tcJsxRoots, tcLowered, tcKeep, tcApplyEdits, parseTree) => (fnSrc: string): string => {
  const s = `(${fnSrc})`;
  const originals = tcJsxRoots(tcMustParse(s, true)).map((n) => s.slice(n.start, n.end));
  const out = tcLowered(s, true);
  const p = parseTree(out, false);
  if (!p.ok) throw new Error(`tc-gap: the lowered JSX does not parse: ${p.message}`);
  const kept = p.ast.comments.filter((c) => c.block && c.text.startsWith("ss<"));
  if (kept.length !== originals.length) throw new Error("JSX originals and kept comments do not match");
  const edits = kept.map((c, i) => ({ from: c.start, to: c.end, text: `/*${"ss"}<${tcKeep(originals[i] ?? "")}*/` }));
  return tcApplyEdits(out, edits).slice(1, -1);
};

// ojsCell: `[viewof ]<name> = <body>` and the variables Observable's compiler makes of it; a viewof input is $0, $1, …
export const tcBuiltOf = (tcSTATE_VALUE) => (name: string, view: boolean, block: boolean, parts: TcPart[]): TcBuilt => {
  const order: Mut<string[]> = [];
  for (const p of parts) if (p.k !== "text" && !order.includes(p.input)) order.push(p.input);
  const inputs = order;
  const views: readonly string[] = inputs.filter((i) => i.startsWith("viewof "));
  const spell = (i: string) => (views.includes(i) ? `$${views.indexOf(i)}` : i);
  let text = "", js = "";
  for (const p of parts) {
    if (p.k === "text") { text += p.text; js += p.text; }
    else if (p.k === "in") { text += p.input; js += spell(p.input); }
  }
  const own = { name: view ? `viewof ${name}` : name, inputs, definition: `function _${name}(${inputs.map(spell).join(",")}) ${block ? js : `{return (${js});}`}` };
  return { text: `${own.name} = ${text}`, vars: view ? [own, { name, inputs: ["Generators", own.name], definition: tcSTATE_VALUE }] : [own], key: null, ref: false };
};

// a cell the checker does not accept: its source kept in the header; the definition only raises the messages
export const tcRejectedCell = (tcBuiltOf, tcVariableName, tcLANG, tcHeader, tcIn, tcT, tcR) => (text: string, key: string, why: string[], ref: boolean, IN: Map<string, string>): TcBuilt =>
  tcBuiltOf(tcVariableName(key), ref, false, [tcR(tcIn(IN, "rejected")), tcT(`(${tcLANG}${tcHeader({ d: text, rejected: why })}${JSON.stringify(key)}, ${JSON.stringify(why)}, `), tcR(tcIn(IN, "release")), tcT("(this))")]);

export const tcTypeCell = (tcBuiltOf, tcVariableName, tcLANG, tcHeader, tcT) => (text: string, id: AstNode): TcBuilt => {
  if (id.type !== "Identifier") throw new Error("tc-gap: a type declaration whose name is not an identifier");
  return tcBuiltOf(tcVariableName(`type ${id.name}`), false, false, [tcT(`void ${tcLANG}${tcHeader({ d: text })}0`)]);
};

// the cell's function: a function declaration, or the one const/let declarator's function initializer
export const tcFnOf = () => (d: AstNode | null): AstNode | null => {
  if (d === null) return null;
  if (d.type === "FunctionDeclaration") return d;
  if (d.type !== "VariableDeclaration" || d.kind === "var" || d.declarations.length !== 1) return null;
  const x = d.declarations[0];
  if (x === undefined || x.type !== "VariableDeclarator" || x.init === null) return null;
  return x.init.type === "ArrowFunctionExpression" || x.init.type === "FunctionExpression" ? x.init : null;
};

export const tcDeclaredIn = (tcIdName) => (d: AstNode | null): string | null => {
  if (d === null) return null;
  if (d.type === "FunctionDeclaration") return tcIdName(d.id);
  const x = d.type === "VariableDeclaration" ? d.declarations[0] : undefined;
  return x !== undefined && x.type === "VariableDeclarator" ? tcIdName(x.id) : null;
};

// erasesToJs: the TypeScript form commentTypes leaves in the code, named
export const tcModifierAt = (nodeKind) => (n: AstNode): string => {
  const prop = (k: string) => n.type === "Other" && n.props.some((p) => p.key === k && p.value !== null && p.value !== false && p.value !== 0 && p.value !== "");
  if ((n.type === "VariableDeclarator" && n.definite === true) || prop("definite")) return "definite assignment `!:`";
  const kind = nodeKind(n);
  if (kind === "TSParameterProperty") return "a parameter property";
  if (kind === "TSEnumDeclaration") return "enum";
  if (kind === "TSModuleDeclaration") return "namespace";
  const mod = (n.type === "ClassDeclaration" && n.abstract === true) || (n.type === "MethodDefinition" && (n.abstract === true || n.override === true)) ||
    (n.type === "PropertyDefinition" && n.override === true) || (n.type === "TSConstructorType" && n.abstract) ||
    ((n.type === "TSDeclareFunction" || n.type === "VariableDeclaration") && n.declare === true);
  return mod || prop("accessibility") || prop("abstract") || prop("declare") || prop("override") ? "a class member modifier" : "";
};

export const tcErasesToJs = (tcJsErrorOf, tcModifierAt, kidsOf) => (typed: string, fn: AstNode): void => {
  const err = tcJsErrorOf(`(${typed})`);
  if (err === null) return;
  const todo: Mut<AstNode[]> = [fn];
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    const what = tcModifierAt(n);
    if (what !== "") throw new Error(`unsupported: ${what} (${err})`);
    for (const k of kidsOf(n).toReversed()) todo.push(k);
  }
  throw new Error(`unsupported: TypeScript syntax that does not erase to JavaScript (${err})`);
};

// the globals the body reads, in order of first use
export const tcGlobalsInOrder = (tcGlobalRefStarts) => (prog: AstNode, names: string[]): string[] =>
  names.map((g) => ({ g, at: Math.min(...tcGlobalRefStarts(prog, g)) })).filter((x) => x.at < Infinity).toSorted((a, b) => a.at - b.at).map((x) => x.g);

// a parameter's argument: the State handle, a capability's input, compileFor over ss_compile, or a crossing
export const tcArgParts = (tcCaps, tcIn, tcT, tcR) => (p: TcParam, cell: string, refs: string[], IN: Map<string, string>, mod: string): TcPart[] => {
  const input = p.refTyped ? `viewof ${p.name}` : tcCaps.includes(p.name) ? tcIn(IN, p.name) : p.name;
  if (p.name === "compile")
    return [tcR(tcIn(IN, "compileFor")), tcT("("), tcR(input), tcT(`, ${JSON.stringify(cell)}, {`), ...refs.flatMap((x, i) => [tcT(`${i > 0 ? ", " : ""}${JSON.stringify(x)}: `), tcR(x)]), tcT("})")];
  const b = p.boundary;
  if (b === null) return [tcR(input)];
  const shape = JSON.stringify([b.shape]).slice(1, -1);
  if (b.ref) return [tcR(tcIn(IN, "viewRef")), tcT("("), tcR(input), tcT(`, ${shape}, ${JSON.stringify(p.name)})`)];
  return [tcR(tcIn(IN, "cross")), tcT("("), tcR(input), tcT(`, ${shape}, ${JSON.stringify(`${cell}.${p.name}`)}, ${mod})`)];
};

// the cell's expression, in text order: ref/events(this|module, name, [args], fn[, invalidation]), listen((fn)(args), …), or (fn)(args)
export const tcExprParts = (tcArgsParts, tcIn, tcT, tcR, tcM) => (kind: string, info: TcInfo, refs: string[], IN: Map<string, string>, mod: string, globals: string[], regs: string[], inner: string, mode: string): TcPart[] => {
  const args = tcArgsParts(info, refs, IN, mod), name = JSON.stringify(info.name), seen = [...globals, ...regs].map(tcM);
  if (kind === "ref" || kind === "events")
    return [tcR(tcIn(IN, kind)), tcT(`(${kind === "ref" ? "this" : mod}, ${name}, [`), ...args, tcT("], "), ...seen, tcT(inner), ...(kind === "events" ? [tcT(", "), tcR("invalidation")] : []), tcT(")")];
  // w1 (2026-11-24): the body runs under the guard runCells puts around a cell (freeze.ts out.run, out.cell)
  if (kind === "listener") return [tcR(tcIn(IN, "out")), tcT(".run(() => "), tcR(tcIn(IN, "listen")), tcT("("), ...seen, tcT(`(${inner})(`), ...args, tcT(`), ${name}, `), tcR("invalidation"), tcT(`, ${mod}))`)];
  // a plain cell's value is deep-frozen as it leaves the cell (freeze.ts out), y1: named, and with its mode (tcAssemble)
  return [tcR(tcIn(IN, "out")), tcT(".cell(() => "), ...seen, tcT(`(${inner})(`), ...args, tcT(`), ${name}${mode})`)];
};

// after the checks and the erasure: the inputs, the kind and the definition
export const tcAssemble = (tcPrelude, tcOjsInputGlobals, tcGlobalRefStarts, tcGlobalsInOrder, mdPreludeCalls, tcExprParts, tcBuiltOf, tcVariableName, tcLANG, tcHeader, tcIn, tcINPUTS, tcT, tcR, tcFnRegs, tcCastEdits, tcApplyEdits) =>
  (text: string, fn: AstNode, info: TcInfo, prog: AstNode, typed: string, ctx: TcCtx): TcBuilt => {
    const IN = ctx.inputs ?? tcINPUTS;
    const used = tcPrelude.filter((n) => tcGlobalRefStarts(prog, n).length > 0);
    // Map, Set and URL in the body are the runtime's freezable SsMap, SsSet and SsURL
    const classes: [string, string][] = [["Map", "SsMap"], ["Set", "SsSet"], ["URL", "SsURL"]];
    const bound: [string, string][] = [...used.filter((n) => tcIn(IN, n) !== n).map((n): [string, string] => [n, n]), ...classes.filter(([g]) => tcGlobalRefStarts(prog, g).length > 0)];
    const globals = tcGlobalsInOrder(prog, [...tcOjsInputGlobals, ...used.filter((n) => tcIn(IN, n) === n)]);
    const kind = info.returnsRef ? "ref" : info.generator && ctx.events.has(info.name) ? "events" : mdPreludeCalls(fn, "on").size > 0 ? "listener" : "cell";
    const refs = [...new Set(info.compiles.flatMap((s) => s.refs))];
    // each function the cell makes registers the locals it captures (fnreg.ts), in a re-parse of `(typed)`: prog is of the uncommented text
    const reg = tcFnRegs(typed, { closure: tcIn(IN, "closure"), methods: tcIn(IN, "methods"), out: tcIn(IN, "out") }, info.holes);
    const inner = `${tcLANG}${tcHeader({ h: text.slice(0, fn.start), t: text.slice(fn.end) })}${tcApplyEdits(typed, [...reg.edits, ...tcCastEdits(typed, info.casts)])}`;
    // y1 (2026-11-24): freeze.ts publishOut's mode when the check says the value type names no promise: 1, +2 async, +4 generator
    const mode = info.strict === true && (fn.type === "ArrowFunctionExpression" || fn.type === "FunctionExpression" || fn.type === "FunctionDeclaration")
      ? `, ${1 + (fn.async ? 2 : 0) + (fn.generator ? 4 : 0)}` : "";
    const expr = tcExprParts(kind, info, refs, IN, JSON.stringify(ctx.module), globals, reg.uses.map((u) => tcIn(IN, u)), inner, mode);
    const block = bound.length > 0;
    const parts = block ? [tcT("{ const "), ...bound.flatMap(([n, c], i) => [tcT(`${i > 0 ? ", " : ""}${n} = `), tcR(tcIn(IN, c))]), tcT("; return "), ...expr, tcT("; }")] : expr;
    const b = tcBuiltOf(tcVariableName(info.name), kind === "ref", block, parts);
    return { text: b.text, vars: b.vars, key: info.name, ref: kind === "ref" };
  };

// compileChecked: a cell the checker accepted (or one compiled with no module context)
export const tcCompileChecked = (tcMustParse, tcDeclOf, tcFnOf, tcDeclaredIn, tcIdName, tcTypeCell, tcStatementKinds, nodeKind, tcInfosOf, tcLowered, tcKeepJsx, tcCommentTypes, tcErasesToJs, tcAssemble, tcLANG) =>
  (text: string, tsx: boolean, ctx: TcCtx): TcBuilt => {
    for (const m of ["/*" + "ss", tcLANG]) if (text.includes(m)) throw new Error(`cell source contains the reserved text ${m}`);
    const prog = tcMustParse(text, tsx).program;
    const body = prog.type === "Program" ? prog.body : [];
    const st = body[0];
    if (body.length !== 1 || st === undefined) throw new Error("a cell is exactly one top-level statement");
    const d = tcDeclOf(st);
    if (st.type === "Other" && tcStatementKinds.has(st.kind)) throw new Error(`tc-gap: a top-level ${st.kind} met as an Other node`);
    if (d !== null && d.type === "Other" && tcStatementKinds.has(d.kind)) throw new Error(`tc-gap: a declaration ${d.kind} met as an Other node`);
    if (d !== null && (d.type === "TSTypeAliasDeclaration" || d.type === "TSInterfaceDeclaration")) return tcTypeCell(text, d.id);
    const fn = tcFnOf(d);
    if (d !== null && d.type === "VariableDeclaration" && d.declarations.length > 1)
      throw new Error(`one editor cell holds one cell; write ${d.declarations.map((x) => (x.type === "VariableDeclarator" ? tcIdName(x.id) ?? "" : "")).join(" and ")} as separate cells`);
    if (fn === null) throw new Error(`unsupported top-level statement (${nodeKind(st)}); a cell is a top-level function, const or let`);
    const declared = tcDeclaredIn(d);
    const info = (declared !== null && ctx.facts !== null ? ctx.facts.get(declared) : undefined) ?? tcInfosOf(tsx ? tcLowered(text, false) : text)[0];
    if (info === undefined) throw new Error("not a cell");
    const fnSrc = text.slice(fn.start, fn.end);
    const lowered = tsx ? tcKeepJsx(fnSrc) : fnSrc;
    const ct = tcCommentTypes(`(${lowered})`);
    const typed = ct.text.slice(1, -1);
    tcErasesToJs(typed, fn);
    return tcAssemble(text, fn, info, ct.ast.program, typed, ctx);
  };

export const tcTryCompile = (tcCompileChecked) => (text: string, tsx: boolean, ctx: TcCtx): { readonly built: TcBuilt | null; readonly err: unknown } => {
  try { return { built: tcCompileChecked(text, tsx, ctx), err: null }; } catch (e) { return { built: null, err: e }; }
};

// build: with a module context, a cell that does not parse, does not compile or is not accepted compiles to rejectedCell
export const tcBuild = (tcCompileChecked, tcTryCompile, tcRejectedCell, tcIsDuplicateKey, tcNameOf, tcINPUTS) => (text: string, tsx: boolean, ctx: TcCtx, nameHint: string | null): TcBuilt => {
  const accepted = ctx.accepted;
  if (accepted === null) return tcCompileChecked(text, tsx, ctx);
  const IN = ctx.inputs ?? tcINPUTS;
  const hinted = nameHint !== null && tcIsDuplicateKey(nameHint) && ctx.why !== null ? ctx.why.get(nameHint) : undefined;
  if (nameHint !== null && hinted !== undefined && tcNameOf(text) !== nameHint) return tcRejectedCell(text, nameHint, hinted, false, IN);
  const r = tcTryCompile(text, tsx, ctx);
  const out = r.built;
  if (out === null) {
    const msg = messageOf(r.err);
    const name = tcNameOf(text) ?? nameHint;
    if (msg.startsWith("tc-gap:") || name === null) throw r.err;
    return tcRejectedCell(text, name, (ctx.why !== null ? ctx.why.get(name) : undefined) ?? [`[compile] ${msg}`], false, IN);
  }
  if (out.key === null || accepted.has(out.key)) return out;
  return tcRejectedCell(text, out.key, (ctx.why !== null ? ctx.why.get(out.key) : undefined) ?? ["[rejected] not accepted by the checker"], out.ref, IN);
};

export const tcCompileModule = (tcSplitCells, tcContextOf, tcCompileCell) => (src: string, tsx: boolean, accepted: Set<string> | null): TcVar[] => {
  const texts = tcSplitCells(src, tsx);
  const ctx = tcContextOf(texts, tsx, accepted);
  return texts.flatMap((t) => tcCompileCell(t, tsx, ctx, null));
};

export const tcSplitCells = (tcMustParse, leadingComments) => (src: string, tsx: boolean): string[] => {
  const ast = tcMustParse(src, tsx);
  const out: Mut<string[]> = [];
  let end = 0;
  for (const st of ast.program.type === "Program" ? ast.program.body : []) {
    const first = leadingComments(ast, st.start)[0];
    const start = first !== undefined ? first.start : st.start;
    const decl = st.type === "ExportNamedDeclaration" ? st.declaration : st;
    const ds = decl !== null && decl.type === "VariableDeclaration" && decl.declarations.length > 1 ? decl.declarations : [];
    const d0 = ds[0];
    if (d0 === undefined) out.push(src.slice(start, st.end));
    for (let i = 0; i < ds.length; i++) {
      const d = ds[i];
      if (d !== undefined) out.push((i > 0 ? "" : src.slice(start, st.start)) + src.slice(st.start, d0 === undefined ? st.start : d0.start) + src.slice(d.start, d.end) + ";");
    }
    end = st.end;
  }
  if (ast.comments.some((c) => c.start >= end)) throw new Error("a comment after the last cell has no cell to belong to");
  return out;
};

export const tcContextOfFacts = () => (infos: TcInfo[], accepted: Set<string> | null, facts: Map<string, TcInfo> | null, why: Map<string, string[]> | null): TcCtx => {
  const generators = new Set(infos.filter((c) => c.generator).map((c) => c.name));
  const events = new Set(infos.flatMap((c) => c.params.filter((p) => p.eventsTyped && generators.has(p.name)).map((p) => p.name)));
  return { generators, events, accepted, facts, why, inputs: null, module: null };
};

// contextOf: the facts parsed from each text; a text whose facts do not parse gives none
export const tcContextOf = (tcInfosOf, tcLowered, tcContextOfFacts) => (texts: string[], tsx: boolean, accepted: Set<string> | null): TcCtx => {
  const infos: Mut<TcInfo[]> = [];
  for (const t of texts) {
    try { infos.push(...tcInfosOf(tsx ? tcLowered(t, false) : t)); } catch (e) { messageOf(e); }
  }
  return tcContextOfFacts(infos, accepted, null, null);
};

// the cells a check accepts: ok, with no errors, and parsed
export const tcAcceptedOf = () => (r: TcCheck): Set<string> =>
  new Set(r.cells.filter((c) => c.status === "ok" && c.errors.length === 0 && !(r.unparsed !== null && r.unparsed.has(c.name))).map((c) => c.name));

// a cell's own reasons for not being accepted, without line numbers
export const tcWhyOf = () => (r: TcCheck, c: TcCheckCell): string[] => {
  const parseMsg = r.unparsed !== null ? r.unparsed.get(c.name) : undefined;
  if (parseMsg !== undefined) return [`[parse] ${parseMsg}`];
  const out = [...c.errors.map((e) => `[${e.rule}] ${e.msg}`), ...c.unsupported.map((u) => `[unsupported] ${u.msg}`)];
  if (out.length === 0 && c.blockedBy.length > 0) return [`[blocked] ${c.blockedBy.join(", ")} has no usable type`];
  return out.length === 0 ? [`[${c.status}] not accepted by the checker`] : out;
};

export const tcContextFromCheck = (tcAcceptedOf, tcWhyOf, tcContextOfFacts) => (r: TcCheck): TcCtx => {
  const facts = r.facts;
  if (facts === null) throw new Error("this check result carries no cell facts");
  const accepted = tcAcceptedOf(r);
  const why = new Map(r.cells.filter((c) => !accepted.has(c.name)).map((c) => [c.name, tcWhyOf(r, c)]));
  return tcContextOfFacts([...facts.values()], accepted, facts, why);
};

// the names in takes whose state is not ok
export const tcNotOk = () => (out: Mut<Map<string, TcCellState>>, takes: string[]): string[] => {
  const by: Mut<string[]> = [];
  for (const n of takes) { const s = out.get(n); if (s === undefined || s.state !== "ok") by.push(n); }
  return by;
};

// ok; rejected (not accepted, or does not parse); blocked (a cell it takes is not ok), to a fixpoint
export const tcCellStates = (tcAcceptedOf, tcWhyOf, tcNotOk) => (r: TcCheck): Map<string, TcCellState> => {
  const accepted = tcAcceptedOf(r);
  const out: Mut<Map<string, TcCellState>> = new Map();
  const names = new Set(r.cells.map((c) => c.name));
  for (const c of r.cells) {
    const own = c.status === "blocked" && c.errors.length === 0 && c.unsupported.length === 0 && !(r.unparsed !== null && r.unparsed.has(c.name));
    const by = own ? c.blockedBy.filter((n) => names.has(n)) : [];
    out.set(c.name, accepted.has(c.name) ? { state: "ok", why: [], blockedBy: [] } : by.length > 0 ? { state: "blocked", why: [], blockedBy: by } : { state: "rejected", why: tcWhyOf(r, c), blockedBy: [] });
  }
  const keys = [...out.keys()];
  const has = new Set(keys);
  const takes = new Map([...(r.facts !== null ? r.facts.values() : [])].map((f) => [f.name, f.params.map((p) => p.name).filter((n) => has.has(n) && n !== f.name)]));
  for (let changed = true; changed; ) {
    changed = false;
    for (const name of keys) {
      const st = out.get(name);
      if (st === undefined || st.state === "rejected") continue;
      const by = [...new Set([...tcNotOk(out, takes.get(name) ?? []), ...(accepted.has(name) ? [] : st.blockedBy)])];
      if (by.length > 0 && (st.state !== "blocked" || by.join() !== st.blockedBy.join())) { out.set(name, { state: "blocked", why: [], blockedBy: by }); changed = true; }
    }
  }
  return out;
};

export const tcRtCall = (tcIn, tcINPUTS) => (n: AstNode | null, names: string[]): string | null => {
  if (n === null || n.type !== "CallExpression") return null;
  const c = n.callee;
  if (c.type !== "Identifier") return null;
  return names.find((x) => c.name === x || c.name === tcIn(tcINPUTS, x)) ?? null;
};

// the header's JSON: d (the whole source), h and t (the text around the function)
export const tcHeaderOf = () => (text: string): TcHeader => {
  const v = JSON.parse(text);
  const field = (k: string): string | null => {
    if (typeof v !== "object" || v === null || Array.isArray(v)) return null;
    const x = k === "d" ? ("d" in v ? v.d : null) : k === "h" ? ("h" in v ? v.h : null) : "t" in v ? v.t : null;
    return typeof x === "string" ? x : null;
  };
  return { d: field("d"), h: field("h"), t: field("t"), text };
};

// the call whose callee or an argument starts at pos, with the node around it
export const tcCallAt = (childrenOf) => (root: AstNode, pos: number): { readonly call: AstNode; readonly fn: AstNode; readonly up: AstNode | null } | null => {
  const todo: Mut<{ readonly n: AstNode; readonly up: AstNode | null }[]> = [{ n: root, up: null }];
  for (let e = todo.pop(); e !== undefined; e = todo.pop()) {
    const n = e.n;
    if (n.type === "CallExpression") {
      const a = n.callee.start === pos ? n.callee : n.arguments.find((x) => x.start === pos);
      if (a !== undefined) return { call: n, fn: a, up: e.up };
    }
    for (const k of childrenOf(n).toReversed()) todo.push({ n: k.node, up: n });
  }
  return null;
};

// outside the function: whether anything reads a runtime cell, and the ref names of compileFor(input, "name", {"ref": ref})
export const tcOutside = (tcRtCall, tcRuntimeInputs, childrenOf) => (root: AstNode, fnNid: number): { readonly ss: boolean; readonly refs: string[] } => {
  let ss = false;
  const refs: Mut<string[]> = [];
  const todo: Mut<AstNode[]> = [root];
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    if (n.nid === fnNid) continue;
    // the deep freeze every plain cell's value goes through (ss_out) does not make it take runtime cells
    if ((n.type === "Identifier" && tcRuntimeInputs.has(n.name) && tcRuntimeInputs.get(n.name) !== "out") || tcRtCall(n, ["cross", "viewRef", "compileFor"]) !== null) ss = true;
    const o = n.type === "CallExpression" && tcRtCall(n, ["compileFor"]) !== null ? n.arguments[2] : undefined;
    if (o !== undefined && o.type === "ObjectExpression")
      for (const p of o.properties) if (p.type === "Property" && p.key.type === "Literal") refs.push(String(p.key.value));
    for (const k of childrenOf(n).toReversed()) todo.push(k.node);
  }
  return { ss, refs: refs };
};

export const tcParseCompiled = (parseTree, tcLangOf, tcLANG, tcHeaderOf, tcCallAt, tcOutside, tcRtCall) => (definition: string): TcCompiled | null => {
  if (tcLangOf(definition) !== "ss") return null;
  const p = parseTree(`(${definition})`, false);
  if (!p.ok) throw new Error(`tc-gap: a definition the typed parse does not read: ${p.message}`);
  const cs = p.ast.comments;
  const at = cs.findIndex((c) => c.block && `/*${c.text}*/` === tcLANG);
  const mark = cs[at], head = cs[at + 1];
  if (mark === undefined) throw new Error("tc-gap: no block marker comment");
  if (head === undefined || head.start !== mark.end || !head.text.startsWith("ss^")) throw new Error("SoundScript variable without a header comment");
  const header = tcHeaderOf(head.text.slice(3));
  const found = tcCallAt(p.ast.program, head.end);
  const out = tcOutside(p.ast.program, found === null ? -1 : found.fn.nid);
  const comments = cs.map((c) => ({ block: c.block, text: c.text, start: c.start - 1, end: c.end - 1 }));
  if (found === null) return { comments, header, headerEnd: head.end - 1, fnEnd: -1, hasFn: false, callee: null, name: null, refs: out.refs };
  const { call, fn, up } = found;
  const calleeNid = call.type === "CallExpression" ? call.callee.nid : -1;
  const listen = fn.nid === calleeNid && up !== null && up.type === "CallExpression" && tcRtCall(up, ["listen"]) !== null && up.arguments[0] !== undefined && up.arguments[0].nid === call.nid ? up : null;
  const rt = tcRtCall(call, ["ref", "events", "rejected"]);
  const callee: TcShape | null = fn.nid === calleeNid ? (listen !== null ? "listen" : out.ss ? "apply" : "plain") : rt === "ref" ? "ref" : rt === "events" ? "events" : rt === "rejected" ? "rejected" : null;
  const holder = listen !== null ? listen : callee === "ref" || callee === "events" ? call : null;
  const named = holder !== null && holder.type === "CallExpression" ? holder.arguments[1] : undefined;
  const name = named !== undefined && named.type === "Literal" && typeof named.value === "string" ? named.value : null;
  return { comments, header, headerEnd: head.end - 1, fnEnd: fn.end - 1, hasFn: true, callee, name, refs: out.refs };
};

export const tcCompiledKind = (tcParseCompiled, tcKinds) => (definition: string): TcKind | null => {
  const p = tcParseCompiled(definition);
  return p === null || p.callee === null ? null : { callee: p.callee, kind: tcKinds.get(p.callee) ?? null, refs: p.refs };
};

// the cell source a variable holds: the header's d, or h + the function with each kept comment put back + t
export const tcDecompileVariable = (tcParseCompiled, tcUnesc, tcUnkeep) => (definition: string): string | null => {
  const p = tcParseCompiled(definition);
  if (p === null) return null;
  if (p.header.d !== null) return p.header.d;
  if (!p.hasFn) throw new Error("SoundScript variable whose marker opens no call");
  if (p.header.h === null || p.header.t === null) throw new Error("tc-gap: a header without h and t");
  let end = p.fnEnd;
  for (const c of p.comments) if (c.start === end && c.block && (c.text === "ss>" || c.text === "ss-" || c.text.startsWith("ss:"))) end = c.end;
  let out = "", at = p.headerEnd, inJsx = false, inReg = false;
  for (const c of p.comments) {
    if (c.start < p.headerEnd || c.end > end || !c.block) continue;
    if (inJsx) { if (c.text === "ss>") { inJsx = false; at = c.end; } continue; }
    // a closure registration (the comments ss+ ... ss-) is not source
    if (inReg) { if (c.text === "ss-") { inReg = false; at = c.end; } continue; }
    if (c.text === "ss+") { out += definition.slice(at, c.start); inReg = true; continue; }
    if (c.text.startsWith("ss<")) { out += definition.slice(at, c.start) + tcUnkeep(c.text.slice(3)); inJsx = true; }
    else if (c.text.startsWith("ss:")) { out += definition.slice(at, c.start) + tcUnesc(c.text.slice(3)); at = c.end; }
  }
  return p.header.h + out + definition.slice(at, end) + p.header.t;
};

export const tcDecompileModule = (tcDecompileVariable) => (definitions: string[]): string => {
  const out: Mut<string[]> = [];
  for (const d of definitions) { const s = tcDecompileVariable(d); if (s !== null) out.push(s); }
  return out.join("\n\n") + "\n";
};

// an array of string literals, or null
export const tcStrings = (tcLitStr) => (n: AstNode | null | undefined): string[] | null => {
  if (n === null || n === undefined || n.type !== "ArrayExpression") return null;
  const out: Mut<string[]> = [];
  for (const e of n.elements) { const s = tcLitStr(e); if (s === null) return null; out.push(s); }
  return out;
};

// one call of the module's define function: a $def(pid, name, inputs, _fn) variable, or an import main.define(name, ["module M", "@variable"], (_, v) => v.import(...))
export const tcModuleCall = (tcLitStr, tcStrings, tcPropName) => (n: AstNode, consts: Map<string, string>): { readonly v: TcModuleVar | null; readonly i: TcModuleImport | null } => {
  if (n.type !== "CallExpression") return { v: null, i: null };
  const [a0, a1, a2, a3] = n.arguments;
  if (n.callee.type === "Identifier" && n.callee.name === "$def" && a3 !== undefined && a3.type === "Identifier") {
    const pid = tcLitStr(a0), definition = consts.get(a3.name);
    if (pid === null || definition === undefined) throw new Error("tc-gap: a $def call without a string pid or a const definition");
    return { v: { pid, name: tcLitStr(a1), inputs: tcStrings(a2) ?? [], definition }, i: null };
  }
  const s = tcStrings(a1), m = s !== null ? s[0] : undefined;
  if (tcPropName(n.callee) !== "define" || s === null || s[1] !== "@variable" || m === undefined || !m.startsWith("module ")) return { v: null, i: null };
  const call = a2 !== undefined && a2.type === "ArrowFunctionExpression" ? a2.body : null;
  if (call === null || call.type !== "CallExpression" || tcPropName(call.callee) !== "import") return { v: null, i: null };
  const args: Mut<string[]> = [];
  for (const a of call.arguments) { const x = tcLitStr(a); if (x !== null) args.push(x); }
  const remote = args[0], local = args.at(-1);
  if (remote === undefined || local === undefined) throw new Error("tc-gap: an import call with no string argument");
  return { v: null, i: { from: m.slice(7), remote, local } };
};

export const tcModuleJs = (parseTree, tcModuleCall, childrenOf) => (src: string): { readonly variables: TcModuleVar[]; readonly imports: TcModuleImport[] } => {
  const p = parseTree(src, false);
  if (!p.ok) throw new Error(`tc-gap: a module the typed parse does not read: ${p.message}`);
  const body = p.ast.program.type === "Program" ? p.ast.program.body : [];
  const consts: Mut<Map<string, string>> = new Map();
  for (const st of body) if (st.type === "VariableDeclaration") for (const d of st.declarations) if (d.type === "VariableDeclarator" && d.id.type === "Identifier" && d.init !== null) consts.set(d.id.name, src.slice(d.init.start, d.init.end));
  const known = consts;
  const variables: Mut<TcModuleVar[]> = [], imports: Mut<TcModuleImport[]> = [];
  const todo: Mut<AstNode[]> = [];
  for (const st of body.toReversed()) if (st.type === "ExportDefaultDeclaration") todo.push(st.declaration);
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    const r = tcModuleCall(n, known);
    if (r.v !== null) variables.push(r.v);
    if (r.i !== null) imports.push(r.i);
    for (const k of childrenOf(n).toReversed()) todo.push(k.node);
  }
  return { variables: variables, imports: imports };
};

// throw Object.assign(new SyntaxError(message), {_sourceExpression: ...}): the message, or null
export const tcStubMessage = (tcPropName) => (n: AstNode): string | null => {
  const a = n.type === "ThrowStatement" ? n.argument : null;
  if (a === null || a.type !== "CallExpression" || a.callee.type !== "MemberExpression" || tcPropName(a.callee) !== "assign") return null;
  const o = a.callee.object, e = a.arguments[0], props = a.arguments[1];
  if (o.type !== "Identifier" || o.name !== "Object" || e === undefined || e.type !== "NewExpression" || e.callee.type !== "Identifier" || e.callee.name !== "SyntaxError") return null;
  if (props === undefined || props.type !== "ObjectExpression" || !props.properties.some((p) => p.type === "Property" && p.key.type === "Identifier" && p.key.name === "_sourceExpression")) return null;
  const m = e.arguments[0];
  return m !== undefined && m.type === "Literal" ? String(m.value) : "undefined";
};

export const tcSyntaxStub = (parseTree, tcStubMessage, childrenOf) => (definition: string): string | null => {
  const p = parseTree(`(${definition})`, false);
  if (!p.ok) throw new Error(`tc-gap: a definition the typed parse does not read: ${p.message}`);
  const todo: Mut<AstNode[]> = [p.ast.program];
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    const m = tcStubMessage(n);
    if (m !== null) return m;
    for (const k of childrenOf(n).toReversed()) todo.push(k.node);
  }
  return null;
};

// ownThis: `this` or `arguments` read by the function itself, not by a function or class body inside it
export const tcOwnThis = (childrenOf) => (body: AstNode): string | null => {
  const todo: Mut<AstNode[]> = [body];
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    if (n.type === "ThisExpression") return "this";
    if (n.type === "Identifier" && n.name === "arguments") return "arguments";
    if (n.type === "FunctionExpression" || n.type === "FunctionDeclaration" || n.type === "ClassBody") continue;
    for (const k of childrenOf(n).toReversed()) todo.push(k.node);
  }
  return null;
};

// `return (x);`: the span of the parentheses around the whole argument, from the tokens after `return`; null when none
export const tcReturnParens = (tcLexed) => (src: string, from: number, to: number): { readonly start: number; readonly end: number } | null => {
  const toks = tcLexed(src.slice(from, to), 1e9).slice(1);
  const region = toks.at(-1)?.label === ";" ? toks.slice(0, -1) : toks;
  const open = region[0], close = region.at(-1);
  if (open === undefined || close === undefined || open.label !== "(" || close.label !== ")") return null;
  let depth = 0;
  for (let i = 0; i < region.length; i++) {
    const t = region[i];
    if (t === undefined) continue;
    if (t.label === "(") depth++;
    if (t.label === ")") depth--;
    if (depth === 0) return i === region.length - 1 ? { start: from + open.start, end: from + close.end } : null;
  }
  return null;
};

// a candidate text reads back as one const of a function of the wanted kind whose body is the slice
export const tcReadsBack = (parseTree) => (text: string, generator: boolean, block: boolean): string | null => {
  const p = parseTree(text, true);
  if (!p.ok) return p.message;
  const st = p.ast.program.type === "Program" ? p.ast.program.body : [];
  const s0 = st[0], d0 = s0 !== undefined && s0.type === "VariableDeclaration" && s0.declarations.length === 1 ? s0.declarations[0] : undefined;
  const init = st.length === 1 && d0 !== undefined && d0.type === "VariableDeclarator" ? d0.init : null;
  const fn = init !== null && (generator ? init.type === "FunctionExpression" : init.type === "ArrowFunctionExpression") ? init : null;
  const bodyBlock = fn !== null && (fn.type === "FunctionExpression" || fn.type === "ArrowFunctionExpression") && fn.body.type === "BlockStatement";
  const ok = fn !== null && bodyBlock === block && s0 !== undefined && s0.end === text.length;
  return ok ? null : "it reads back as a different cell";
};

// why the variables have no SoundScript form, before the definition is read
export const tcObsRefusal = (tcIdentOk, tcRuntimeInputs, tcCaps, tcIn, tcINPUTS) => (vars: TcObsVar[]): string | null => {
  if (vars.length === 0) return "the text compiles to no variable";
  const names = vars.map((v) => v.name ?? "");
  if (names.some((n) => n.startsWith("viewof "))) return "a viewof cell has no SoundScript form";
  if (names.some((n) => n.startsWith("mutable ") || n.startsWith("initial "))) return "a mutable cell has no SoundScript form";
  if (names.some((n) => n.startsWith("module ")) || vars.some((v) => v.inputs.includes("@variable"))) return "an import has no SoundScript form";
  const v = vars[0];
  if (vars.length !== 1 || v === undefined) return `the text compiles to ${vars.length} variables; a SoundScript cell is one`;
  if (v.name === null || v.name === "") return "an anonymous cell has no SoundScript form; a SoundScript cell is named";
  if (!tcIdentOk(v.name)) return `the cell name ${v.name} is not an identifier`;
  const bad = v.inputs.find((i) => !tcIdentOk(i));
  if (bad !== undefined) return `the cell takes ${bad}, which a SoundScript parameter cannot name`;
  const rt = v.inputs.find((i) => tcRuntimeInputs.has(i));
  if (rt !== undefined) return `the cell takes ${rt}, the input compiled SoundScript cells take for the runtime's ${tcRuntimeInputs.get(rt) ?? ""}`;
  const cap = v.inputs.find((i) => tcCaps.includes(i) && tcIn(tcINPUTS, i) !== i);
  return cap !== undefined ? `the cell takes ${cap}, which as a SoundScript parameter is the ${cap} capability` : null;
};

// the definition as a function of its inputs that reads no `this`: its node in the parse of `(definition)`, or why not
export const tcObsFunction = (tcJsErrorOf, parseTree, tcOwnThis) => (definition: string, inputs: string[]): { readonly fn: AstNode | null; readonly src: string; readonly reason: string } => {
  const err = tcJsErrorOf(definition);
  if (err !== null) return { fn: null, src: "", reason: `the definition does not parse: ${err}` };
  const p = parseTree(`(${definition})`, false);
  if (!p.ok) throw new Error(`tc-gap: a definition the typed parse does not read: ${p.message}`);
  const s0 = p.ast.program.type === "Program" ? p.ast.program.body[0] : undefined;
  const fn = s0 !== undefined && s0.type === "ExpressionStatement" ? s0.expression : null;
  if (fn === null || fn.end !== definition.length + 1 || (fn.type !== "ArrowFunctionExpression" && fn.type !== "FunctionExpression")) return { fn: null, src: "", reason: "the definition is not a function" };
  if (fn.params.length !== inputs.length || fn.params.some((q, i) => q.type !== "Identifier" || q.name !== inputs[i])) return { fn: null, src: "", reason: "the definition's parameters are not its inputs" };
  const own = tcOwnThis(fn.body);
  return own !== null ? { fn: null, src: "", reason: `the definition reads ${own}, which a SoundScript cell's arrow function does not have` } : { fn, src: p.ast.src, reason: "" };
};

// the texts to try, in order: Observable's compiler writes an expression cell as {return (<expression>);}
export const tcObsCandidates = (tcReturnParens) => (fn: AstNode, src: string, head: string, params: string, expression: boolean | null): { readonly texts: string[]; readonly block: boolean } => {
  if (fn.type !== "ArrowFunctionExpression" && fn.type !== "FunctionExpression") return { texts: [], block: false };
  const body = fn.body, slice = (a: number, b: number) => src.slice(a, b);
  const r0 = body.type === "BlockStatement" && body.body.length === 1 ? body.body[0] : undefined;
  const ret = r0 !== undefined && r0.type === "ReturnStatement" && r0.argument !== null ? tcReturnParens(src, r0.start, r0.end) : null;
  const asExpr = ret !== null && expression !== false;
  const block = fn.generator || (body.type === "BlockStatement" && !asExpr);
  if (fn.generator) return { texts: [`${head}function* ${params} ${slice(body.start, body.end)};`], block };
  if (body.type !== "BlockStatement") return { texts: [`${head}${params} => ${slice(body.start, body.end)};`], block };
  if (ret !== null && asExpr) return { texts: [`${head}${params} => ${slice(ret.start + 1, ret.end - 1)};`, `${head}${params} => (${slice(ret.start + 1, ret.end - 1)});`], block };
  return { texts: [`${head}${params} => ${slice(body.start, body.end)};`], block };
};

export const tcFromObservableVariables = (tcObsRefusal, tcObsFunction, tcObsCandidates, tcReadsBack) => (vars: TcObsVar[], expression: boolean | null): TcTranslated => {
  const refused = tcObsRefusal(vars);
  const v = vars[0];
  if (refused !== null || v === undefined) return { text: null, reason: refused ?? "" };
  const f = tcObsFunction(v.definition, v.inputs);
  const fn = f.fn;
  if (fn === null || (fn.type !== "ArrowFunctionExpression" && fn.type !== "FunctionExpression")) return { text: null, reason: f.reason };
  const c = tcObsCandidates(fn, f.src, `const ${v.name ?? ""} = ${fn.async ? "async " : ""}`, `(${v.inputs.join(", ")})`, expression);
  let why = "";
  for (const text of c.texts) {
    const no = tcReadsBack(text, fn.generator, c.block);
    if (no === null) return { text, reason: null };
    why = no;
  }
  return { text: null, reason: `the translation does not parse as SoundScript: ${why}` };
};

// the names a binding pattern binds
export const tcPatNames = () => (p: AstNode | null): string[] => {
  const out: Mut<string[]> = [];
  const todo: Mut<(AstNode | null)[]> = [p];
  for (let q = todo.pop(); q !== undefined; q = todo.pop()) {
    if (q === null) continue;
    if (q.type === "Identifier") out.push(q.name);
    else if (q.type === "ObjectPattern") for (const x of q.properties) todo.push(x.type === "RestElement" ? x.argument : x.type === "Property" ? x.value : null);
    else if (q.type === "ArrayPattern") todo.push(...q.elements);
    else if (q.type === "AssignmentPattern") todo.push(q.left);
    else if (q.type === "RestElement") todo.push(q.argument);
  }
  return out;
};

// the names a list of statements declares at its own level (let, const, function; with vars, var anywhere below but not in a function)
export const tcLevelNames = (tcDeclNames, tcPatNames, kidsOf) => (body: AstNode[], vars: boolean): string[] => {
  const out: Mut<string[]> = [];
  for (const s of body) {
    if (s.type === "VariableDeclaration" && s.kind !== "var") out.push(...tcDeclNames(s.declarations));
    if (s.type === "FunctionDeclaration") out.push(...tcPatNames(s.id));
    if (!vars) continue;
    const todo: Mut<AstNode[]> = [s];
    for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
      if (n.type === "ArrowFunctionExpression" || n.type === "FunctionExpression" || n.type === "FunctionDeclaration") continue;
      if (n.type === "VariableDeclaration" && n.kind === "var") out.push(...tcDeclNames(n.declarations));
      todo.push(...kidsOf(n));
    }
  }
  return out;
};

// freeIn at a binding pattern: it binds its names and reads its defaults and computed keys
export const tcFreePat = () => (p: AstNode, b: Set<string>): TcFreeItem[] => {
  const x = (n: AstNode | null): TcFreeItem => ({ n, b, pat: false });
  const q = (n: AstNode | null): TcFreeItem => ({ n, b, pat: true });
  if (p.type === "Identifier") return [];
  if (p.type === "ObjectPattern") return p.properties.flatMap((r) => (r.type === "RestElement" ? [q(r.argument)] : r.type === "Property" ? [...(r.computed ? [x(r.key)] : []), q(r.value)] : []));
  if (p.type === "ArrayPattern") return p.elements.map(q);
  if (p.type === "AssignmentPattern") return [q(p.left), x(p.right)];
  if (p.type === "RestElement") return [q(p.argument)];
  return [x(p)];
};

// freeIn at a function: its parameters, its expression name and (for a block body) its body's level names and vars are bound
export const tcFreeFn = (tcPatNames, tcLevelNames, tcWith) => (n: AstNode, b: Set<string>): TcFreeItem[] => {
  if (n.type !== "ArrowFunctionExpression" && n.type !== "FunctionExpression" && n.type !== "FunctionDeclaration") return [];
  const own = n.type === "FunctionDeclaration" ? [] : tcPatNames(n.id);
  const pb = tcWith(b, [...n.params.flatMap((p) => tcPatNames(p)), ...own]);
  const ps = n.params.map((p): TcFreeItem => ({ n: p, b: pb, pat: true }));
  const body = n.body;
  if (body.type !== "BlockStatement") return [...ps, { n: body, b: pb, pat: false }];
  const bb = tcWith(pb, tcLevelNames(body.body, true));
  return [...ps, ...body.body.map((s): TcFreeItem => ({ n: s, b: bb, pat: false }))];
};

// freeIn at a block, a switch, a for or a catch clause: the names it binds; null at any other node
export const tcFreeScoped = (tcDeclNames, tcPatNames, tcLevelNames, tcWith, kidsOf) => (n: AstNode, b: Set<string>): TcFreeItem[] | null => {
  const x = (k: AstNode | null, s: Set<string>): TcFreeItem => ({ n: k, b: s, pat: false });
  if (n.type === "BlockStatement" || n.type === "StaticBlock") {
    const bb = tcWith(b, tcLevelNames(n.body, false));
    return n.body.map((s) => x(s, bb));
  }
  if (n.type === "SwitchStatement") {
    const cs = n.cases.flatMap((c) => (c.type === "SwitchCase" ? [c] : []));
    const bb = tcWith(b, tcLevelNames(cs.flatMap((c) => c.consequent), false));
    return [x(n.discriminant, b), ...cs.flatMap((c) => [x(c.test, bb), ...c.consequent.map((s) => x(s, bb))])];
  }
  if (n.type === "ForStatement" || n.type === "ForInStatement" || n.type === "ForOfStatement") {
    const head = n.type === "ForStatement" ? n.init : n.left;
    const bb = tcWith(b, head !== null && head.type === "VariableDeclaration" && head.kind !== "var" ? tcDeclNames(head.declarations) : []);
    return kidsOf(n).map((k) => x(k, bb));
  }
  if (n.type === "CatchClause") {
    const bb = tcWith(b, tcPatNames(n.param));
    return [{ n: n.param, b: bb, pat: true }, x(n.body, bb)];
  }
  return null;
};

// freeIn, one work item: the free name it reads, if any, and the items under it
export const tcFreeStep = (tcFreePat, tcFreeFn, tcFreeScoped, kidsOf) => (e: TcFreeItem): { readonly ref: string | null; readonly next: TcFreeItem[] } => {
  const n = e.n, b = e.b;
  const x = (k: AstNode | null): TcFreeItem => ({ n: k, b, pat: false });
  const go = (next: TcFreeItem[]) => ({ ref: null, next });
  if (n === null) return go([]);
  if (e.pat) return go(tcFreePat(n, b));
  if (n.type === "Identifier") return { ref: b.has(n.name) ? null : n.name, next: [] };
  if (n.type === "MemberExpression") return go([x(n.object), ...(n.computed ? [x(n.property)] : [])]);
  if (n.type === "Property") return go([...(n.computed ? [x(n.key)] : []), x(n.value)]);
  if (n.type === "LabeledStatement") return go([x(n.body)]);
  if (n.type === "BreakStatement" || n.type === "ContinueStatement" || n.type === "MetaProperty" || n.type === "ThisExpression" || n.type === "Super") return go([]);
  if (n.type === "ArrowFunctionExpression" || n.type === "FunctionExpression" || n.type === "FunctionDeclaration") return go(tcFreeFn(n, b));
  const scoped = tcFreeScoped(n, b);
  if (scoped !== null) return go(scoped);
  if (n.type === "VariableDeclarator") return go([{ n: n.id, b, pat: true }, x(n.init)]);
  if (n.type === "AssignmentExpression") return go([{ n: n.left, b, pat: n.left.type !== "Identifier" }, x(n.right)]);
  return go(kidsOf(n).map(x));
};

// the free names of a node: references no binding inside it declares
export const tcFreeIn = (tcFreeStep) => (root: AstNode): string[] => {
  const free: Mut<Set<string>> = new Set();
  const todo: Mut<TcFreeItem[]> = [{ n: root, b: new Set(), pat: false }];
  for (let e = todo.pop(); e !== undefined; e = todo.pop()) {
    const s = tcFreeStep(e);
    if (s.ref !== null) free.add(s.ref);
    todo.push(...s.next);
  }
  return [...free];
};

// the cell locals a function captures, sorted
export const tcRegCaps = (tcFreeIn) => (f: AstNode, locals: Set<string>): string[] =>
  tcFreeIn(f).filter((x) => locals.has(x)).toSorted((a, b) => (a < b ? -1 : a > b ? 1 : 0));

// (ss_i) => the i-th capture's current value; ss_i < 0: the count. e1 (2026-11-23): the parameter was i, which a
// capture named i read instead of itself; ss_i is a reserved name (messages.ss.ts emittedName), so no capture has it
export const tcThunk = () => (cs: string[]): string =>
  `(ss_i) => ss_i < 0 ? ${cs.length} : ${cs.slice(0, -1).map((c, i) => `ss_i === ${i} ? ${c} : `).join("")}${cs[cs.length - 1] ?? ""}`;

// a method's key as the object literal makes it (fnreg.ts keyOf): a BigInt literal's key is its value's digits in
// base 10, which the tree keeps as written (0x10n is "0x10"), so it is read through BigInt
export const tcRegKey = () => (k: AstNode): string =>
  k.type === "Identifier" ? k.name : k.type === "Literal" ? (k.bigint !== null ? String(BigInt(k.bigint)) : String(k.value)) : "";

// the names a node binds: a function's parameters and name, a declarator's, a catch clause's parameter
export const tcBindsAt = (tcPatNames) => (n: AstNode): string[] => {
  if (n.type === "ArrowFunctionExpression" || n.type === "FunctionExpression" || n.type === "FunctionDeclaration") return [...n.params.flatMap((p) => tcPatNames(p)), ...tcPatNames(n.id)];
  return n.type === "VariableDeclarator" ? tcPatNames(n.id) : n.type === "CatchClause" ? tcPatNames(n.param) : [];
};

// the cell function's nodes in preorder with their parents and depths, and the cell's locals: the names its inner
// functions, declarators and catch clauses bind, and a parameter of the cell function the cell assigns
export const tcRegWalk = (tcBindsAt, tcPatNames, kidsOf) => (cellFn: AstNode): { readonly all: TcRegNode[]; readonly locals: Set<string> } => {
  const all: Mut<TcRegNode[]> = [];
  const locals: Mut<Set<string>> = new Set(), assigned: Mut<Set<string>> = new Set();
  const todo: Mut<TcRegNode[]> = [{ n: cellFn, parent: null, depth: 0 }];
  for (let e = todo.pop(); e !== undefined; e = todo.pop()) {
    const n = e.n;
    all.push(e);
    if (n.nid !== cellFn.nid) for (const x of tcBindsAt(n)) locals.add(x);
    if (n.type === "AssignmentExpression" && n.left.type === "Identifier") assigned.add(n.left.name);
    if (n.type === "UpdateExpression" && n.argument.type === "Identifier") assigned.add(n.argument.name);
    for (const k of kidsOf(n).toReversed()) todo.push({ n: k, parent: n, depth: e.depth + 1 });
  }
  const own = cellFn.type === "ArrowFunctionExpression" || cellFn.type === "FunctionExpression" ? cellFn.params.flatMap((p) => tcPatNames(p)) : [];
  for (const p of own) if (assigned.has(p)) locals.add(p);
  return { all, locals };
};

// an object literal whose methods capture: ss_methods(obj, "m", thunk, ...)
export const tcRegMethods = (tcRegCaps, tcThunk, tcRegKey, tcREG_OPEN, tcREG_CLOSE) => (n: AstNode, depth: number, locals: Set<string>, names: TcRegNames): TcRegHit => {
  if (n.type !== "ObjectExpression") return { edits: [] };
  const ms = n.properties.flatMap((p) => (p.type === "Property" && p.method && !p.computed
    ? [{ key: tcRegKey(p.key), cs: tcRegCaps(p.value, locals), start: p.value.start }] : []));
  const reg = ms.filter((m) => m.cs.length > 0);
  if (reg.length === 0) return { edits: [] };
  const list = reg.map((m) => `${JSON.stringify(m.key)}, ${tcThunk(m.cs)}`).join(", ");
  const open: TcRegEdit = { at: n.start, depth, end: false, text: `${tcREG_OPEN}${names.methods}(${tcREG_CLOSE}`, use: "methods" };
  const close: TcRegEdit = { at: n.end, depth, end: true, text: `${tcREG_OPEN}, ${list})${tcREG_CLOSE}`, use: null };
  return { edits: [open, close] };
};

// the edits at one node of the walk: a capturing function (a declaration at the start of its block: it is hoisted)
export const tcRegAt = (tcRegMethods, tcRegCaps, tcThunk, tcREG_OPEN, tcREG_CLOSE) => (e: TcRegNode, locals: Set<string>, names: TcRegNames): TcRegHit => {
  const n = e.n, p = e.parent, depth = e.depth;
  if (p === null) return { edits: [] };
  if (n.type === "ObjectExpression") return tcRegMethods(n, depth, locals, names);
  if (n.type !== "ArrowFunctionExpression" && n.type !== "FunctionExpression" && n.type !== "FunctionDeclaration") return { edits: [] };
  // a method, getter or setter is registered by its object literal (ss_methods) or not at all
  if ((p.type === "Property" && (p.method || p.kind !== "init") && p.value.nid === n.nid) || p.type === "MethodDefinition") return { edits: [] };
  const cs = tcRegCaps(n, locals);
  if (cs.length === 0) return { edits: [] };
  const block = n.type === "FunctionDeclaration" && p.type === "BlockStatement";
  const at = block ? p.start + 1 : n.start;
  if (n.type === "FunctionDeclaration") {
    const id = n.id.type === "Identifier" ? n.id.name : "";
    return { edits: [{ at, depth: block ? depth : depth - 1, end: false, text: `${tcREG_OPEN}${names.closure}(${id}, ${tcThunk(cs)});${tcREG_CLOSE}`, use: "closure" }] };
  }
  const open: TcRegEdit = { at: n.start, depth, end: false, text: `${tcREG_OPEN}${names.closure}(${tcREG_CLOSE}`, use: "closure" };
  return { edits: [open, { at: n.end, depth, end: true, text: `${tcREG_OPEN}, ${tcThunk(cs)})${tcREG_CLOSE}`, use: null }] };
};

// e1 (2026-11-23), S9.8: each call of the prelude's cast gets its type's shape as a second argument, the shapes the
// check kept in source order. With no shapes (a cell compiled without its check) there is no edit, and cast fails each
// value; a count that differs from the calls is a gap, so no call is given another call's shape
export const tcCastEdits = (parseTree, tcGlobalRefStarts, kidsOf, tcREG_OPEN, tcREG_CLOSE) => (typed: string, shapes: readonly unknown[]): TcEdit[] => {
  if (shapes.length === 0) return [];
  const p = parseTree(`(${typed})`, false);
  if (!p.ok) throw new Error(`tc-gap: a typed cell function that does not parse: ${p.message}`);
  const free = new Set(tcGlobalRefStarts(p.ast.program, "cast"));
  const calls: Mut<AstNode[]> = [];
  const todo: Mut<AstNode[]> = [p.ast.program];
  for (let n = todo.pop(); n !== undefined; n = todo.pop()) {
    if (n.type === "CallExpression" && n.callee.type === "Identifier" && free.has(n.callee.start)) calls.push(n);
    for (const k of kidsOf(n)) todo.push(k);
  }
  if (calls.length !== free.size || calls.length !== shapes.length) throw new Error(`tc-gap: ${free.size} references to cast, ${calls.length} of them calls, and ${shapes.length} shapes from the check`);
  return calls.toSorted((a, b) => (a.type === "CallExpression" && b.type === "CallExpression" ? a.callee.start - b.callee.start : 0)).map((c, i) => {
    const end = c.type === "CallExpression" ? (c.arguments.at(-1) ?? c.callee).end : c.end;
    return { from: end - 1, to: end - 1, text: `${tcREG_OPEN}, ${JSON.stringify([shapes[i]]).slice(1, -1)}${tcREG_CLOSE}` };
  });
};

// x1 (2026-11-24): fnreg.ts guardEdits over the typed tree, the async guard (freeze.ts guardAsync): each async
// function's body declares ss_g; each await, and each yield of an async generator, leaves and resumes it; each argument
// of a call of a member named then or finally is bound. Depth k + 0.5 encloses the edits tcRegAt makes at the same position
export const tcGuardEdits = (kidsOf, tcREG_OPEN, tcREG_CLOSE) => (cellFn: AstNode, o: string): TcRegEdit[] => {
  const wrap = (a: AstNode, depth: number, open: string, close: string): TcRegEdit[] =>
    [{ at: a.start, depth, end: false, text: tcREG_OPEN + open + tcREG_CLOSE, use: "out" }, { at: a.end, depth, end: true, text: tcREG_OPEN + close + tcREG_CLOSE, use: null }];
  const ed: Mut<TcRegEdit[]> = [];
  const todo: Mut<{ readonly n: AstNode; readonly inAsync: boolean; readonly depth: number }[]> = [{ n: cellFn, inAsync: false, depth: 0 }];
  for (let e = todo.pop(); e !== undefined; e = todo.pop()) {
    const n = e.n, d = e.depth;
    const fn = n.type === "ArrowFunctionExpression" || n.type === "FunctionExpression" || n.type === "FunctionDeclaration" ? n : null;
    if (fn !== null && fn.async && fn.body.type !== "BlockStatement") ed.push(...wrap(fn.body, d + 0.5, `(async () => { const ss_g = ${o}.enter(); try { return (`, `); } finally { ${o}.exit(ss_g); } })()`));
    else if (fn !== null && fn.async && fn.body.type === "BlockStatement" && fn.body.body.length > 0)
      ed.push({ at: fn.body.start + 1, depth: d + 0.5, end: false, text: `${tcREG_OPEN}const ss_g = ${o}.enter(); try {${tcREG_CLOSE}`, use: "out" }, { at: fn.body.end - 1, depth: d + 0.5, end: true, text: `${tcREG_OPEN}} finally { ${o}.exit(ss_g); }${tcREG_CLOSE}`, use: null });
    if (n.type === "AwaitExpression") ed.push(...wrap(n, d, `${o}.back(ss_g, `, ")"), ...wrap(n.argument, d + 0.5, `${o}.away(ss_g, `, ")"));
    if (n.type === "YieldExpression" && e.inAsync) ed.push(...wrap(n, d, `${o}.resumed(ss_g, `, ")"), ...wrap(n.argument, d + 0.5, `${o}.left(ss_g, ${o}.back(ss_g, await ${o}.away(ss_g, `, ")))"));
    // a yield with no operand is an Other node of the tree
    if (n.type === "Other" && n.kind === "YieldExpression" && e.inAsync) ed.push(...wrap(n, d, `${o}.resumed(ss_g, `, ` ${o}.left(ss_g, void 0))`));
    const m = n.type === "CallExpression" && n.callee.type === "MemberExpression" ? n.callee : null, key = m === null ? null : m.property;
    if (n.type === "CallExpression" && m !== null && key !== null && (m.computed ? key.type === "Literal" && (key.value === "then" || key.value === "finally") : key.type === "Identifier" && (key.name === "then" || key.name === "finally")))
      for (const a of n.arguments) if (a.type !== "SpreadElement") ed.push(...wrap(a, d + 0.5, `${o}.bind(`, ")"));
    for (const k of kidsOf(n).toReversed()) todo.push({ n: k, inAsync: fn !== null ? fn.async : e.inAsync, depth: d + 1 });
  }
  return ed;
};

// open part 6 (HO, S3.21): the index and length writes of a typed cell function (the checker's ixHoleSite targets), in
// the order of their targets, each with its depth in the tree as tcGuardEdits counts it
export const tcHoleSites = (kidsOf) => (cellFn: AstNode): TcHoleSite[] => {
  const out: Mut<TcHoleSite[]> = [];
  const todo: Mut<{ readonly n: AstNode; readonly depth: number }[]> = [{ n: cellFn, depth: 0 }];
  for (let e = todo.pop(); e !== undefined; e = todo.pop()) {
    const n = e.n, t = n.type === "AssignmentExpression" ? n.left : n.type === "UpdateExpression" ? n.argument : null;
    if (t !== null && t.type === "MemberExpression" && (t.computed || (t.property.type === "Identifier" && t.property.name === "length"))) out.push({ n, t, depth: e.depth });
    for (const k of kidsOf(n)) todo.push({ n: k, depth: e.depth + 1 });
  }
  return out.toSorted((a, b) => a.t.start - b.t.start);
};

// the tokens of src between from and to, at their positions in src
export const tcTokensIn = (tcLexed) => (src: string, from: number, to: number): TcToken[] =>
  tcLexed(src.slice(from, to), 1e9).map((k) => ({ label: k.label, start: k.start + from, end: k.end + from }));

// one write as a call of freeze.ts holeWrites: R[I] = V is o.put(R, I, V), R[I] op= V o.putOp(o.at(R, I), "op", V), R[I]++
// o.putUp(R, I, 1, false), and R.length the same with putLen, lenAt and putLenUp. Each token the call replaces is kept
// in an ss: comment, so the source reads back; a comment or a parenthesis among them is not compiled
export const tcHoleEdit = (tcTokensIn, tcREG_OPEN, tcREG_CLOSE) => (src: string, comments: AstComment[], s: TcHoleSite, o: string): TcRegEdit[] => {
  const n = s.n, t = s.t, d = s.depth, add = (x: string) => (x === "" ? "" : tcREG_OPEN + x + tcREG_CLOSE);
  if (t.type !== "MemberExpression" || (n.type !== "AssignmentExpression" && n.type !== "UpdateExpression")) return [];
  const len = !t.computed || (t.property.type === "Literal" && t.property.value === "length"), pre = n.type === "UpdateExpression" && n.prefix;
  const toks = tcTokensIn(src, t.object.end, n.type === "AssignmentExpression" ? n.right.start : n.end), rb = toks.find((k) => k.label === "]" && k.start >= t.property.end);
  const lb = toks.find((k) => k.label === "[" || (len && k.label === ".")) ?? { start: -1, end: -1 }, hide = "/*" + "ss:";
  const opTok = toks.find((k) => k.start >= t.end && k.label !== ")");
  const opEnd = pre ? n.end : opTok !== undefined && ["=", "_=", "++/--"].includes(opTok.label) ? opTok.end : -1, cut = len ? lb.start : rb?.start ?? -1;
  const ok = (a: number, b: number, n0: number) => a >= 0 && tcTokensIn(src, a, b).length === n0 && !comments.some((c) => c.end > a && c.start < b);
  // open part 7: a parenthesized target, (xs[0]) = 2, has its parentheses kept in the ss: comments
  const lead = tcTokensIn(src, n.start, t.start), opens = lead.filter((k) => k.label === "(").length;
  if (cut < 0 || opEnd < 0 || !ok(cut, opEnd, (len && t.computed ? 3 : len ? 2 : 1) + (pre ? 0 : 1) + opens) || lead.length !== opens + (pre ? 1 : 0))
    throw new Error("tc-gap: an index or length write with a comment among its tokens");
  const op = n.type === "AssignmentExpression" ? n.operator : "", up = n.type === "UpdateExpression" ? `, ${n.operator === "++" ? 1 : -1}, ${pre})` : "";
  const fn = op === "=" ? (len ? "putLen(" : "put(") : op !== "" ? `putOp(${o}.${len ? "lenAt" : "at"}(` : len ? "putLenUp(" : "putUp(";
  const mid = op === "=" ? ", " : op !== "" ? `), ${JSON.stringify(op.slice(0, -1))}, ` : "";
  const e = (at: number, end: boolean, text: string, use: string | null = null): TcRegEdit => ({ at, depth: d, end, text, use });
  const head = lead.length > 0 ? [e(n.start, false, hide), e(t.start, false, "*/" + add(`${o}.${fn}`), "out")] : [e(n.start, false, add(`${o}.${fn}`), "out")];
  const index = len ? [] : [e(lb.start, true, hide), e(lb.end, true, "*/" + add(", "))];
  return [...head, ...index, e(cut, true, add(mid) + hide), e(opEnd, true, "*/" + add(up)), ...(op === "" ? [] : [e(n.end, true, add(")"))])];
};

// the registrations of a typed cell function, as edits to its text in their final order (at one position: ends deepest
// first, then starts outermost first), and the runtime cells they call, in the order closure, methods
export const tcFnRegs = (parseTree, tcRegWalk, tcRegAt, tcGuardEdits, tcHoleSites, tcHoleEdit) => (typed: string, names: TcRegNames, holes: readonly boolean[]): TcRegs => {
  const p = parseTree(`(${typed})`, false);
  if (!p.ok) throw new Error(`tc-gap: a typed cell function that does not parse: ${p.message}`);
  const prog = p.ast.program;
  const st = prog.type === "Program" ? prog.body[0] : undefined;
  if (st === undefined || st.type !== "ExpressionStatement") throw new Error("tc-gap: a typed cell function that is not one expression");
  const w = tcRegWalk(st.expression);
  const hits = w.all.map((e) => tcRegAt(e, w.locals, names));
  const guard = names.out === undefined ? [] : tcGuardEdits(st.expression, names.out);
  // open part 6 (HO): each index or length write the check marks (every one when the marks do not match the writes)
  const sites = names.out === undefined ? [] : tcHoleSites(st.expression), o = names.out ?? "";
  const ho = sites.flatMap((h, i) => (sites.length === holes.length && holes[i] === false ? [] : tcHoleEdit(p.ast.src, p.ast.comments, h, o)));
  const es = [...hits.flatMap((h) => h.edits), ...guard, ...ho]
    .toSorted((a, b) => a.at - b.at || (a.end === b.end ? (a.end ? b.depth - a.depth : a.depth - b.depth) : a.end ? -1 : 1));
  const uses = ["closure", "methods", "out"].filter((u) => es.some((e) => e.use === u));
  return { edits: es.map((e) => ({ from: e.at - 1, to: e.at - 1, text: e.text })), uses };
};

export type Shape =
  | { k: "num" } | { k: "str" } | { k: "bool" } | { k: "null" } | { k: "undef" } | { k: "unknown" }
  | { k: "lit"; v: string | number | boolean }
  | { k: "arr"; el: Shape }
  | { k: "tup"; els: Shape[] }
  | { k: "rec"; props: [string, Shape, boolean][] }
  | { k: "union"; ts: Shape[] }
  // a recursive alias: a ref names its definition, and defs, at the top of a shape, lists each definition once
  | { k: "ref"; n: string }
  | { k: "defs"; defs: [string, Shape][]; body: Shape }
  // a function from another language, only as the whole of a parameter's shape: its parameters' shapes and its result's
  | { k: "fn"; ps: Shape[]; ret: Shape; async: boolean };

// the ownership built-ins, which the checker gives their meaning: at run time mut returns its argument; freeze (a deep
// freeze) and borrow (which marks a lent value so a yield does not freeze it) are unchecked cells of ./freeze.ts
export const mut = () => <T,>(v: T): T => v;

// what a value of a shape is, for a mismatch message (boundary.ts copy)
export const want = () => {
  const w = (s: Shape): string => {
    switch (s.k) {
      case "num": return "number"; case "str": return "string"; case "bool": return "boolean";
      case "null": return "null"; case "undef": return "undefined"; case "unknown": return "data";
      case "lit": return JSON.stringify(s.v);
      case "arr": return "an array"; case "tup": return `an array of ${s.els.length}`;
      // a9 (2026-11-23): a record names its first members, so two members of a union read apart
      case "rec": {
        const inner = (x: Shape): string => (x.k === "rec" ? "{…}" : x.k === "union" ? x.ts.map(inner).join(" | ") : w(x));
        return s.props.length === 0 ? "an object" : `an object { ${s.props.slice(0, 4).map(([k, p, o]) => `${k}${o ? "?" : ""}: ${inner(p)}`).join(", ")}${s.props.length > 4 ? ", …" : ""} }`;
      }
      case "union": return s.ts.map(w).join(" or ");
      case "ref": return s.n;
      case "defs": return w(s.body);
      case "fn": return "a function";
    }
  };
  return w;
};

// two copies the boundary made are equal: the same own keys, and equal values under each (boundary.ts cross)
export const deepEqual = () => {
  const eq = (a: Data, b: Data): boolean => {
    if (Object.is(a, b)) return true;
    if (a === null || b === null || typeof a !== "object" || typeof b !== "object") return false;
    const ka = Object.keys(a), kb = new Set(Object.keys(b));
    if (ka.length !== kb.size || !ka.every((k) => kb.has(k))) return false;
    if (Array.isArray(a)) return Array.isArray(b) && ka.every((k) => eq(a[Number(k)], b[Number(k)]));
    // d1 (2026-11-24): own entries through a Map, since a run-time key on a record may name an inherited member
    if (Array.isArray(b)) return false;
    const mb = new Map(Object.entries(b));
    return Object.entries(a).every(([k, v]) => mb.has(k) && eq(v, mb.get(k)));
  };
  return eq;
};

// JSX children flattened: nested arrays spread, null, undefined and booleans dropped (jsx/h.ts)
export const flat = () => {
  const f = (xs: readonly unknown[]): unknown[] =>
    xs.flatMap((x) => (Array.isArray(x) ? f(x) : x === null || x === undefined || x === false || x === true ? [] : [x]));
  return f;
};

// each event prop: the DOM event and the arguments its action is called with
export const DOM_EVENTS = (ptr: (e: PointerLike) => Ptr): { readonly [k: string]: readonly [string, (e: PointerLike, node: { readonly value?: unknown }) => readonly unknown[]] } => ({
  onClick: ["click", () => []],
  onInput: ["input", (_e: PointerLike, node: { readonly value?: unknown }) => [String(node.value)]],
  onPointerDown: ["pointerdown", (e: PointerLike) => [ptr(e)]],
  onPointerMove: ["pointermove", (e: PointerLike) => [ptr(e)]],
  onPointerUp: ["pointerup", (e: PointerLike) => [ptr(e)]],
  onPointerCancel: ["pointercancel", (e: PointerLike) => [ptr(e)]],
});

// The listeners of one events cell in the order they run, from the places the host
// gives: places[0] is the events cell's, places[i + 1] list[i]'s. complete: every listener is placed, so the
// order may be kept until the cells change.
export const orderKeyed = () => <L,>(list: readonly L[], places: readonly Place[]): { out: L[]; complete: boolean } => {
  const own = places[0] ?? null;
  const key = (p: Place): readonly [number, string, number] | null => (p === null ? null : [own !== null && p[0] === own[0] ? 0 : 1, p[0], p[1]]);
  const keyed = list.map((l, i) => ({ l, i, k: key(places[i + 1] ?? null) }));
  const sorted = keyed.toSorted((a, b) => {
    const ak = a.k, bk = b.k;
    if (ak === null || bk === null) return ak !== null ? -1 : bk !== null ? 1 : a.i - b.i;
    return ak[0] - bk[0] || (ak[1] < bk[1] ? -1 : ak[1] > bk[1] ? 1 : 0) || ak[2] - bk[2] || a.i - b.i;
  });
  return { out: sorted.map((x) => x.l), complete: own !== null && keyed.every((x) => x.k !== null) };
};

// The body of a cell the checker did not accept: it raises the checker's messages and runs nothing else.
export const rejected = () => (name: string, why: readonly string[]): never => {
  throw new Error(`${name} does not check: ${why.join("; ")}`);
};

// compile for the calling cell, from the module's ss_compile (stdlib/runtime.ts compiler)
export const compileFor = () => (c: Compiler | null | undefined, caller: string, refs: { readonly [k: string]: unknown }): unknown => {
  if (c === null || c === undefined || typeof c.for !== "function") throw new Error(`${caller} takes compile, and this module defines no ss_compile = ss.compiler(...)`);
  return c.for(caller, refs);
};

export type EventsRecord = {
  readonly key: string; readonly name: string; readonly args: readonly unknown[] | null; readonly make: string;
  readonly hasGenerator: boolean; readonly epoch: number; readonly done: boolean;
  readonly busy: boolean; readonly pending: boolean; readonly born: number | null;
  readonly listeners: readonly number[]; readonly order: readonly number[] | null;
  readonly queue: readonly unknown[]; readonly draining: boolean; readonly current: unknown; readonly toCall: readonly number[];
};

export type Delivery = {
  readonly handles: Map<number, EventsRecord>; readonly handleAt: Map<string, number>;
  readonly listeners: Map<number, ListenerRecord>; readonly listenerAt: Map<string, number>;
  readonly placer: boolean; readonly generation: number;
};

export type DeliveryEvent =
  | OpenEvent | RunEvent | ListenEvent | ListenerInvalidated | Result | Failure | PlacedEvent | SweepEvent
  | { readonly t: "eventsInvalidated" | "awaiting" | "schedule" | "deliver" | "placeFailed" | "releaseEvents"; readonly hid: number }
  | { readonly t: "pull"; readonly hid: number; readonly epoch: number }
  | { readonly t: "orderChanged"; readonly placer: boolean }
  | { readonly t: "releaseListener"; readonly lid: number }
  | { readonly t: "releaseAction"; readonly aid: number };

export type Effect =
  | { readonly fx: "frame" | "next"; readonly hid: number; readonly epoch: number }
  | { readonly fx: "return" | "make" | "forgetHandle"; readonly hid: number }
  | { readonly fx: "call"; readonly lid: number; readonly value: unknown; readonly cell: string; readonly events: string }
  | { readonly fx: "place"; readonly hid: number; readonly lids: readonly number[] }
  | { readonly fx: "fail"; readonly name: string; readonly error: unknown }
  | { readonly fx: "then"; readonly ev: DeliveryEvent }
  | { readonly fx: "forgetListener"; readonly lid: number };

export const newEventsRecord = () => (key: string, name: string): EventsRecord => ({
  key, name, args: null, make: "", hasGenerator: false, epoch: 0, done: false, busy: false, pending: false, born: null,
  listeners: [], order: null, queue: [], draining: false, current: undefined, toCall: [],
});

// the first listener still to call that is still attached, and those after it
export const nextListener = () => (h: EventsRecord, listeners: Listeners): { readonly lid: number | null; readonly rest: readonly number[] } => {
  let i = 0;
  for (const lid of h.toCall) {
    i++;
    if (listeners.has(lid) && h.listeners.includes(lid)) return { lid, rest: h.toCall.slice(i) };
  }
  return { lid: null, rest: [] };
};

// one that no variable holds is marked at its first sweep and released at the next (it may be a value the runtime
// has not assigned yet); a parked one was a value, so it is released at once
export const sweepVerdict = () => (held: boolean, parked: boolean, born: number | null, generation: number): Verdict =>
  held ? "spare" : parked ? "release" : born === null ? "mark" : born < generation ? "release" : "keep";

export const schedulePull = (wantsValues) => (handles: Handles, fx: Effects, hid: number): void => {
  const h = handles.get(hid);
  if (h === undefined || h.busy || !wantsValues(h)) return;
  handles.set(hid, { ...h, busy: true });
  fx.push({ fx: "frame", hid, epoch: h.epoch });
};

export const stopGenerator = () => (handles: Handles, fx: Effects, hid: number, h: EventsRecord): void => {
  if (h.hasGenerator) fx.push({ fx: "return", hid });
  handles.set(hid, { ...h, hasGenerator: false, args: null, epoch: h.epoch + 1, queue: [] });
};

export const queueValue = () => (handles: Handles, fx: Effects, hid: number, h: EventsRecord, v: unknown): void => {
  handles.set(hid, { ...h, queue: [...h.queue, v], draining: true });
  if (!h.draining) fx.push({ fx: "then", ev: { t: "deliver", hid } });
};

export const failGenerator = (isStaleResult) => (handles: Handles, fx: Effects, hid: number, epoch: number, error: unknown): void => {
  const h = handles.get(hid);
  if (h === undefined || isStaleResult(h, epoch)) return;
  fx.push({ fx: "fail", name: h.name, error });
  handles.set(hid, { ...h, done: true });
};

export const detachListener = () => (handles: Handles, listeners: Listeners, listenerAt: Keys, fx: Effects, lid: number): void => {
  const l = listeners.get(lid);
  if (l === undefined) return;
  const h = handles.get(l.hid);
  if (h !== undefined) handles.set(l.hid, { ...h, listeners: h.listeners.filter((x) => x !== lid), order: null });
  if (listenerAt.get(l.key) === lid) listenerAt.delete(l.key);
  listeners.delete(lid);
  fx.push({ fx: "forgetListener", lid });
};

export const releaseHandle = (stopGenerator, detachListener) => (handles: Handles, handleAt: Keys, listeners: Listeners, listenerAt: Keys, fx: Effects, hid: number): void => {
  const h = handles.get(hid);
  if (h === undefined) return;
  stopGenerator(handles, fx, hid, h);
  if (handleAt.get(h.key) === hid) handleAt.delete(h.key);
  for (const lid of h.listeners) detachListener(handles, listeners, listenerAt, fx, lid);
  handles.delete(hid);
  fx.push({ fx: "forgetHandle", hid });
};

// one listener call is one effect, so the next is decided after it ran; false when no listener is left for this value
export const callNextListener = (nextListener) => (handles: Handles, listeners: Listeners, fx: Effects, hid: number, h: EventsRecord): boolean => {
  const n = nextListener(h, listeners);
  const l = n.lid === null ? undefined : listeners.get(n.lid);
  if (n.lid === null || l === undefined) return false;
  handles.set(hid, { ...h, toCall: n.rest });
  fx.push({ fx: "call", lid: n.lid, value: h.current, cell: l.cell, events: h.name });
  fx.push({ fx: "then", ev: { t: "deliver", hid } });
  return true;
};

// the next queued value becomes current; true when its listeners are in order and can be called
export const startNextValue = (needsPlacing) => (handles: Handles, fx: Effects, placer: boolean, hid: number, h: EventsRecord): boolean => {
  if (!h.queue.length) {
    handles.set(hid, { ...h, toCall: [], draining: false, current: undefined });
    return false;
  }
  const next: EventsRecord = { ...h, current: h.queue[0], queue: h.queue.slice(1), toCall: [] };
  if (needsPlacing(next, placer)) {
    handles.set(hid, next);
    fx.push({ fx: "place", hid, lids: next.listeners });
    return false;
  }
  handles.set(hid, { ...next, toCall: next.order ?? next.listeners });
  return true;
};

export const deliver = (callNextListener, startNextValue) => (handles: Handles, listeners: Listeners, fx: Effects, placer: boolean, hid: number): void => {
  for (;;) {
    const h = handles.get(hid);
    if (h === undefined) return;
    // a listener call is pending, or no value is ready to deliver
    if (callNextListener(handles, listeners, fx, hid, h)) return;
    if (!startNextValue(handles, fx, placer, hid, h)) return;
  }
};

export const onOpen = (newEventsRecord) => (handles: Handles, handleAt: Keys, ev: OpenEvent): void => {
  handles.set(ev.hid, newEventsRecord(ev.key, ev.name));
  handleAt.set(ev.key, ev.hid);
};

// the same run again ends the listeners parked on it: their cells run again after it
export const onRun = (needsNewGenerator, stopGenerator, detachListener) => (handles: Handles, listeners: Listeners, listenerAt: Keys, fx: Effects, ev: RunEvent): void => {
  const h = handles.get(ev.hid);
  if (h === undefined) return;
  if (needsNewGenerator(h, ev.args, ev.make)) {
    stopGenerator(handles, fx, ev.hid, h);
    fx.push({ fx: "make", hid: ev.hid });
    return;
  }
  for (const lid of h.listeners) if (listeners.get(lid)?.parked === true) detachListener(handles, listeners, listenerAt, fx, lid);
  handles.set(ev.hid, { ...(handles.get(ev.hid) ?? h), pending: false });
};

export const onMade = (schedulePull) => (handles: Handles, fx: Effects, ev: RunEvent): void => {
  const h = handles.get(ev.hid);
  if (h === undefined) return;
  handles.set(ev.hid, { ...h, hasGenerator: true, args: ev.args, make: ev.make, done: false });
  schedulePull(handles, fx, ev.hid);
  handles.set(ev.hid, { ...(handles.get(ev.hid) ?? h), pending: false });
};

export const onEventsInvalidated = () => (handles: Handles, hid: number): void => {
  const h = handles.get(hid);
  if (h !== undefined) handles.set(hid, { ...h, pending: true });
};

// a listener cell's run attaches its listener and ends the one its last run attached
export const onListen = (newEventsRecord, detachListener, schedulePull) => (handles: Handles, listeners: Listeners, listenerAt: Keys, fx: Effects, ev: ListenEvent): void => {
  const old = listenerAt.get(ev.key);
  if (old === ev.lid) return;
  if (old !== undefined) detachListener(handles, listeners, listenerAt, fx, old);
  // a released handle: epoch -1, so a result its stopped generator still sends is stale
  const h: EventsRecord = handles.get(ev.hid) ?? { ...newEventsRecord("", ev.name), epoch: -1 };
  listeners.set(ev.lid, { hid: ev.hid, key: ev.key, cell: ev.cell, aid: ev.aid, parked: false, born: null });
  listenerAt.set(ev.key, ev.lid);
  handles.set(ev.hid, { ...h, listeners: h.listeners.includes(ev.lid) ? h.listeners : [...h.listeners, ev.lid], order: null });
  schedulePull(handles, fx, ev.hid);
};

export const onListenerInvalidated = (parksOnInvalidation, detachListener) => (handles: Handles, listeners: Listeners, listenerAt: Keys, fx: Effects, ev: ListenerInvalidated): void => {
  const l = listeners.get(ev.lid);
  if (listenerAt.get(ev.key) !== ev.lid || l === undefined) return;
  if (parksOnInvalidation(handles.get(ev.hid))) listeners.set(ev.lid, { ...l, parked: true });
  else detachListener(handles, listeners, listenerAt, fx, ev.lid);
};

// a pull of the next value, from a frame (sync) or right after the last value (async); a stale one asks for a pull
// of the current generator
export const onPull = (schedulePull, isStaleResult, wantsValues) => (handles: Handles, fx: Effects, hid: number, epoch: number): void => {
  const h = handles.get(hid);
  if (h === undefined) return;
  handles.set(hid, { ...h, busy: false });
  if (isStaleResult(h, epoch) || !wantsValues(h)) schedulePull(handles, fx, hid);
  else fx.push({ fx: "next", hid, epoch });
};

// a sync generator's value: the next pull waits for a frame
export const onGot = (queueValue) => (handles: Handles, fx: Effects, ev: Result): void => {
  const h = handles.get(ev.hid);
  if (h === undefined) return;
  if (ev.done) {
    handles.set(ev.hid, { ...h, done: true });
    return;
  }
  queueValue(handles, fx, ev.hid, h, ev.value);
  fx.push({ fx: "then", ev: { t: "schedule", hid: ev.hid } });
};

// an async generator's value: it is pulled again at once
export const onResolved = (schedulePull, isStaleResult, queueValue) => (handles: Handles, fx: Effects, ev: Result): void => {
  const h0 = handles.get(ev.hid);
  if (h0 === undefined) return;
  const h: EventsRecord = { ...h0, busy: false };
  handles.set(ev.hid, h);
  if (isStaleResult(h, ev.epoch)) schedulePull(handles, fx, ev.hid);
  else if (ev.done) handles.set(ev.hid, { ...h, done: true });
  else {
    queueValue(handles, fx, ev.hid, h, ev.value);
    fx.push({ fx: "then", ev: { t: "pull", hid: ev.hid, epoch: ev.epoch } });
  }
};

export const onAwaiting = () => (handles: Handles, hid: number): void => {
  const h = handles.get(hid);
  if (h !== undefined) handles.set(hid, { ...h, busy: true });
};

export const onRejected = (failGenerator) => (handles: Handles, fx: Effects, ev: Failure): void => {
  const h = handles.get(ev.hid);
  if (h !== undefined) handles.set(ev.hid, { ...h, busy: false });
  failGenerator(handles, fx, ev.hid, ev.epoch, ev.error);
};

// the host's order for this value; kept for later values only when every listener was placed
export const onPlaced = (deliver) => (handles: Handles, listeners: Listeners, fx: Effects, placer: boolean, ev: PlacedEvent): void => {
  const h = handles.get(ev.hid);
  if (h === undefined) return;
  handles.set(ev.hid, { ...h, toCall: ev.order, order: ev.complete ? ev.order : h.order });
  deliver(handles, listeners, fx, placer, ev.hid);
};

export const onPlaceFailed = () => (handles: Handles, hid: number): void => {
  const h = handles.get(hid);
  if (h !== undefined) handles.set(hid, { ...h, draining: false, toCall: [] });
};

// cells were added, moved or deleted, or the host changed: every order is worked out again before the next value
export const onOrderChanged = () => (handles: Handles, counters: Counters, placer: boolean): void => {
  counters.placer = placer;
  for (const [hid, h] of [...handles]) if (h.order !== null) handles.set(hid, { ...h, order: null });
};

// an action ends the listeners that give values to it
export const onReleaseAction = (detachListener) => (handles: Handles, listeners: Listeners, listenerAt: Keys, fx: Effects, aid: number): void => {
  for (const lid of [...listenerAt.values()]) if (listeners.get(lid)?.aid === aid) detachListener(handles, listeners, listenerAt, fx, lid);
};

// detaches listeners and stops generators that no live variable holds
export const onSweep = (sweepVerdict, nextBorn, detachListener, releaseHandle) => (handles: Handles, handleAt: Keys, listeners: Listeners, listenerAt: Keys, fx: Effects, counters: Counters, ev: SweepEvent): void => {
  counters.generation += 1;
  const g = counters.generation, heldListeners = new Set(ev.heldListeners), heldHandles = new Set(ev.heldHandles);
  for (const lid of [...listenerAt.values()]) {
    const l = listeners.get(lid);
    const v = sweepVerdict(heldListeners.has(lid), l?.parked === true, l?.born ?? null, g);
    if (l !== undefined) listeners.set(lid, { ...l, born: nextBorn(v, l.born, g) });
    if (v === "release") detachListener(handles, listeners, listenerAt, fx, lid);
  }
  for (const hid of [...handleAt.values()]) {
    const h = handles.get(hid);
    const v = sweepVerdict(heldHandles.has(hid), false, h?.born ?? null, g);
    if (h !== undefined) handles.set(hid, { ...h, born: nextBorn(v, h.born, g) });
    if (v === "release") releaseHandle(handles, handleAt, listeners, listenerAt, fx, hid);
  }
};

export const dispatch = (onOpen, onRun, onMade, onEventsInvalidated, onListen, onListenerInvalidated, onPull, onGot, onResolved, onAwaiting, failGenerator, onRejected, schedulePull, deliver, onPlaced, onPlaceFailed, onOrderChanged, detachListener, releaseHandle, onReleaseAction, onSweep) =>
  (handles: Handles, handleAt: Keys, listeners: Listeners, listenerAt: Keys, fx: Effects, counters: Counters, ev: DeliveryEvent): void => {
    switch (ev.t) {
      case "open": return onOpen(handles, handleAt, ev);
      case "run": return onRun(handles, listeners, listenerAt, fx, ev);
      case "made": return onMade(handles, fx, ev);
      case "eventsInvalidated": return onEventsInvalidated(handles, ev.hid);
      case "listen": return onListen(handles, listeners, listenerAt, fx, ev);
      case "listenerInvalidated": return onListenerInvalidated(handles, listeners, listenerAt, fx, ev);
      case "pull": return onPull(handles, fx, ev.hid, ev.epoch);
      case "got": return onGot(handles, fx, ev);
      case "resolved": return onResolved(handles, fx, ev);
      case "awaiting": return onAwaiting(handles, ev.hid);
      case "threw": return failGenerator(handles, fx, ev.hid, ev.epoch, ev.error);
      case "rejected": return onRejected(handles, fx, ev);
      case "schedule": return schedulePull(handles, fx, ev.hid);
      case "deliver": return deliver(handles, listeners, fx, counters.placer, ev.hid);
      case "placed": return onPlaced(handles, listeners, fx, counters.placer, ev);
      case "placeFailed": return onPlaceFailed(handles, ev.hid);
      case "orderChanged": return onOrderChanged(handles, counters, ev.placer);
      case "releaseListener": return detachListener(handles, listeners, listenerAt, fx, ev.lid);
      case "releaseEvents": return releaseHandle(handles, handleAt, listeners, listenerAt, fx, ev.hid);
      case "releaseAction": return onReleaseAction(handles, listeners, listenerAt, fx, ev.aid);
      case "sweep": return onSweep(handles, handleAt, listeners, listenerAt, fx, counters, ev);
    }
  };

// one event applied to working copies of the state; the copies are frozen into the next state
export const step = (dispatch) => (st: Delivery, ev: DeliveryEvent): StepResult => {
  const handles = new Map(st.handles), handleAt = new Map(st.handleAt);
  const listeners = new Map(st.listeners), listenerAt = new Map(st.listenerAt);
  const counters: Counters = { placer: st.placer, generation: st.generation };
  const fx: Effects = [];
  dispatch(handles, handleAt, listeners, listenerAt, fx, counters, ev);
  const next = { handles: handles, handleAt: handleAt, listeners: listeners, listenerAt: listenerAt, placer: counters.placer, generation: counters.generation };
  return { state: next, effects: fx };
};

// of: count only listeners on these handles
export const runningCount = () => (st: Delivery, of: readonly number[] | null): number =>
  of === null ? st.listenerAt.size : [...st.listenerAt.values()].filter((lid) => { const l = st.listeners.get(lid); return l !== undefined && of.includes(l.hid); }).length;

// events cells whose generator is being pulled: live, not finished, with a listener attached
export const pullingCount = (wantsValues) => (st: Delivery, of: readonly number[] | null): number =>
  [...st.handleAt.values()].filter((hid) => { const h = st.handles.get(hid); return h !== undefined && (of === null || of.includes(hid)) && wantsValues(h); }).length;

// one store of a handle. sid tells it from the store a state cell made again over the same handle; value is the
// committed value, except for a view, whose element holds it
export type StoreRecord = { readonly sid: number; readonly name: string; readonly view: boolean; readonly value: unknown; readonly run: StoreRun | null };

// depth: how many action functions are running; call: the running top-level call's writes; ready: the writes
// of finished calls, in call order, until the commit
export type StoreState = { readonly depth: number; readonly call: Writes | null; readonly ready: Writes; readonly nextSid: number };

export type StoreEvent =
  | { readonly t: "enter"; readonly evaluating: boolean }
  | { readonly t: "exit"; readonly threw: boolean }
  | { readonly t: "write"; readonly handle: unknown; readonly name: string; readonly store: StoreRecord; readonly value: unknown }
  | { readonly t: "made"; readonly handle: unknown; readonly name: string; readonly value: unknown; readonly view: boolean; readonly run: StoreRun | null }
  | { readonly t: "commit"; readonly stores: Map<number, StoreRecord> }
  | { readonly t: "reset" };

export type StoreEffect =
  | { readonly fx: "throw"; readonly msg: string }
  | { readonly fx: "schedule" }
  | { readonly fx: "keep"; readonly handle: unknown; readonly store: StoreRecord }
  | { readonly fx: "setView"; readonly handle: unknown; readonly value: unknown }
  | { readonly fx: "tell" | "tellView"; readonly handle: unknown };

// a set or update is legal only while an action's function runs; name is the written handle's
export const writeTarget = (ownerOf) => (st: StoreState, name: string): Owner => {
  const call = ownerOf(st);
  return call === null ? { ok: false, msg: `State ${name}: set/update called outside an action` } : { ok: true, call };
};

// the value as of this point in the call order: this call's writes, then finished calls', then committed
export const currentOf = (committedOf) => (st: StoreState, call: Writes, store: StoreRecord): Seen => {
  const w = call.get(store.sid) ?? st.ready.get(store.sid);
  return w === undefined ? committedOf(store) : { k: "value", value: w.value };
};

// what update's function is given, before it runs
export const updateSees = (writeTarget, currentOf) => (st: StoreState, name: string, store: StoreRecord): Seen => {
  const w = writeTarget(st, name);
  return w.ok ? currentOf(st, w.call, store) : { k: "refused", msg: w.msg };
};

// read(r): store is null when r is not a state cell's handle
export const readSees = (ownerOf, currentOf) => (st: StoreState, store: StoreRecord | null): Seen => {
  if (store === null) return { k: "refused", msg: "read(...) needs a State" };
  const call = ownerOf(st);
  return call === null ? { k: "refused", msg: `read(${store.name}) called outside an action` } : currentOf(st, call, store);
};

// a state cell's run keeps its handle when the same function text made it, and its store unless an input changed
export const refPlan = (same) => (last: StoreRecord | null, fid: string, args: readonly unknown[]): RefPlan => {
  const keep = last !== null && last.run !== null && last.run.fid === fid;
  return { keep, remake: !keep || last === null || last.run === null || !same(last.run.args, args) };
};

// a call made while an action's function runs is part of that call; otherwise it starts one, unless a cell is evaluating
export const enterCall = () => (st: StoreState, evaluating: boolean): StoreStep => {
  if (st.depth > 0) return { state: { ...st, depth: st.depth + 1 }, effects: [] };
  if (evaluating) return { state: st, effects: [{ fx: "throw", msg: "action called during a cell evaluation" }] };
  const call: Writes = new Map();
  return { state: { ...st, depth: 1, call }, effects: [] };
};

// a finished call's writes join those waiting for the commit, in first-write order; the first to join asks for the commit
export const mergeWrites = () => (ready: Writes, call: Writes): { readonly ready: Writes; readonly schedule: boolean } => {
  if (call.size === 0) return { ready, schedule: false };
  const next = new Map(ready);
  for (const [sid, p] of call) next.set(sid, p);
  return { ready: next, schedule: ready.size === 0 };
};

// a nested call leaves its writes in the call, also when it threw (its caller caught it); a top-level call's writes join
// ready unless it threw. y1 (2026-11-24): no call gives back what its function returned (an Action's call is typed void)
export const exitCall = (mergeWrites) => (st: StoreState, threw: boolean): StoreStep => {
  if (st.depth > 1) return { state: { ...st, depth: st.depth - 1 }, effects: [] };
  const ended: StoreState = { ...st, depth: 0, call: null };
  if (threw || st.call === null) return { state: ended, effects: [] };
  const m = mergeWrites(st.ready, st.call);
  return { state: { ...ended, ready: m.ready }, effects: m.schedule ? [{ fx: "schedule" }] : [] };
};

export const writeInCall = (writeTarget) => (st: StoreState, handle: unknown, name: string, store: StoreRecord, value: unknown): StoreStep => {
  const w = writeTarget(st, name);
  if (!w.ok) return { state: st, effects: [{ fx: "throw", msg: w.msg }] };
  const call = new Map(w.call);
  call.set(store.sid, { handle, value });
  return { state: { ...st, call: call }, effects: [] };
};

// a new store for a handle; a write waiting for the store it replaces is not committed
export const makeStore = () => (st: StoreState, handle: unknown, name: string, value: unknown, view: boolean, run: StoreRun | null): StoreStep => {
  const store: StoreRecord = { sid: st.nextSid, name, view, value, run };
  return { state: { ...st, nextSid: st.nextSid + 1 }, effects: [{ fx: "keep", handle, store }] };
};

// stores: the records the handles in ready hold now, by sid. Every store takes its value before any is told, so no
// reader sees some of a commit's values and not others; a view's element is told as a user's change would tell it
export const commitReady = () => (st: StoreState, stores: Map<number, StoreRecord>): StoreStep => {
  const sets: Mut<StoreEffect[]> = [], tells: Mut<StoreEffect[]> = [];
  for (const [sid, p] of st.ready) {
    const s = stores.get(sid);
    if (s === undefined) continue;
    sets.push(s.view ? { fx: "setView", handle: p.handle, value: p.value } : { fx: "keep", handle: p.handle, store: { ...s, value: p.value } });
    tells.push({ fx: s.view ? "tellView" : "tell", handle: p.handle });
  }
  const ready: Writes = new Map();
  return { state: { ...st, ready }, effects: [...sets, ...tells] };
};

export const storeStep = (enterCall, exitCall, writeInCall, makeStore, commitReady, resetStore) => (st: StoreState, ev: StoreEvent): StoreStep => {
  switch (ev.t) {
    case "enter": return enterCall(st, ev.evaluating);
    case "exit": return exitCall(st, ev.threw);
    case "write": return writeInCall(st, ev.handle, ev.name, ev.store, ev.value);
    case "made": return makeStore(st, ev.handle, ev.name, ev.value, ev.view, ev.run);
    case "commit": return commitReady(st, ev.stores);
    case "reset": return resetStore(st);
  }
};

// prop: set the DOM property unless it already holds the value; listen: add the one DOM listener for this prop
export type PropOp =
  | { readonly op: "listen"; readonly name: string; readonly event: string }
  | { readonly op: "handler" | "prop"; readonly name: string; readonly value: PropValue }
  | { readonly op: "attr"; readonly name: string; readonly text: string }
  | { readonly op: "unattr" | "unhandle"; readonly name: string }
  | { readonly op: "reset"; readonly name: string; readonly value: string | boolean };

// old: index into the DOM children as found; kid: index into the new children; place: insert kid's node at its index
export type ChildOp =
  | { readonly op: "remove"; readonly old: number }
  | { readonly op: "reuse" | "replace"; readonly old: number; readonly kid: number }
  | { readonly op: "text"; readonly old: number; readonly text: string }
  | { readonly op: "create" | "place"; readonly kid: number };

// a fragment (tag "") is drawn as a span with display: contents
export const drawnTag = () => (tag: string): { readonly tag: string; readonly fragment: boolean } =>
  tag === "" ? { tag: "span", fragment: true } : { tag, fragment: false };

// the DOM event of an event prop; own keys only, so a prop named "constructor" is not an event
export const eventOf = (DOM_EVENTS) => {
  // a fresh Map bound to an annotated const is writable (S4.1); the kept function captures a plain-typed name for it
  const made = new Map(Object.entries(DOM_EVENTS).map(([k, v]) => [k, v[0]]));
  const events: Map<string, string> = made;
  return (name: string): string | undefined => events.get(name);
};

// a prop the old element had and the new one has not; removing the attribute does not reset a DOM property
export const propGone = (eventOf, PROPS) => (name: string): readonly PropOp[] =>
  eventOf(name) !== undefined ? [{ op: "unhandle", name }] : PROPS.has(name) ? [{ op: "reset", name, value: name === "value" ? "" : false }] : [{ op: "unattr", name }];

// one prop of the new element; was: the old element's value under that name. A DOM property given undefined is
// reset as if removed, once: resetting it on every patch would clear what the user typed
export const propSet = (eventOf, PROPS, removesAttribute, propGone, sameAttribute) => (name: string, value: PropValue, was: PropValue, listening: Set<string>): readonly PropOp[] => {
  if (name === "key" || name === "children") return [];
  const event = eventOf(name);
  if (event !== undefined) return listening.has(name) ? [{ op: "handler", name, value }] : [{ op: "listen", name, event }, { op: "handler", name, value }];
  if (PROPS.has(name)) return value !== undefined ? [{ op: "prop", name, value }] : was === undefined ? [] : propGone(name);
  if (removesAttribute(value)) return [{ op: "unattr", name }];
  return sameAttribute(was, value) ? [] : [{ op: "attr", name, text: String(value) }];
};

// listening: the event props the node has a DOM listener for
export const propOps = (propSet, propGone) => (old: Props, now: Props, listening: Set<string>): readonly PropOp[] => {
  const still = new Set(Object.keys(now));
  const gone = Object.keys(old).filter((k) => !still.has(k) && k !== "key" && k !== "children");
  // d1 (2026-11-24): old's own entries through a Map: a run-time key on a record may name an inherited member
  const was = new Map(Object.entries(old));
  const set = Object.entries(now).flatMap(([k, v]) => propSet(k, v, was.get(k), listening));
  const unset = gone.flatMap((k) => propGone(k));
  return [...set, ...unset];
};

// the children's slot ids when every one is an element with a key, else null: they are matched by position
export const keyedIds = (slotId) => (kids: readonly Kid[]): readonly string[] | null => {
  const out: Mut<string[]> = [];
  for (const c of kids) {
    if (c.k !== "elem" || c.key === undefined) return null;
    out.push(slotId(c.tag, c.key));
  }
  return out.length ? out : null;
};

// for each new slot, the old child it reuses: of old children with its id, the last, each used once
export const matchKeyed = () => (oldIds: readonly (string | null)[], ids: readonly string[]): readonly (number | null)[] => {
  const byId: Mut<Map<string, number>> = new Map();
  for (const [j, id] of oldIds.entries()) if (id !== null) byId.set(id, j);
  const out: Mut<(number | null)[]> = [];
  for (const id of ids) {
    const j = byId.get(id);
    out.push(j ?? null);
    if (j !== undefined) byId.delete(id);
  }
  return out;
};

// the old children kept by the first pass: those whose id some new slot has (an unused duplicate too)
export const keptByKey = () => (oldIds: readonly (string | null)[], ids: readonly string[]): readonly number[] => {
  const wanted = new Set(ids);
  return oldIds.flatMap((id, j) => (id !== null && wanted.has(id) ? [j] : []));
};

// whether each new child must be inserted at its index: after i placements the DOM is the first i new children,
// then the kept old children not yet placed, in their old order; a child already first among those stays
export const mustPlace = () => (kept: readonly number[], reuse: readonly (number | null)[]): readonly boolean[] => {
  const placedAt: Mut<Map<number, number>> = new Map();
  for (const [i, j] of reuse.entries()) if (j !== null) placedAt.set(j, i);
  const out: Mut<boolean[]> = [];
  let p = 0;
  for (const [i, j] of reuse.entries()) {
    while (p < kept.length && (placedAt.get(kept[p] ?? -1) ?? Infinity) < i) p++;
    out.push(j === null || kept[p] !== j);
  }
  return out;
};

// keyed children: drop the old ones no slot wants, reuse or create each, insert where not in place, drop unused duplicates
export const keyedOps = (drawnId, matchKeyed, keptByKey, mustPlace) => (old: readonly Drawn[], ids: readonly string[]): readonly ChildOp[] => {
  const oldIds = old.map((d) => drawnId(d));
  const reuse = matchKeyed(oldIds, ids), kept = keptByKey(oldIds, ids), place = mustPlace(kept, reuse);
  const keptSet = new Set(kept), used = new Set(reuse);
  const out: Mut<ChildOp[]> = old.flatMap((_d, j): ChildOp[] => (keptSet.has(j) ? [] : [{ op: "remove", old: j }]));
  for (const [i, j] of reuse.entries()) {
    out.push(j === null ? { op: "create", kid: i } : { op: "reuse", old: j, kid: i });
    if (place[i] === true) out.push({ op: "place", kid: i });
  }
  for (const j of kept) if (!used.has(j)) out.push({ op: "remove", old: j });
  return out;
};

// one child matched by position: patch, retext, replace or append
export const childAt = (keepsNode) => (cur: Drawn | undefined, kid: Kid, i: number): readonly ChildOp[] => {
  if (cur === undefined) return [{ op: "create", kid: i }, { op: "place", kid: i }];
  if (keepsNode(cur, kid)) return [{ op: "reuse", old: i, kid: i }];
  if (cur.k === "text" && kid.k === "text") return cur.text === kid.text ? [] : [{ op: "text", old: i, text: kid.text }];
  return [{ op: "replace", old: i, kid: i }];
};

export const positionalOps = (childAt) => (old: readonly Drawn[], kids: readonly Kid[]): readonly ChildOp[] => [
  ...kids.flatMap((k, i) => childAt(old[i], k, i)),
  ...old.flatMap((_d, j): ChildOp[] => (j >= kids.length ? [{ op: "remove", old: j }] : [])),
];

export const childOps = (keyedIds, keyedOps, positionalOps) => (old: readonly Drawn[], kids: readonly Kid[]): readonly ChildOp[] => {
  const ids = keyedIds(kids);
  return ids === null ? positionalOps(old, kids) : keyedOps(old, ids);
};

export type ValueSeen =
  | { readonly t: "null" } | { readonly t: "-0" } | { readonly t: "function" } | { readonly t: "promise" }
  | { readonly t: "string"; readonly s: string }
  | { readonly t: "number" | "boolean" | "bigint"; readonly text: string }
  | { readonly t: "array"; readonly length: number }
  | { readonly t: "object"; readonly plain: boolean; readonly ctor: string | null }
  | { readonly t: "other"; readonly type: string };

export const describeSeen = () => (s: ValueSeen): string => {
  switch (s.t) {
    case "null": return "null";
    case "string": return `string ${JSON.stringify(s.s.length > 40 ? s.s.slice(0, 40) + "…" : s.s)}`;
    case "-0": return "number -0";
    case "number": case "boolean": case "bigint": return `${s.t} ${s.text}`;
    case "function": return "a function";
    case "array": return `an array of ${s.length}`;
    case "promise": return "a promise";
    // a9 (2026-11-23): Object as the constructor means the prototype is another object that inherits from Object.prototype
    case "object": return s.plain ? "an object" : s.ctor === "Object" ? "an object whose prototype is not Object.prototype" : `a ${s.ctor ?? "non-plain"} object`;
    case "other": return s.type;
  }
};

// a ref followed to its definition, at most 64 steps
export const resolveRef = () => (m: Shape, defs: Map<string, Shape> | null): Shape => {
  let x = m, i = 0;
  while (x.k === "ref" && defs !== null && i < 64) { x = defs.get(x.n) ?? x; i++; }
  return x;
};

// each member by its literal at key, when every member is a record with a literal there of its own; else null
export const tagTable = () => (ms: readonly Shape[], key: string): Map<string | number | boolean, Shape> | null => {
  const by: Mut<Map<string | number | boolean, Shape>> = new Map();
  for (const m of ms) {
    const p = m.k === "rec" ? m.props.find((q) => q[0] === key) : undefined;
    if (p === undefined || p[2]) return null;
    const lit = p[1];
    if (lit.k !== "lit" || by.has(lit.v)) return null;
    by.set(lit.v, m);
  }
  return by;
};

// a union whose members are records that each give one property a literal of its own (a tag): that property and the
// member for each literal; else null. A member that is a ref is looked up in defs
export const tagDispatch = (resolveRef, tagTable) => (s: UnionShape, defs: Map<string, Shape> | null): Dispatch | null => {
  const ms = s.ts.map((m) => resolveRef(m, defs));
  const first = ms[0];
  if (first === undefined || first.k !== "rec" || !ms.every((m) => m.k === "rec")) return null;
  for (const [key, ks, opt] of first.props) {
    if (opt || ks.k !== "lit") continue;
    const by = tagTable(ms, key);
    if (by !== null) return { key, by };
  }
  return null;
};

// the kinds of value a shape could take, as bits: 1 a record, 2 an array, 4 a primitive. wide: a shape that throws
// other than a mismatch (a function, a ref with no definition) counts as taking every kind
export const memberKinds = () => (s0: Shape, defs: Map<string, Shape> | null, wide: boolean): number => {
  const met: Mut<Set<string>> = new Set();
  function go(s: Shape): number {
    switch (s.k) {
      case "rec": return 1;
      case "arr": case "tup": return 2;
      case "unknown": return 7;
      case "union": { let a = 0; for (const m of s.ts) a = a | go(m); return a; }
      case "defs": return go(s.body);
      case "ref": { const d = defs === null ? undefined : defs.get(s.n); if (d === undefined) return wide ? 7 : 0; if (met.has(s.n)) return 0; met.add(s.n); return go(d); }
      case "fn": return wide ? 7 : 4;
      default: return 4;
    }
  }
  return go(s0);
};

// per member, the kinds of value it could take. A member that cannot take a primitive fails on one with a mismatch at
// the union's place, so it is not tried; an object or array is still tried, as the mismatch reads it and a getter
// there may throw
export const memberTakes = (memberKinds) => (s: UnionShape, defs: Map<string, Shape> | null): readonly number[] => s.ts.map((m) => memberKinds(m, defs, true));

// for a record, an array and a primitive, the index of the one member that could take a value of that kind, else -1
export const soleMembers = (memberKinds) => (s: UnionShape, defs: Map<string, Shape> | null): readonly number[] => {
  const ks = s.ts.map((m) => memberKinds(m, defs, false));
  return [1, 2, 4].map((bit) => { const at = ks.flatMap((k, i) => ((k & bit) !== 0 ? [i] : [])); return at.length === 1 ? at[0] ?? -1 : -1; });
};

// member i failed with a mismatch at ePath: that mismatch is the union's when it is below the union's place and the
// member was the only one that could take the value (the tag named it, or it alone takes the value's kind)
export const isSoleMiss = () => (ePath: string, path: string, tagged: boolean, sole: number, i: number): boolean => ePath !== path && (tagged || sole === i);

// a value fits a primitive's shape (num, str, bool, null, undef, lit); null for a shape that is not a primitive's
export const primFits = () => (s: Shape, v: unknown): boolean | null => {
  switch (s.k) {
    case "num": return typeof v === "number";
    case "str": return typeof v === "string";
    case "bool": return typeof v === "boolean";
    case "null": return v === null;
    case "undef": return v === undefined;
    case "lit": return Object.is(v, s.v);
    default: return null;
  }
};

// a property the record shape declares: skipped when optional and absent or undefined, missing when required and absent,
// else checked (a required property that holds undefined is checked as undefined)
export const propStep = () => (has: boolean, undef: boolean, opt: boolean): "skip" | "missing" | "check" => (has && !undef ? "check" : opt ? "skip" : has ? "check" : "missing");

// union member i is tried on a primitive only when it could take one (takes: memberTakes's bits, null for an object or
// an array, on which every member is tried)
export const triesMember = () => (takes: readonly number[] | null, i: number): boolean => takes === null || ((takes[i] ?? 0) & 4) !== 0;

// a union no member took: the mismatch of the one member that could take the value, else under a recursive shape the
// cycle a member met, else the union's own mismatch
export const unionMiss = () => (sole: boolean, recursive: boolean, cycle: boolean): "sole" | "cycle" | "union" => (sole ? "sole" : recursive && cycle ? "cycle" : "union");
